@Test
public void bootstrapTest() throws Throwable {
    int originalNodeCount = 2;
    int expandedNodeCount = originalNodeCount + 1;
    try (Cluster cluster = Cluster.build().withNodes(originalNodeCount).withoutVNodes().withTokenSupplier(TokenSupplier.evenlyDistributedTokens(expandedNodeCount)).withNodeIdTopology(NetworkTopology.singleDcNetworkTopology(expandedNodeCount, "dc0", "rack0")).withConfig(config -> config.set("accord.command_store_shard_count", 2).set("accord.queue_shard_count", 2).set("accord.shard_durability_cycle", "20s").set("accord.shard_durability_target_splits", "1").set("accord.retry_syncpoint", "1s*attempts").set("accord.retry_durability", "1s*attempts").with(NETWORK, GOSSIP)).start()) {
        cluster.schemaChange("CREATE KEYSPACE ks WITH REPLICATION={'class':'SimpleStrategy', 'replication_factor':2}");
        cluster.schemaChange("CREATE TABLE ks.tbl (k int, c int, v int, primary key(k, c)) WITH transactional_mode='full'");
        long initialMax = maxEpoch(cluster);
        for (IInvokableInstance node : cluster) {
            node.runOnInstance(() -> {
                Assert.assertEquals(initialMax, ClusterMetadata.current().epoch.getEpoch());
                awaitEpoch(initialMax);
                AccordConfigurationService configService = service().configService();
                long minEpoch = configService.minEpoch();
                Assert.assertEquals(initialMax, configService.maxEpoch());
                for (long epoch = minEpoch; epoch < initialMax; epoch++) {
                    awaitEpoch(epoch);
                    Assert.assertEquals(EpochSnapshot.completed(epoch), configService.getEpochSnapshot(epoch));
                }
                awaitLocalSyncNotification(initialMax);
                Assert.assertEquals(EpochSnapshot.completed(initialMax), configService.getEpochSnapshot(initialMax));
            });
        }
        for (IInvokableInstance node : cluster) {
            node.runOnInstance(StreamListener::register);
        }
        long schemaChangeMax = maxEpoch(cluster);
        for (IInvokableInstance node : cluster) {
            node.runOnInstance(() -> {
                ClusterMetadataService.instance().fetchLogFromCMS(Epoch.create(schemaChangeMax));
                awaitEpoch(schemaChangeMax);
                AccordConfigurationService configService = service().configService();
                for (long epoch = initialMax + 1; epoch <= schemaChangeMax; epoch++) {
                    awaitLocalSyncNotification(epoch);
                    Assert.assertEquals(EpochSnapshot.completed(epoch), configService.getEpochSnapshot(epoch));
                }
            });
        }
        for (int key = 0; key < 100; key++) {
            String query = "BEGIN TRANSACTION\n" + "  LET row1 = (SELECT * FROM ks.tbl WHERE k = " + key + " AND c = 0);\n" + "  SELECT row1.v;\n" + "  IF row1 IS NULL THEN\n" + "    INSERT INTO ks.tbl (k, c, v) VALUES (" + key + ", " + key + ", " + key + ");\n" + "  END IF\n" + "COMMIT TRANSACTION";
            AccordTestBase.executeWithRetry(cluster, query);
        }
        for (IInvokableInstance node : cluster) {
            node.runOnInstance(() -> {
                Assert.assertTrue(StreamListener.listener.registered.isEmpty());
            });
        }
        bootstrapAndJoinNode(cluster);
        long bootstrapMax = maxEpoch(cluster);
        for (IInvokableInstance node : cluster) {
            node.runOnInstance(() -> {
                ClusterMetadataService.instance().fetchLogFromCMS(Epoch.create(bootstrapMax));
                Assert.assertEquals(bootstrapMax, ClusterMetadata.current().epoch.getEpoch());
                AccordService service = (AccordService) AccordService.instance();
                awaitEpoch(bootstrapMax);
                AccordConfigurationService configService = service.configService();
                awaitLocalSyncNotification(bootstrapMax);
                Assert.assertEquals(EpochSnapshot.completed(bootstrapMax), configService.getEpochSnapshot(bootstrapMax));
            });
        }
        InetAddress node3Addr = cluster.get(3).broadcastAddress().getAddress();
        for (IInvokableInstance node : cluster.get(1, 2)) {
            node.runOnInstance(() -> {
                StreamListener.listener.forSession(session -> {
                    Assert.assertEquals(node3Addr, session.peer.getAddress());
                    Assert.assertEquals(0, session.getNumRequests());
                    Assert.assertTrue(session.getNumKeyspaceTransfers() > 0);
                });
                getBlocking(service().node().commandStores().forEach((PreLoadContext.Empty) () -> "Test", safeStore -> {
                    AccordSafeCommandStore ss = (AccordSafeCommandStore) safeStore;
                    Assert.assertEquals(Timestamp.NONE, getOnlyElement(ss.bootstrapBeganAt().keySet()));
                    Assert.assertEquals(Timestamp.NONE, getOnlyElement(ss.safeToReadAt().keySet()));
                    //
                    //                        Assert.assertTrue(commandStore.maxBootstrapEpoch() > 0);
                    //                        Assert.assertTrue(commandStore.bootstrapBeganAt().isEmpty());
                    //                        Assert.assertTrue(commandStore.safeToRead().isEmpty());
                }));
            });
        }
        cluster.get(3).runOnInstance(() -> {
            List<Range<Token>> ranges = StorageService.instance.getLocalRanges("ks");
            TopologyManager topologyManager = service().node().topology();
            for (long epoch = topologyManager.minEpoch(); epoch <= topologyManager.epoch(); ++epoch) {
                CountDownLatch latch = new CountDownLatch(1);
                topologyManager.epochReady(epoch).data.invokeIfSuccess(latch::countDown);
                while (true) {
                    try {
                        if (latch.await(1L, TimeUnit.SECONDS))
                            break;
                    } catch (InterruptedException e) {
                        throw new RuntimeException(e);
                    }
                }
            }
            for (int key = 0; key < 100; key++) {
                UntypedResultSet result = QueryProcessor.executeInternal("SELECT * FROM ks.tbl WHERE k=?", key);
                PartitionKey partitionKey = pk(key, "ks", "tbl");
                if (ranges.stream().anyMatch(range -> range.contains(partitionKey.token()))) {
                    UntypedResultSet.Row row = getOnlyElement(result);
                    Assert.assertEquals(key, row.getInt("c"));
                    Assert.assertEquals(key, row.getInt("v"));
                    getBlocking(service().node().commandStores().forEach((PreLoadContext.Empty) () -> "Test", safeStore -> {
                        if (safeStore.ranges().currentRanges().contains(partitionKey)) {
                            AccordSafeCommandStore ss = (AccordSafeCommandStore) safeStore;
                            Assert.assertFalse(ss.bootstrapBeganAt().isEmpty());
                            Assert.assertFalse(ss.safeToReadAt().isEmpty());
                            Assert.assertEquals(1, ss.bootstrapBeganAt().entrySet().stream().filter(entry -> entry.getValue().contains(partitionKey)).map(entry -> {
                                Assert.assertTrue(entry.getKey().compareTo(Timestamp.NONE) > 0);
                                return entry;
                            }).count());
                            Assert.assertEquals(1, ss.safeToReadAt().entrySet().stream().filter(entry -> entry.getValue().contains(partitionKey)).map(entry -> {
                                Assert.assertTrue(entry.getKey().compareTo(Timestamp.NONE) > 0);
                                return entry;
                            }).count());
                        }
                    }));
                } else {
                    Assert.assertTrue(result.isEmpty());
                }
            }
        });
    }
}

@Test
public void moveTest() throws Throwable {
    try (Cluster cluster = Cluster.build().withNodes(3).withoutVNodes().withTokenSupplier(TokenSupplier.evenlyDistributedTokens(3)).withNodeIdTopology(NetworkTopology.singleDcNetworkTopology(3, "dc0", "rack0")).withConfig(config -> config.set("accord.shard_durability_target_splits", "1").set("accord.shard_durability_cycle", "20s").with(NETWORK, GOSSIP)).start()) {
        cluster.schemaChange("CREATE KEYSPACE ks WITH REPLICATION={'class':'SimpleStrategy', 'replication_factor':2}");
        cluster.schemaChange("CREATE TABLE ks.tbl (k int, c int, v int, primary key(k, c)) WITH transactional_mode='full'");
        long initialMax = maxEpoch(cluster);
        long[] tokens = new long[3];
        for (int i = 0; i < 3; i++) {
            tokens[i] = cluster.get(i + 1).callOnInstance(() -> Long.valueOf(getOnlyElement(StorageService.instance.getTokens())));
        }
        for (IInvokableInstance node : cluster) {
            node.runOnInstance(() -> {
                Assert.assertEquals(initialMax, ClusterMetadata.current().epoch.getEpoch());
                awaitEpoch(initialMax);
                AccordConfigurationService configService = service().configService();
                long minEpoch = configService.minEpoch();
                Assert.assertEquals(initialMax, configService.maxEpoch());
                for (long epoch = minEpoch; epoch < initialMax; epoch++) {
                    awaitEpoch(epoch);
                    Assert.assertEquals(EpochSnapshot.completed(epoch), configService.getEpochSnapshot(epoch));
                }
                awaitLocalSyncNotification(initialMax);
                Assert.assertEquals(EpochSnapshot.completed(initialMax), configService.getEpochSnapshot(initialMax));
            });
        }
        long schemaChangeMax = maxEpoch(cluster);
        for (IInvokableInstance node : cluster) {
            node.runOnInstance(() -> {
                Assert.assertEquals(schemaChangeMax, ClusterMetadata.current().epoch.getEpoch());
                AccordService service = (AccordService) AccordService.instance();
                awaitEpoch(schemaChangeMax);
                AccordConfigurationService configService = service.configService();
                for (long epoch = initialMax + 1; epoch <= schemaChangeMax; epoch++) {
                    awaitLocalSyncNotification(epoch);
                    Assert.assertEquals(EpochSnapshot.completed(epoch), configService.getEpochSnapshot(epoch));
                }
            });
        }
        for (int key = 0; key < 100; key++) {
            String query = "BEGIN TRANSACTION\n" + "  LET row1 = (SELECT * FROM ks.tbl WHERE k = " + key + " AND c = 0);\n" + "  SELECT row1.v;\n" + "  IF row1 IS NULL THEN\n" + "    INSERT INTO ks.tbl (k, c, v) VALUES (" + key + ", " + key + ", " + key + ");\n" + "  END IF\n" + "COMMIT TRANSACTION";
            AccordTestBase.executeWithRetry(cluster, query);
        }
        long token = ((tokens[1] - tokens[0]) / 2) + tokens[0];
        long preMove = maxEpoch(cluster);
        cluster.get(1).runOnInstance(() -> StorageService.instance.move(Long.toString(token)));
        long moveMax = maxEpoch(cluster);
        for (IInvokableInstance node : cluster) {
            node.runOnInstance(() -> {
                ClusterMetadataService.instance().fetchLogFromCMS(Epoch.create(moveMax));
                Assert.assertEquals(moveMax, ClusterMetadata.current().epoch.getEpoch());
                AccordService service = (AccordService) AccordService.instance();
                awaitEpoch(moveMax);
                AccordConfigurationService configService = service.configService();
                awaitLocalSyncNotification(moveMax);
                Assert.assertEquals(EpochSnapshot.completed(moveMax), configService.getEpochSnapshot(moveMax));
            });
        }
        for (IInvokableInstance node : cluster) {
            node.runOnInstance(() -> {
                // validate streaming
                List<Range<Token>> ranges = StorageService.instance.getLocalRanges("ks");
                TableId tableId = Schema.instance.getTableMetadata("ks", "tbl").id;
                for (int key = 0; key < 100; key++) {
                    DecoratedKey dk = dk(key);
                    UntypedResultSet result = QueryProcessor.executeInternal("SELECT * FROM ks.tbl WHERE k=?", key);
                    if (ranges.stream().anyMatch(range -> range.contains(dk.getToken()))) {
                        UntypedResultSet.Row row = getOnlyElement(result);
                        Assert.assertEquals(key, row.getInt("c"));
                        Assert.assertEquals(key, row.getInt("v"));
                        PartitionKey partitionKey = new PartitionKey(tableId, dk);
                        getBlocking(service().node().commandStores().forEach((PreLoadContext.Empty) () -> "Test", partitionKey.toUnseekable(), moveMax, moveMax, safeStore -> {
                            if (!safeStore.ranges().allAt(preMove).contains(partitionKey)) {
                                AccordSafeCommandStore ss = (AccordSafeCommandStore) safeStore;
                                Assert.assertFalse(ss.bootstrapBeganAt().isEmpty());
                                Assert.assertFalse(ss.safeToReadAt().isEmpty());
                                Assert.assertEquals(1, ss.bootstrapBeganAt().entrySet().stream().filter(entry -> entry.getValue().contains(partitionKey)).map(entry -> {
                                    Assert.assertTrue(entry.getKey().compareTo(Timestamp.NONE) > 0);
                                    return entry;
                                }).count());
                                Assert.assertEquals(1, ss.safeToReadAt().entrySet().stream().filter(entry -> entry.getValue().contains(partitionKey)).map(entry -> {
                                    Assert.assertTrue(entry.getKey().compareTo(Timestamp.NONE) > 0);
                                    return entry;
                                }).count());
                            }
                        }));
                    }
                }
            });
        }
    }
}

@Test
public void testRejectTransactionStatement() throws Throwable {
    test("CREATE TABLE " + qualifiedAccordTableName + " (k int, c int, v int, primary key (k, c))", cluster -> {
        ICoordinator coordinator = cluster.coordinator(1);
        String readQuery = "BEGIN TRANSACTION\n" + "  SELECT * FROM " + qualifiedAccordTableName + " WHERE k = 0;\n" + "COMMIT TRANSACTION;";
        String writeQuery = "BEGIN TRANSACTION\n" + "  INSERT INTO " + qualifiedAccordTableName + " (k, c, v) VALUES (42, 43, 44);\n" + "COMMIT TRANSACTION;";
        // Not enabled on table or migrating/migrated
        try {
            coordinator.execute(readQuery, ConsistencyLevel.ALL);
            fail("Expected exception");
        } catch (Throwable t) {
            assertEquals(InvalidRequestException.class.getName(), t.getClass().getName());
            assertEquals(t.getMessage(), format(TransactionStatement.TRANSACTIONS_DISABLED_ON_TABLE_MESSAGE, "SELECT", "at [2:3]"));
        }
        try {
            coordinator.execute(writeQuery, ConsistencyLevel.ALL);
            fail("Expected exception");
        } catch (Throwable t) {
            assertEquals(InvalidRequestException.class.getName(), t.getClass().getName());
            assertEquals(t.getMessage(), format(TransactionStatement.TRANSACTIONS_DISABLED_ON_TABLE_MESSAGE, "INSERT", "at [2:3]"));
        }
        // Enabled on table but not migrating/migrated
        coordinator.execute("ALTER TABLE " + qualifiedAccordTableName + " WITH transactional_mode = '" + transactionalMode.name() + "';", ConsistencyLevel.ALL);
        try {
            cluster.coordinator(1).execute(readQuery, ConsistencyLevel.ALL);
            fail("Expected exception");
        } catch (Throwable t) {
            assertEquals(InvalidRequestException.class.getName(), t.getClass().getName());
            assertEquals(t.getMessage(), TransactionStatement.UNSUPPORTED_MIGRATION);
        }
        // Blind writes are allowed because Accord does know how to execute them correctly via interop
        coordinator.execute(writeQuery, ConsistencyLevel.ALL);
        // Enabled on table but migrating
        nodetool(coordinator, "consensus_admin", "begin-migration", KEYSPACE, accordTableName);
        try {
            coordinator.execute(readQuery, ConsistencyLevel.ALL);
            fail("Expected exception");
        } catch (Throwable t) {
            assertEquals(InvalidRequestException.class.getName(), t.getClass().getName());
            assertEquals(t.getMessage(), TransactionStatement.UNSUPPORTED_MIGRATION);
        }
        // Write query should succeed even if Accord can't read
        coordinator.execute(writeQuery, ConsistencyLevel.ALL);
        // Should also work as a non-SERIAL insert
        coordinator.execute("INSERT INTO " + qualifiedAccordTableName + " (k, c, v) VALUES (42, 43, 44);", ConsistencyLevel.ALL);
        // And CAS
        coordinator.execute("INSERT INTO " + qualifiedAccordTableName + " (k, c, v) VALUES (42, 43, 44) IF NOT EXISTS;", ConsistencyLevel.SERIAL, ConsistencyLevel.ALL);
        // Enabled on table and migration has done data repair
        nodetool(coordinator, "repair", "-skip-accord", "-skip-paxos", KEYSPACE, accordTableName);
        coordinator.execute(readQuery, ConsistencyLevel.ALL);
        coordinator.execute(writeQuery, ConsistencyLevel.ALL);
    });
}

