            for (int j = 0; j < 10; j++) cluster.coordinator(1).execute("INSERT INTO " + qualifiedAccordTableName + "(k, c, v) VALUES (?, ?, ?);", ConsistencyLevel.ALL, i, j, i + j);
        }
        // multi row
        String cql = "BEGIN TRANSACTION\n" + "  SELECT * FROM " + qualifiedAccordTableName + " WHERE k=? AND c IN (?, ?);\n" + "COMMIT TRANSACTION";
        SimpleQueryResult result = cluster.coordinator(1).executeWithResult(cql, ConsistencyLevel.ANY, 0, 0, 1);
        assertThat(result).isEqualTo(QueryResults.builder().columns("k", "c", "v").row(0, 0, 0).row(0, 1, 1).build());
        // Results should be in Partiton/Clustering order, so make sure
        // multi partition
        cql = "BEGIN TRANSACTION\n" + "  SELECT * FROM " + qualifiedAccordTableName + " WHERE k IN (?, ?) AND c = ?;\n" + "COMMIT TRANSACTION";
        for (boolean asc : Arrays.asList(true, false)) {
            Object[] binds = asc ? row(0, 1, 0) : row(1, 0, 0);
            result = cluster.coordinator(1).executeWithResult(cql, ConsistencyLevel.ANY, binds);
            assertThat(result).isEqualTo(QueryResults.builder().columns("k", "c", "v").row(0, 0, 0).row(1, 0, 1).build());
        }
        // multi-partition, multi-clustering
        cql = "BEGIN TRANSACTION\n" + "  SELECT * FROM " + qualifiedAccordTableName + " WHERE k IN (?, ?) AND c IN (?, ?);\n" + "COMMIT TRANSACTION";
        for (boolean asc : Arrays.asList(true, false)) {
            Object[] binds = asc ? row(0, 1, 0, 1) : row(1, 0, 1, 0);
            result = cluster.coordinator(1).executeWithResult(cql, ConsistencyLevel.ANY, binds);
            assertThat(result).isEqualTo(QueryResults.builder().columns("k", "c", "v").row(0, 0, 0).row(0, 1, 1).row(1, 0, 1).row(1, 1, 2).build());
        }
    });
}

@Test
public void testMultipleShards() throws Exception {
    String keyspace = "multipleShards";
    String currentTable = keyspace + ".tbl";
    List<String> ddls = Arrays.asList("DROP KEYSPACE IF EXISTS " + keyspace + ";", "CREATE KEYSPACE " + keyspace + " WITH REPLICATION={'class':'SimpleStrategy', 'replication_factor': 1}", "CREATE TABLE " + currentTable + " (k blob, c int, v int, primary key (k, c)) WITH transactional_mode='" + transactionalMode + "'");
    List<String> tokens = tokens();
    List<ByteBuffer> keys = tokensToKeys(tokens);
    List<String> keyStrings = keys.stream().map(bb -> "0x" + ByteBufferUtil.bytesToHex(bb)).collect(Collectors.toList());
    StringBuilder query = new StringBuilder("BEGIN TRANSACTION\n");
    for (int i = 0; i < keys.size(); i++) query.append("  LET row" + i + " = (SELECT * FROM " + currentTable + " WHERE k=" + keyStrings.get(i) + " AND c=0);\n");
    query.append("  SELECT row0.v;\n").append("  IF ");
    for (int i = 0; i < keyStrings.size(); i++) query.append((i > 0 ? " AND row" : "row") + i + " IS NULL");
    query.append(" THEN\n");
    for (int i = 0; i < keyStrings.size(); i++) query.append("    INSERT INTO " + currentTable + " (k, c, v) VALUES (" + keyStrings.get(i) + ", 0, " + i + ");\n");
    query.append("  END IF\n");
    query.append("COMMIT TRANSACTION");
    test(ddls, cluster -> {
        // row0.v shouldn't have existed when the txn's SELECT was executed
        assertRowEqualsWithPreemptedRetry(cluster, new Object[] { null }, query.toString());
        cluster.get(1).runOnInstance(() -> {
            StringBuilder sb = new StringBuilder("BEGIN TRANSACTION\n");
            for (int i = 0; i < keyStrings.size() - 1; i++) sb.append(format("LET row%d = (SELECT * FROM %s WHERE k=%s AND c=0);\n", i, currentTable, keyStrings.get(i)));
            sb.append(format("SELECT * FROM %s WHERE k=%s AND c=0;\n", currentTable, keyStrings.get(keyStrings.size() - 1)));
            sb.append("COMMIT TRANSACTION");
            Unseekables<?> routables = AccordTestUtils.createTxn(sb.toString()).keys().toParticipants();
            long epoch = AccordService.instance().topology().epoch();
            Topologies topology = AccordService.instance().topology().withUnsyncedEpochs(routables, epoch, epoch);
            // we don't detect out-of-bounds read/write yet, so use this to validate we reach different shards
            Assertions.assertThat(topology.totalShards()).isEqualTo(2);
        });
        String check = "BEGIN TRANSACTION\n" + "  SELECT * FROM " + currentTable + " WHERE k = ? AND c = ?;\n" + "COMMIT TRANSACTION";
        for (int i = 0; i < keys.size(); i++) assertRowEqualsWithPreemptedRetry(cluster, new Object[] { keys.get(i), 0, i }, check, keys.get(i), 0);
    });
}

