@Test
public void testTupleSubstitution() throws Exception {
    test("CREATE TABLE " + qualifiedAccordTableName + " (k int PRIMARY KEY, pair tuple<text, int>) WITH transactional_mode='" + transactionalMode + "'", cluster -> {
        Object initialTupleValue = CQLTester.tuple("age", 37);
        ByteBuffer initialTupleBuffer = CQLTester.makeByteBuffer(initialTupleValue, null);
        cluster.coordinator(1).execute("INSERT INTO " + qualifiedAccordTableName + " (k, pair) VALUES (0, ?);", ConsistencyLevel.ALL, initialTupleBuffer);
        String insert = "BEGIN TRANSACTION\n" + "  LET row1 = (SELECT * FROM " + qualifiedAccordTableName + " WHERE k = ?);\n" + "  SELECT row1.pair;\n" + "  IF row1.pair IS NOT NULL THEN\n" + "    INSERT INTO " + qualifiedAccordTableName + " (k, pair) VALUES (?, row1.pair);\n" + "  END IF\n" + "COMMIT TRANSACTION";
        assertRowEqualsWithPreemptedRetry(cluster, new Object[] { initialTupleBuffer }, insert, 0, 1);
        String check = "BEGIN TRANSACTION\n" + "  SELECT * FROM " + qualifiedAccordTableName + " WHERE k = ?;\n" + "COMMIT TRANSACTION";
        assertRowEqualsWithPreemptedRetry(cluster, new Object[] { 1, initialTupleBuffer }, check, 1);
    });
}

