public void testMultiKeyQueryAndInsert() throws Throwable {
    test("CREATE TABLE " + qualifiedAccordTableName + " (k int, c int, v int, primary key (k, c)) WITH transactional_mode='" + transactionalMode + "'", cluster -> {
        String query1 = "BEGIN TRANSACTION
" + "  LET select1 = (SELECT * FROM " + qualifiedAccordTableName + " WHERE k=0 AND c=0);
" + "  LET select2 = (SELECT * FROM " + qualifiedAccordTableName + " WHERE k=1 AND c=0);
" + "  SELECT v FROM " + qualifiedAccordTableName + " WHERE k=0 AND c=0;
" + "  IF select1 IS NULL THEN
" + "    INSERT INTO " + qualifiedAccordTableName + " (k, c, v) VALUES (0, 0, 0);
" + "    INSERT INTO " + qualifiedAccordTableName + " (k, c, v) VALUES (1, 0, 0);
" + "  END IF
" + "COMMIT TRANSACTION";
        assertEmptyWithPreemptedRetry(cluster, query1);
        String check = "BEGIN TRANSACTION
" + "  SELECT * FROM " + qualifiedAccordTableName + " WHERE k = ? AND c = ?;
" + "COMMIT TRANSACTION";
        assertRowEqualsWithPreemptedRetry(cluster, new Object[] { 0, 0, 0 }, check, 0, 0);
        assertRowEqualsWithPreemptedRetry(cluster, new Object[] { 1, 0, 0 }, check, 1, 0);
        String query2 = "BEGIN TRANSACTION
" + "  LET select1 = (SELECT * FROM " + qualifiedAccordTableName + " WHERE k=1 AND c=0);
" + "  LET select2 = (SELECT * FROM " + qualifiedAccordTableName + " WHERE k=2 AND c=0);
" + "  SELECT v FROM " + qualifiedAccordTableName + " WHERE k=1 AND c=0;
" + "  IF select1.v = ? THEN
" + "    INSERT INTO " + qualifiedAccordTableName + " (k, c, v) VALUES (1, 0, 1);
" + "    INSERT INTO " + qualifiedAccordTableName + " (k, c, v) VALUES (2, 0, 1);
" + "  END IF
" + "COMMIT TRANSACTION";
        assertRowEqualsWithPreemptedRetry(cluster, new Object[] { 0 }, query2, 0);
        assertRowEqualsWithPreemptedRetry(cluster, new Object[] { 0, 0, 0 }, check, 0, 0);
        assertRowEqualsWithPreemptedRetry(cluster, new Object[] { 1, 0, 1 }, check, 1, 0);
        assertRowEqualsWithPreemptedRetry(cluster, new Object[] { 2, 0, 1 }, check, 2, 0);
    });
}

