    Symbol v1 = new Symbol("v1", Int32Type.instance);
    Symbol row = Symbol.unknownType("row");
    test("CREATE TABLE " + qualifiedAccordTableName + "(k int, c int, v0 set<int>, v1 int, primary key(k, c)) WITH transactional_mode='" + transactionalMode + "'", cluster -> {
