        Statement stmt = Txn.builder().addLet("row", Select.builder().table(KEYSPACE, accordTableName).value("k", 0).value("c", 0).build()).addUpdate(Mutation.update(KEYSPACE, accordTableName).set(v0, new Literal(Collections.singleton(1), v0.type())).set(v1, new AssignmentOperator(AssignmentOperator.Kind.ADD, Reference.of(row, v1))).value("k", 0).value("c", 0).build()).build();
        coordinator.execute(stmt.toCQL(), QUORUM, stmt.bindsEncoded());
        // is the data correct?
