@Test
public void usingTimestamp() throws Exception {
    // This test was discovered by org.apache.cassandra.distributed.test.cql3.MixedReadsAccordInteropMultiNodeTableWalkTest
    // It could be simplified but was boiled down to the minimum steps to reproduce the timestamp issue: USING TIMESTAMP
    // was not respected operations that happen post read
    test("CREATE TABLE " + qualifiedAccordTableName + " (\n" + "\t\t    pk0 float,\n" + "\t\t    pk1 varint,\n" + "\t\t    ck0 smallint,\n" + "\t\t    ck1 tinyint,\n" + "\t\t    v3 uuid,\n" + "\t\t    v1 list<uuid>,\n" + "\t\t    v4 map<vector<uuid, 1>, frozen<map<smallint, text>>>,\n" + "\t\t    PRIMARY KEY ((pk0, pk1), ck0, ck1)\n" + "\t\t) WITH CLUSTERING ORDER BY (ck0 DESC, ck1 ASC)\n" + "\t\t    AND " + transactionalMode.asCqlParam(), cluster -> {
        ICoordinator node = cluster.coordinator(2);
        node.execute("UPDATE " + qualifiedAccordTableName + " USING TIMESTAMP 6 " + "SET " + "    v1=[00000000-0000-4e00-8c00-000000000000], " + "    v4={[00000000-0000-4800-b300-000000000000]: {-30955: 'ϵ', -10479: '虑퐕㐧', 7904: '䁋'}}, " + "    v3=00000000-0000-4600-b300-000000000000 " + "WHERE  pk0 = -1.1763917E35 AND  pk1 = -466454 " + "       AND  ck0 IN (-26786, 10038, 4991) AND  ck1 IN (124 - 36, -100)", ConsistencyLevel.QUORUM);
