@Test
public void testRecovery() throws Exception {
    pauseSimpleProgressLog();
    test(cluster -> {
        IMessageFilters.Filter lostApply = cluster.filters().verbs(Verb.ACCORD_APPLY_REQ.id).drop();
        IMessageFilters.Filter lostCommit = cluster.filters().verbs(Verb.ACCORD_COMMIT_REQ.id).to(2).drop();
        String query = "BEGIN TRANSACTION
" + "  LET row1 = (SELECT v FROM " + qualifiedAccordTableName + " WHERE k=0 AND c=0);
" + "  SELECT row1.v;
" + "  IF row1 IS NULL THEN
" + "    INSERT INTO " + qualifiedAccordTableName + " (k, c, v) VALUES (0, 0, 1);
" + "  END IF
" + "COMMIT TRANSACTION";
        // row1.v shouldn't have existed when the txn's SELECT was executed
        assertRowEqualsWithPreemptedRetry(cluster, new Object[] { null }, query);
        lostApply.off();
        lostCommit.off();
        query = "BEGIN TRANSACTION
" + "  LET row1 = (SELECT v FROM " + qualifiedAccordTableName + " WHERE k=0 AND c=0);
" + "  SELECT row1.v;
" + "  IF row1.v = 1 THEN
" + "    UPDATE " + qualifiedAccordTableName + " SET v=2 WHERE k = 0 AND c = 0;
" + "  END IF
" + "COMMIT TRANSACTION";
        assertRowEqualsWithPreemptedRetry(cluster, new Object[] { 1 }, query);
        String check = "BEGIN TRANSACTION
" + "  SELECT * FROM " + qualifiedAccordTableName + " WHERE k = ? AND c = ?;
" + "COMMIT TRANSACTION";
        assertRowEqualsWithPreemptedRetry(cluster, new Object[] { 0, 0, 2 }, check, 0, 0);
        query = "BEGIN TRANSACTION
" + "  LET row1 = (SELECT v FROM " + qualifiedAccordTableName + " WHERE k=0 AND c=0);
" + "  SELECT row1.v;
" + "  IF row1 IS NULL THEN
" + "    INSERT INTO " + qualifiedAccordTableName + " (k, c, v) VALUES (0, 0, 3);
" + "  END IF
" + "COMMIT TRANSACTION";
        assertRowEqualsWithPreemptedRetry(cluster, new Object[] { 2 }, query);
        assertRowEqualsWithPreemptedRetry(cluster, new Object[] { 0, 0, 2 }, check, 0, 0);
    });
}

