@Test
public void saveLoadSanityCheck() throws Throwable {
    try (WithProperties wp = new WithProperties().set(CassandraRelevantProperties.DTEST_ACCORD_JOURNAL_SANITY_CHECK_ENABLED, "true");
        Cluster cluster = init(Cluster.build(1).withoutVNodes().start())) {
        final String TABLE = createTable(cluster);
        List<Thread> threads = new ArrayList<>();
        int numThreads = 10;
        CountDownLatch latch = CountDownLatch.newCountDownLatch(numThreads);
        AtomicInteger counter = new AtomicInteger();
        for (int i = 0; i < numThreads; i++) {
            int finalI = i;
            Thread t = new Thread(() -> {
                latch.decrement();
                latch.awaitUninterruptibly();
                try {
                    for (int j = 0; j < 100; j++) {
                        cluster.coordinator(1).execute("BEGIN TRANSACTION\n" + "INSERT INTO " + TABLE + "(k, c, v) VALUES (?, ?, ?);\n" + "INSERT INTO " + TABLE + "(k, c, v) VALUES (?, ?, ?);\n" + "COMMIT TRANSACTION", ConsistencyLevel.ALL, 1, j, finalI * 100 + j, 2, j, finalI * 100 + j);
                        counter.incrementAndGet();
                    }
                } catch (Throwable throwable) {
                    throwable.printStackTrace();
                }
            });
            t.start();
            threads.add(t);
        }
        for (Thread thread : threads) thread.join();
        cluster.coordinator(1).execute("SELECT * FROM " + TABLE + " WHERE k = ?;", ConsistencyLevel.SERIAL, 1);
    }
}

