        final RateLimiter rateLimiter = RateLimiter.create(ratePerSecond);
        while (true) {
            final EstimatedHistogram histogram = new EstimatedHistogram(200);
            long batchStart = System.nanoTime();
            long batchEnd = batchStart + batchTime;
            int batchSize = 0;
