                        try {
                            int index = 1 + random.nextInt(cluster.size());
                            logger.info("Picking new coordinator ... {}", index);
                            coordinator = cluster.coordinator(index);
                            if (cluster.get(index).callOnInstance(() -> AccordService.started()))
                                break;
                        } catch (Throwable t) {
                            logger.info("Failed to select coordinator", t);
                        }
                    }
                }
                batchSize++;
                if (System.nanoTime() >= batchEnd)
                    break;
            }
            if ((nextRepairAt -= batchSize) <= 0) {
                nextRepairAt += repairInterval;
                System.out.println("repairing...");
                cluster.coordinator(1).instance().nodetool("repair", qualifiedAccordTableName);
            }
            if ((nextCompactionAt -= batchSize) <= 0) {
                nextCompactionAt += compactionInterval;
                System.out.println("compacting accord...");
                cluster.forEach(i -> {
                    try {
                        i.nodetool("compact", "system_accord.journal");
                    } catch (Throwable t) {
                        logger.error("", t);
                    }
                });
            }
            if ((nextJournalFlushAt -= batchSize) <= 0) {
                nextJournalFlushAt += journalFlushInterval;
                System.out.println("flushing journal...");
                cluster.forEach(i -> {
                    try {
                        i.runOnInstance(() -> {
                            if (AccordService.started())
                                ((AccordService) AccordService.instance()).journal().closeCurrentSegmentForTestingIfNonEmpty();
                        });
                    } catch (Throwable t) {
                        logger.error("", t);
                    }
                });
            }
            if ((nextDataFlushAt -= batchSize) <= 0) {
                nextDataFlushAt += dataFlushInterval;
                System.out.println("flushing data...");
                cluster.forEach(i -> {
                    try {
                        i.acceptOnInstance(name -> {
                            Schema.instance.getColumnFamilyStoreInstance(Schema.instance.getTableMetadata(KEYSPACE, name).id).forceFlush(UNIT_TESTS);
                        }, accordTableName);
                    } catch (Throwable t) {
                        logger.error("", t);
                    }
                });
            }
            if ((nextCfkFlushAt -= batchSize) <= 0) {
                nextCfkFlushAt += cfkFlushInterval;
                System.out.println("flushing data...");
                cluster.forEach(i -> {
                    try {
                        i.acceptOnInstance(name -> {
                            if (CommitLog.instance.isStarted())
                                AccordKeyspace.AccordColumnFamilyStores.commandsForKey.forceFlush(UNIT_TESTS);
                        }, accordTableName);
                    } catch (Throwable t) {
                        logger.error("", t);
                    }
                });
            }
            if ((nextRestartAt -= batchSize) <= 0) {
                nextRestartAt += restartInterval;
                restartInterval = Math.max(restartInterval, restartInterval * restartDecay);
                int nodeIdx = 1 + random.nextInt(cluster.size());
                restartExecutor.submit(() -> {
                    System.out.printf("restarting node %d...\n", nodeIdx);
                    try {
                        cluster.get(nodeIdx).shutdown().get();
                        cluster.get(nodeIdx).startup();
                        while (!cluster.get(nodeIdx).callOnInstance(() -> AccordService.started())) Thread.sleep(1000);
                        return null;
                    } catch (InterruptedException | ExecutionException e) {
                        throw new RuntimeException(e);
                    }
                });
            }
            final Date date = new Date();
            System.out.printf("%tT rate: %.2f/s (%d total)\n", date, (((float) batchSizeLimit * 1000) / NANOSECONDS.toMillis(System.nanoTime() - batchStart)), batchSize);
            System.out.printf("%tT percentiles: %d %d %d %d\n", date, histogram.percentile(.25) / 1000, histogram.percentile(.5) / 1000, histogram.percentile(.75) / 1000, histogram.percentile(1) / 1000);
            class VerbCount {

                final Verb verb;

                final int count;

                VerbCount(Verb verb, int count) {
                    this.verb = verb;
                    this.count = count;
                }
            }
            List<VerbCount> verbCounts = new ArrayList<>();
            for (Map.Entry<Verb, AtomicInteger> e : verbs.entrySet()) {
                int count = e.getValue().getAndSet(0);
                if (count != 0)
                    verbCounts.add(new VerbCount(e.getKey(), count));
            }
            verbCounts.sort(Comparator.comparing(v -> -v.count));
            StringBuilder verbSummary = new StringBuilder();
            for (VerbCount vs : verbCounts) {
                {
                    if (verbSummary.length() > 0)
                        verbSummary.append(", ");
                    verbSummary.append(vs.verb);
                    verbSummary.append(": ");
                    verbSummary.append(vs.count);
                }
            }
            System.out.printf("%tT verbs: %s\n", date, verbSummary);
        }
    } catch (Throwable t) {
        t.printStackTrace();
        System.exit(1);
    }
}

