@Test
public void test() throws IOException {
    try (Cluster cluster = Cluster.build(1).start()) {
        init(cluster);
        String createTable = withKeyspace("CREATE TABLE %s.tbl (pk blob primary key)");
        if (mode != null)
            createTable += " WITH " + mode.asCqlParam();
        cluster.schemaChange(createTable);
        ICoordinator node = cluster.coordinator(1);
        NavigableSet<Long> tokens = tokens();
        for (long token : tokens) node.executeWithResult(withKeyspace("INSERT INTO %s.tbl (pk) VALUES (?)"), QUORUM, keyForToken(token));
        for (long token : tokens) {
            ByteBuffer pk = keyForToken(token);
            for (TokenOperator op : TokenOperator.values()) {
                Assertions.assertThat(tokens(node.executeWithResult(withKeyspace("SELECT * FROM %s.tbl WHERE " + op.condition), QUORUM, pk))).describedAs("Token %d with operator %s", token, op.condition).isEqualTo(op.expected(token, tokens));
                Assertions.assertThat(tokens(node.executeWithPagingWithResult(withKeyspace("SELECT * FROM %s.tbl WHERE " + op.condition), QUORUM, 1, pk))).describedAs("Token %d with operator %s", token, op.condition).isEqualTo(op.expected(token, tokens));
            }
            for (TokenOperator lt : Arrays.asList(TokenOperator.lt, TokenOperator.lte)) {
                for (TokenOperator gt : Arrays.asList(TokenOperator.gt, TokenOperator.gte)) {
                    Assertions.assertThat(tokens(node.executeWithResult(withKeyspace("SELECT * FROM %s.tbl WHERE " + lt.condition + " AND " + gt.condition), QUORUM, pk, pk))).describedAs("Token %d with operators %s / %s", token, lt.condition, gt.condition).isEqualTo(Sets.intersection(lt.expected(token, tokens), gt.expected(token, tokens)));
                }
            }
            Assertions.assertThat(tokens(node.executeWithResult(withKeyspace("SELECT * FROM %s.tbl WHERE token(pk) BETWEEN token(?) AND token(?)"), QUORUM, pk, pk))).describedAs("Token %d with operator token(pk) BETWEEN token(?) AND token(?)", token).isEqualTo(TokenOperator.eq.expected(token, tokens));
        }
    }
}

