 */
@Test
public void testAutoSnapshotTTlOnDropAfterRestart() throws IOException {
    // longer TTL to allow snapshot to survive node restart
    int ONE_MINUTE = 60;
    try (Cluster cluster = init(build().withNodes(1).withConfig(c -> c.with(Feature.GOSSIP).set("auto_snapshot_ttl", String.format("%ds", ONE_MINUTE))).start())) {
