@Test
public void testNoSpaceLeft() throws IOException {
    try (Cluster cluster = init(Cluster.build(1).withConfig(config -> config.set("min_free_space_per_drive_in_mb", "0")).withDataDirCount(3).withInstanceInitializer(BB::install).start())) {
        cluster.schemaChange("create table " + KEYSPACE + ".tbl (id int primary key, x int) with compaction = {'class':'SizeTieredCompactionStrategy'}");
        cluster.coordinator(1).execute("insert into " + KEYSPACE + ".tbl (id, x) values (1,1)", ConsistencyLevel.ALL);
        cluster.get(1).flush(KEYSPACE);
        cluster.setUncaughtExceptionsFilter((t) -> t.getMessage() != null && t.getMessage().contains("Not enough space for compaction") && (t.getMessage().contains(KEYSPACE + ".tbl") || t.getMessage().contains("system_")));
        cluster.get(1).runOnInstance(() -> {
            ColumnFamilyStore cfs = Keyspace.open(KEYSPACE).getColumnFamilyStore("tbl");
            BB.estimatedRemaining.set(2000);
            BB.freeSpace.set(2000);
            BB.sstableDir = cfs.getLiveSSTables().iterator().next().descriptor.directory;
            try {
                cfs.forceMajorCompaction();
                fail("This should fail, we have 2000b free space, 2000b estimated remaining compactions and the new compaction > 0");
            } catch (Exception e) {
                // ignored
            }
            // and available space again:
            BB.estimatedRemaining.set(1000);
            cfs.forceMajorCompaction();
            BB.estimatedRemaining.set(2000);
            BB.freeSpace.set(10000);
            cfs.forceMajorCompaction();
            // make sure we fail if other dir on the same file store runs out of disk
            BB.freeSpace.set(0);
            for (Directories.DataDirectory newDir : cfs.getDirectories().getWriteableLocations()) {
                File newSSTableDir = cfs.getDirectories().getLocationForDisk(newDir);
                if (!BB.sstableDir.equals(newSSTableDir)) {
                    BB.sstableDir = cfs.getDirectories().getLocationForDisk(newDir);
                    break;
                }
            }
            try {
                cfs.forceMajorCompaction();
                fail("this should fail, data dirs share filestore");
            } catch (Exception e) {
                //ignored
            }
        });
    }
}

@Test
public void partialCompactionOverlappingTest() throws IOException, TimeoutException {
    try (Cluster cluster = init(builder().withNodes(1).withDataDirCount(1).withInstanceInitializer(BB::install).start())) {
        cluster.schemaChange(withKeyspace("alter keyspace %s with replication = {'class': 'SimpleStrategy', 'replication_factor':3}"));
        cluster.schemaChange(withKeyspace("create table %s.tbl (id int primary key) with compaction = {'class':'SizeTieredCompactionStrategy', 'enabled': 'false'} AND gc_grace_seconds=0"));
        Set<Integer> expected = Sets.newHashSetWithExpectedSize(990);
        for (int i = 0; i < 1000; i++) {
            cluster.coordinator(1).execute(withKeyspace("insert into %s.tbl (id) values (?)"), ConsistencyLevel.ONE, i);
            if (i >= 10)
                expected.add(i);
        }
        cluster.get(1).flush(KEYSPACE);
        for (int i = 0; i < 10; i++) {
            cluster.coordinator(1).execute(withKeyspace("delete from %s.tbl where id = ?"), ConsistencyLevel.ONE, i);
            cluster.get(1).flush(KEYSPACE);
        }
        assertEquals(expected, Arrays.stream(cluster.coordinator(1).execute(withKeyspace("select * from %s.tbl"), ConsistencyLevel.ONE)).map(x -> x[0]).collect(Collectors.toSet()));
        // make sure tombstones are gc:able
        Uninterruptibles.sleepUninterruptibly(2, TimeUnit.SECONDS);
        cluster.get(1).runOnInstance(() -> {
            BB.enabled.set(true);
            ColumnFamilyStore cfs = Keyspace.open(KEYSPACE).getColumnFamilyStore("tbl");
            cfs.forceMajorCompaction();
            assertEquals("We should have 2 sstables (not 1) after major compaction since we reduced the scope of the compaction", 2, Iterables.size(cfs.getSSTables(SSTableSet.CANONICAL)));
        });
        assertEquals(expected, Arrays.stream(cluster.coordinator(1).execute(withKeyspace("select * from %s.tbl"), ConsistencyLevel.ONE)).map(x -> x[0]).collect(Collectors.toSet()));
    }
}

