@Test
public void testFinishInProgressQueries() throws Throwable {
    ExecutorService executor = Executors.newFixedThreadPool(REQUESTS);
    try (Cluster control = init(Cluster.build().withNodes(1).withInstanceInitializer(BlockingSelect::install).withConfig(config -> config.with(GOSSIP, NETWORK, NATIVE_PROTOCOL)).start());
        com.datastax.driver.core.Cluster cluster = driver(control);
