@Test
public void test() throws Throwable {
    try (final Cluster cluster = init(builder().withNodes(1).withConfig(updater -> updater.with(NETWORK, GOSSIP, NATIVE_PROTOCOL)).start())) {
        final IInvokableInstance node = cluster.get(1);
        // using driver path is important because dtest API and query execution does not invoke code
        // in Cassandra where events are propagated to logger
        try (com.datastax.driver.core.Cluster c = com.datastax.driver.core.Cluster.builder().addContactPoint("127.0.0.1").build();
            Session s = c.connect()) {
            s.execute("CREATE KEYSPACE fql_ks WITH replication = {'class': 'SimpleStrategy', 'replication_factor': 1};");
            node.nodetool("enablefullquerylog", "--path", temporaryFolder.getRoot().getAbsolutePath());
            s.execute("CREATE TABLE fql_ks.fql_table (id int primary key);");
            s.execute("INSERT INTO fql_ks.fql_table (id) VALUES (1)");
            node.nodetool("disablefullquerylog");
            // here we are dropping and we expect that ddl replay will reconstruct it
            node.executeInternal("DROP TABLE fql_ks.fql_table;");
            // without --replay-ddl-statements, the replay will fail on insert because underlying table is not there
            final ToolResult negativeRunner = ToolRunner.invokeClass("org.apache.cassandra.fqltool.FullQueryLogTool", "replay", "--keyspace", "fql_ks", "--target", "127.0.0.1", "--", temporaryFolder.getRoot().getAbsolutePath());
            assertEquals(0, negativeRunner.getExitCode());
            try {
                node.executeInternalWithResult("SELECT * from fql_ks.fql_table");
                fail("This query should fail because we do not expect fql_ks.fql_table to be created!");
            } catch (final Exception ex) {
                assertTrue(ex.getMessage().contains("table fql_table does not exist"));
            }
            // here we replay with --replay-ddl-statements so table will be created and insert will succeed
            final ToolResult positiveRunner = ToolRunner.invokeClass("org.apache.cassandra.fqltool.FullQueryLogTool", "replay", "--keyspace", "fql_ks", "--target", "127.0.0.1", // important
            "--replay-ddl-statements", "--", temporaryFolder.getRoot().getAbsolutePath());
            assertEquals(0, positiveRunner.getExitCode());
            assertRows(node.executeInternalWithResult("SELECT * from fql_ks.fql_table"), QueryResults.builder().row(1).build());
        }
    }
}

@Test
public void testNullCellBindingInBatch() {
    String tableName = "null_as_tombstone_in_batch";
    CLUSTER.schemaChange(withKeyspace("CREATE TABLE %s." + tableName + " (k int, c int, s set<int>, primary key (k, c))"));
    CLUSTER.get(1).nodetool("enablefullquerylog", "--path", temporaryFolder.getRoot().getAbsolutePath());
    String insertTemplate = withKeyspace("INSERT INTO %s." + tableName + " (k, c, s) VALUES ( ?, ?, ?) USING TIMESTAMP 2");
    String select = withKeyspace("SELECT * FROM %s." + tableName + " WHERE k = 0 AND c = 0");
    com.datastax.driver.core.Cluster.Builder builder1 = com.datastax.driver.core.Cluster.builder().addContactPoint("127.0.0.1");
    // Use the driver to write this initial row, since otherwise we won't hit the dispatcher
    try (com.datastax.driver.core.Cluster cluster1 = builder1.build();
        Session session1 = cluster1.connect()) {
        BatchStatement batch = new BatchStatement(BatchStatement.Type.UNLOGGED);
        PreparedStatement preparedWrite = session1.prepare(insertTemplate);
        batch.add(preparedWrite.bind(0, 0, null));
        session1.execute(batch);
    }
    CLUSTER.get(1).nodetool("disablefullquerylog");
    // The dump should contain a null entry for our tombstone
    ToolRunner.ToolResult runner = ToolRunner.invokeClass("org.apache.cassandra.fqltool.FullQueryLogTool", "dump", "--", temporaryFolder.getRoot().getAbsolutePath());
    assertTrue(runner.getStdout().contains(insertTemplate));
    assertEquals(0, runner.getExitCode());
    Object[][] preReplayResult = CLUSTER.get(1).executeInternal(select);
    assertRows(preReplayResult, row(0, 0, null));
    // Make sure the row no longer exists after truncate...
    CLUSTER.get(1).executeInternal(withKeyspace("TRUNCATE %s." + tableName));
    assertRows(CLUSTER.get(1).executeInternal(select));
    // ...insert a new row with an actual value for the set at an earlier timestamp...
    CLUSTER.get(1).executeInternal(withKeyspace("INSERT INTO %s." + tableName + " (k, c, s) VALUES ( ?, ?, ?) USING TIMESTAMP 1"), 0, 0, Sets.newHashSet(1));
    assertRows(CLUSTER.get(1).executeInternal(select), row(0, 0, Sets.newHashSet(1)));
    runner = ToolRunner.invokeClass("org.apache.cassandra.fqltool.FullQueryLogTool", "replay", "--keyspace", KEYSPACE, "--target", "127.0.0.1", "--", temporaryFolder.getRoot().getAbsolutePath());
    assertEquals(0, runner.getExitCode());
    // ...then ensure the replayed row deletes the one we wrote before replay.
    Object[][] postReplayResult = CLUSTER.get(1).executeInternal(select);
    assertRows(postReplayResult, preReplayResult);
}

