@Test
public void testHintedHandoffDisabled() throws IOException {
    try (Cluster cluster = init(Cluster.build(2).withDataDirCount(1).withConfig(config -> config.with(NETWORK, GOSSIP).set("write_request_timeout", "1000ms").set("hinted_handoff_enabled", false)).start(), 2)) {
        String createTableStatement = String.format("CREATE TABLE %s.cf (k text PRIMARY KEY, c1 text) " + "WITH compaction = {'class': 'SizeTieredCompactionStrategy', 'enabled': 'false'} ", KEYSPACE);
        cluster.schemaChange(createTableStatement);
        CountDownLatch dropped = CountDownLatch.newCountDownLatch(1);
        // Drop all messages from node1 to node2 so hints should be created
        IMessageFilters.Filter drop1to2 = cluster.filters().verbs(MUTATION_REQ.id).messagesMatching((from, to, m) -> {
            if (from != 1 || to != 2)
                return false;
            dropped.decrement();
            return true;
        }).drop();
        cluster.coordinator(1).execute(withKeyspace("INSERT INTO %s.cf (k, c1) VALUES (?, ?) USING TIMESTAMP 1;"), ConsistencyLevel.ONE, String.valueOf(1), String.valueOf(1));
        // make sure the write response handler has completed after a chance to hint
        assertTrue(dropped.awaitUninterruptibly(1, TimeUnit.MINUTES));
        cluster.get(1).runOnInstance(() -> {
            Awaitility.waitAtMost(1, TimeUnit.MINUTES).until(() -> Stage.INTERNAL_RESPONSE.executor().getPendingTaskCount() == 0);
        });
        // Check that no hints were created on node1
        assertThat(cluster.get(1).callOnInstance(() -> Long.valueOf(StorageMetrics.totalHints.getCount()))).isEqualTo(0L);
    }
}

@Test
public void testMaxHintedHandoffSize() throws Exception {
    try (Cluster cluster = init(Cluster.build(2).withDataDirCount(1).withConfig(config -> config.with(NETWORK, GOSSIP).set("hinted_handoff_enabled", true).set("max_hints_delivery_threads", "1").set("hints_flush_period", "1s").set("max_hints_size_per_host", "2MiB").set("max_hints_file_size", "1MiB")).start(), 2)) {
        final IInvokableInstance node1 = cluster.get(1);
        final IInvokableInstance node2 = cluster.get(2);
        waitForExistingRoles(cluster);
        String createTableStatement = format("CREATE TABLE %s.cf (k text PRIMARY KEY, c1 text) " + "WITH compaction = {'class': 'SizeTieredCompactionStrategy', 'enabled': 'false'} ", KEYSPACE);
        cluster.schemaChange(createTableStatement);
        UUID node2UUID = node2.callOnInstance((IIsolatedExecutor.SerializableCallable<UUID>) () -> StorageService.instance.getLocalHostUUID());
        // shutdown the second node in a blocking manner
        node2.shutdown().get();
        // insert data and sleep every 10k to have a chance to flush hints
        for (int i = 0; i < 70000; i++) {
            cluster.coordinator(1).execute(withKeyspace("INSERT INTO %s.cf (k, c1) VALUES (?, ?);"), ONE, valueOf(i), UUID.randomUUID().toString());
            if (i % 10000 == 0)
                await().atLeast(2, SECONDS).pollDelay(2, SECONDS).until(() -> true);
        }
        await().atLeast(3, SECONDS).pollDelay(3, SECONDS).until(() -> true);
        // we see that metrics are updated
        await().until(() -> node1.callOnInstance(() -> StorageMetrics.totalHints.getCount()) > 0);
        // we do not have 100k of hints because it violated max_hints_size_per_host
        assertThat(node1.callOnInstance(() -> StorageMetrics.totalHints.getCount())).isLessThan(70000);
        assertHintsSizes(node1, node2UUID);
        // restart the first node and check hints sizes again
        // to be sure sizes were picked up correctly
        node1.shutdown().get();
        node1.startup();
        assertHintsSizes(node1, node2UUID);
    }
}

@Test
public void testHintsKeepRecordingAfterNodeGoesOfflineRepeatedly() throws Exception {
    try (Cluster cluster = init(Cluster.build(2).withDataDirCount(1).withConfig(config -> config.with(NETWORK, GOSSIP).set("hinted_handoff_enabled", true).set("max_hints_delivery_threads", "1").set("hints_flush_period", "1s").set("max_hint_window", "30s").set("max_hints_file_size", "1MiB")).start(), 2)) {
        final IInvokableInstance node1 = cluster.get(1);
        final IInvokableInstance node2 = cluster.get(2);
        waitForExistingRoles(cluster);
        String createTableStatement = format("CREATE TABLE %s.cf (k text PRIMARY KEY, c1 text) " + "WITH compaction = {'class': 'SizeTieredCompactionStrategy', 'enabled': 'false'} ", KEYSPACE);
        cluster.schemaChange(createTableStatement);
        UUID node2UUID = node2.callOnInstance((IIsolatedExecutor.SerializableCallable<UUID>) () -> StorageService.instance.getLocalHostUUID());
        // shutdown the second node in a blocking manner
        node2.shutdown().get();
        waitUntilNodeState(node1, node2UUID, false);
        Long totalHintsAfterFirstShutdown = insertData(cluster);
        // check hints are there etc
        assertHintsSizes(node1, node2UUID);
        // start the second node, this will deliver hints to it from the first
        node2.startup();
        waitUntilNodeState(node1, node2UUID, true);
        waitUntilNoHints(node1, node2UUID);
        assertEquals(totalHintsAfterFirstShutdown, getTotalHintsCount(node1));
        // all hints were delivered, so lets take that node down again to see if hints
        // delivery works after node goes down for the second time
        node2.shutdown().get();
        waitUntilNodeState(node1, node2UUID, false);
        // insert again, this will increase the number of total hints sent
        Long totalHintsAfterSecondShutdown = insertData(cluster);
        assertHintsSizes(node1, node2UUID);
        // the fact it is greater than 0 means that we created new hints again
        // after we stopped the second node for the second time
        assertTrue(totalHintsAfterSecondShutdown - totalHintsAfterFirstShutdown > 0);
        // wait to pass max_hint_window
        Thread.sleep(35000);
        // we should not hint anything because the node was down more than max_hint_window
        Long totalHintsAfterThirdShutdown = insertData(cluster);
        // so we have not created any hints because we have passed max_hint_window
        assertEquals(0, totalHintsAfterThirdShutdown - totalHintsAfterSecondShutdown);
    }
}

@Test
public void testPersistentHintWindow() throws Exception {
    try (Cluster cluster = init(Cluster.build(2).withDataDirCount(1).withConfig(config -> config.with(NETWORK, GOSSIP).set("hinted_handoff_enabled", true).set("max_hints_delivery_threads", "1").set("hints_flush_period", "1s").set("max_hint_window", "30s").set("max_hints_file_size", "10MiB")).start(), 2)) {
        final IInvokableInstance node1 = cluster.get(1);
        final IInvokableInstance node2 = cluster.get(2);
        waitForExistingRoles(cluster);
        String createTableStatement = format("CREATE TABLE %s.cf (k text PRIMARY KEY, c1 text) " + "WITH compaction = {'class': 'SizeTieredCompactionStrategy', 'enabled': 'false'} ", KEYSPACE);
        cluster.schemaChange(createTableStatement);
        UUID node2UUID = node2.callOnInstance((IIsolatedExecutor.SerializableCallable<UUID>) () -> StorageService.instance.getLocalHostUUID());
        // shutdown the second node in a blocking manner
        node2.shutdown().get();
        waitUntilNodeState(node1, node2UUID, false);
        Long totalHintsAfterFirstShutdown = insertData(cluster);
        Long totalHitsSizeAfterFirstShutdown = getTotalHintsSize(node1, node2UUID);
        // check hints are there etc
        assertHintsSizes(node1, node2UUID);
        pauseHintsDelivery(node1);
        // wait to pass max_hint_window
        Thread.sleep(60000);
        // start the second node, this will not deliver hints to it from the first because dispatch is paused
        // we need this in order to keep hints still on disk, so we can check that the oldest hint
        // is older than max_hint_window which will not deliver any hints even the node is not down long enough
        node2.startup();
        waitUntilNodeState(node1, node2UUID, true);
        Long totalHitsSizeAfterSecondShutdown = getTotalHintsSize(node1, node2UUID);
        assertEquals(totalHitsSizeAfterFirstShutdown, totalHitsSizeAfterSecondShutdown);
        // stop the node again
        // boolean hintWindowExpired = endpointDowntime > maxHintWindow will be false
        // then persistent window kicks in, because even it has not expired,
        // there are hints to be delivered on the disk which were stil not dispatched
        node2.shutdown().get();
        Long totalHintsAfterSecondShutdown = insertData(cluster);
        assertNotEquals(0L, (long) getTotalHintsSize(node1, node2UUID));
        assertEquals(totalHintsAfterFirstShutdown, totalHintsAfterSecondShutdown);
    }
}

