public void bounceTest() throws Exception {
    try (Cluster cluster = init(builder().withNodes(1).withConfig(config -> config.with(NETWORK, GOSSIP)).start())) {
        cluster.schemaChange(withKeyspace("create table %s.tbl (id int primary key, x int)"));
        for (int i = 0; i < 10; i++) cluster.coordinator(1).execute(withKeyspace("insert into %s.tbl (id, x) values (?, ?)"), ConsistencyLevel.ALL, i, i);
