    set("node_proximity", NoOpProximity.class.getName()).set("initial_location_provider", SimpleLocationProvider.class.getName())).createWithoutStarting()) {
        // This test relies on node IDs being in the same order as IP addresses
        for (int i = 1; i <= 3; i++) cluster.get(i).startup();
        cluster.get(2).shutdown().get();
        ClusterUtils.updateAddress(cluster.get(2), "127.0.0.4");
        cluster.get(2).startup();
        cluster.get(3).shutdown().get();
        ClusterUtils.updateAddress(cluster.get(3), "127.0.0.2");
        cluster.get(3).startup();
        cluster.get(2).shutdown().get();
        ClusterUtils.updateAddress(cluster.get(2), "127.0.0.3");
        cluster.get(2).startup();
        ClusterUtils.waitForCMSToQuiesce(cluster, cluster.get(1));
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(30);
        while (true) {
            try {
                AssertUtils.assertRows(sortHelper(cluster.coordinator(2).execute("select peer, host_id from system.peers_v2", ConsistencyLevel.QUORUM)), rows(row(InetAddress.getByName("127.0.0.1"), new NodeId(1).toUUID()), row(InetAddress.getByName("127.0.0.2"), new NodeId(3).toUUID())));
