public void testCMSMembershipMetrics() throws Exception {
    try (Cluster cluster = init(builder().withNodes(3).withConfig(// needed for addtocms below
    c -> c.with(Feature.NETWORK, Feature.GOSSIP)).start())) {
        cluster.forEach(i -> assertMembershipSize(1, i));
