@Test
public void testPendingDeadlock() throws IOException, ExecutionException, InterruptedException {
    try (Cluster cluster = init(builder().withNodes(4).withConfig(config -> config.with(NETWORK, GOSSIP).set("progress_barrier_default_consistency_level", "NODE_LOCAL").set("progress_barrier_min_consistency_level", "NODE_LOCAL")).withoutVNodes().withInstanceInitializer(// make GossipTask.run slower to increase the deadlock window
    BB::install).start())) {
        cluster.schemaChange(withKeyspace("alter keyspace %s with replication = {'class': 'SimpleStrategy', 'replication_factor':1 }"));
        cluster.schemaChange("alter keyspace system_distributed with replication = {'class': 'SimpleStrategy', 'replication_factor':1 }");
        cluster.schemaChange("alter keyspace system_traces with replication = {'class': 'SimpleStrategy', 'replication_factor':1 }");
        ExecutorPlus e = ExecutorFactory.Global.executorFactory().pooled("BounceMove", 2);
        long startToken = cluster.get(2).callOnInstance(() -> {
            NodeId nodeId = ClusterMetadata.current().myNodeId();
            return ((Murmur3Partitioner.LongToken) ClusterMetadata.current().tokenMap.tokens(nodeId).get(0)).token;
        });
        AtomicBoolean stop = new AtomicBoolean(false);
        Future<Integer> moves = e.submit(() -> {
            long token = startToken;
            while (!stop.get()) {
                token++;
                cluster.get(2).nodetoolResult("move", String.valueOf(token)).asserts().success();
            }
            return (int) (token - startToken);
        });
        Future<Integer> bounces = e.submit(() -> {
            int iters = 0;
            while (!stop.get()) {
                cluster.get(4).nodetoolResult("disablegossip").asserts().success();
                Uninterruptibles.sleepUninterruptibly(100, TimeUnit.MILLISECONDS);
                cluster.get(4).nodetoolResult("enablegossip").asserts().success();
                Uninterruptibles.sleepUninterruptibly(100, TimeUnit.MILLISECONDS);
                iters++;
            }
            return iters;
        });
        Uninterruptibles.sleepUninterruptibly(120, TimeUnit.SECONDS);
        stop.set(true);
        System.out.println("MOVES = " + moves.get());
        System.out.println("BOUNCES = " + bounces.get());
        long epoch = cluster.get(1).callOnInstance(() -> ClusterMetadata.current().epoch.getEpoch());
        for (int i = 1; i <= 4; i++) assertEquals(epoch, (long) cluster.get(i).callOnInstance(() -> ClusterMetadata.current().epoch.getEpoch()));
    }
}

@Test
public void bounceTest() throws Exception {
    try (Cluster cluster = builder().withNodes(1).withConfig(config -> config.set("default_secondary_index", "legacy_local_table").set("default_secondary_index_enabled", "true")).start()) {
        cluster.coordinator(1).execute("CREATE KEYSPACE before_bounce WITH replication = {'class': 'SimpleStrategy'}", ConsistencyLevel.ALL);
        cluster.coordinator(1).execute(String.format(CREATE_TABLE_TEMPLATE, "before_bounce.tbl1"), ConsistencyLevel.ALL);
        cluster.coordinator(1).execute(String.format(CREATE_DEFAULT_INDEX_TEMPLATE, "before_bounce.tbl1", "v1"), ConsistencyLevel.ALL);
        cluster.coordinator(1).execute(String.format(CREATE_LEGACY_INDEX_TEMPLATE, "before_bounce.tbl1", "v2"), ConsistencyLevel.ALL);
        cluster.coordinator(1).execute(String.format(CREATE_SAI_INDEX_TEMPLATE, "before_bounce.tbl1", "v3"), ConsistencyLevel.ALL);
        cluster.get(1).shutdown().get();
        cluster.get(1).config().set("default_secondary_index", "sai").set("default_secondary_index_enabled", "true");
        cluster.get(1).startup();
        cluster.coordinator(1).execute("CREATE KEYSPACE after_bounce WITH replication = {'class': 'SimpleStrategy'}", ConsistencyLevel.ALL);
        cluster.coordinator(1).execute(String.format(CREATE_TABLE_TEMPLATE, "after_bounce.tbl1"), ConsistencyLevel.ALL);
        cluster.coordinator(1).execute(String.format(CREATE_DEFAULT_INDEX_TEMPLATE, "after_bounce.tbl1", "v1"), ConsistencyLevel.ALL);
        cluster.coordinator(1).execute(String.format(CREATE_LEGACY_INDEX_TEMPLATE, "after_bounce.tbl1", "v2"), ConsistencyLevel.ALL);
        cluster.coordinator(1).execute(String.format(CREATE_SAI_INDEX_TEMPLATE, "after_bounce.tbl1", "v3"), ConsistencyLevel.ALL);
        // Where an index class was explicitly specified with USING, changing the default should have no effect.
        // The index created using the default implementation before the bounce should preserve its original type
        // while the one created after bounce should use the new default.
        cluster.stream().forEach(i -> {
            i.runOnInstance(() -> {
                Indexes before_bounce = ClusterMetadata.current().schema.getKeyspace("before_bounce").getMetadata().getTableNullable("tbl1").indexes;
                assertIndex(before_bounce.get("legacy_idx").get(), IndexMetadata.Kind.COMPOSITES, CassandraIndex.class);
                assertIndex(before_bounce.get("sai_idx").get(), IndexMetadata.Kind.CUSTOM, StorageAttachedIndex.class);
                // the original default was legacy 2i
                assertIndex(before_bounce.get("default_idx").get(), IndexMetadata.Kind.COMPOSITES, CassandraIndex.class);
                Indexes after_bounce = ClusterMetadata.current().schema.getKeyspace("after_bounce").getMetadata().getTableNullable("tbl1").indexes;
                assertIndex(after_bounce.get("legacy_idx").get(), IndexMetadata.Kind.COMPOSITES, CassandraIndex.class);
                assertIndex(after_bounce.get("sai_idx").get(), IndexMetadata.Kind.CUSTOM, StorageAttachedIndex.class);
                // the updated default is sai
                assertIndex(after_bounce.get("default_idx").get(), IndexMetadata.Kind.CUSTOM, StorageAttachedIndex.class);
            });
        });
    }
}

