        inst.runOnInstance(() -> {
            ClusterMetadataService.instance().log().append(new Entry(Entry.Id.NONE, newEpoch, CustomTransformation.make("DANGER")));
            try {
                ClusterMetadataService.instance().awaitAtLeast(newEpoch);
            } catch (InterruptedException | TimeoutException e) {
                throw new RuntimeException(e);
            }
        });
        Map<String, Epoch> canonicalEpochs = getEpochsDirectly(cluster);
        assertTrue(canonicalEpochs.get(inst.broadcastAddress().toString()).isAfter(canonicalEpochs.get(cmsNode.broadcastAddress().toString())));
        assertEpochs(cluster);
    }
}

