        for (int tbl = 1; tbl <= 5; tbl++) for (int i = 1; i <= cluster.size(); i++) cluster.get(i).executeInternal(withKeyspace("insert into %s.tbl" + tbl + " (id, x) values (1,1)"));
    }
}

