@Test
public void bounceTest() throws Exception {
    try (Cluster cluster = init(builder().withNodes(1).withConfig(config -> config.set("default_compaction", Map.of("class_name", "SizeTieredCompactionStrategy", "parameters", Map.of("min_threshold", "16", "max_threshold", "64")))).start())) {
