@Test
public void testFinishInProgressQueries() throws Throwable {
    ExecutorService executor = Executors.newCachedThreadPool();
    try (Cluster control = init(Cluster.build().withNodes(1).withInstanceInitializer(SlowSelect::install).withConfig(config -> config.with(GOSSIP, NETWORK, NATIVE_PROTOCOL).set("read_request_timeout_in_ms", 1000).set("write_request_timeout_in_ms", 1000).set("range_request_timeout_in_ms", 1000).set("counter_write_request_timeout_in_ms", 1000)).start());
        com.datastax.driver.core.Cluster cluster = driver(control, ProtocolVersion.V5);
        Session session = cluster.connect(KEYSPACE)) {
        control.schemaChange(withKeyspace("CREATE TABLE %s.tbl (pk int PRIMARY KEY, v int)"));
        session.execute("select * from tbl").one();
        control.get(1).runOnInstance(() -> {
            Assert.assertTrue(SlowSelect.enabled.compareAndSet(false, true));
        });
        List<Future<?>> futures = new ArrayList<>();
        for (int i = 0; i < 1000; i++) futures.add(CompletableFuture.supplyAsync(() -> session.execute("select * from tbl").one(), executor));
        int success = 0;
        int timedOut = 0;
        int overloaded = 0;
        for (Future<?> future : futures) {
            try {
                future.get();
                success++;
            } catch (ExecutionException e) {
                if (e.getCause() instanceof OperationTimedOutException)
                    timedOut++;
                else if (e.getCause() instanceof ReadTimeoutException)
                    timedOut++;
                else if (e.getCause() instanceof OverloadedException)
                    overloaded++;
                else
                    throw e;
            }
        }
        Assert.assertEquals(1000, success + timedOut + overloaded);
    } finally {
        executor.shutdown();
    }
}

