        String query = "BEGIN BATCH\n" + "INSERT INTO ks1.t (key, val) VALUES (1, text_as_blob('" + payload + "'))\n" + "INSERT INTO ks1.t (key, val) VALUES (2, text_as_blob('222'))\n" + "APPLY BATCH";
        Assertions.assertThatThrownBy(() -> cluster.coordinator(1).execute(withKeyspace(query), ALL)).hasMessageContaining("Rejected an oversized mutation (").hasMessageContaining("/49152) for keyspace: ks1. Top keys are: t.1");
