/**
 * Makes sure we only snapshot sstables containing the mismatching token
 * <p>
 * 1. create 100 sstables per instance, compaction disabled, one token per sstable
 * 2. make 3 tokens mismatching on node2, one token per sstable
 * 3. run preview repair
 * 4. make sure that only the sstables containing the token are in the snapshot
 */
@Test
public void testSnapshotOfSStablesContainingMismatchingTokens() throws IOException {
    try (Cluster cluster = init(Cluster.build(2).withConfig(config -> config.set("snapshot_on_repaired_data_mismatch", true).with(GOSSIP).with(NETWORK)).start())) {
        Set<Integer> tokensToMismatch = Sets.newHashSet(1, 50, 99);
        cluster.schemaChange(withKeyspace("create table %s.tbl (id blob primary key) with compaction = {'class' : 'SizeTieredCompactionStrategy', 'enabled':false }"));
        // 1 token per sstable;
        for (int i = 0; i < 100; i++) {
            // BigFormat severely overestimates the number of partitions per range when the sstable size is small.
            // Do multiple writes per sstable, with the same token, to compensate.
            for (int j = 0; j < 10; ++j) cluster.coordinator(1).execute(withKeyspace("insert into %s.tbl (id) values (?)"), ConsistencyLevel.ALL, matchingHashBlob(i, j));
            cluster.stream().forEach(instance -> instance.flush(KEYSPACE));
        }
        cluster.stream().forEach(instance -> instance.flush(KEYSPACE));
        for (int i = 1; i <= 2; i++) markRepaired(cluster, i);
        cluster.get(1).nodetoolResult("repair", "-vd", "-pr", KEYSPACE, "tbl").asserts().success().stdoutContains("Repaired data is in sync");
        Set<Token> mismatchingTokens = new HashSet<>();
        for (Integer token : tokensToMismatch) {
            final ByteBuffer b = matchingHashBlob(token, 0);
            cluster.get(2).executeInternal(withKeyspace("insert into %s.tbl (id) values (?)"), b);
            cluster.get(2).flush(KEYSPACE);
            Object[][] res = cluster.get(2).executeInternal(withKeyspace("select token(id) from %s.tbl where id = ?"), b);
            mismatchingTokens.add(new Murmur3Partitioner.LongToken((long) res[0][0]));
        }
        markRepaired(cluster, 2);
        cluster.get(1).nodetoolResult("repair", "-vd", KEYSPACE, "tbl").asserts().success().stdoutContains("Repaired data is inconsistent");
        cluster.get(1).runOnInstance(checkSnapshot(mismatchingTokens, 3));
        // node2 got the duplicate mismatch-tokens above, so it should exist in exactly 6 sstables
        cluster.get(2).runOnInstance(checkSnapshot(mismatchingTokens, 6));
    }
}

/**
 * makes sure that the repaired sstables are not matching on the two
 * nodes by disabling autocompaction on node2 and then running an
 * incremental repair
 */
@Test
public void testWithMismatchingPending() throws Throwable {
    try (Cluster cluster = init(Cluster.build(2).withConfig(config -> config.with(GOSSIP).with(NETWORK)).start())) {
        cluster.schemaChange("create table " + KEYSPACE + ".tbl (id int primary key, t int)");
        insert(cluster.coordinator(1), 0, 100);
        cluster.forEach((node) -> node.flush(KEYSPACE));
        cluster.get(1).callOnInstance(repair(options(false, false)));
        insert(cluster.coordinator(1), 100, 100);
        cluster.forEach((node) -> node.flush(KEYSPACE));
        // make sure that all sstables have moved to repaired by triggering a compaction
        // also disables autocompaction on the nodes
        cluster.forEach((node) -> node.runOnInstance(() -> {
            ColumnFamilyStore cfs = Keyspace.open(KEYSPACE).getColumnFamilyStore("tbl");
            FBUtilities.waitOnFutures(CompactionManager.instance.submitBackground(cfs));
            cfs.disableAutoCompaction();
        }));
        long[] marks = logMark(cluster);
        cluster.get(1).callOnInstance(repair(options(false, false)));
        // now re-enable autocompaction on node1, this moves the sstables for the new repair to repaired
        cluster.get(1).runOnInstance(() -> {
            ColumnFamilyStore cfs = Keyspace.open(KEYSPACE).getColumnFamilyStore("tbl");
            cfs.enableAutoCompaction();
            FBUtilities.waitOnFutures(CompactionManager.instance.submitBackground(cfs));
        });
        waitLogsRepairFullyFinished(cluster, marks);
        RepairResult rs = cluster.get(1).callOnInstance(repair(options(true, false)));
        // preview repair should succeed
        assertTrue(rs.success);
        // and we should see no mismatches
        assertFalse(rs.wasInconsistent);
    }
}

/**
 * another case where the repaired datasets could mismatch is if an incremental repair finishes just as the preview
 * repair is starting up.
 *
 * This tests this case:
 * 1. we start a preview repair
 * 2. pause the validation requests from node1 -> node2
 * 3. node1 starts its validation
 * 4. run an incremental repair which completes fine
 * 5. node2 resumes its validation
 *
 * Now we will include sstables from the second incremental repair on node2 but not on node1
 * This should fail since we fail any preview repair which is ongoing when an incremental repair finishes (step 4 above)
 */
@Test
public void testFinishingIncRepairDuringPreview() throws IOException, InterruptedException, ExecutionException {
    ExecutorService es = Executors.newSingleThreadExecutor();
    try (Cluster cluster = init(Cluster.build(2).withConfig(config -> config.with(GOSSIP).with(NETWORK)).start())) {
        cluster.schemaChange("create table " + KEYSPACE + ".tbl (id int primary key, t int)");
        insert(cluster.coordinator(1), 0, 100);
        cluster.forEach((node) -> node.flush(KEYSPACE));
        cluster.get(1).callOnInstance(repair(options(false, false)));
        insert(cluster.coordinator(1), 100, 100);
        cluster.forEach((node) -> node.flush(KEYSPACE));
        Condition previewRepairStarted = newOneTimeCondition();
        Condition continuePreviewRepair = newOneTimeCondition();
        DelayFirstRepairTypeMessageFilter filter = validationRequest(previewRepairStarted, continuePreviewRepair);
        // this pauses the validation request sent from node1 to node2 until we have run a full inc repair below
        cluster.filters().outbound().verbs(VALIDATION_REQ.id).from(1).to(2).messagesMatching(filter).drop();
        Future<RepairResult> rsFuture = es.submit(() -> cluster.get(1).callOnInstance(repair(options(true, false))));
        previewRepairStarted.await();
        // this needs to finish before the preview repair is unpaused on node2
        cluster.get(1).callOnInstance(repair(options(false, false)));
        RepairResult irResult = cluster.get(1).callOnInstance(repair(options(false, false)));
        continuePreviewRepair.signalAll();
        RepairResult rs = rsFuture.get();
        // preview repair was started before IR, but has lower priority, so its task will get cancelled
        assertFalse(rs.success);
        // and no mismatches should have been reported
        assertFalse(rs.wasInconsistent);
        // IR was started after preview repair, but has a higher priority, so it'll be allowed to finish
        assertTrue(irResult.success);
        assertFalse(irResult.wasInconsistent);
    } finally {
        es.shutdown();
    }
}

/**
 * Tests that a IR is running, but not completed before validation compaction starts
 */
@Test
public void testConcurrentIncRepairDuringPreview() throws IOException, InterruptedException, ExecutionException {
    try (Cluster cluster = init(Cluster.build(2).withConfig(config -> config.with(GOSSIP).with(NETWORK)).start())) {
        cluster.schemaChange("create table " + KEYSPACE + ".tbl (id int primary key, t int)");
        insert(cluster.coordinator(1), 0, 100);
        cluster.forEach((node) -> node.flush(KEYSPACE));
        cluster.get(1).callOnInstance(repair(options(false, false)));
        insert(cluster.coordinator(1), 100, 100);
        cluster.forEach((node) -> node.flush(KEYSPACE));
        Condition previewRepairStarted = newOneTimeCondition();
        Condition continuePreviewRepair = newOneTimeCondition();
        // this pauses the validation request sent from node1 to node2 until the inc repair below has run
        cluster.filters().outbound().verbs(VALIDATION_REQ.id).from(1).to(2).messagesMatching(validationRequest(previewRepairStarted, continuePreviewRepair)).drop();
        Future<RepairResult> previewResult = cluster.get(1).asyncCallsOnInstance(repair(options(true, false))).call();
        previewRepairStarted.await();
        // trigger IR and wait till it's ready to commit
        Future<RepairResult> irResult = cluster.get(1).asyncCallsOnInstance(repair(options(false, false))).call();
        RepairResult ir = irResult.get();
        // IR was submitted after preview repair has acquired sstables, but has higher priority
        assertTrue(ir.success);
        // not preview, so we don't care about preview notification
        assertFalse(ir.wasInconsistent);
        // unblock preview repair and wait for it to complete
        continuePreviewRepair.signalAll();
        RepairResult rs = previewResult.get();
        // preview repair was started earlier than IR session; but has smaller priority
        assertFalse(rs.success);
        // and no mismatches should have been reported
        assertFalse(rs.wasInconsistent);
    }
}

/**
 * Same as testFinishingIncRepairDuringPreview but the previewed range does not intersect the incremental repair
 * so both preview and incremental repair should finish fine (without any mismatches)
 */
@Test
public void testFinishingNonIntersectingIncRepairDuringPreview() throws IOException, InterruptedException, ExecutionException {
    ExecutorService es = Executors.newSingleThreadExecutor();
    try (Cluster cluster = init(Cluster.build(2).withConfig(config -> config.with(GOSSIP).with(NETWORK)).start())) {
        int tokenCount = ClusterUtils.getTokenCount(cluster.get(1));
        cluster.schemaChange("create table " + KEYSPACE + ".tbl (id int primary key, t int)");
        insert(cluster.coordinator(1), 0, 100);
        cluster.forEach((node) -> node.flush(KEYSPACE));
        assertTrue(cluster.get(1).callOnInstance(repair(options(false, false))).success);
        insert(cluster.coordinator(1), 100, 100);
        cluster.forEach((node) -> node.flush(KEYSPACE));
        // pause preview repair validation messages on node2 until node1 has finished
        Condition previewRepairStarted = newOneTimeCondition();
        Condition continuePreviewRepair = newOneTimeCondition();
        DelayFirstRepairTypeMessageFilter filter = validationRequest(previewRepairStarted, continuePreviewRepair);
        cluster.filters().outbound().verbs(VALIDATION_REQ.id).from(1).to(2).messagesMatching(filter).drop();
        // get local ranges to repair two separate ranges:
        List<String> localRanges = cluster.get(1).callOnInstance(() -> {
            List<String> res = new ArrayList<>();
            for (Range<Token> r : instance.getLocalReplicas(KEYSPACE).ranges()) res.add(r.left.getTokenValue() + ":" + r.right.getTokenValue());
            return res;
        });
        assertEquals(2 * tokenCount, localRanges.size());
        Future<RepairResult> repairStatusFuture = es.submit(() -> cluster.get(1).callOnInstance(repair(options(true, false, localRanges.get(0)))));
        // wait for node1 to start validation compaction
        previewRepairStarted.await();
        // this needs to finish before the preview repair is unpaused on node2
        assertTrue(cluster.get(1).callOnInstance(repair(options(false, false, localRanges.get(1)))).success);
        continuePreviewRepair.signalAll();
        RepairResult rs = repairStatusFuture.get();
        // repair should succeed
        assertTrue(rs.success);
        // and no mismatches
        assertFalse(rs.wasInconsistent);
    } finally {
        es.shutdown();
    }
}

/**
 * Makes sure we can start a non-intersecting preview repair while there are other pending sstables on disk
 */
@Test
public void testStartNonIntersectingPreviewRepair() throws IOException, InterruptedException, ExecutionException {
    ExecutorService es = Executors.newSingleThreadExecutor();
    try (Cluster cluster = init(Cluster.build(2).withConfig(config -> config.with(GOSSIP).with(NETWORK)).start())) {
        int tokenCount = ClusterUtils.getTokenCount(cluster.get(1));
        cluster.schemaChange("create table " + KEYSPACE + ".tbl (id int primary key, t int)");
        insert(cluster.coordinator(1), 0, 100);
        cluster.forEach((node) -> node.flush(KEYSPACE));
        cluster.get(1).nodetoolResult("repair", KEYSPACE, "tbl").asserts().success();
        insert(cluster.coordinator(1), 100, 100);
        cluster.forEach((node) -> node.flush(KEYSPACE));
        // pause inc repair validation messages on node2 until node1 has finished
        Condition incRepairStarted = newOneTimeCondition();
        Condition continueIncRepair = newOneTimeCondition();
        DelayFirstRepairTypeMessageFilter filter = DelayFirstRepairTypeMessageFilter.validationRequest(incRepairStarted, continueIncRepair);
        cluster.filters().outbound().verbs(Verb.VALIDATION_REQ.id).from(1).to(2).messagesMatching(filter).drop();
        // get local ranges to repair two separate ranges:
        List<String> localRanges = cluster.get(1).callOnInstance(() -> {
            List<String> res = new ArrayList<>();
            for (Range<Token> r : StorageService.instance.getLocalReplicas(KEYSPACE).ranges()) res.add(r.left.getTokenValue() + ":" + r.right.getTokenValue());
            return res;
        });
        assertEquals(2 * tokenCount, localRanges.size());
        String[] previewedRange = localRanges.get(0).split(":");
        String[] repairedRange = localRanges.get(1).split(":");
        Future<NodeToolResult> repairStatusFuture = es.submit(() -> cluster.get(1).nodetoolResult("repair", "-st", repairedRange[0], "-et", repairedRange[1], KEYSPACE, "tbl"));
        // wait for node1 to start validation compaction
        incRepairStarted.await();
        // now we have pending sstables in range "repairedRange", make sure we can preview "previewedRange"
        cluster.get(1).nodetoolResult("repair", "-vd", "-st", previewedRange[0], "-et", previewedRange[1], KEYSPACE, "tbl").asserts().success().notificationContains("Repaired data is in sync");
        continueIncRepair.signalAll();
        repairStatusFuture.get().asserts().success();
    } finally {
        es.shutdown();
    }
}

@Test
public void snapshotTest() throws IOException, InterruptedException {
    try (Cluster cluster = init(Cluster.build(3).withConfig(config -> config.set("snapshot_on_repaired_data_mismatch", true).with(GOSSIP).with(NETWORK)).start())) {
        cluster.schemaChange("create table " + KEYSPACE + ".tbl (id int primary key, t int)");
        cluster.schemaChange("create table " + KEYSPACE + ".tbl2 (id int primary key, t int)");
        // populate 2 tables
        insert(cluster.coordinator(1), 0, 100, "tbl");
        insert(cluster.coordinator(1), 0, 100, "tbl2");
        cluster.forEach((n) -> n.flush(KEYSPACE));
        // make sure everything is marked repaired
        cluster.get(1).callOnInstance(repair(options(false, false)));
        waitMarkedRepaired(cluster);
        // make node2 mismatch
        unmarkRepaired(cluster.get(2), "tbl");
        verifySnapshots(cluster, "tbl", true);
        verifySnapshots(cluster, "tbl2", true);
        AtomicInteger snapshotMessageCounter = new AtomicInteger();
        cluster.filters().verbs(Verb.SNAPSHOT_REQ.id).messagesMatching((from, to, message) -> {
            snapshotMessageCounter.incrementAndGet();
            return false;
        }).drop();
        cluster.get(1).callOnInstance(repair(options(true, true)));
        verifySnapshots(cluster, "tbl", false);
        // tbl2 should not have a mismatch, so the snapshots should be empty here
        verifySnapshots(cluster, "tbl2", true);
        assertEquals(3, snapshotMessageCounter.get());
        // and make sure that we don't try to snapshot again
        snapshotMessageCounter.set(0);
        cluster.get(3).callOnInstance(repair(options(true, true)));
        assertEquals(0, snapshotMessageCounter.get());
    }
}

@Test
public void testScheduledSamplingTaskLogs() throws IOException {
    try (Cluster cluster = init(Cluster.build(1).start())) {
        cluster.schemaChange(withKeyspace("CREATE TABLE %s.tbl (pk int, ck int, v int, PRIMARY KEY (pk, ck));"));
        // start the scheduled profileload task that samples for 1 second and every second.
        cluster.get(1).nodetoolResult("profileload", "1000", "-i", "1000").asserts().success();
        Random rnd = new Random();
        // 800 * 2ms = 1.6 seconds. It logs every second. So it logs at least once.
        for (int i = 0; i < 800; i++) {
            cluster.coordinator(1).execute(withKeyspace("INSERT INTO %s.tbl (pk, ck, v) VALUES (?,?,?)"), ConsistencyLevel.QUORUM, rnd.nextInt(), rnd.nextInt(), i);
            Uninterruptibles.sleepUninterruptibly(2, TimeUnit.MILLISECONDS);
        }
        // --list should display all active tasks.
        String expectedOutput = String.format("KEYSPACE TABLE%n" + "%8s %5s", "*", "*");
        cluster.get(1).nodetoolResult("profileload", "--list").asserts().success().stdoutContains(expectedOutput);
        // loop assert the log contains the frequency readout; give this 15 seconds which should be plenty of time
        // even on very badly underprovisioned environments
        int timeout = 15;
        boolean testPassed = false;
        while (timeout-- > 0) {
            List<String> freqHeadings = cluster.get(1).logs().grep("Frequency of (reads|writes|cas contentions) by partition").getResult();
            if (freqHeadings.size() > 3) {
                testPassed = true;
                break;
            }
            Uninterruptibles.sleepUninterruptibly(1, TimeUnit.SECONDS);
        }
        Assert.assertTrue("The scheduled task should at least run and log once", testPassed);
        List<String> startSamplingLogs = cluster.get(1).logs().grep("Starting to sample tables").getResult();
        Assert.assertTrue("It should start sampling at least once", startSamplingLogs.size() > 0);
        // stop the scheduled sampling
        cluster.get(1).nodetoolResult("profileload", "--stop").asserts().success();
        // wait for the last schedule to be stopped. --list should list nothing after stopping
        assertListEmpty(cluster.get(1));
        // schedule on the specific table
        cluster.get(1).nodetoolResult("profileload", KEYSPACE, "tbl", "1000", "-i", "1000").asserts().success();
        expectedOutput = String.format("%" + KEYSPACE.length() + "s %5s%n" + "%s %5s", "KEYSPACE", "TABLE", KEYSPACE, "tbl");
        cluster.get(1).nodetoolResult("profileload", "--list").asserts().success().stdoutContains(expectedOutput);
        // stop all should stop the task scheduled with the specific table
        cluster.get(1).nodetoolResult("profileload", "--stop").asserts().success();
        assertListEmpty(cluster.get(1));
    }
}

@Test
public void testPreventDuplicatedSchedule() throws IOException {
    try (Cluster cluster = init(Cluster.build(1).start())) {
        cluster.schemaChange(withKeyspace("CREATE TABLE %s.tbl (pk int, ck int, v int, PRIMARY KEY (pk, ck));"));
        // New sampling; we are good
        cluster.get(1).nodetoolResult("profileload", KEYSPACE, "tbl", "1000", "-i", "1000").asserts().success().stdoutNotContains("Unable to schedule sampling for keyspace");
        // Duplicated sampling (against the same table) but different interval. Nodetool should reject
        cluster.get(1).nodetoolResult("profileload", KEYSPACE, "tbl", "1000", "-i", "1000").asserts().success().stdoutContains("Unable to schedule sampling for keyspace");
        // The "sampling all" request creates overlaps, so it should be rejected too
        cluster.get(1).nodetoolResult("profileload", "1000", "-i", "1000").asserts().success().stdoutContains("Unable to schedule sampling for keyspace");
        cluster.get(1).nodetoolResult("profileload", KEYSPACE, "tbl", "--stop").asserts().success();
        assertListEmpty(cluster.get(1));
        cluster.get(1).nodetoolResult("profileload", "nonexistks", "nonexisttbl", "--stop").asserts().success().stdoutContains("Unable to stop the non-existent scheduled sampling");
    }
}

