public void testReplayAndCloseMultipleTimes() throws Throwable {
    try (ICluster<IInvokableInstance> cluster = init(builder().withNodes(3).withConfig(conf -> conf.with(Feature.NATIVE_PROTOCOL, Feature.GOSSIP, Feature.NETWORK)).start())) {
        cluster.schemaChange("CREATE TABLE " + KEYSPACE + ".tbl (pk int, ck int, v int, PRIMARY KEY (pk, ck))");
