/**
 * This regression test for CASSANDRA-19902 ensures {@link StorageServiceMBean} JMX
 * interface is published before the node finishes bootstrapping
 */
@Test
@Ignore("FIXME: CASSANDRA-20795 Operation mode is STARTING instead of JOINING during bootstrap")
public void testStorageServiceMBeanIsPublishedOnJMXDuringBootstrap() throws Throwable {
    ExecutorService es = Executors.newFixedThreadPool(1);
    try (Cluster cluster = builder().withNodes(2).withConfig(config -> config.with(GOSSIP).with(NETWORK).with(JMX).set("auto_bootstrap", true)).withInstanceInitializer(BBBootstrapInterceptor::install).createWithoutStarting();
        Closeable ignored = es::shutdown) {
        Runnable test = () -> {
            // Wait for bootstrap to start via countdown latch
            IInvokableInstance joiningInstance = cluster.get(2);
            joiningInstance.runOnInstance(() -> BBBootstrapInterceptor.bootstrapStart.awaitUninterruptibly());
            // At this point, it should be possible to check bootstrap status via JMX.
            IInstanceConfig config = joiningInstance.config();
            try (JMXConnector jmxc = JMXUtil.getJmxConnector(config)) {
                MBeanServerConnection mbsc = jmxc.getMBeanServerConnection();
                StorageServiceMBean sp = javax.management.JMX.newMBeanProxy(mbsc, new ObjectName("org.apache.cassandra.db:type=StorageService"), StorageServiceMBean.class);
                assertEquals(sp.getOperationMode(), StorageService.Mode.JOINING.toString());
            } catch (Throwable t) {
                throw new AssertionError("Should not fail to connect via JMX before bootstrap is completed.", t);
            } finally {
                // Complete bootstrap via countdown latch so test will finish properly
                joiningInstance.runOnInstance(() -> BBBootstrapInterceptor.bootstrapReady.decrement());
            }
        };
        Future<?> testResult = es.submit(test);
        try {
            cluster.startup();
        } catch (Exception ex) {
            // ignore exceptions from startup process. More interested in the test result.
        }
        testResult.get();
    }
    es.awaitTermination(5, TimeUnit.SECONDS);
}

@Test
public void cleanupDuringDecommissionTest() throws Throwable {
    ExecutorService executor = Executors.newSingleThreadExecutor();
    try (Cluster cluster = init(builder().withNodes(2).withTokenSupplier(evenlyDistributedTokens(2)).withNodeIdTopology(NetworkTopology.singleDcNetworkTopology(2, "dc0", "rack0")).withConfig(config -> config.with(NETWORK, GOSSIP)).start(), 1)) {
        IInvokableInstance cmsInstance = cluster.get(1);
        IInvokableInstance nodeToDecommission = cluster.get(2);
        // CMS instance remains in the cluster
        IInvokableInstance nodeToRemainInCluster = cluster.get(1);
        // Create table before starting decommission as at the moment schema changes are not permitted
        // while range movements are in-flight. Additionally, pausing the CMS instance to block the
        // leave sequence from completing would also block the commit of the schema transformation
        cluster.schemaChange("CREATE TABLE IF NOT EXISTS " + KEYSPACE + ".tbl (pk int, ck int, v int, PRIMARY KEY (pk, ck))");
        // Prime the CMS node to pause before the finish leave event is committed
        Callable<?> pending = pauseBeforeCommit(cmsInstance, (e) -> e instanceof PrepareLeave.FinishLeave);
        // Start decomission on nodeToDecommission
        Future<Boolean> decomFuture = executor.submit(() -> decommission(nodeToDecommission));
        pending.call();
        // Add data to cluster while node is decomissioning
        int numRows = 100;
        insertData(cluster, 2, numRows, ConsistencyLevel.ONE);
        cluster.forEach(c -> c.flush(KEYSPACE));
        // Check data before cleanup on nodeToRemainInCluster
        assertEquals(numRows, nodeToRemainInCluster.executeInternal("SELECT * FROM " + KEYSPACE + ".tbl").length);
        // Run cleanup on nodeToRemainInCluster
        NodeToolResult result = nodeToRemainInCluster.nodetoolResult("cleanup");
        result.asserts().success();
        // Check data after cleanup on nodeToRemainInCluster
        assertEquals(numRows, nodeToRemainInCluster.executeInternal("SELECT * FROM " + KEYSPACE + ".tbl").length);
        unpauseCommits(cmsInstance);
        assertTrue(decomFuture.get());
    }
}

