@Test
public void shrinkCmsTest() throws Throwable {
    try (Cluster cluster = builder().withNodes(3).appendConfig(c -> c.with(Feature.NETWORK)).start()) {
        cluster.get(1).runOnInstance(() -> {
            try {
                // When there's only one CMS node left, we should reject even `forced` transformatiosn
                ClusterMetadataService.instance().commit(new RemoveFromCMS(FBUtilities.getBroadcastAddressAndPort(), true));
            } catch (IllegalStateException e) {
                if (!e.getMessage().contains("would leave no members in CMS"))
                    throw new AssertionError(e.getMessage());
            }
        });
        cluster.get(1).runOnInstance(() -> {
            ClusterMetadata metadata = ClusterMetadata.current();
            for (NodeId nodeId : metadata.directory.peerIds()) {
                if (nodeId.equals(metadata.myNodeId()))
                    continue;
                AddToCMS.initiate(nodeId, metadata.directory.getNodeAddresses(nodeId).broadcastAddress);
            }
        });
        Set<String> initialCMS = getCMSMembers(cluster.get(1));
        Assert.assertEquals(3, initialCMS.size());
        for (int i = 2; i <= 3; i++) {
            cluster.get(i).runOnInstance(() -> ClusterMetadataService.instance().processor().fetchLogAndWait());
            Assert.assertEquals(initialCMS, getCMSMembers(cluster.get(i)));
        }
        // Without the force option set, removing a node from the CMS should
        // be rejected if it would cause the size to go below 3 nodes
        cluster.get(1).runOnInstance(() -> {
            ClusterMetadata metadata = ClusterMetadata.current();
            for (InetAddressAndPort addr : metadata.directory.allAddresses()) {
                if (addr.toString().contains("127.0.0.3")) {
                    try {
                        ClusterMetadataService.instance().commit(new RemoveFromCMS(addr, false));
                    } catch (IllegalStateException e) {
                        if (!e.getMessage().contains("resubmit with force=true"))
                            throw new AssertionError(e.getMessage());
                    }
                    return;
                }
            }
        });
        // expect no changes to the CMS membership yet
        for (int i = 1; i <= 3; i++) {
            cluster.get(i).runOnInstance(() -> ClusterMetadataService.instance().processor().fetchLogAndWait());
            Assert.assertEquals(initialCMS, getCMSMembers(cluster.get(i)));
        }
        // Run again, this time with the force option
        cluster.get(1).runOnInstance(() -> {
            ClusterMetadata metadata = ClusterMetadata.current();
            for (InetAddressAndPort addr : metadata.directory.allAddresses()) {
                if (addr.toString().contains("127.0.0.3")) {
                    ClusterMetadataService.instance().commit(new RemoveFromCMS(addr, true));
                    return;
                }
            }
        });
        // node3 should have been removed from the CMS
        Set<String> updatedCMS = initialCMS.stream().filter(s -> !s.contains("127.0.0.3")).collect(Collectors.toSet());
        for (int i = 1; i <= 3; i++) {
            cluster.get(i).runOnInstance(() -> ClusterMetadataService.instance().processor().fetchLogAndWait());
            Assert.assertEquals(updatedCMS, getCMSMembers(cluster.get(i)));
        }
        // Commit some transformations as a smoke test
        for (int idx : new int[] { 1, 2, 3 }) {
            cluster.get(idx).runOnInstance(() -> {
                ClusterMetadataService.instance().commit(CustomTransformation.make(idx));
            });
        }
    }
}

@Test
public void allPaxosMessagesAreUrgentTest() throws Throwable {
    try (Cluster cluster = builder().withNodes(3).start()) {
        List<Throwable> thrown = new CopyOnWriteArrayList<>();
        cluster.filters().allVerbs().messagesMatching((from, to, msg) -> {
            Verb verb = Verb.fromId(msg.verb());
            if (!verb.toString().contains("PAXOS2"))
                return false;
            try {
                boolean hasFlag = cluster.get(1).callOnInstance(() -> Instance.deserializeHeader(msg).hasFlag(MessageFlag.URGENT));
                assert hasFlag : String.format("%s does not have URGENT flag set: %s", verb, msg);
            } catch (Throwable t) {
                thrown.add(t);
            }
            return false;
        }).drop();
        for (int idx : new int[] { 2, 3 }) cluster.get(idx).runOnInstance(() -> AddToCMS.initiate());
        if (!thrown.isEmpty()) {
            Throwable t = new AssertionError("Caught exceptions");
            for (Throwable throwable : thrown) t.addSuppressed(throwable);
            throw t;
        }
    }
}

@Test
public void internodeConnectionsDuringDecom() throws Throwable {
    try (Cluster cluster = builder().withNodes(4).withConfig(config -> config.with(NETWORK, GOSSIP, NATIVE_PROTOCOL)).start()) {
        BootstrapTest.populate(cluster, 0, 100);
        int decomissioningNode = 4;
        cluster.get(decomissioningNode).nodetoolResult("decommission").asserts().success();
        cluster.filters().allVerbs().from(decomissioningNode).messagesMatching((i, i1, iMessage) -> {
            throw new AssertionError("Decomissioned node should not send any messages");
        }).drop();
        ClusterUtils.waitForCMSToQuiesce(cluster, cluster.get(1), decomissioningNode);
        Map<Integer, Long> connectionAttempts = new HashMap<>();
        long deadline = currentTimeMillis() + TimeUnit.SECONDS.toMillis(10);
        // Wait 10 seconds and check if there are any new connection attempts to the decomissioned node
        while (currentTimeMillis() <= deadline) {
            for (int i = 1; i <= 3; i++) {
                Object[][] res = cluster.get(i).executeInternal("SELECT active_connections, connection_attempts FROM system_views.internode_outbound WHERE address = '127.0.0.4' AND port = 7012");
                Assert.assertEquals(1, res.length);
                Assert.assertEquals(0L, ((Long) res[0][0]).longValue());
                long attempts = ((Long) res[0][1]).longValue();
                if (connectionAttempts.get(i) == null)
                    connectionAttempts.put(i, attempts);
                else
                    Assert.assertEquals(String.format("Number of connection attempts from %d to %d should have been stable but changed from %d to %d", i, decomissioningNode, connectionAttempts.get(i), attempts), connectionAttempts.get(i), (Long) attempts);
            }
            LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(100));
        }
    }
}

