@Test
public void testIndexComponentStreaming() throws IOException {
    try (Cluster cluster = init(Cluster.build(2).withConfig(c -> c.with(Feature.values()).set("stream_entire_sstables", isZeroCopyStreaming).set("streaming_slow_events_log_timeout", "0s")).start())) {
        cluster.schemaChange(withKeyspace(isWide ? "CREATE TABLE %s.test (pk int, ck int , literal text, numeric int, b blob, PRIMARY KEY(pk, ck)) WITH compression = { 'enabled' : false };" : "CREATE TABLE %s.test (pk int PRIMARY KEY , literal text, numeric int, b blob) WITH compression = { 'enabled' : false };"));
        int numSSTableComponents = isWide ? V1OnDiskFormat.WIDE_PER_SSTABLE_COMPONENTS.size() : V1OnDiskFormat.SKINNY_PER_SSTABLE_COMPONENTS.size();
        int numIndexComponents = isLiteral ? V1OnDiskFormat.LITERAL_COMPONENTS.size() : V1OnDiskFormat.NUMERIC_COMPONENTS.size();
        int numComponents = sstableStreamingComponentsCount() + numSSTableComponents + numIndexComponents + 1;
        cluster.schemaChange(withKeyspace("CREATE INDEX ON %s.test(literal) USING 'sai';"));
        cluster.schemaChange(withKeyspace("CREATE INDEX ON %s.test(numeric) USING 'sai';"));
        cluster.stream().forEach(i -> i.nodetoolResult("disableautocompaction", KEYSPACE).asserts().success());
        IInvokableInstance first = cluster.get(1);
        IInvokableInstance second = cluster.get(2);
        long sstableCount = 10;
        long expectedFiles = isZeroCopyStreaming ? sstableCount * numComponents : sstableCount;
        for (int i = 0; i < sstableCount; i++) {
            if (isWide) {
                String insertTemplate = "INSERT INTO %s.test(pk, ck, " + (isLiteral ? "literal" : "numeric") + ", b) VALUES (?, ?, ?, ?)";
                first.executeInternal(withKeyspace(insertTemplate), i, i, isLiteral ? "v" + i : Integer.valueOf(i), BLOB);
            } else {
                String insertTemplate = "INSERT INTO %s.test(pk, " + (isLiteral ? "literal" : "numeric") + ", b) VALUES (?, ?, ?)";
                first.executeInternal(withKeyspace(insertTemplate), i, isLiteral ? "v" + i : Integer.valueOf(i), BLOB);
            }
            first.flush(KEYSPACE);
        }
        second.nodetoolResult("rebuild", "--keyspace", KEYSPACE).asserts().success();
        SimpleQueryResult qr = first.executeInternalWithResult("SELECT * FROM system_views.streaming");
        String txt = QueryResultUtil.expand(qr);
        qr.reset();
        assertThat(qr.toObjectArrays().length).describedAs("Found rows\n%s", txt).isEqualTo(1);
        assertThat(qr.hasNext()).isTrue();
        Row row = qr.next();
        QueryResultUtil.assertThat(row).isEqualTo("peers", Collections.singletonList(second.broadcastAddress().toString())).isEqualTo("follower", true).isEqualTo("operation", "Rebuild").isEqualTo("status", "success").isEqualTo("progress_percentage", 100.0F).isEqualTo("success_message", null).isEqualTo("failure_cause", null).isEqualTo("files_sent", expectedFiles).columnsEqualTo("files_sent", "files_to_send").columnsEqualTo("bytes_sent", "bytes_to_send").isEqualTo("files_received", 0L).columnsEqualTo("files_received", "files_to_receive", "bytes_received", "bytes_to_receive");
        long totalBytes = row.getLong("bytes_sent");
        assertThat(totalBytes).isGreaterThan(0);
        qr = second.executeInternalWithResult("SELECT * FROM system_views.streaming");
        txt = QueryResultUtil.expand(qr);
        qr.reset();
        assertThat(qr.toObjectArrays().length).describedAs("Found rows\n%s", txt).isEqualTo(1);
        assertThat(qr.hasNext()).isTrue();
        QueryResultUtil.assertThat(qr.next()).isEqualTo("peers", Collections.singletonList(first.broadcastAddress().toString())).isEqualTo("follower", false).isEqualTo("operation", "Rebuild").isEqualTo("status", "success").isEqualTo("progress_percentage", 100.0F).isEqualTo("success_message", null).isEqualTo("failure_cause", null).columnsEqualTo("files_to_receive", "files_received").isEqualTo("files_received", expectedFiles).columnsEqualTo("bytes_to_receive", "bytes_received").isEqualTo("bytes_received", totalBytes).columnsEqualTo("files_sent", "files_to_send", "bytes_sent", "bytes_to_send").isEqualTo("files_sent", 0L);
        // did we trigger slow event log?
        cluster.forEach(i -> Assertions.assertThat(i.logs().grep("Handling streaming events took longer than").getResult()).describedAs("Unable to find slow log for node%d", i.config().num()).isNotEmpty());
        for (int i = 0; i < sstableCount; i++) {
            Object[][] rs = isLiteral ? second.executeInternal(withKeyspace("select pk from %s.test where literal = ?"), "v" + i) : second.executeInternal(withKeyspace("select pk from %s.test where numeric = ?"), i);
            assertThat(rs.length).isEqualTo(1);
            assertThat(rs[0][0]).isEqualTo(i);
        }
    }
}

@Test
public void testPartialUpdateResolution() {
    Model model = new Model(specification);
    // Write and repair rows that contain values for all columns we might query:
    if (specification.existing) {
        model.writeRepairedRows();
        model.validateCurrent();
    }
    // Introduce partial writes that span replicas:
    model.writeUnrepairedRows();
    if (specification.flushPartials)
        // Flushg partial rows from Memtable-attached indexes to SSTable indexes:
        CLUSTER.stream().forEach(i -> i.flush(KEYSPACE));
    // If we wrote an initial (repaired) version of the row, do negative validation.
    // (i.e. Ensure queries that would have initially produced matches no longer do.)
    if (specification.existing)
        model.validatePrevious();
    // In DELETE scenarios, which always have existing data, (negative) validation is already complete by now:
    if (specification.partialUpdateType == StatementType.INSERT)
        model.validateCurrent();
}

@Test
public void test() throws IOException {
    try (Cluster cluster = Cluster.build(2).withConfig(c -> c.with(Feature.values())).start()) {
        init(cluster);
        cluster.schemaChange(withKeyspace("CREATE TABLE %s.tbl (pk vector<bigint, 2>, ck int, s1 int static, v1 int, v2 int, PRIMARY KEY (pk, ck))"));
        cluster.schemaChange(withKeyspace("CREATE INDEX ON %s.tbl(s1) USING 'sai'"));
        cluster.schemaChange(withKeyspace("CREATE INDEX ON %s.tbl(v1) USING 'sai'"));
        cluster.schemaChange(withKeyspace("CREATE INDEX ON %s.tbl(v2) USING 'sai'"));
        IInvokableInstance node1 = cluster.get(1);
        IInvokableInstance node2 = cluster.get(2);
        // see org.apache.cassandra.service.StorageService.repair
        List<Range> partialRanges = ClusterUtils.getPrimaryRanges(node1, KEYSPACE);
        var completeRanges = completeRanges(partialRanges);
        // write to each column for the complete set
        // avoid writing to one of the columns for the partial set
        for (var range : completeRanges) {
            ByteBuffer pk = key(range);
            node2.executeInternal(withKeyspace("INSERT INTO %s.tbl(pk, ck, s1, v1, v2) VALUES (?, ?, ?, ?, ?)"), pk, 0, 0, 0, 0);
            node2.executeInternal(withKeyspace("INSERT INTO %s.tbl(pk, ck, s1, v1, v2) VALUES (?, ?, ?, ?, ?)"), pk, 1, 0, 1, 1);
        }
        for (var range : partialRanges) {
            ByteBuffer pk = key(range);
            node2.executeInternal(withKeyspace("INSERT INTO %s.tbl(pk, ck, v1) VALUES (?, ?, ?)"), pk, 0, 0);
            node2.executeInternal(withKeyspace("INSERT INTO %s.tbl(pk, ck, v1) VALUES (?, ?, ?)"), pk, 1, 1);
        }
        node1.nodetoolResult("repair", KEYSPACE, "-pr").asserts().success();
    }
}

