public void test2iCompaction() throws IOException {
    try (Cluster cluster = init(Cluster.build(1).start())) {
        Assume.assumeFalse("Test only valid for legacy index", "sai".equals(cluster.get(1).config().getString("default_secondary_index")));
        cluster.schemaChange(withKeyspace("create table %s.tbl (id int, ck int, something int, else int, primary key (id, ck));"));
        cluster.schemaChange(withKeyspace("create index tbl_idx on %s.tbl (ck)"));
        for (int i = 0; i < 10; i++) cluster.coordinator(1).execute(withKeyspace("insert into %s.tbl (id, ck, something, else) values (?, ?, ?, ?)"), ConsistencyLevel.ALL, i, i, i, i);
        cluster.get(1).runOnInstance(() -> {
            ColumnFamilyStore cfs = Keyspace.open(KEYSPACE).getColumnFamilyStore("tbl");
            CassandraIndex i = (CassandraIndex) cfs.indexManager.getIndexByName("tbl_idx");
            i.getIndexCfs().forceBlockingFlush(ColumnFamilyStore.FlushReason.UNIT_TESTS);
            Set<SSTableReader> idxSSTables = i.getIndexCfs().getLiveSSTables();
            // emulate ongoing index compaction:
            CompactionInfo.Holder h = new MockHolder(i.getIndexCfs().metadata(), idxSSTables);
            CompactionManager.instance.active.beginCompaction(h);
            CompactionManager.instance.active.estimatedRemainingWriteBytes();
            CompactionManager.instance.active.finishCompaction(h);
        });
    }
}

@Test
public void test_only_coordinator_chooses_index_for_query() {
    for (int i = 0; i < 99; ++i) cluster.coordinator(1).execute(String.format("INSERT INTO %s (k, v) VALUES (?, ?)", tableName), ConsistencyLevel.ALL, i, i / 3);
    cluster.forEach(i -> i.flush(KEYSPACE));
    Pattern indexScanningPattern = Pattern.compile(String.format("Index mean cardinalities are v_index_%d:[-0-9]+. Scanning with v_index_%d.", seq.get(), seq.get()));
    for (int i = 0; i < 33; ++i) {
        UUID trace = TimeUUID.Generator.nextTimeUUID().asUUID();
        Object[][] result = cluster.coordinator(1).executeWithTracing(trace, String.format("SELECT * FROM %s WHERE v = ?", tableName), ConsistencyLevel.ALL, i);
        Assert.assertEquals("Failed on iteration " + i, 3, result.length);
        Awaitility.await("For all events in the tracing session to persist").pollInterval(100, TimeUnit.MILLISECONDS).atMost(10, TimeUnit.SECONDS).untilAsserted(() -> {
            Object[][] traces = cluster.coordinator(1).execute("SELECT source, activity FROM system_traces.events WHERE session_id = ?", ConsistencyLevel.ALL, trace);
            List<InetAddress> scanning = Arrays.stream(traces).filter(t -> indexScanningPattern.matcher(t[1].toString()).matches()).map(t -> (InetAddress) t[0]).distinct().collect(Collectors.toList());
            List<InetAddress> executing = Arrays.stream(traces).filter(t -> t[1].toString().equals(String.format("Executing read on " + tableName + " using index v_index_%d", seq.get()))).map(t -> (InetAddress) t[0]).distinct().collect(Collectors.toList());
            Assert.assertEquals(Collections.singletonList(cluster.get(1).broadcastAddress().getAddress()), scanning);
            Assert.assertEquals(3, executing.size());
        });
    }
}

