public void test() throws IOException {
    try (Cluster cluster = init(Cluster.build(2).withInstanceInitializer(BBHelper::install).withConfig(c -> c.with(Feature.values()).set("stream_entire_sstables", false).set("disk_failure_policy", "die")).start())) {
        cluster.schemaChange(withKeyspace("CREATE TABLE %s.tbl (p int, c int, v int, PRIMARY KEY(p, c))"));
