@Test
public void testRequestingPeerWatermarks() throws Throwable {
    try (Cluster cluster = builder().withNodes(3).withConfig(config -> config.with(GOSSIP).with(NETWORK)).start()) {
        init(cluster);
        IInvokableInstance cmsNode = cluster.get(1);
        ClusterUtils.waitForCMSToQuiesce(cluster, cmsNode);
        Epoch initialEpoch = getConsistentEpoch(cluster);
        int initialVal = getConsistentValue(cluster);
        assertEquals(-1, initialVal);
        Epoch expectedEpoch = initialEpoch.nextEpoch();
        final int expectedVal = new Random(System.nanoTime()).nextInt();
        cluster.get(3).runOnInstance(() -> {
            ClusterMetadataService.instance().commit(CustomTransformation.make(expectedVal));
        });
        ClusterUtils.waitForCMSToQuiesce(cluster, cmsNode);
        Epoch currentEpoch = getConsistentEpoch(cluster);
        assertTrue(currentEpoch.is(expectedEpoch));
        int currentVal = getConsistentValue(cluster);
        assertEquals(expectedVal, currentVal);
    }
}

@Test
public void testCatchUpOnRejection() throws Throwable {
    try (Cluster cluster = builder().withNodes(3).withConfig(config -> config.with(GOSSIP).with(NETWORK)).start()) {
        init(cluster);
        IInvokableInstance cmsNode = cluster.get(1);
        ClusterUtils.waitForCMSToQuiesce(cluster, cmsNode);
        cluster.coordinator(1).execute("CREATE KEYSPACE only_once WITH replication = {'class': 'SimpleStrategy', 'replication_factor': 1};", ConsistencyLevel.ONE);
        long cmsEpoch = cluster.get(1).callsOnInstance(() -> ClusterMetadata.current().epoch.getEpoch()).call();
        long epochBefore = cluster.get(2).callsOnInstance(() -> ClusterMetadata.current().epoch.getEpoch()).call();
        Assert.assertTrue(cmsEpoch > epochBefore);
        // should get rejected
        try {
            cluster.coordinator(2).execute("CREATE KEYSPACE only_once WITH replication = {'class': 'SimpleStrategy', 'replication_factor': 1};", ConsistencyLevel.ONE);
            Assert.fail("Creation should have failed");
        } catch (Throwable t) {
            Assert.assertTrue(t.getMessage().contains("Cannot add existing keyspace"));
            System.out.println("t.getMessage() = " + t.getMessage());
        }
        long epochAfter = cluster.get(2).callsOnInstance(() -> ClusterMetadata.current().epoch.getEpoch()).call();
        Assert.assertTrue(epochAfter > epochBefore);
    }
}

@Test
public void paxosRepairWithReversePartitionerTest() throws IOException, InterruptedException {
    try (Cluster cluster = init(Cluster.build(2).withConfig(c -> c.with(Feature.NETWORK, Feature.GOSSIP)).start())) {
        cluster.get(1).nodetoolResult("cms", "reconfigure", "2").asserts().success();
        cluster.schemaChange(withKeyspace("create table %s.tbl (id int primary key)"));
        for (int i = 0; i < 1000; i++) cluster.coordinator(1).execute(withKeyspace("insert into %s.tbl (id) values (?)"), ConsistencyLevel.ALL, i);
        cluster.forEach(i -> i.flush(KEYSPACE));
        // flush system.paxos to create some UncommittedTableData files
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) cluster.schemaChange(withKeyspace(String.format("alter table %%s.tbl with comment = 'comment " + i + j + "'", i, j)));
            cluster.forEach(inst -> inst.flush("system"));
        }
        // unflushed rows in the system.paxos memtable
        for (int i = 0; i < 3; i++) cluster.schemaChange(withKeyspace(String.format("alter table %%s.tbl with comment = 'comment x " + i + "'", i)));
        long start = Long.MIN_VALUE;
