@Test
public void test() throws Exception {
    IInvokableInstance paused = null;
    try (Cluster cluster = Cluster.build(8).withRacks(2, 4).withInstanceInitializer(new BB()).withConfig(c -> c.with(Feature.GOSSIP, Feature.NETWORK).set("transfer_hints_on_decommission", false).set("severity_during_decommission", 10000D).set("dynamic_snitch_badness_threshold", 0)).start()) {
        // failure happens in PendingRangeCalculatorService.update, so the keyspace is being removed
        cluster.setUncaughtExceptionsFilter((ignore, throwable) -> !"Unknown keyspace system_distributed".equals(throwable.getMessage()));
        fixDistributedSchemas(cluster);
        cluster.schemaChange("CREATE KEYSPACE " + KEYSPACE + " WITH replication = {'class': 'NetworkTopologyStrategy', 'datacenter1': 3, 'datacenter2': 3}");
        String table = KEYSPACE + ".tbl";
        cluster.schemaChange("CREATE TABLE " + table + " (pk blob PRIMARY KEY)");
        cluster.forEach(i -> i.runOnInstance(() -> Undead.State.enabled = true));
        List<IInvokableInstance> dc1 = cluster.get(1, 2, 3, 4);
        List<IInvokableInstance> dc2 = cluster.get(5, 6, 7, 8);
        IInvokableInstance toDecom = dc2.get(1);
        List<Murmur3Partitioner.LongToken> tokens = ClusterUtils.getLocalTokens(toDecom).stream().map(t -> new Murmur3Partitioner.LongToken(Long.parseLong(t))).collect(Collectors.toList());
        for (Murmur3Partitioner.LongToken token : tokens) {
            ByteBuffer key = Murmur3Partitioner.LongToken.keyForToken(token);
            toDecom.coordinator().execute("INSERT INTO " + table + "(pk) VALUES (?)", ConsistencyLevel.EACH_QUORUM, key);
        }
        paused = cluster.get(1);
        Callable<?> pending = pauseBeforeCommit(paused, (e) -> e instanceof PrepareLeave.StartLeave);
        CompletableFuture<Void> nodetool = CompletableFuture.runAsync(() -> toDecom.nodetoolResult("decommission").asserts().success());
        ClusterUtils.awaitGossipStateMatch(cluster, cluster.get(DECOM_NODE), ApplicationState.SEVERITY);
        pending.call();
        unpauseCommits(paused);
        paused = null;
        cluster.forEach(i -> i.runOnInstance(() -> ((DynamicEndpointSnitch) DatabaseDescriptor.getNodeProximity()).updateScores()));
        cluster.filters().verbs(Verb.GOSSIP_DIGEST_SYN.id).drop();
        nodetool.join();
        List<String> failures = new ArrayList<>();
        String query = getQuery(table);
        for (Murmur3Partitioner.LongToken token : tokens) {
            ByteBuffer key = Murmur3Partitioner.LongToken.keyForToken(token);
            for (IInvokableInstance i : dc1) {
                for (ConsistencyLevel cl : levels()) {
                    try {
                        Coordinators.withTracing(i.coordinator(), query, cl, key);
                    } catch (Coordinators.WithTraceException e) {
                        Throwable cause = e.getCause();
                        if (AssertionUtils.isInstanceof(WriteTimeoutException.class).matches(cause) || AssertionUtils.isInstanceof(ReadTimeoutException.class).matches(cause)) {
                            List<String> traceMesssages = Arrays.asList("Sending mutation to remote replica", "reading data from", "reading digest from");
                            SimpleQueryResult filtered = QueryResultUtil.query(e.trace).select("activity").filter(row -> traceMesssages.stream().anyMatch(row.getString("activity")::startsWith)).build();
                            InetAddressAndPort decomeNode = BB.address((byte) DECOM_NODE);
                            while (filtered.hasNext()) {
                                String log = filtered.next().getString("activity");
                                if (log.contains(decomeNode.toString()))
                                    failures.add("Failure with node" + i.config().num() + ", cl=" + cl + ";\n\t" + cause.getMessage() + ";\n\tTrace activity=" + log);
                            }
                        } else {
                            throw e;
                        }
                    }
                }
            }
        }
        if (!failures.isEmpty())
            throw new AssertionError(String.join("\n", failures));
        // since only one tests exists per file, shutdown without blocking so .close does not timeout
        try {
            FBUtilities.waitOnFutures(cluster.stream().map(IInstance::shutdown).collect(Collectors.toList()), 1, TimeUnit.MINUTES);
        } catch (Exception e) {
            // ignore
        }
    } finally {
        if (paused != null)
            unpauseCommits(paused);
    }
}

@Test
public void testDecommission() throws Throwable {
    try (Cluster control = init(Cluster.build().withNodes(3).withNodeProvisionStrategy(strategy).withConfig(config -> config.with(GOSSIP, NETWORK, NATIVE_PROTOCOL)).start());
        com.datastax.driver.core.Cluster cluster = com.datastax.driver.core.Cluster.builder().addContactPoint("127.0.0.1").build();
        Session session = cluster.connect()) {
        EventStateListener eventStateListener = new EventStateListener();
        session.getCluster().register(eventStateListener);
        control.get(3).nodetoolResult("disablebinary").asserts().success();
        control.get(3).nodetoolResult("decommission", "-f").asserts().success();
        await().atMost(5, TimeUnit.SECONDS).untilAsserted(() -> Assert.assertEquals(2, cluster.getMetadata().getAllHosts().size()));
        session.getCluster().unregister(eventStateListener);
        // DOWN UP can also be seen if the jvm is slow and connections are closed; to avoid this make sure to use
        // containsSequence to check that down/remove happen in this order
        assertThat(eventStateListener.events).containsSequence(new Event(Down, control.get(3)), new Event(Remove, control.get(3)));
    }
}

@Test
public void testRestartNode() throws Throwable {
    try (Cluster control = init(Cluster.build().withNodes(3).withNodeProvisionStrategy(strategy).withConfig(config -> config.with(GOSSIP, NETWORK, NATIVE_PROTOCOL)).start());
        com.datastax.driver.core.Cluster cluster = com.datastax.driver.core.Cluster.builder().addContactPoint("127.0.0.1").build();
