@Test
public void simpleUpgradeTest() {
    AtomicReference<Interruptible> executor = new AtomicReference<>();
    AtomicLong loops = new AtomicLong(0);
    Listener listener = new Listener();
    Runnable awaitHarryProgress = () -> {
        long startingLoopCount = loops.get();
        long deadline = startingLoopCount + 100;
        long nowNanos = System.nanoTime();
        boolean matched = false;
        for (int i = 0; i < 20 && !(matched = loops.get() >= deadline); i++) {
            try {
                TimeUnit.MILLISECONDS.sleep(500);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new UncheckedInterruptedException(e);
            }
        }
        if (!matched)
            throw new AssertionError("Harry did not make enough progress within " + Duration.ofNanos(System.nanoTime() - nowNanos) + "; starting loops " + startingLoopCount + ", ending loops " + loops.get());
    };
    withRandom(rng -> {
        new TestCase().nodes(3).nodesToUpgrade(1, 2, 3).withConfig((cfg) -> cfg.with(Feature.NETWORK, Feature.GOSSIP).set(Constants.KEY_DTEST_FULL_STARTUP, true)).upgradesToCurrentFrom(v41).withUpgradeListener(listener).setup((cluster) -> {
            SchemaSpec schema = new SchemaSpec(rng.next(), 10_000, "harry", "test_table", asList(pk("pk1", asciiType), pk("pk2", int64Type)), asList(ck("ck1", asciiType, false), ck("ck2", int64Type, false)), asList(regularColumn("regular1", asciiType), regularColumn("regular2", int64Type)), asList(staticColumn("static1", asciiType), staticColumn("static2", int64Type)));
            cluster.schemaChange(String.format("CREATE KEYSPACE IF NOT EXISTS %s WITH replication = {'class': 'SimpleStrategy', 'replication_factor': %d};", schema.keyspace, 3));
            cluster.schemaChange(schema.compile());
            HistoryBuilder history = new ReplayingHistoryBuilder(schema.valueGenerators, hb -> InJvmDTestVisitExecutor.builder().retryPolicy(retry -> true).nodeSelector(lts -> {
                while (true) {
                    int node = rng.nextInt(0, cluster.size()) + 1;
                    if (listener.isDown(node))
                        continue;
                    return node;
                }
            }).consistencyLevel(ConsistencyLevel.QUORUM).build(schema, hb, cluster));
            Generator<Integer> pkIdxGen = Generators.int32(0, Math.min(10_000, schema.valueGenerators.ckPopulation()));
            executor.set(executorFactory().infiniteLoop("R/W Worload", () -> {
                history.insert(pkIdxGen.generate(rng));
                history.selectPartition(pkIdxGen.generate(rng));
                loops.incrementAndGet();
            }, UNSAFE));
            awaitHarryProgress.run();
        }).runAfterNodeUpgrade((cluster, node) -> {
            // make sure harry executes in mixed mode
            awaitHarryProgress.run();
        }).runAfterClusterUpgrade((cluster) -> {
            // make sure we haven't persisted any events;
            cluster.stream().forEach((i) -> {
                Object[][] res = i.executeInternal(String.format("select * from %s.%s", SchemaConstants.SYSTEM_KEYSPACE_NAME, NAME));
                assertEquals(0, res.length);
            });
            cluster.get(1).nodetoolResult("cms", "initialize").asserts().success();
            cluster.get(1).nodetoolResult("cms", "reconfigure", "3").asserts().success();
            cluster.schemaChange(withKeyspace("create table %s.xyz (id int primary key)"));
            executor.get().shutdownNow();
            executor.get().awaitTermination(1, TimeUnit.MINUTES);
        }).run();
    });
}

@Test
public void hibernateUpgradeTest() throws Throwable {
    new TestCase().nodes(3).nodesToUpgrade(1, // not node3 - we manually upgrade that below
    2).withConfig((cfg) -> cfg.with(Feature.NETWORK, Feature.GOSSIP)).upgradesToCurrentFrom(v50).setup((cluster) -> {
        cluster.schemaChange("CREATE TABLE " + KEYSPACE + ".tbl (pk int, ck int, v int, PRIMARY KEY (pk, ck))");
        cluster.get(3).shutdown().get();
        // stopping a fully joined node and then starting it with join_ring=false puts it in hibernate status - it still owns tokens:
        withProperty(CassandraRelevantProperties.JOIN_RING, false, () -> cluster.get(3).startup());
        assertTrue(hibernating(cluster.get(1), "127.0.0.3"));
    }).runAfterClusterUpgrade((cluster) -> {
        // manually upgrade node3 to be able to keep join_ring=false
        cluster.get(3).shutdown().get();
        cluster.get(3).setVersion(Versions.find().getLatest(v51));
        assertTrue(hibernating(cluster.get(1), "127.0.0.3"));
        withProperty(CassandraRelevantProperties.JOIN_RING, false, () -> cluster.get(3).startup());
        cluster.forEach(i -> checkPlacements(i, true));
        assertTrue(hibernating(cluster.get(1), "127.0.0.3"));
        cluster.forEach(i -> checkPlacements(i, true));
        cluster.get(1).nodetoolResult("cms", "initialize").asserts().success();
        assertTrue(hibernating(cluster.get(1), "127.0.0.3"));
        cluster.forEach(i -> checkPlacements(i, true));
        // and remove join_ring=false and make sure it is no longer hibernating
        cluster.get(3).shutdown().get();
        cluster.get(3).startup();
        assertFalse(hibernating(cluster.get(1), "127.0.0.3"));
        cluster.forEach(i -> checkPlacements(i, true));
    }).run();
}

@Test
public void hibernateBadGossipUpgradeTest() throws Throwable {
    new TestCase().nodes(3).nodesToUpgrade(1, 2).withConfig((cfg) -> cfg.with(Feature.NETWORK, Feature.GOSSIP)).upgradesToCurrentFrom(v50).setup((cluster) -> {
        cluster.schemaChange("CREATE TABLE " + KEYSPACE + ".tbl (pk int, ck int, v int, PRIMARY KEY (pk, ck))");
        cluster.get(3).shutdown().get();
        withProperty(CassandraRelevantProperties.JOIN_RING, false, () -> cluster.get(3).startup());
        cluster.get(3).shutdown();
        assertTrue(hibernating(cluster.get(1), "127.0.0.3"));
        assertTrue(hibernating(cluster.get(2), "127.0.0.3"));
        // terrible - we might have old hibernating nodes in gossip which don't exist in peers_v2 - this
        // is an approximation of that state to be able to upgrade and ignore these nodes
        for (int i = 1; i <= 2; i++) cluster.get(i).executeInternal("delete from system.peers_v2 where peer = '127.0.0.3'");
    }).runAfterClusterUpgrade((cluster) -> {
        checkPlacements(cluster.get(1), false);
