@Test
public void upgradeMismatchTest() throws Throwable {
    new TestCase().nodes(3).nodesToUpgrade(1, 2, 3).withConfig((cfg) -> cfg.with(Feature.NETWORK, Feature.GOSSIP).set(Constants.KEY_DTEST_FULL_STARTUP, true)).upgradesToCurrentFrom(v50).setup((cluster) -> {
