    try (Cluster cluster = builder().withNodes(3).withTokenSupplier(TokenSupplier.evenlyDistributedTokens(4)).withNodeIdTopology(NetworkTopology.singleDcNetworkTopology(4, "dc0", "rack0")).withConfig((config) -> config.with(Feature.NETWORK, Feature.GOSSIP).set("write_request_timeout", "10s").set("metadata_snapshot_frequency", 5)).start();
        CloseableRef<IInvokableInstance> forShutdown = new CloseableRef<>(ClusterUtils::unpauseCommits)) {
