            RingAwareInJvmDTestVisitExecutor.replay(RingAwareInJvmDTestVisitExecutor.builder().replicationFactor(new TokenPlacementModel.SimpleReplicationFactor(2)).consistencyLevel(ConsistencyLevel.ALL).build(schema, history, cluster), history);
        });
    }
}

@Test
public void coordinatorIsBehindTest() throws Throwable {
    Generator<SchemaSpec> schemaGen = SchemaGenerators.schemaSpecGen(KEYSPACE, "coordinator_is_behind", 1000);
    try (Cluster cluster = builder().withNodes(3).withTokenSupplier(TokenSupplier.evenlyDistributedTokens(4)).withNodeIdTopology(NetworkTopology.singleDcNetworkTopology(4, "dc0", "rack0")).withConfig((config) -> config.with(Feature.NETWORK, Feature.GOSSIP).set("write_request_timeout", "10s").set("accord.enabled", false).set("cms_await_timeout", "60s").set("metadata_snapshot_frequency", 5)).start();
        CloseableRef<IInvokableInstance> forShutdown = new CloseableRef<>(ClusterUtils::unpauseCommits)) {
        IInvokableInstance cmsInstance = cluster.get(1);
        waitForCMSToQuiesce(cluster, cmsInstance);
        withRandom(rng -> {
            SchemaSpec schema = schemaGen.generate(rng);
            Generator<Integer> ckGen = Generators.int32(0, Math.min(schema.valueGenerators.ckPopulation(), 1000));
            HistoryBuilder history = new ReplayingHistoryBuilder(schema.valueGenerators, hb -> RingAwareInJvmDTestVisitExecutor.builder().replicationFactor(new TokenPlacementModel.SimpleReplicationFactor(3)).consistencyLevel(ConsistencyLevel.ALL).build(schema, hb, cluster));
            cluster.schemaChange(String.format("CREATE KEYSPACE %s WITH replication = {'class': 'SimpleStrategy', 'replication_factor' : 3};", KEYSPACE));
            cluster.schemaChange(schema.compile());
            waitForCMSToQuiesce(cluster, cluster.get(1));
            cluster.filters().verbs(Verb.TCM_REPLICATION.id, Verb.TCM_FETCH_CMS_LOG_RSP.id, Verb.TCM_FETCH_PEER_LOG_RSP.id, Verb.TCM_CURRENT_EPOCH_REQ.id).to(2).drop().on();
            DataTracker tracker = new DataTracker.SequentialDataTracker();
            RingAwareInJvmDTestVisitExecutor executor = RingAwareInJvmDTestVisitExecutor.builder().replicationFactor(new TokenPlacementModel.SimpleReplicationFactor(2)).nodeSelector(i -> 2).consistencyLevel(ConsistencyLevel.ALL).retryPolicy(InJvmDTestVisitExecutor.RetryPolicy.NO_RETRY).build(schema, tracker, new QuiescentChecker(schema.valueGenerators, tracker, history), cluster);
            // Prime the CMS node to pause before the finish join event is committed
            Callable<?> pending = pauseBeforeCommit(cmsInstance, (e) -> e instanceof PrepareJoin.MidJoin);
            forShutdown.set(cmsInstance);
            IInstanceConfig config = cluster.newInstanceConfig().set("auto_bootstrap", true).set(Constants.KEY_DTEST_FULL_STARTUP, true).set("progress_barrier_default_consistency_level", "NODE_LOCAL");
            IInvokableInstance newInstance = cluster.bootstrap(config);
            long[] metricCounts = new long[4];
            for (int i = 1; i <= 4; i++) metricCounts[i - 1] = cluster.get(i).callOnInstance(() -> TCMMetrics.instance.coordinatorBehindPlacements.getCount());
            Thread startup = new Thread(() -> newInstance.startup());
            startup.start();
            pending.call();
            long[] markers = new long[4];
            for (int n = 0; n < 4; n++) markers[n] = cluster.get(n + 1).logs().mark();
            boolean triggered = false;
            outer: for (int i = 0; i < history.valueGenerators().pkPopulation(); i++) {
                long pd = history.valueGenerators().pkGen().descriptorAt(i);
                for (TokenPlacementModel.Replica replica : executor.getReplicasFor(pd)) {
                    if (cluster.get(1).config().broadcastAddress().toString().contains(replica.node().id())) {
                        try {
                            HistoryBuilderHelper.insertRandomData(schema, i, ckGen.generate(rng), rng, history);
                        } catch (Throwable t) {
                            // ignore; expected
                        }
                    }
                }
                for (int n = 0; n < markers.length; n++) {
                    if (// skip 2nd node
                    (n + 1) == 2)
                        continue;
                    if (!cluster.get(n + 1).logs().grep(markers[n], "Routing is correct, but coordinator needs to catch-up").getResult().isEmpty()) {
                        triggered = true;
                        break outer;
                    }
                }
            }
            Assert.assertTrue("Should have triggered routing exception on the replica", triggered);
            boolean metricTriggered = false;
            for (int i = 1; i <= 4; i++) {
                long prevMetric = metricCounts[i - 1];
                long newMetric = cluster.get(i).callOnInstance(() -> TCMMetrics.instance.coordinatorBehindPlacements.getCount());
                if (newMetric - prevMetric > 0) {
                    metricTriggered = true;
                    break;
                }
            }
            Assert.assertTrue("Metric CoordinatorBehindRing should have been bumped by at least one replica", metricTriggered);
            cluster.filters().reset();
            unpauseCommits(cmsInstance);
            forShutdown.set(null);
            startup.join();
        });
    }
}

@Test
public void decommissionTest() throws Throwable {
    Generator<SchemaSpec> schemaGen = SchemaGenerators.schemaSpecGen(KEYSPACE, "decomission", 1000);
    IInvokableInstance forShutdown = null;
    try (Cluster cluster = builder().withNodes(3).withTokenSupplier(TokenSupplier.evenlyDistributedTokens(3)).withNodeIdTopology(NetworkTopology.singleDcNetworkTopology(3, "dc0", "rack0")).appendConfig(c -> c.with(Feature.NETWORK)).start()) {
        IInvokableInstance cmsInstance = cluster.get(1);
        forShutdown = cmsInstance;
        IInvokableInstance leavingInstance = cluster.get(2);
        waitForCMSToQuiesce(cluster, cmsInstance);
        withRandom(rng -> {
            SchemaSpec schema = schemaGen.generate(rng);
            Generators.TrackingGenerator<Integer> pkGen = Generators.tracking(Generators.int32(0, Math.min(schema.valueGenerators.pkPopulation(), 1000)));
            Generator<Integer> ckGen = Generators.int32(0, Math.min(schema.valueGenerators.ckPopulation(), 1000));
            HistoryBuilder history = new ReplayingHistoryBuilder(schema.valueGenerators, (hb) -> RingAwareInJvmDTestVisitExecutor.builder().replicationFactor(new TokenPlacementModel.SimpleReplicationFactor(2)).consistencyLevel(ConsistencyLevel.ALL).retryPolicy(InJvmDTestVisitExecutor.RetryPolicy.RETRY_ON_TIMEOUT).nodeSelector(lts -> 1).build(schema, hb, cluster));
            Runnable writeAndValidate = () -> {
                for (int i = 0; i < WRITES; i++) history.insert(pkGen.generate(rng), ckGen.generate(rng));
                for (int pk : pkGen.generated()) history.selectPartition(pk);
            };
            cluster.schemaChange(String.format("CREATE KEYSPACE %s WITH replication = {'class': 'SimpleStrategy', 'replication_factor' : 2};", KEYSPACE));
            cluster.schemaChange(schema.compile());
            waitForCMSToQuiesce(cluster, cmsInstance);
            writeAndValidate.run();
            history.customThrowing(() -> {
                // Prime the CMS node to pause before the finish leave event is committed
                Callable<?> pending = pauseBeforeCommit(cmsInstance, (e) -> e instanceof PrepareLeave.FinishLeave);
                new Thread(() -> leavingInstance.runOnInstance(() -> StorageService.instance.decommission(true))).start();
                pending.call();
                waitForCMSToQuiesce(cluster, cmsInstance);
                assertGossipStatus(cluster, leavingInstance.config().num(), "LEAVING");
            }, "Start Leave");
            writeAndValidate.run();
            history.customThrowing(() -> {
                // Make sure there can be only one FinishLeave in flight
                waitForCMSToQuiesce(cluster, cmsInstance);
                // set expectation of finish leave & retrieve the sequence when it gets committed
                Epoch currentEpoch = getClusterMetadataVersion(cmsInstance);
                Callable<Epoch> finishedLeaving = getSequenceAfterCommit(cmsInstance, (e, r) -> e instanceof PrepareLeave.FinishLeave && r.isSuccess());
                unpauseCommits(cmsInstance);
                Epoch nextEpoch = finishedLeaving.call();
                Assert.assertEquals(String.format("Epoch %s should have immediately superseded epoch %s.", nextEpoch, currentEpoch), nextEpoch.getEpoch(), currentEpoch.getEpoch() + 1);
                // wait for the cluster to all witness the finish join event
                waitForCMSToQuiesce(cluster, nextEpoch);
                assertGossipStatus(cluster, leavingInstance.config().num(), "LEFT");
            }, "Finish leave");
            writeAndValidate.run();
        });
    } catch (Throwable t) {
        if (forShutdown != null)
            unpauseCommits(forShutdown);
        throw t;
    }
}

