    TableMetadata metadata = defaultTable().addPartitionKeyColumn("pk0", InetAddressType.instance).addClusteringColumn("ck0", ReversedType.getInstance(ShortType.instance)).addRegularColumn("v0", TimestampType.instance).addRegularColumn("v1", LexicalUUIDType.instance).build();
