            for (int i = 0; i < order.length; i++) columns.add(ColumnSpec.ck("test", ColumnSpec.asciiType, order[i]));
            InvertibleGenerator<Object[]> generator = new InvertibleGenerator<>(rng, MAX_ENTROPY, 100, SchemaSpec.forKeys(columns), (Object[] a, Object[] b) -> HistoryBuilder.compareKeys(columns, a, b));
            Object[] previous = null;
            for (int i = 0; i < 100; i++) {
                long descr = generator.descriptorAt(i);
                Object[] next = generator.inflate(descr);
                if (previous != null)
                    Assert.assertTrue(HistoryBuilder.compareKeys(columns, next, previous) > 0);
                Assert.assertEquals(descr, generator.deflate(next));
                previous = next;
            }
        }
    });
}

