public void manyEpochsAndAccordConverges() throws IOException {
    simulate(simulation -> {
        // setup
        ClusterActions.Options options = noActions(simulation.cluster.size());
        ClusterActions clusterActions = new ClusterActions(simulation.simulated, simulation.cluster, options, new ClusterActionListener.NoOpListener(), new Debug(new EnumMap<>(Debug.Info.class), new int[0]));
        return ActionList.of(clusterActions.initializeCluster(initializeAll(simulation.cluster.size())), simulation.schemaChange(1, "CREATE KEYSPACE ks WITH replication = {'class': 'NetworkTopologyStrategy', 'replication_factor' : 3}"), simulation.schemaChange(1, "CREATE TABLE IF NOT EXISTS ks.tbl (pk int PRIMARY KEY, v int) WITH " + TransactionalMode.full.asCqlParam()));
    }, simulation -> {
        // test
        RandomSource random = simulation.simulated.random;
        int numEpochs = 100;
        List<Action> actions = new ArrayList<>(numEpochs);
        for (int i = 0; i < numEpochs; i++) {
            int node = random.uniform(1, simulation.cluster.size() + 1);
            actions.add(simulation.schemaChange(node, "ALTER TABLE ks.tbl WITH comment = 'step=" + i + '\'', EpochStressTest::allowedExceptions));
        }
        return ActionList.of(actions);
    }, simulation -> {
        // teardown
        List<Action> actions = new ArrayList<>(simulation.cluster.size());
        for (int i = 0; i < simulation.cluster.size(); i++) actions.add(HarrySimulatorTest.lazy(simulation.simulated, simulation.cluster.get(i + 1), EpochStressTest::validate));
        return ActionList.of(actions);
    }, config -> config.nodes(3, 3).dcs(1, 1).threadCount(100), (rs, config) -> {
        // Cluster defaults cause ~100% test failure before reaching 100 epochs, so we cover this case
        // for potential visibility violations. With CMS retry configs at 1h, failure rate drops to 10%
        // and more seeds complete all 100 epochs.
        // 30% of the time use the cluster defaults, so have a high failure rate for TCM transactions
        if (rs.decide(0.3f))
            return;
        // Make the retry rate long enough that it should recover most of the time.
        // As of this moment this only impacts CMS nodes, so if the CQL is sent to a non-CMS node then request_timeout is used for retry timeout, which makes this fail ~10% of the time
        config.set("cms_await_timeout", "3600s").set("cms_retry_delay", "3600s").set("cms_default_max_retries", Integer.toString(Integer.MAX_VALUE));
    });
}

