@Test
public void testCqlUSERCommandsAuditing() {
    //CREATE USER and ALTER USER are supported only for backwards compatibility.
    String user = TEST_ROLE + "user";
    String cql = "CREATE USER " + user + " WITH PASSWORD '" + TEST_PW + "'";
    executeWithCredentials(Arrays.asList(cql), CASS_USER, CASS_PW, AuditLogEntryType.LOGIN_SUCCESS);
    assertTrue(getInMemAuditLogger().size() > 0);
    AuditLogEntry logEntry = getInMemAuditLogger().poll();
    assertLogEntry(logEntry, AuditLogEntryType.CREATE_ROLE, "CREATE USER " + user + " WITH PASSWORD '" + PasswordObfuscator.OBFUSCATION_TOKEN + "'", CASS_USER, TEST_PW);
    cql = "ALTER USER " + user + " WITH PASSWORD '" + TEST_PW + "'";
    executeWithCredentials(Arrays.asList(cql), CASS_USER, CASS_PW, AuditLogEntryType.LOGIN_SUCCESS);
    assertTrue(getInMemAuditLogger().size() > 0);
    logEntry = getInMemAuditLogger().poll();
    assertLogEntry(logEntry, AuditLogEntryType.ALTER_ROLE, "ALTER USER " + user + " WITH PASSWORD '" + PasswordObfuscator.OBFUSCATION_TOKEN + "'", CASS_USER, TEST_PW);
    cql = "ALTER USER " + user + " WITH PASSWORD " + TEST_PW;
    executeWithCredentials(Arrays.asList(cql), CASS_USER, CASS_PW, AuditLogEntryType.LOGIN_SUCCESS);
    assertTrue(getInMemAuditLogger().size() > 0);
    logEntry = getInMemAuditLogger().poll();
    assertLogEntry(logEntry, AuditLogEntryType.REQUEST_FAILURE, "ALTER USER " + user + " WITH PASSWORD " + PasswordObfuscator.OBFUSCATION_TOKEN + "; Syntax Exception. Obscured for security reasons.", CASS_USER, TEST_PW);
}

