@Test
public void fromMapTest() {
    int storagePort = 123;
    Config.CommitLogSync commitLogSync = Config.CommitLogSync.batch;
    ParameterizedClass seedProvider = new ParameterizedClass("org.apache.cassandra.locator.SimpleSeedProvider", Collections.emptyMap());
    Map<String, Object> encryptionOptions = ImmutableMap.of("cipher_suites", Collections.singletonList("FakeCipher"), "optional", false, "enabled", true);
    Map<String, Object> autoRepairConfig = ImmutableMap.of("enabled", true, "global_settings", ImmutableMap.of("number_of_repair_threads", 1), "repair_type_overrides", ImmutableMap.of("full", ImmutableMap.of("number_of_repair_threads", 2)));
    Map<String, Object> map = new ImmutableMap.Builder<String, Object>().put("storage_port", storagePort).put("commitlog_sync", commitLogSync).put("seed_provider", seedProvider).put("client_encryption_options", encryptionOptions).put("internode_socket_send_buffer_size", "5B").put("internode_socket_receive_buffer_size", "5B").put("commitlog_sync_group_window_in_ms", "42").put("auto_repair", autoRepairConfig).build();
    Config config = YamlConfigurationLoader.fromMap(map, Config.class);
    // Check a simple integer
    assertEquals(storagePort, config.storage_port);
    // Check an enum
    assertEquals(commitLogSync, config.commitlog_sync);
    // Check a parameterized class
    assertEquals(seedProvider, config.seed_provider);
    // Check a nested object
    assertEquals(false, config.client_encryption_options.optional);
    // Check a nested object
    assertEquals(true, config.client_encryption_options.enabled);
    // Check names backward compatibility (CASSANDRA-17141 and CASSANDRA-15234)
    assertEquals(new DataStorageSpec.IntBytesBound("5B"), config.internode_socket_send_buffer_size);
    // Check names backward compatibility (CASSANDRA-17141 and CASSANDRA-15234)
    assertEquals(new DataStorageSpec.IntBytesBound("5B"), config.internode_socket_receive_buffer_size);
    assertTrue(config.auto_repair.enabled);
    assertEquals(new DurationSpec.IntSecondsBound("6h"), config.auto_repair.getAutoRepairTableMaxRepairTime(AutoRepairConfig.RepairType.INCREMENTAL));
    config.auto_repair.setMaterializedViewRepairEnabled(AutoRepairConfig.RepairType.INCREMENTAL, false);
}

