    assertThatThrownBy(() -> createTable("CREATE TABLE %s (pk int, cl " + typeString + " CHECK NOT NULL, PRIMARY KEY (pk, cl))")).isInstanceOf(InvalidRequestException.class).hasRootCauseInstanceOf(InvalidConstraintDefinitionException.class).hasRootCauseMessage("NOT_NULL constraint can not be specified on a clustering key column 'cl'");
}

