@Test
public void testNotNullConstraintValidation() {
    unaryConstraint.setColumnName(columnIdentifier);
    scalarConstraint.setColumnName(columnIdentifier);
    functionConstraint.setColumnName(columnIdentifier);
    // unary
    unaryConstraint.validate(getColumnOfType(UTF8Type.instance));
    assertThatThrownBy(() -> unaryConstraint.evaluate(UTF8Type.instance, EMPTY_BYTE_BUFFER)).hasMessage("Column value does not satisfy value constraint for column 'a_column' as it is null.").isInstanceOf(ConstraintViolationException.class);
    // not null / empty
    unaryConstraint.evaluate(UTF8Type.instance, UTF8Type.instance.fromString("a value"));
    // scalar
    scalarConstraint.validate(getColumnOfType(Int32Type.instance));
    assertThatThrownBy(() -> scalarConstraint.evaluate(Int32Type.instance, EMPTY_BYTE_BUFFER)).hasMessage("Column value does not satisfy value constraint for column 'a_column' as it is null.").isInstanceOf(ConstraintViolationException.class);
    // function, e.g. length
    functionConstraint.validate(getColumnOfType(UTF8Type.instance));
    assertThatThrownBy(() -> functionConstraint.evaluate(UTF8Type.instance, EMPTY_BYTE_BUFFER)).hasMessage("Column value does not satisfy value constraint for column 'a_column' as it is null.").isInstanceOf(ConstraintViolationException.class);
    // empty string is not _null_ string so this passes
    unaryConstraint.evaluate(UTF8Type.instance, UTF8Type.instance.fromString(""));
    // test a type for which empty value is meaningless
    assertThatThrownBy(() -> unaryConstraint.evaluate(UUIDType.instance, ByteBuffer.allocate(0))).hasMessage("Column value does not satisfy value constraint for column 'a_column' as it is empty.").isInstanceOf(ConstraintViolationException.class);
}

