@Test
public void testTimeConstraint() {
    evaluateTime(EQ, "12:00:00", "12:00:00");
    evaluateTime(NEQ, "12:00:00", "11:00:00");
    evaluateTime(LT, "12:00:00", "11:00:00");
    evaluateTime(GT, "12:00:00", "13:00:00");
    evaluateTime(GT, "12:00:00", "12:00:00.1234");
    evaluateTime(GTE, "12:00:00", "12:00:00");
    evaluateTime(LTE, "12:00:00", "12:00:00");
    assertThatThrownBy(() -> evaluateTime(GT, "12:00:00", "01:00:00")).isInstanceOf(ConstraintViolationException.class);
    assertThatThrownBy(() -> evaluateTime(LT, "12:00:00", "13:00:00")).isInstanceOf(ConstraintViolationException.class);
    assertThatThrownBy(() -> evaluateTime(LT, "-3:00:00", "13:00:00")).isInstanceOf(ConstraintViolationException.class).hasMessage(cantParse("-3:00:00"));
    evaluate(timeColumn, TimeType.instance, GT, "06:00:00", LT, "15:00:00", "12:00:00");
    assertThatThrownBy(() -> evaluate(timeColumn, TimeType.instance, GT, "06:00:00", LT, "15:00:00", "18:00:00")).isInstanceOf(ConstraintViolationException.class).hasMessage("Column value does not satisfy value constraint for column 'a_column'. It should be a_column < '15:00:00'");
    assertThatThrownBy(() -> evaluate(timeColumn, TimeType.instance, GT, "06:00:00", LT, "03:00:00", "18:00:00")).isInstanceOf(InvalidConstraintDefinitionException.class).hasMessage("Constraints of scalar are not satisfiable: a_column > '06:00:00', a_column < '03:00:00'");
}

