@Test
public void testTimeCastsInSelectionClause() throws Throwable {
    createTable("CREATE TABLE %s (a timeuuid primary key, b timestamp, c date, d time)");
    final String yearMonthDay = "2015-05-21";
    final LocalDate localDate = LocalDate.of(2015, 5, 21);
    ZonedDateTime date = localDate.atStartOfDay(ZoneOffset.UTC);
    ZonedDateTime dateTime = ZonedDateTime.of(localDate, LocalTime.of(11, 3, 2), ZoneOffset.UTC);
    long timeInMillis = dateTime.toInstant().toEpochMilli();
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, '" + yearMonthDay + " 11:03:02+00', '2015-05-21', '11:03:02')", TimeUUID.Generator.atUnixMillis(timeInMillis));
    assertRows(execute("SELECT CAST(a AS timestamp), " + "CAST(b AS timestamp), " + "CAST(c AS timestamp) FROM %s"), row(Date.from(dateTime.toInstant()), Date.from(dateTime.toInstant()), Date.from(date.toInstant())));
    int timeInMillisToDay = SimpleDateSerializer.timeInMillisToDay(date.toInstant().toEpochMilli());
    assertRows(execute("SELECT CAST(a AS date), " + "CAST(b AS date), " + "CAST(c AS date) FROM %s"), row(timeInMillisToDay, timeInMillisToDay, timeInMillisToDay));
    assertRows(execute("SELECT CAST(b AS text), " + "CAST(c AS text), " + "CAST(d AS text) FROM %s"), row(yearMonthDay + "T11:03:02.000Z", yearMonthDay, "11:03:02.000000000"));
}

