/**
 * Verifies that the {@code CAST} function can be used in the {@code WHERE} clause of {@code CREATE MATERIALIZED
 * VIEW} statements.
 */
@Test
public void testCastsInCreateViewWhereClause() throws Throwable {
    createTable("CREATE TABLE %s (k int PRIMARY KEY, v int)");
    String viewName = keyspace() + ".mv_with_cast";
    execute(String.format("CREATE MATERIALIZED VIEW %s AS SELECT * FROM %%s" + "   WHERE k < CAST(3.14 AS int) AND v IS NOT NULL" + "   PRIMARY KEY (v, k)", viewName));
    // start storage service so MV writes are applied
    StorageService.instance.initServer();
    execute("INSERT INTO %s (k, v) VALUES (1, 10)");
    execute("INSERT INTO %s (k, v) VALUES (2, 20)");
    execute("INSERT INTO %s (k, v) VALUES (3, 30)");
    assertRows(execute(String.format("SELECT * FROM %s", viewName)), row(10, 1), row(20, 2));
    execute("DROP MATERIALIZED VIEW " + viewName);
}

@Test
public void testTransformationKind() throws CharacterCodingException {
    int max = -1;
    for (Transformation.Kind kind : Transformation.Kind.values()) {
        Arguments arguments = transformationKind.newArguments(ProtocolVersion.CURRENT);
        arguments.set(0, Int32Type.instance.decompose(kind.id));
        assertEquals(kind.name(), ByteBufferUtil.string(transformationKind.execute(arguments)));
        if (kind.id > max)
            max = kind.id;
    }
    for (int boundary : new int[] { -1, max + 1 }) {
        Arguments arguments = transformationKind.newArguments(ProtocolVersion.CURRENT);
        arguments.set(0, Int32Type.instance.decompose(boundary));
        try {
            transformationKind.execute(arguments);
        } catch (Exception e) {
            Assertions.assertThat(e).isInstanceOf(InvalidRequestException.class).hasMessageContaining(boundary + " is not a valid Transformation.Kind id");
        }
    }
}

@Test
public void testNotNumericCollection() throws Throwable {
    createTable("CREATE TABLE %s (k int PRIMARY KEY, v uuid, l list<text>, s set<boolean>, fl frozen<list<text>>, fs frozen<set<boolean>>)");
    // sum
    assertInvalidThrowMessage("Function system.collection_sum requires a numeric set/list argument, " + "but found argument v of type uuid", InvalidRequestException.class, "SELECT collection_sum(v) FROM %s");
    assertInvalidThrowMessage("Function system.collection_sum requires a numeric set/list argument, " + "but found argument l of type list<text>", InvalidRequestException.class, "SELECT collection_sum(l) FROM %s");
    assertInvalidThrowMessage("Function system.collection_sum requires a numeric set/list argument, " + "but found argument s of type set<boolean>", InvalidRequestException.class, "SELECT collection_sum(s) FROM %s");
    assertInvalidThrowMessage("Function system.collection_sum requires a numeric set/list argument, " + "but found argument fl of type frozen<list<text>>", InvalidRequestException.class, "SELECT collection_sum(fl) FROM %s");
    assertInvalidThrowMessage("Function system.collection_sum requires a numeric set/list argument, " + "but found argument fs of type frozen<set<boolean>>", InvalidRequestException.class, "SELECT collection_sum(fs) FROM %s");
    // avg
    assertInvalidThrowMessage("Function system.collection_avg requires a numeric set/list argument, " + "but found argument v of type uuid", InvalidRequestException.class, "SELECT collection_avg(v) FROM %s");
    assertInvalidThrowMessage("Function system.collection_avg requires a numeric set/list argument, " + "but found argument l of type list<text>", InvalidRequestException.class, "SELECT collection_avg(l) FROM %s");
    assertInvalidThrowMessage("Function system.collection_avg requires a numeric set/list argument, " + "but found argument s of type set<boolean>", InvalidRequestException.class, "SELECT collection_avg(s) FROM %s");
    assertInvalidThrowMessage("Function system.collection_avg requires a numeric set/list argument, " + "but found argument fl of type frozen<list<text>>", InvalidRequestException.class, "SELECT collection_avg(fl) FROM %s");
    assertInvalidThrowMessage("Function system.collection_avg requires a numeric set/list argument, " + "but found argument fs of type frozen<set<boolean>>", InvalidRequestException.class, "SELECT collection_avg(fs) FROM %s");
}

