@Test
public void testSimpleTypes() throws Throwable {
    createTable("CREATE TABLE %s (k int PRIMARY KEY, " + "tinyint tinyint, " + "smallint smallint, " + "int int, " + "bigint bigint, " + "float float, " + "double double, " + "varint varint, " + "decimal decimal, " + "text text, " + "ascii ascii, " + "boolean boolean, " + "date date, " + "timestamp timestamp, " + "duration duration, " + "uuid uuid, " + "timeuuid timeuuid," + "inet inet," + "blob blob)");
    // Test with empty table
    String select = "SELECT " + "identity(tinyint),  identity(smallint), identity(int), " + "identity(bigint), identity(float), identity(double), " + "identity(varint), identity(decimal), identity(text), " + "identity(ascii), identity(boolean), identity(date), " + "identity(timestamp), identity(duration), identity(uuid), " + "identity(timeuuid), identity(inet), identity(blob) " + "FROM %s";
    UntypedResultSet rs = execute(select);
    assertColumnNames(rs, "system.identity(tinyint)", "system.identity(smallint)", "system.identity(int)", "system.identity(bigint)", "system.identity(float)", "system.identity(double)", "system.identity(varint)", "system.identity(decimal)", "system.identity(text)", "system.identity(ascii)", "system.identity(boolean)", "system.identity(date)", "system.identity(timestamp)", "system.identity(duration)", "system.identity(uuid)", "system.identity(timeuuid)", "system.identity(inet)", "system.identity(blob)");
    assertEmpty(rs);
    // Test with not-empty table
    Object[] row = row((byte) 1, (short) 1, 123, 123L, 1.23f, 1.23d, bigint, bigdecimal, "ábc", "abc", true, 1, date, duration, uuid, timeUUID, inet, blob);
    execute("INSERT INTO %s (k, tinyint, smallint, int, bigint, float, double, varint, decimal, " + "text, ascii, boolean, date, timestamp, duration, uuid, timeuuid, inet, blob) " + "VALUES (1, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", row);
    assertRows(execute(select), row);
    // Test with bind markers
    execute("INSERT INTO %s (k, tinyint, smallint, int, bigint, float, double, varint, decimal, " + "text, ascii, boolean, date, timestamp, duration, uuid, timeuuid, inet, blob) " + "VALUES (1, " + "identity(?), identity(?), identity(?), identity(?), identity(?), identity(?), " + "identity(?), identity(?), identity(?), identity(?), identity(?), identity(?), " + "identity(?), identity(?), identity(?), identity(?), identity(?), identity(?))", row);
    assertRows(execute(select), row);
    // Test literals
    testLiteral("(tinyint) 1", (byte) 1);
    testLiteral("(smallint) 1", (short) 1);
    testLiteral(123);
    testLiteral(1234567890123L);
    testLiteral(1.23);
    testLiteral(1234567.1234567D);
    testLiteral(bigint);
    testLiteral(bigdecimal);
    testLiteral("'abc'", "abc");
    testLiteral("'ábc'", "ábc");
    testLiteral(true);
    testLiteral(false);
    testLiteral("(timestamp) '1970-01-01 00:00:00.000+0000'", new Date(0));
    testLiteral("(time) '00:00:00.000000'", 0L);
    testLiteral(duration);
    testLiteral(uuid);
    testLiteral(timeUUID);
    testLiteral("(inet) '0.0.0.0'", inet);
    testLiteral("0x" + ByteBufferUtil.bytesToHex(blob), blob);
}

@Test
public void testSets() throws Throwable {
    createTable("CREATE TABLE %s (k int PRIMARY KEY, s set<int>, fs frozen<set<int>>)");
    // Test with empty table
    String select = "SELECT identity(s), identity(fs) FROM %s";
    UntypedResultSet rs = execute(select);
    assertColumnNames(rs, "system.identity(s)", "system.identity(fs)");
    assertEmpty(rs);
    // Test with not-empty table
    execute("INSERT INTO %s (k, s, fs) VALUES (1, {1, 2}, {1, 2})");
    execute("INSERT INTO %s (k, s, fs) VALUES (2, {1, 2, 3}, {1, 2, 3})");
    execute("INSERT INTO %s (k, s, fs) VALUES (3, {2, 1}, {2, 1})");
    assertRows(execute(select), row(set(1, 2), set(1, 2)), row(set(1, 2, 3), set(1, 2, 3)), row(set(2, 1), set(2, 1)));
    // Test with bind markers
    Object[] row = row(set(1, 2, 3), set(4, 5, 6));
    execute("INSERT INTO %s (k, s, fs) VALUES (4, identity(?), identity(?))", row);
    assertRows(execute("SELECT s, fs FROM %s WHERE k = 4"), row);
    // Test literals
    testLiteralFails("[]");
    testLiteral("{1, 1234567890}", set(1, 1234567890));
    testLiteral(String.format("{1, %s}", bigint), set(BigInteger.ONE, bigint));
    testLiteral("{'abc'}", set("abc"));
    testLiteral("{'ábc'}", set("ábc"));
    testLiteral("{'abc', 'ábc'}", set("abc", "ábc"));
    testLiteral("{'ábc', 'abc'}", set("ábc", "abc"));
    testLiteral("{true}", set(true));
    testLiteral("{false}", set(false));
    testLiteral(String.format("{%s}", uuid), set(uuid));
    testLiteral(String.format("{%s}", timeUUID), set(timeUUID));
    testLiteral(String.format("{%s, %s}", uuid, timeUUID), set(uuid, timeUUID.asUUID()));
}

