@Test
public void queryIndexedSSTableTest() throws Throwable {
    // That test reproduces the bug from CASSANDRA-10903 and the fact we have a static column is
    // relevant to that reproduction in particular as it forces a slightly different code path that
    // if there wasn't a static.
    int ROWS = 1000;
    int VALUE_LENGTH = 100;
    createTable("CREATE TABLE %s (k int, t int, s text static, v text, PRIMARY KEY (k, t))");
    // We create a partition that is big enough that the underlying sstable will be indexed
    // For that, we use a large-ish number of row, and a value that isn't too small.
    String text = TombstonesWithIndexedSSTableTest.makeRandomString(VALUE_LENGTH);
    for (int i = 0; i < ROWS; i++) execute("INSERT INTO %s(k, t, v) VALUES (?, ?, ?)", 0, i, text + i);
    flush();
    compact();
    // Sanity check that we're testing what we want to test, that is that we're reading from an indexed
    // sstable. Note that we'll almost surely have a single indexed sstable in practice, but it's theorically
    // possible for a compact strategy to yield more than that and as long as one is indexed we're pretty
    // much testing what we want. If this check ever fails on some specific setting, we'll have to either
    // tweak ROWS and VALUE_LENGTH, or skip the test on those settings.
    DecoratedKey dk = Util.dk(ByteBufferUtil.bytes(0));
    boolean hasIndexed = false;
    for (SSTableReader sstable : getCurrentColumnFamilyStore().getLiveSSTables()) {
        class IndexEntryAccessor extends ForwardingSSTableReader {

            public IndexEntryAccessor(SSTableReader delegate) {
                super(delegate);
            }

            public AbstractRowIndexEntry getRowIndexEntry(PartitionPosition key, Operator op, boolean updateCacheAndStats, SSTableReadsListener listener) {
                return super.getRowIndexEntry(key, op, updateCacheAndStats, listener);
            }
        }
        IndexEntryAccessor accessor = new IndexEntryAccessor(sstable);
        AbstractRowIndexEntry indexEntry = accessor.getRowIndexEntry(dk, SSTableReader.Operator.EQ, false, SSTableReadsListener.NOOP_LISTENER);
        hasIndexed |= indexEntry != null && indexEntry.isIndexed();
    }
    assert hasIndexed;
    assertRowCount(execute("SELECT s FROM %s WHERE k = ?", 0), ROWS);
    assertRowCount(execute("SELECT s FROM %s WHERE k = ? ORDER BY t DESC", 0), ROWS);
    assertRowCount(execute("SELECT DISTINCT s FROM %s WHERE k = ?", 0), 1);
    assertRowCount(execute("SELECT DISTINCT s FROM %s WHERE k = ? ORDER BY t DESC", 0), 1);
}

@Test
public void test() {
    // in accord branch there is a much cleaner api for this pattern...
    Gen<AbstractTypeGenerators.ValueDomain> domainGen = SourceDSL.integers().between(1, 100).map(i -> i < 2 ? AbstractTypeGenerators.ValueDomain.NULL : i < 4 ? AbstractTypeGenerators.ValueDomain.EMPTY_BYTES : AbstractTypeGenerators.ValueDomain.NORMAL);
    Gen<SSTableFormat<?, ?>> sstableFormatGen = CassandraGenerators.sstableFormat();
    qt().checkAssert(random -> {
        resetSchema();
        // TODO : when table level override of sstable format is allowed, migrate to that
        DatabaseDescriptor.setSelectedSSTableFormat(sstableFormatGen.generate(random));
        Gen<String> udtName = Generators.unique(IDENTIFIER_GEN);
        TypeGenBuilder withoutUnsafeEquality = AbstractTypeGenerators.withoutUnsafeEquality().withUDTNames(udtName);
        TableMetadata metadata = new TableMetadataBuilder().withKeyspaceName(KEYSPACE).withTableKinds(TableMetadata.Kind.REGULAR).withKnownMemtables().withDefaultTypeGen(AbstractTypeGenerators.builder().withoutEmpty().withMaxDepth(2).withDefaultSetKey(withoutUnsafeEquality).withoutTypeKinds(AbstractTypeGenerators.TypeKind.COUNTER).withUDTNames(udtName)).withPartitionColumnsCount(1).withPrimaryColumnTypeGen(new TypeGenBuilder(withoutUnsafeEquality).// map of vector of map crossed the size cut-off for one of the tests, so changed max depth from 2 to 1, so we can't have the second map
        withMaxDepth(1)).withClusteringColumnsBetween(1, 2).withRegularColumnsBetween(1, 5).withStaticColumnsBetween(0, 2).build(random);
        maybeCreateUDTs(metadata);
        String createTable = metadata.toCqlString(true, false, false);
        // just to make the CREATE TABLE stmt easier to read for CUSTOM types
        createTable = createTable.replaceAll("org.apache.cassandra.db.marshal.", "");
        createTable(KEYSPACE, createTable);
        serde(ClusterMetadata.current(), metadata);
        Gen<ByteBuffer[]> dataGen = CassandraGenerators.data(metadata, domainGen);
        String insertStmt = insertStmt(metadata);
        int partitionColumnCount = metadata.partitionKeyColumns().size();
        int primaryColumnCount = primaryColumnCount(metadata);
        String selectStmt = selectStmt(metadata);
        String tokenStmt = tokenStmt(metadata);
        for (int i = 0; i < 100; i++) {
            ByteBuffer[] expected = dataGen.generate(random);
            try {
                ByteBuffer[] partitionKeys = Arrays.copyOf(expected, partitionColumnCount);
                ByteBuffer[] rowKey = Arrays.copyOf(expected, primaryColumnCount);
                execute(insertStmt, (Object[]) expected);
                // check memtable
                assertRows(execute(selectStmt, (Object[]) rowKey), expected);
                assertRows(execute(tokenStmt, (Object[]) partitionKeys), partitionKeys);
                assertRowsNet(executeNet(selectStmt, (Object[]) rowKey), expected);
                // check sstable
                flush(KEYSPACE, metadata.name);
                compact(KEYSPACE, metadata.name);
                assertRows(execute(selectStmt, (Object[]) rowKey), expected);
                assertRows(execute(tokenStmt, (Object[]) partitionKeys), partitionKeys);
                assertRowsNet(executeNet(selectStmt, (Object[]) rowKey), expected);
                execute("TRUNCATE " + metadata);
            } catch (Throwable t) {
                Iterator<ColumnMetadata> it = metadata.allColumnsInSelectOrder();
                List<String> literals = new ArrayList<>(expected.length);
                for (int idx = 0; idx < expected.length; idx++) {
                    assert it.hasNext();
                    ColumnMetadata meta = it.next();
                    ByteBuffer expct = expected[idx];
                    literals.add(expct == null ? "null" : !expct.hasRemaining() ? "empty" : meta.type.asCQL3Type().toCQLLiteral(expct));
                }
                throw new AssertionError(String.format("Failure at attempt %d with schema\n%s\nAnd SSTable Format %s\nfor values %s", i, createTable, DatabaseDescriptor.getSelectedSSTableFormat(), literals), t);
            }
        }
    });
}

@Test
public void toCQLStringTest() {
    ColumnIdentifier col = new ColumnIdentifier("col", false);
    ColumnIdentifier col2 = new ColumnIdentifier("col2", false);
    Marker.Raw marker = new Marker.Raw(0);
    InMarker.Raw inMarker = new InMarker.Raw(0);
    Term.Raw one = Constants.Literal.integer("1");
    Term.Raw two = Constants.Literal.integer("2");
    Term.Raw three = Constants.Literal.integer("3");
    Terms.Raw oneTwo = Terms.Raw.of(asList(one, two));
    Term.Raw text = Constants.Literal.string("text");
    assertEquals("col = ?", singleColumn(col, Operator.EQ, marker).toCQLString());
    assertEquals("col = 2", singleColumn(col, Operator.EQ, two).toCQLString());
    assertEquals("col = 'text'", singleColumn(col, Operator.EQ, text).toCQLString());
    assertEquals("col >= ?", singleColumn(col, Operator.GTE, marker).toCQLString());
    assertEquals("col BETWEEN 1 AND 2", singleColumn(col, Operator.BETWEEN, oneTwo).toCQLString());
    assertEquals("col IN ?", singleColumn(col, Operator.IN, inMarker).toCQLString());
    assertEquals("col IN (1, 2)", singleColumn(col, Operator.IN, oneTwo).toCQLString());
    assertEquals("col IN (1)", singleColumn(col, Operator.IN, Terms.Raw.of(List.of(one))).toCQLString());
    Term.Raw tuple1 = new Tuples.Literal(asList(one, two));
    Term.Raw tuple2 = new Tuples.Literal(asList(two, three));
    Terms.Raw tuples = Terms.Raw.of(asList(tuple1, tuple2));
    assertEquals("(col, col2) = ?", multiColumn(asList(col, col2), Operator.EQ, marker).toCQLString());
    assertEquals("(col, col2) = (1, 2)", multiColumn(asList(col, col2), Operator.EQ, tuple1).toCQLString());
    assertEquals("(col, col2) IN ((1, 2), (2, 3))", multiColumn(asList(col, col2), Operator.IN, tuples).toCQLString());
    assertEquals("(col, col2) IN ?", multiColumn(asList(col, col2), Operator.IN, inMarker).toCQLString());
    Term.Raw tokenCall = new FunctionCall.Raw(FunctionName.nativeFunction("token"), asList(one, two));
    assertEquals("token(col, col2) = ?", token(asList(col, col2), Operator.EQ, marker).toCQLString());
    assertEquals("token(col, col2) = token(1, 2)", token(asList(col, col2), Operator.EQ, tokenCall).toCQLString());
    assertEquals("col['text'] = ?", mapElement(col, text, EQ, marker).toCQLString());
    assertEquals("col[?] = ?", collectionElementCondition(col, marker, EQ, Terms.Raw.of(marker)).toCQLString());
    // element access is not allowed for sets
    FieldIdentifier f = FieldIdentifier.forQuoted("f1");
    assertEquals("col.f1 = ?", udtFieldCondition(col, f, EQ, Terms.Raw.of(marker)).toCQLString());
    assertEquals("col.f1 = 1", udtFieldCondition(col, f, EQ, Terms.Raw.of(one)).toCQLString());
}

