@Test
public void shouldRejectTTL() {
    for (Mutation.Kind kind : Mutation.Kind.values()) {
        // deletes don't support TTL
        if (kind == Mutation.Kind.DELETE)
            continue;
        Mutation mutation;
        switch(kind) {
            case INSERT:
                mutation = Mutation.insert(tbl5()).value("k", 1).value("v", 2).ttl(42).build();
                break;
            case UPDATE:
                mutation = Mutation.update(tbl5()).value("k", 1).set("v", 2).ttl(42).build();
                break;
            default:
                throw new UnsupportedOperationException(kind.name());
        }
        String query = Txn.wrap(mutation).toCQL();
        Assertions.assertThatThrownBy(() -> prepare(query)).isInstanceOf(InvalidRequestException.class).hasMessageContaining(String.format(NO_TTLS_IN_UPDATES_MESSAGE, kind.name(), "at"));
        var txn = Txn.builder().addLet("a", Select.builder().table(tbl5()).value("k", 1).build()).addIf(new Is("a", Is.Kind.Null), mutation).build();
        Assertions.assertThatThrownBy(() -> prepare(txn.toCQL())).isInstanceOf(InvalidRequestException.class).hasMessageContaining(String.format(NO_TTLS_IN_UPDATES_MESSAGE, kind.name(), "at"));
    }
}

