    QueryState state = QueryState.forInternalCalls();
    Dispatcher.RequestTime now = Dispatcher.RequestTime.forImmediateExecution();
    Assertions.assertThatThrownBy(() -> stmt.execute(state, QueryOptions.forInternalCalls(Arrays.asList(select.bindsEncoded())), now)).isInstanceOf(InvalidRequestException.class).hasMessageContaining(String.format(NO_PARTITION_IN_CLAUSE_WITH_LIMIT, "SELECT", "at"));
