@Test
public void testClusteringColumnFiltering() throws Throwable {
    Util.assumeLegacySecondaryIndex();
    createTable("CREATE TABLE %s (a int, b frozen<map<int, int>>, c int, d int, PRIMARY KEY (a, b, c))");
