    assertRows(execute("SELECT * FROM %s WHERE d=? AND b CONTAINS KEY ? ALLOW FILTERING", 0, 0), row(0, map(0, 0, 1, 1), 0, 0), row(1, map(0, 0, 1, 1), 0, 0));
