@Test
public void testAllowFilteringOnPartitionKeyWithSecondaryIndex() throws Throwable {
    createTable("CREATE TABLE %s (pk1 int, pk2 int, c1 int, c2 int, v int, " + "PRIMARY KEY ((pk1, pk2), c1, c2))");
    createIndex("CREATE INDEX v_idx_1 ON %s (v);");
    for (int i = 1; i <= 5; i++) {
        for (int j = 1; j <= 2; j++) {
            execute("INSERT INTO %s (pk1, pk2, c1, c2, v) VALUES (?, ?, ?, ?, ?)", j, 1, 1, 1, i);
            execute("INSERT INTO %s (pk1, pk2, c1, c2, v) VALUES (?, ?, ?, ?, ?)", j, 1, 1, i, i);
            execute("INSERT INTO %s (pk1, pk2, c1, c2, v) VALUES (?, ?, ?, ?, ?)", j, 1, i, i, i);
            execute("INSERT INTO %s (pk1, pk2, c1, c2, v) VALUES (?, ?, ?, ?, ?)", j, i, i, i, i);
        }
    }
    beforeAndAfterFlush(() -> {
        assertEmpty(execute("SELECT * FROM %s WHERE pk1 = 1 AND  c1 > 0 AND c1 < 5 AND c2 = 1 AND v = 3 ALLOW FILTERING;"));
        assertRows(execute("SELECT * FROM %s WHERE pk1 = 1 AND  c1 > 0 AND c1 < 5 AND c2 = 3 AND v = 3 ALLOW FILTERING;"), row(1, 3, 3, 3, 3), row(1, 1, 1, 3, 3), row(1, 1, 3, 3, 3));
        assertEmpty(execute("SELECT * FROM %s WHERE pk1 = 1 AND  c2 > 1 AND c2 < 5 AND v = 1 ALLOW FILTERING;"));
        assertRows(execute("SELECT * FROM %s WHERE pk1 = 1 AND  c1 > 1 AND c2 > 2 AND v = 3 ALLOW FILTERING;"), row(1, 3, 3, 3, 3), row(1, 1, 3, 3, 3));
        assertRows(execute("SELECT * FROM %s WHERE pk1 = 1 AND  pk2 > 1 AND c2 > 2 AND v = 3 ALLOW FILTERING;"), row(1, 3, 3, 3, 3));
        assertRowsIgnoringOrder(execute("SELECT * FROM %s WHERE pk2 > 1 AND  c1 IN(0,1,2) AND v <= 3 ALLOW FILTERING;"), row(1, 2, 2, 2, 2), row(2, 2, 2, 2, 2));
        assertRows(execute("SELECT * FROM %s WHERE pk1 >= 2 AND pk2 <=3 AND  c1 IN(0,1,2) AND c2 IN(0,1,2) AND v < 3  ALLOW FILTERING;"), row(2, 2, 2, 2, 2), row(2, 1, 1, 2, 2), row(2, 1, 2, 2, 2));
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE pk1 >= 1 AND pk2 <=3 AND  c1 IN(0,1,2) AND c2 IN(0,1,2) AND v = 3");
    });
}

