    createTable(String.format("CREATE TABLE %%s " + "(key int primary key, lst list<frozen<%s>>, st set<frozen<%s>>, mp map<int, frozen<%s>>)", type, type, type));
    // The mix of the package names org.apache.cassandra.cql3.functions.types and com.datastax.driver.core is
    // intentional to test the replacement of com.datastax.driver.core with org.apache.cassandra.cql3.functions.types.
    String fName1 = createFunction(KEYSPACE, "list<frozen<" + type + ">>", "CREATE FUNCTION %s( lst list<frozen<" + type + ">> ) " + "RETURNS NULL ON NULL INPUT " + "RETURNS text " + "LANGUAGE java\n" + "AS $$" + "     org.apache.cassandra.cql3.functions.types.UDTValue udtVal = (com.datastax.driver.core.UDTValue)lst.get(1);" + "     return udtVal.getString(\"txt\");$$;");
    String fName2 = createFunction(KEYSPACE, "set<frozen<" + type + ">>", "CREATE FUNCTION %s( st set<frozen<" + type + ">> ) " + "RETURNS NULL ON NULL INPUT " + "RETURNS text " + "LANGUAGE java\n" + "AS $$" + "     com.datastax.driver.core.UDTValue udtVal = (org.apache.cassandra.cql3.functions.types.UDTValue)st.iterator().next();" + "     return udtVal.getString(\"txt\");$$;");
    String fName3 = createFunction(KEYSPACE, "map<int, frozen<" + type + ">>", "CREATE FUNCTION %s( mp map<int, frozen<" + type + ">> ) " + "RETURNS NULL ON NULL INPUT " + "RETURNS text " + "LANGUAGE java\n" + "AS $$" + "     org.apache.cassandra.cql3.functions.types.UDTValue udtVal = (com.datastax.driver.core.UDTValue)mp.get(Integer.valueOf(3));" + "     return udtVal.getString(\"txt\");$$;");
    execute("INSERT INTO %s (key, lst, st, mp) values (1, " + "[ {txt: 'one', i:1}, {txt: 'three', i:1}, {txt: 'one', i:1} ] , " + "{ {txt: 'one', i:1}, {txt: 'three', i:3}, {txt: 'two', i:2} }, " + "{ 1: {txt: 'one', i:1}, 2: {txt: 'one', i:3}, 3: {txt: 'two', i:2} })");
    assertRows(execute("SELECT " + fName1 + "(lst), " + fName2 + "(st), " + fName3 + "(mp) FROM %s WHERE key = 1"), row("three", "one", "two"));
    for (ProtocolVersion version : PROTOCOL_VERSIONS) assertRowsNet(version, executeNet(version, "SELECT " + fName1 + "(lst), " + fName2 + "(st), " + fName3 + "(mp) FROM %s WHERE key = 1"), row("three", "one", "two"));
}

@Test
public void testAllNativeTypes() throws Throwable {
    StringBuilder sig = new StringBuilder();
    StringBuilder args = new StringBuilder();
    for (CQL3Type.Native type : CQL3Type.Native.values()) {
        if (type == CQL3Type.Native.EMPTY)
            continue;
        if (sig.length() > 0)
            sig.append(',');
        sig.append(type.toString());
        if (args.length() > 0)
            args.append(',');
        args.append("arg").append(type.toString()).append(' ').append(type.toString());
    }
    createFunction(KEYSPACE, sig.toString(), "CREATE OR REPLACE FUNCTION %s(" + args + ") " + "RETURNS NULL ON NULL INPUT " + "RETURNS int " + "LANGUAGE JAVA\n" + "AS 'return 0;'");
    for (CQL3Type.Native type : CQL3Type.Native.values()) {
        if (type == CQL3Type.Native.EMPTY)
            continue;
        createFunction(KEYSPACE_PER_TEST, type.toString(), "CREATE OR REPLACE FUNCTION %s(val " + type.toString() + ") " + "RETURNS NULL ON NULL INPUT " + "RETURNS int " + "LANGUAGE JAVA\n" + "AS 'return 0;'");
    }
}

