@Test
public void testSecurityPermissions() throws Throwable {
    createTable("CREATE TABLE %s (key int primary key, dval double)");
    execute("INSERT INTO %s (key, dval) VALUES (?, ?)", 1, 1d);
    // Java UDFs
    try {
        String fName = createFunction(KEYSPACE_PER_TEST, "double", "CREATE OR REPLACE FUNCTION %s(val double) " + "RETURNS NULL ON NULL INPUT " + "RETURNS double " + "LANGUAGE JAVA\n" + // checkstyle: suppress nearby 'blockSystemPropertyUsage'
        "AS 'System.getProperty(\"foo.bar.baz\"); return 0d;';");
        execute("SELECT " + fName + "(dval) FROM %s WHERE key=1");
        Assert.fail();
    } catch (FunctionExecutionException e) {
        // checkstyle: suppress nearby 'blockSystemPropertyUsage'
        assertAccessControlException("System.getProperty(\"foo.bar.baz\"); return 0d;", e);
    }
    String[] cfnSources = { "try { Class.forName(\"" + JavaDriverUtils.class.getName() + "\"); } catch (Exception e) { throw new RuntimeException(e); } return 0d;", "try { Class.forName(\"sun.misc.Unsafe\"); } catch (Exception e) { throw new RuntimeException(e); } return 0d;" };
    for (String source : cfnSources) {
        assertInvalidMessage("Java UDF validation failed: [call to java.lang.Class.forName()]", "CREATE OR REPLACE FUNCTION " + KEYSPACE + ".invalid_class_access(val double) " + "RETURNS NULL ON NULL INPUT " + "RETURNS double " + "LANGUAGE JAVA\n" + "AS '" + source + "';");
    }
    String[][] typesAndSources = { { "sun.misc.Unsafe", "sun.misc.Unsafe.getUnsafe(); return 0d;" }, { "java.nio.file.FileSystems", "try {" + "     java.nio.file.FileSystems.getDefault(); return 0d;" + "} catch (Exception t) {" + "     throw new RuntimeException(t);" + '}' }, { "java.nio.channels.FileChannel", "try {" + "     java.nio.channels.FileChannel.open(java.nio.file.FileSystems.getDefault().getPath(\"/etc/passwd\")).close(); return 0d;" + "} catch (Exception t) {" + "     throw new RuntimeException(t);" + '}' }, { "java.nio.channels.SocketChannel", "try {" + "     java.nio.channels.SocketChannel.open().close(); return 0d;" + "} catch (Exception t) {" + "     throw new RuntimeException(t);" + '}' }, { "java.io.FileInputStream", "try {" + "     new java.io.FileInputStream(\"./foobar\").close(); return 0d;" + "} catch (Exception t) {" + "     throw new RuntimeException(t);" + '}' }, { "java.lang.Runtime", "try {" + "     java.lang.Runtime.getRuntime(); return 0d;" + "} catch (Exception t) {" + "     throw new RuntimeException(t);" + '}' }, { "org.apache.cassandra.service.StorageService", "try {" + "     org.apache.cassandra.service.StorageService v = org.apache.cassandra.service.StorageService.instance; v.isShutdown(); return 0d;" + "} catch (Exception t) {" + "     throw new RuntimeException(t);" + '}' }, { "java.net.ServerSocket", "try {" + "     new java.net.ServerSocket().bind(); return 0d;" + "} catch (Exception t) {" + "     throw new RuntimeException(t);" + '}' }, { "java.io.FileOutputStream", "try {" + "     new java.io.FileOutputStream(\".foo\"); return 0d;" + "} catch (Exception t) {" + "     throw new RuntimeException(t);" + '}' }, { "java.lang.Runtime", "try {" + "     java.lang.Runtime.getRuntime().exec(\"/tmp/foo\"); return 0d;" + "} catch (Exception t) {" + "     throw new RuntimeException(t);" + '}' }, { "org.apache.cassandra.utils.vint.VIntCoding", "try {" + "     org.apache.cassandra.utils.vint.VIntCoding.computeUnsignedVIntSize(0L); return 0d;" + "} catch (Exception t) {" + "     throw new RuntimeException(t);" + '}' } };
    for (String[] typeAndSource : typesAndSources) {
        assertInvalidMessage(typeAndSource[0] + " cannot be resolved", "CREATE OR REPLACE FUNCTION " + KEYSPACE + ".invalid_class_access(val double) " + "RETURNS NULL ON NULL INPUT " + "RETURNS double " + "LANGUAGE JAVA\n" + "AS '" + typeAndSource[1] + "';");
    }
}

@Test
public void testAmokUDF() throws Throwable {
    createTable("CREATE TABLE %s (key int primary key, dval double)");
    execute("INSERT INTO %s (key, dval) VALUES (?, ?)", 1, 1d);
    long udfWarnTimeout = DatabaseDescriptor.getUserDefinedFunctionWarnTimeout();
    long udfFailTimeout = DatabaseDescriptor.getUserDefinedFunctionFailTimeout();
    int maxTries = 5;
    for (int i = 1; i <= maxTries; i++) {
        try {
            // short timeout
            DatabaseDescriptor.setUserDefinedFunctionWarnTimeout(10);
            DatabaseDescriptor.setUserDefinedFunctionFailTimeout(250);
            // don't kill the unit test... - default policy is "die"
            DatabaseDescriptor.setUserFunctionTimeoutPolicy(Config.UserFunctionTimeoutPolicy.ignore);
            ClientWarn.instance.captureWarnings();
            String fName = createFunction(KEYSPACE_PER_TEST, "double", "CREATE OR REPLACE FUNCTION %s(val double) " + "RETURNS NULL ON NULL INPUT " + "RETURNS double " + "LANGUAGE JAVA\n" + "AS 'long t=System.currentTimeMillis()+110; while (t>System.currentTimeMillis()) { }; return 0d;'");
            execute("SELECT " + fName + "(dval) FROM %s WHERE key=1");
            List<String> warnings = ClientWarn.instance.getWarnings();
            Assert.assertNotNull(warnings);
            Assert.assertFalse(warnings.isEmpty());
            ClientWarn.instance.resetWarnings();
            // Java UDF
            fName = createFunction(KEYSPACE_PER_TEST, "double", "CREATE OR REPLACE FUNCTION %s(val double) " + "RETURNS NULL ON NULL INPUT " + "RETURNS double " + "LANGUAGE JAVA\n" + "AS 'long t=System.currentTimeMillis()+500; while (t>System.currentTimeMillis()) { }; return 0d;';");
            assertInvalidMessage("ran longer than 250ms", "SELECT " + fName + "(dval) FROM %s WHERE key=1");
            return;
        } catch (Error | RuntimeException e) {
            if (i == maxTries)
                throw e;
        } finally {
            // reset to defaults
            DatabaseDescriptor.setUserDefinedFunctionWarnTimeout(udfWarnTimeout);
            DatabaseDescriptor.setUserDefinedFunctionFailTimeout(udfFailTimeout);
        }
    }
}

