        assertRows(execute("SELECT * FROM %s WHERE x = 1"), row(1, set(userType("a", 1), userType("a", 2))));
        execute("ALTER TYPE " + columnType + " ADD b int");
        execute("UPDATE %s SET y = y + ? WHERE x = 1", set(userType("a", 1, "b", 1), userType("a", 1, "b", 2), userType("a", 2, "b", 1)));
