    assertRowsIgnoringOrder(execute("SELECT * FROM test_virtual_ks.vt2"), row("pk1_1", "pk2_1", "c1_1", "c2_1", 1, 1L), row("pk1_1", "pk2_2", "c1_1", "c2_2", 2, 2L), row("pk1_2", "pk2_1", "c1_1", "c2_1", 3, 3L), row("pk1_2", "pk2_1", "c1_2", "c2_3", 4, 4L), row("pk1_2", "pk2_1", "c1_1", "c2_5", 5, 5L), row("pk1_2", "pk2_1", "c1_2", "c2_6", 6, 6L), row("pk1_2", "pk2_2", "c1_1", "c2_1", 7, 7L), row("pk1_2", "pk2_2", "c1_1", "c2_2", 8, 8L), row("pk1_1", "pk2_3", "c1_1", "c2_1", 9, 9L), row("pk1_1", "pk2_3", "c1_2", "c2_2", 10, 10L));
    // delete multiple partitions with IN
    execute("DELETE FROM test_virtual_ks.vt2 WHERE pk1 = 'pk1_1' AND pk2 IN('pk2_1', 'pk2_2')");
    assertRowsIgnoringOrder(execute("SELECT * FROM test_virtual_ks.vt2"), row("pk1_2", "pk2_1", "c1_1", "c2_1", 3, 3L), row("pk1_2", "pk2_1", "c1_2", "c2_3", 4, 4L), row("pk1_2", "pk2_1", "c1_1", "c2_5", 5, 5L), row("pk1_2", "pk2_1", "c1_2", "c2_6", 6, 6L), row("pk1_2", "pk2_2", "c1_1", "c2_1", 7, 7L), row("pk1_2", "pk2_2", "c1_1", "c2_2", 8, 8L), row("pk1_1", "pk2_3", "c1_1", "c2_1", 9, 9L), row("pk1_1", "pk2_3", "c1_2", "c2_2", 10, 10L));
    // delete multiple rows via first-level IN
    execute("DELETE FROM test_virtual_ks.vt2 WHERE pk1 = 'pk1_1' AND pk2 = 'pk2_3' AND c1 IN('c1_1', 'c1_2')");
    assertRowsIgnoringOrder(execute("SELECT * FROM test_virtual_ks.vt2"), row("pk1_2", "pk2_1", "c1_1", "c2_1", 3, 3L), row("pk1_2", "pk2_1", "c1_2", "c2_3", 4, 4L), row("pk1_2", "pk2_1", "c1_1", "c2_5", 5, 5L), row("pk1_2", "pk2_1", "c1_2", "c2_6", 6, 6L), row("pk1_2", "pk2_2", "c1_1", "c2_1", 7, 7L), row("pk1_2", "pk2_2", "c1_1", "c2_2", 8, 8L));
    // delete multiple rows via second-level IN
    execute("DELETE FROM test_virtual_ks.vt2 WHERE pk1 = 'pk1_2' AND pk2 = 'pk2_2' AND c1 = 'c1_1' AND c2 IN('c2_1', 'c2_2')");
    assertRowsIgnoringOrder(execute("SELECT * FROM test_virtual_ks.vt2"), row("pk1_2", "pk2_1", "c1_1", "c2_1", 3, 3L), row("pk1_2", "pk2_1", "c1_2", "c2_3", 4, 4L), row("pk1_2", "pk2_1", "c1_1", "c2_5", 5, 5L), row("pk1_2", "pk2_1", "c1_2", "c2_6", 6, 6L));
    // delete multiple rows with first-level IN and second-level range (one-sided limit)
    execute("DELETE FROM test_virtual_ks.vt2 WHERE pk1 = 'pk1_2' AND pk2 = 'pk2_1' AND c1 IN('c1_1', 'c1_2') AND c2 <= 'c2_3'");
    assertRowsIgnoringOrder(execute("SELECT * FROM test_virtual_ks.vt2"), row("pk1_2", "pk2_1", "c1_1", "c2_5", 5, 5L), row("pk1_2", "pk2_1", "c1_2", "c2_6", 6, 6L));
    // delete multiple rows via first-level and second-level IN
    execute("DELETE v1 FROM test_virtual_ks.vt2 WHERE pk1 = 'pk1_2' AND pk2 = 'pk2_1' AND c1 IN('c1_1', 'c1_2') AND c2 IN('c2_5', 'c2_6')");
