    // truncate
    execute("TRUNCATE test_virtual_ks.vt2");
    assertEmpty(execute("SELECT * FROM test_virtual_ks.vt2"));
}

@Test
public void testInvalidDMLOperationsOnMutableTable() throws Throwable {
    // test that LOGGED batch doesn't allow virtual table updates
    assertInvalidMessage("Cannot include a virtual table statement in a logged batch", "BEGIN BATCH " + "UPDATE test_virtual_ks.vt2 SET v1 = 1 WHERE pk1 = 'pk1_1' AND pk2 = 'pk2' AND c1 = 'c1' AND c2 = 'c2';" + "UPDATE test_virtual_ks.vt2 SET v1 = 2 WHERE pk1 = 'pk1_2' AND pk2 = 'pk2' AND c1 = 'c1' AND c2 = 'c2';" + "UPDATE test_virtual_ks.vt2 SET v1 = 3 WHERE pk1 = 'pk1_3' AND pk2 = 'pk2' AND c1 = 'c1' AND c2 = 'c2';" + "APPLY BATCH");
    // test that UNLOGGED batch doesn't allow mixing updates for regular and virtual tables
    createTable("CREATE TABLE %s (pk1 text, pk2 text, c1 text, c2 text, v1 int, v2 bigint, PRIMARY KEY ((pk1, pk2), c1, c2))");
    assertInvalidMessage("Mutations for virtual and regular tables cannot exist in the same batch", "BEGIN UNLOGGED BATCH " + "UPDATE test_virtual_ks.vt2 SET v1 = 1 WHERE pk1 = 'pk1_1' AND pk2 = 'pk2' AND c1 = 'c1' AND c2 = 'c2';" + "UPDATE %s                  SET v1 = 2 WHERE pk1 = 'pk1_2' AND pk2 = 'pk2' AND c1 = 'c1' AND c2 = 'c2';" + "UPDATE test_virtual_ks.vt2 SET v1 = 3 WHERE pk1 = 'pk1_3' AND pk2 = 'pk2' AND c1 = 'c1' AND c2 = 'c2';" + "APPLY BATCH");
    // test that TIMESTAMP is (currently) rejected with INSERT and UPDATE
    assertInvalidMessage("Custom timestamp is not supported by virtual tables", "INSERT INTO test_virtual_ks.vt2 (pk1, pk2, c1, c2, v1, v2) VALUES ('pk1', 'pk2', 'c1', 'c2', 1, 11) USING TIMESTAMP 123456789");
    assertInvalidMessage("Custom timestamp is not supported by virtual tables", "UPDATE test_virtual_ks.vt2 USING TIMESTAMP 123456789 SET v1 = 1, v2 = 11 WHERE pk1 = 'pk1' AND pk2 = 'pk2' AND c1 = 'c1' AND c2 = 'c2'");
    // test that TTL is (currently) rejected with INSERT and UPDATE
    assertInvalidMessage("Expiring columns are not supported by virtual tables", "INSERT INTO test_virtual_ks.vt2 (pk1, pk2, c1, c2, v1, v2) VALUES ('pk1', 'pk2', 'c1', 'c2', 1, 11) USING TTL 86400");
    assertInvalidMessage("Expiring columns are not supported by virtual tables", "UPDATE test_virtual_ks.vt2 USING TTL 86400 SET v1 = 1, v2 = 11 WHERE pk1 = 'pk1' AND pk2 = 'pk2' AND c1 = 'c1' AND c2 = 'c2'");
    // test that LWT is (currently) rejected with BATCH
    assertInvalidMessage("Conditional BATCH statements cannot include mutations for virtual tables", "BEGIN UNLOGGED BATCH " + "UPDATE test_virtual_ks.vt2 SET v1 = 3 WHERE pk1 = 'pk1' AND pk2 = 'pk2' AND c1 = 'c1' AND c2 = 'c2' IF v1 = 2;" + "APPLY BATCH");
    // test that LWT is (currently) rejected with INSERT and UPDATE
    assertInvalidMessage("Conditional updates are not supported by virtual tables", "INSERT INTO test_virtual_ks.vt2 (pk1, pk2, c1, c2, v1) VALUES ('pk1', 'pk2', 'c1', 'c2', 2) IF NOT EXISTS");
    assertInvalidMessage("Conditional updates are not supported by virtual tables", "UPDATE test_virtual_ks.vt2 SET v1 = 3 WHERE pk1 = 'pk1' AND pk2 = 'pk2' AND c1 = 'c1' AND c2 = 'c2' IF v1 = 2");
    // test that row DELETE without full primary key with equality relation is (currently) rejected
    assertInvalidMessage("Some partition key parts are missing: pk2", "DELETE FROM test_virtual_ks.vt2 WHERE pk1 = 'pk1' AND c1 = 'c1' AND c2 > 'c2'");
    assertInvalidMessage("Only EQ and IN relation are supported on the partition key (unless you use the token() function) for DELETE statements", "DELETE FROM test_virtual_ks.vt2 WHERE pk1 = 'pk1' AND pk2 > 'pk2' AND c1 = 'c1' AND c2 > 'c2'");
    assertInvalidMessage("KEY column \"c2\" cannot be restricted as preceding column \"c1\" is not restricted", "DELETE FROM test_virtual_ks.vt2 WHERE pk1 = 'pk1' AND pk2 = 'pk2' AND c2 > 'c2'");
    assertInvalidMessage("Clustering column \"c2\" cannot be restricted (preceding column \"c1\" is restricted by a non-EQ relation)", "DELETE FROM test_virtual_ks.vt2 WHERE pk1 = 'pk1' AND pk2 = 'pk2' AND c1 > 'c1' AND c2 > 'c2'");
    assertInvalidMessage("DELETE statements must restrict all PRIMARY KEY columns with equality relations", "DELETE FROM test_virtual_ks.vt2 WHERE pk1 = 'pk1' AND pk2 = 'pk2' AND c1 = 'c1' AND c2 > 'c2' IF v1 = 2");
    // test that column DELETE without full primary key with equality relation is (currently) rejected
    assertInvalidMessage("Range deletions are not supported for specific columns", "DELETE v1 FROM test_virtual_ks.vt2 WHERE pk1 = 'pk1' AND pk2 = 'pk2' AND c1 = 'c1'");
    assertInvalidMessage("Range deletions are not supported for specific columns", "DELETE v1 FROM test_virtual_ks.vt2 WHERE pk1 = 'pk1' AND pk2 = 'pk2' AND c1 = 'c1' AND c2 > 'c2'");
}

