@Test
public void testSkippingByKeyRangeInPartitionRangeReads() throws Throwable {
    DecoratedKey[] keys = new DecoratedKey[8];
    for (int i = 0; i < keys.length; i++) keys[i] = DatabaseDescriptor.getPartitioner().decorateKey(Int32Type.instance.decompose(i));
    Arrays.sort(keys);
