    assertRows(execute("SELECT max(a), max(to_unix_timestamp(b)) FROM %s"), row(3, date.getTime()));
    assertRows(execute("SELECT max(a), to_unix_timestamp(max(b)) FROM %s"), row(3, date.getTime()));
    assertRows(execute("SELECT " + copySign + "(max(c), min(c)) FROM %s"), row(-1.4));
    assertRows(execute("SELECT " + copySign + "(c, d) FROM %s"), row(1.2), row(-1.3), row(1.4));
    assertRows(execute("SELECT max(" + copySign + "(c, d)) FROM %s"), row(1.4));
    assertRows(execute("SELECT " + copySign + "(c, max(c)) FROM %s"), row(1.2));
    assertRows(execute("SELECT " + copySign + "(max(c), c) FROM %s"), row(-1.4));
    ;
}

@Test
public void testSchemaChange() throws Throwable {
    String f = createFunction(KEYSPACE, "double, double", "CREATE OR REPLACE FUNCTION %s(state double, val double) " + "RETURNS NULL ON NULL INPUT " + "RETURNS double " + "LANGUAGE java " + "AS ' return state;';");
    createFunctionOverload(f, "double, double", "CREATE OR REPLACE FUNCTION %s(state int, val int) " + "RETURNS NULL ON NULL INPUT " + "RETURNS int " + "LANGUAGE java " + "AS 'return state;';");
    String a = createAggregateName(KEYSPACE);
    String aggregateName = shortFunctionName(a);
    registerAggregate(a, "double");
    assertSchemaChange("CREATE OR REPLACE AGGREGATE " + a + "(double) " + "SFUNC " + shortFunctionName(f) + " " + "STYPE double " + "INITCOND 0", Change.CREATED, Target.AGGREGATE, KEYSPACE, aggregateName, "double");
    assertSchemaChange("CREATE OR REPLACE AGGREGATE " + a + "(double) " + "SFUNC " + shortFunctionName(f) + " " + "STYPE double " + "INITCOND 1", Change.UPDATED, Target.AGGREGATE, KEYSPACE, aggregateName, "double");
    registerAggregate(a, "int");
    assertSchemaChange("CREATE OR REPLACE AGGREGATE " + a + "(int) " + "SFUNC " + shortFunctionName(f) + " " + "STYPE int " + "INITCOND 0", Change.CREATED, Target.AGGREGATE, KEYSPACE, aggregateName, "int");
    assertSchemaChange("DROP AGGREGATE " + a + "(double)", Change.DROPPED, Target.AGGREGATE, KEYSPACE, aggregateName, "double");
    // The aggregate with nested tuple should be created without throwing InvalidRequestException. See CASSANDRA-15857
    String f1 = createFunction(KEYSPACE, "double, double", "CREATE OR REPLACE FUNCTION %s(state double, val list<tuple<int, int>>) " + "RETURNS NULL ON NULL INPUT " + "RETURNS double " + "LANGUAGE java " + "AS ' return state;';");
    String a1 = createAggregateName(KEYSPACE);
    registerAggregate(a1, "list<tuple<int, int>>");
    assertSchemaChange("CREATE OR REPLACE AGGREGATE " + a1 + "(list<tuple<int, int>>) " + "SFUNC " + shortFunctionName(f1) + " " + "STYPE double " + "INITCOND 0", Change.CREATED, Target.AGGREGATE, KEYSPACE, shortFunctionName(a1), "list<tuple<int, int>>");
}

@Test
public void testDropStatements() throws Throwable {
    String f = createFunction(KEYSPACE, "double, double", "CREATE OR REPLACE FUNCTION %s(state double, val double) " + "RETURNS NULL ON NULL INPUT " + "RETURNS double " + "LANGUAGE java " + "AS 'return state;';");
    createFunctionOverload(f, "double, double", "CREATE OR REPLACE FUNCTION %s(state int, val int) " + "RETURNS NULL ON NULL INPUT " + "RETURNS int " + "LANGUAGE java " + "AS ' return state;';");
    // DROP AGGREGATE must not succeed against a scalar
    assertInvalidMessage("matches multiple function definitions", "DROP AGGREGATE " + f);
    assertInvalidMessage("doesn't exist", "DROP AGGREGATE " + f + "(double, double)");
    String a = createAggregate(KEYSPACE, "double", "CREATE OR REPLACE AGGREGATE %s(double) " + "SFUNC " + shortFunctionName(f) + " " + "STYPE double " + "INITCOND 0");
    createAggregateOverload(a, "int", "CREATE OR REPLACE AGGREGATE %s(int) " + "SFUNC " + shortFunctionName(f) + " " + "STYPE int " + "INITCOND 0");
    // DROP FUNCTION must not succeed against an aggregate
    assertInvalidMessage("matches multiple function definitions", "DROP FUNCTION " + a);
    assertInvalidMessage("doesn't exist", "DROP FUNCTION " + a + "(double)");
    // ambigious
    assertInvalidMessage("matches multiple function definitions", "DROP AGGREGATE " + a);
    assertInvalidMessage("matches multiple function definitions", "DROP AGGREGATE IF EXISTS " + a);
    execute("DROP AGGREGATE IF EXISTS " + KEYSPACE + ".non_existing");
    execute("DROP AGGREGATE IF EXISTS " + a + "(int, text)");
    execute("DROP AGGREGATE " + a + "(double)");
    execute("DROP AGGREGATE IF EXISTS " + a + "(double)");
}

