@Test
public void testNormalColumnUsage() throws Throwable {
    createTable("CREATE TABLE %s (a int PRIMARY KEY, b frozen<map<set<int>, list<int>>>, c frozen<set<int>>)" + compactOption);
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 0, map(), set());
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 1, map(set(), list(99999, 999999, 99999)), set());
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 2, map(set(1, 2, 3), list(1, 2, 3)), set(1, 2, 3));
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 3, map(set(4, 5, 6), list(1, 2, 3)), set(1, 2, 3));
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 4, map(set(7, 8, 9), list(1, 2, 3)), set(1, 2, 3));
    // overwrite with update
    execute("UPDATE %s SET b=? WHERE a=?", map(set(), list(1, 2, 3)), 1);
    assertRowsIgnoringOrder(execute("SELECT * FROM %s"), row(0, map(), set()), row(1, map(set(), list(1, 2, 3)), set()), row(2, map(set(1, 2, 3), list(1, 2, 3)), set(1, 2, 3)), row(3, map(set(4, 5, 6), list(1, 2, 3)), set(1, 2, 3)), row(4, map(set(7, 8, 9), list(1, 2, 3)), set(1, 2, 3)));
    assertRowsIgnoringOrder(execute("SELECT b FROM %s"), row(map()), row(map(set(), list(1, 2, 3))), row(map(set(1, 2, 3), list(1, 2, 3))), row(map(set(4, 5, 6), list(1, 2, 3))), row(map(set(7, 8, 9), list(1, 2, 3))));
    assertRowsIgnoringOrder(execute("SELECT c FROM %s"), row(set()), row(set()), row(set(1, 2, 3)), row(set(1, 2, 3)), row(set(1, 2, 3)));
    assertRowsIgnoringOrder(execute("SELECT * FROM %s WHERE a=?", 3), row(3, map(set(4, 5, 6), list(1, 2, 3)), set(1, 2, 3)));
    execute("UPDATE %s SET b=? WHERE a=?", null, 1);
    assertRowsIgnoringOrder(execute("SELECT * FROM %s WHERE a=?", 1), row(1, null, set()));
    execute("UPDATE %s SET b=? WHERE a=?", map(), 1);
    assertRowsIgnoringOrder(execute("SELECT * FROM %s WHERE a=?", 1), row(1, map(), set()));
    execute("UPDATE %s SET c=? WHERE a=?", null, 2);
    assertRowsIgnoringOrder(execute("SELECT * FROM %s WHERE a=?", 2), row(2, map(set(1, 2, 3), list(1, 2, 3)), null));
    execute("UPDATE %s SET c=? WHERE a=?", set(), 2);
    assertRowsIgnoringOrder(execute("SELECT * FROM %s WHERE a=?", 2), row(2, map(set(1, 2, 3), list(1, 2, 3)), set()));
    execute("DELETE b FROM %s WHERE a=?", 3);
    assertRowsIgnoringOrder(execute("SELECT * FROM %s WHERE a=?", 3), row(3, null, set(1, 2, 3)));
    execute("DELETE c FROM %s WHERE a=?", 4);
    assertRowsIgnoringOrder(execute("SELECT * FROM %s WHERE a=?", 4), row(4, map(set(7, 8, 9), list(1, 2, 3)), null));
}

