    execute("INSERT INTO %s (a, b, c, d) VALUES (2, 3, 7, 8)");
    // Adds tomstones
    execute("INSERT INTO %s (a, b, c, d) VALUES (1, 1, 4, 5)");
    execute("INSERT INTO %s (a, b, c, d) VALUES (2, 2, 7, 8)");
    execute("DELETE FROM %s WHERE a = 1 AND b = 1 AND c = 4");
    execute("DELETE FROM %s WHERE a = 2 AND b = 2 AND c = 7");
    beforeAndAfterFlush(() -> {
        assertRows(execute("SELECT * FROM %s WHERE a = 1 AND b = 4 AND c = 4"), row(1, 4, 4, 5));
        // Checks filtering
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE a = 1 AND b = 4 AND c = 4 AND d = 5");
