            assertRows(execute("SELECT * FROM %s WHERE pk = text_as_blob('foo123') AND c > text_as_blob('');"), row(bytes("foo123"), bytes("1"), bytes("1")), row(bytes("foo123"), bytes("2"), bytes("2")));
            assertRows(execute("SELECT * FROM %s WHERE pk = text_as_blob('foo123') AND (c) > (text_as_blob(''));"), row(bytes("foo123"), bytes("1"), bytes("1")), row(bytes("foo123"), bytes("2"), bytes("2")));
            assertRows(execute("SELECT * FROM %s WHERE pk = text_as_blob('foo123') AND c >= text_as_blob('');"), row(bytes("foo123"), bytes("1"), bytes("1")), row(bytes("foo123"), bytes("2"), bytes("2")));
            assertRows(execute("SELECT * FROM %s WHERE pk = text_as_blob('foo123') AND (c) >= (text_as_blob(''));"), row(bytes("foo123"), bytes("1"), bytes("1")), row(bytes("foo123"), bytes("2"), bytes("2")));
            assertEmpty(execute("SELECT * FROM %s WHERE pk = text_as_blob('foo123') AND c <= text_as_blob('');"));
            assertEmpty(execute("SELECT * FROM %s WHERE pk = text_as_blob('foo123') AND (c) <= (text_as_blob(''));"));
            assertEmpty(execute("SELECT * FROM %s WHERE pk = text_as_blob('foo123') AND c < text_as_blob('');"));
            assertEmpty(execute("SELECT * FROM %s WHERE pk = text_as_blob('foo123') AND (c) < (text_as_blob(''));"));
            assertEmpty(execute("SELECT * FROM %s WHERE pk = text_as_blob('foo123') AND c > text_as_blob('') AND c < text_as_blob('');"));
        });
        if (options.contains("COMPACT")) {
            assertInvalidMessage("Invalid empty or null value for column c", "INSERT INTO %s (pk, c, v) VALUES (?, ?, ?)", bytes("foo123"), EMPTY_BYTE_BUFFER, bytes("4"));
        } else {
            execute("INSERT INTO %s (pk, c, v) VALUES (?, ?, ?)", bytes("foo123"), EMPTY_BYTE_BUFFER, bytes("4"));
            beforeAndAfterFlush(() -> {
                assertRows(execute("SELECT * FROM %s WHERE pk = text_as_blob('foo123') AND c = text_as_blob('');"), row(bytes("foo123"), EMPTY_BYTE_BUFFER, bytes("4")));
                assertRows(execute("SELECT * FROM %s WHERE pk = text_as_blob('foo123') AND (c) = (text_as_blob(''));"), row(bytes("foo123"), EMPTY_BYTE_BUFFER, bytes("4")));
                assertRows(execute("SELECT * FROM %s WHERE pk = text_as_blob('foo123') AND c IN (text_as_blob(''), text_as_blob('1'));"), row(bytes("foo123"), EMPTY_BYTE_BUFFER, bytes("4")), row(bytes("foo123"), bytes("1"), bytes("1")));
                assertRows(execute("SELECT * FROM %s WHERE pk = text_as_blob('foo123') AND (c) IN ((text_as_blob('')), (text_as_blob('1')));"), row(bytes("foo123"), EMPTY_BYTE_BUFFER, bytes("4")), row(bytes("foo123"), bytes("1"), bytes("1")));
