@Test
public void testCreateTableWithMemtable() throws Throwable {
    createTable("CREATE TABLE %s (a text, b int, c int, primary key (a, b))");
    assertSame(MemtableParams.DEFAULT.factory(), getCurrentColumnFamilyStore().metadata().params.memtable.factory());
    Class<? extends Memtable> defaultClass = getCurrentColumnFamilyStore().getTracker().getView().getCurrentMemtable().getClass();
    assertSchemaOption("memtable", null);
    testMemtableConfig("skiplist", SkipListMemtable.FACTORY, SkipListMemtable.class);
    testMemtableConfig("trie", MemtableParams.get("trie").factory(), TrieMemtable.class);
    testMemtableConfig("skiplist_remapped", SkipListMemtable.FACTORY, SkipListMemtable.class);
    testMemtableConfig("test_fullname", TestMemtable.FACTORY, SkipListMemtable.class);
    testMemtableConfig("test_shortname", SkipListMemtable.FACTORY, SkipListMemtable.class);
    testMemtableConfig("default", MemtableParams.DEFAULT.factory(), defaultClass);
    assertThrowsConfigurationException("The 'class_name' option must be specified.", "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH memtable = 'test_empty_class';");
    assertThrowsConfigurationException("The 'class_name' option must be specified.", "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH memtable = 'test_missing_class';");
    assertThrowsConfigurationException("Memtable class org.apache.cassandra.db.memtable.SkipListMemtable does not accept any futher parameters, but {invalid=throw} were given.", "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH memtable = 'test_invalid_param';");
    assertThrowsConfigurationException("Could not create memtable factory for class NotExisting", "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH memtable = 'test_unknown_class';");
    assertThrowsConfigurationException("Memtable class org.apache.cassandra.db.memtable.TestMemtable does not accept any futher parameters, but {invalid=throw} were given.", "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH memtable = 'test_invalid_extra_param';");
    assertThrowsConfigurationException("Could not create memtable factory for class " + InvalidMemtableFactoryMethod.class.getName(), "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH memtable = 'test_invalid_factory_method';");
    assertThrowsConfigurationException("Could not create memtable factory for class " + InvalidMemtableFactoryField.class.getName(), "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH memtable = 'test_invalid_factory_field';");
    assertThrowsConfigurationException("Memtable configuration \"unknown\" not found.", "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH memtable = 'unknown';");
}

@Test
public void testCreateTableWithCompression() throws Throwable {
    createTable("CREATE TABLE %s (a text, b int, c int, primary key (a, b))");
    assertSchemaOption("compression", map("chunk_length_in_kb", "16", "class", "org.apache.cassandra.io.compress.LZ4Compressor"));
    createTable("CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH compression = { 'class' : 'SnappyCompressor', 'chunk_length_in_kb' : 32 };");
    assertSchemaOption("compression", map("chunk_length_in_kb", "32", "class", "org.apache.cassandra.io.compress.SnappyCompressor"));
    createTable("CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH compression = { 'class' : 'SnappyCompressor', 'chunk_length_in_kb' : 32, 'enabled' : true };");
    assertSchemaOption("compression", map("chunk_length_in_kb", "32", "class", "org.apache.cassandra.io.compress.SnappyCompressor"));
    createTable("CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH compression = { 'class' : 'SnappyCompressor', 'min_compress_ratio' : 2 };");
    assertSchemaOption("compression", map("chunk_length_in_kb", "16", "class", "org.apache.cassandra.io.compress.SnappyCompressor", "min_compress_ratio", "2.0"));
    createTable("CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH compression = { 'class' : 'SnappyCompressor', 'min_compress_ratio' : 1 };");
    assertSchemaOption("compression", map("chunk_length_in_kb", "16", "class", "org.apache.cassandra.io.compress.SnappyCompressor", "min_compress_ratio", "1.0"));
    createTable("CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH compression = { 'class' : 'SnappyCompressor', 'min_compress_ratio' : 0 };");
    assertSchemaOption("compression", map("chunk_length_in_kb", "16", "class", "org.apache.cassandra.io.compress.SnappyCompressor"));
    createTable("CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH compression = { 'enabled' : 'false'};");
    assertSchemaOption("compression", map("enabled", "false"));
    assertThrowsConfigurationException("Missing sub-option 'class' for the 'compression' option.", "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH compression = {'chunk_length_in_kb' : 32};");
    assertThrowsConfigurationException("The 'class' option must not be empty. To disable compression use 'enabled' : false", "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH compression = { 'class' : ''};");
    assertThrowsConfigurationException("If the 'enabled' option is set to false no other options must be specified", "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH compression = { 'enabled' : 'false', 'class' : 'SnappyCompressor'};");
    assertThrowsConfigurationException("If the 'enabled' option is set to false no other options must be specified", "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH compression = { 'enabled' : 'false', 'chunk_length_in_kb' : 32};");
    assertThrowsConfigurationException("chunk_length_in_kb must be a power of 2", "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH compression = { 'class' : 'SnappyCompressor', 'chunk_length_in_kb' : 31 };");
    assertThrowsConfigurationException("Invalid negative or null chunk_length_in_kb", "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH compression = { 'class' : 'SnappyCompressor', 'chunk_length_in_kb' : -1 };");
    assertThrowsConfigurationException("Invalid negative min_compress_ratio", "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH compression = { 'class' : 'SnappyCompressor', 'min_compress_ratio' : -1 };");
    assertThrowsConfigurationException("Unknown compression options unknownOption", "CREATE TABLE %s (a text, b int, c int, primary key (a, b))" + " WITH compression = { 'class' : 'SnappyCompressor', 'unknownOption' : 32 };");
}

