@Test
public void compositeValuePk() {
    createTable(KEYSPACE, "CREATE TABLE %s (a blob, b blob, PRIMARY KEY ((a, b)))");
    // sum of columns is too large
    Assertions.assertThatThrownBy(() -> executeNet("INSERT INTO %s (a, b) VALUES (?, ?)", MEDIUM_BLOB, MEDIUM_BLOB)).hasRootCauseInstanceOf(InvalidQueryException.class).hasRootCauseMessage("Key length of " + (MEDIUM_BLOB.remaining() * 2) + " is longer than maximum of 65535");
    // single column is too large
    Assertions.assertThatThrownBy(() -> executeNet("INSERT INTO %s (a, b) VALUES (?, ?)", MEDIUM_BLOB, LARGE_BLOB)).hasRootCauseInstanceOf(InvalidQueryException.class).hasRootCauseMessage("Key length of " + (MEDIUM_BLOB.remaining() + LARGE_BLOB.remaining()) + " is longer than maximum of 65535");
    // null / empty checks
    // this is an inconsistent behavior... null is blocked by org.apache.cassandra.db.MultiCBuilder.OneClusteringBuilder.addElementToAll
    // but this does not count empty as null, and doesn't check for this case...  We have a requirement in cqlsh that empty is allowed when
    // user opts-in to allow it (NULL='-'), so we will find that null is blocked, but empty is allowed!
    Assertions.assertThatThrownBy(() -> executeNet("INSERT INTO %s (a, b) VALUES (?, ?)", new Object[] { null, null })).hasRootCauseInstanceOf(InvalidQueryException.class).hasRootCauseMessage("Invalid null value for column a");
    Assertions.assertThatThrownBy(() -> executeNet("INSERT INTO %s (a, b) VALUES (?, ?)", new Object[] { MEDIUM_BLOB, null })).hasRootCauseInstanceOf(InvalidQueryException.class).hasRootCauseMessage("Invalid null value for column b");
    Assertions.assertThatThrownBy(() -> executeNet("INSERT INTO %s (a, b) VALUES (?, ?)", new Object[] { null, MEDIUM_BLOB })).hasRootCauseInstanceOf(InvalidQueryException.class).hasRootCauseMessage("Invalid null value for column a");
    // empty is allowed when composite partition columns...
    executeNet("INSERT INTO %s (a, b) VALUES (?, ?)", EMPTY_BYTE_BUFFER, EMPTY_BYTE_BUFFER);
    execute("TRUNCATE %s");
    executeNet("INSERT INTO %s (a, b) VALUES (?, ?)", MEDIUM_BLOB, EMPTY_BYTE_BUFFER);
    execute("TRUNCATE %s");
    executeNet("INSERT INTO %s (a, b) VALUES (?, ?)", EMPTY_BYTE_BUFFER, MEDIUM_BLOB);
}

@Test
public void singleValueClustering() {
    createTable(KEYSPACE, "CREATE TABLE %s (a blob, b blob, PRIMARY KEY (a, b))");
    Assertions.assertThatThrownBy(() -> executeNet("INSERT INTO %s (a, b) VALUES (?, ?)", MEDIUM_BLOB, LARGE_BLOB)).hasRootCauseInstanceOf(InvalidQueryException.class).hasRootCauseMessage("Key length of " + LARGE_BLOB.remaining() + " is longer than maximum of 65535");
    // null / empty checks
    Assertions.assertThatThrownBy(() -> executeNet("INSERT INTO %s (a, b) VALUES (?, ?)", MEDIUM_BLOB, null)).hasRootCauseInstanceOf(InvalidQueryException.class).hasRootCauseMessage("Invalid null value for column b");
    // org.apache.cassandra.db.MultiCBuilder.OneClusteringBuilder.addElementToAll defines "null" differently than most of the code;
    // most of the code defines null as:
    //   value == null || accessor.isEmpty(value)
    // but the code defines null as
    //   value == null
    // In CASSANDRA-18504 a new isNull method was added to the type, as blob and text both "should" allow empty, but this scattered null logic doesn't allow...
    // For backwards compatability reasons, need to keep empty support
    executeNet("INSERT INTO %s (a, b) VALUES (?, ?)", MEDIUM_BLOB, EMPTY_BYTE_BUFFER);
}

@Test
public void compositeValueClustering() {
    createTable(KEYSPACE, "CREATE TABLE %s (a blob, b blob, c blob, PRIMARY KEY (a, b, c))");
    // sum of columns is too large
    Assertions.assertThatThrownBy(() -> executeNet("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", MEDIUM_BLOB, MEDIUM_BLOB, MEDIUM_BLOB)).hasRootCauseInstanceOf(InvalidQueryException.class).hasRootCauseMessage("Key length of " + (MEDIUM_BLOB.remaining() * 2) + " is longer than maximum of 65535");
