    assertRows(execute("SELECT a, b, d, count(b), max(d) FROM %s WHERE b IN (1, 2) and c IN (1, 2) GROUP BY a, b ALLOW FILTERING"), row(1, 1, 2, 2L, 2), row(1, 2, 3, 2L, 3), row(2, 1, 3, 2L, 3), row(2, 2, 4, 2L, 4), row(4, 1, 5, 2L, 5), row(4, 2, 6, 2L, 6));
