        assertInvalidMessage("Only monotonic functions are supported in the GROUP BY clause. Got: system.floor : (timestamp, duration(constant), timestamp) -> timestamp", "SELECT pk, floor(time, 2h, time), v FROM %s GROUP BY pk, floor(time, 2h, time)");
        execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27 16:10:00 UTC', 1)");
        execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27 16:12:00 UTC', 2)");
        execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27 16:14:00 UTC', 3)");
        execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27 16:15:00 UTC', 4)");
        execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27 16:21:00 UTC', 5)");
        execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27 16:22:00 UTC', 6)");
        execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27 16:26:00 UTC', 7)");
        execute("INSERT INTO %s (pk, time, v) VALUES (1, '2016-09-27 16:26:20 UTC', 8)");
        execute("INSERT INTO %s (pk, time, v) VALUES (2, '2016-09-27 16:26:20 UTC', 10)");
        execute("INSERT INTO %s (pk, time, v) VALUES (2, '2016-09-27 16:30:00 UTC', 11)");
        // Test prepared statement
        assertRows(execute("SELECT pk, floor(time, 5m, ?), min(v), max(v), count(v) FROM %s GROUP BY pk, floor(time, 5m, ?)", toTimestamp("2016-09-27 00:00:00 UTC"), toTimestamp("2016-09-27 00:00:00 UTC")), row(1, toTimestamp("2016-09-27 16:10:00 UTC"), 1, 3, 3L), row(1, toTimestamp("2016-09-27 16:15:00 UTC"), 4, 4, 1L), row(1, toTimestamp("2016-09-27 16:20:00 UTC"), 5, 6, 2L), row(1, toTimestamp("2016-09-27 16:25:00 UTC"), 7, 8, 2L), row(2, toTimestamp("2016-09-27 16:25:00 UTC"), 10, 10, 1L), row(2, toTimestamp("2016-09-27 16:30:00 UTC"), 11, 11, 1L));
        for (String startingTime : new String[] { "", ", '2016-09-27 UTC'" }) {
            assertRows(execute("SELECT pk, floor(time, 5m" + startingTime + "), min(v), max(v), count(v) FROM %s GROUP BY pk, floor(time, 5m" + startingTime + ")"), row(1, toTimestamp("2016-09-27 16:10:00 UTC"), 1, 3, 3L), row(1, toTimestamp("2016-09-27 16:15:00 UTC"), 4, 4, 1L), row(1, toTimestamp("2016-09-27 16:20:00 UTC"), 5, 6, 2L), row(1, toTimestamp("2016-09-27 16:25:00 UTC"), 7, 8, 2L), row(2, toTimestamp("2016-09-27 16:25:00 UTC"), 10, 10, 1L), row(2, toTimestamp("2016-09-27 16:30:00 UTC"), 11, 11, 1L));
            // Checks with duration lower than precisions
            assertInvalidMessage("The floor cannot be computed for the 10us duration as precision is below 1 millisecond", "SELECT pk, floor(time, 10us" + startingTime + "), min(v), max(v), count(v) FROM %s GROUP BY pk, floor(time, 10us" + startingTime + ")");
            // Checks with a negative duration
            assertInvalidMessage("Negative durations are not supported by the floor function", "SELECT pk, floor(time, 10us" + startingTime + "), min(v), max(v), count(v) FROM %s GROUP BY pk, floor(time, -5m" + startingTime + ")");
            assertRows(execute("SELECT pk, floor(time, 5m" + startingTime + "), min(v), max(v), count(v) FROM %s GROUP BY pk, floor(time, 5m" + startingTime + ") LIMIT 2"), row(1, toTimestamp("2016-09-27 16:10:00 UTC"), 1, 3, 3L), row(1, toTimestamp("2016-09-27 16:15:00 UTC"), 4, 4, 1L));
            assertRows(execute("SELECT pk, floor(time, 5m" + startingTime + "), min(v), max(v), count(v) FROM %s GROUP BY pk, floor(time, 5m" + startingTime + ") PER PARTITION LIMIT 1"), row(1, toTimestamp("2016-09-27 16:10:00 UTC"), 1, 3, 3L), row(2, toTimestamp("2016-09-27 16:25:00 UTC"), 10, 10, 1L));
            assertRows(execute("SELECT pk, floor(time, 5m" + startingTime + "), min(v), max(v), count(v) FROM %s WHERE pk = 1 GROUP BY pk, floor(time, 5m" + startingTime + ") ORDER BY time DESC"), row(1, toTimestamp("2016-09-27 16:25:00 UTC"), 7, 8, 2L), row(1, toTimestamp("2016-09-27 16:20:00 UTC"), 5, 6, 2L), row(1, toTimestamp("2016-09-27 16:15:00 UTC"), 4, 4, 1L), row(1, toTimestamp("2016-09-27 16:10:00 UTC"), 1, 3, 3L));
            assertRows(execute("SELECT pk, floor(time, 5m" + startingTime + "), min(v), max(v), count(v) FROM %s WHERE pk = 1 GROUP BY pk, floor(time, 5m" + startingTime + ") ORDER BY time DESC LIMIT 2"), row(1, toTimestamp("2016-09-27 16:25:00 UTC"), 7, 8, 2L), row(1, toTimestamp("2016-09-27 16:20:00 UTC"), 5, 6, 2L));
        }
        // Checks with start time is greater than the timestamp
        assertInvalidMessage("The floor function starting time is greater than the provided time", "SELECT pk, floor(time, 5m, '2016-10-27'), min(v), max(v), count(v) FROM %s GROUP BY pk, floor(time, 5m, '2016-10-27')");
