@Test
public void testNonEqualsRelation() {
    createTable("CREATE TABLE %s (a int, b int, c int, PRIMARY KEY (a, b, c))");
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 0, 0, 0);
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 0, 0, 1);
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 0, 1, 0);
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 0, 1, 1);
    // Excluding subtrees
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND (b) != (?)", 0, 0), row(0, 1, 0), row(0, 1, 1));
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND (b) != (?)", 0, 1), row(0, 0, 0), row(0, 0, 1));
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND (b) != (?)", 0, -1), row(0, 0, 0), row(0, 0, 1), row(0, 1, 0), row(0, 1, 1));
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND (b) != (?)", 0, 2), row(0, 0, 0), row(0, 0, 1), row(0, 1, 0), row(0, 1, 1));
    // Excluding single rows
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND (b, c) != (?, ?)", 0, -1, -1), row(0, 0, 0), row(0, 0, 1), row(0, 1, 0), row(0, 1, 1));
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND (b, c) != (?, ?)", 0, 0, 1), row(0, 0, 0), row(0, 1, 0), row(0, 1, 1));
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND (b, c) != (?, ?)", 0, 2, 2), row(0, 0, 0), row(0, 0, 1), row(0, 1, 0), row(0, 1, 1));
    // Merging multiple != =
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND (b, c) != ? AND (b, c) != ?", 0, tuple(0, 1), tuple(1, 0)), row(0, 0, 0), row(0, 1, 1));
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND b != ? AND (b, c) != ?", 0, 1, tuple(0, 1)), row(0, 0, 0));
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND (b) != (?) AND (b, c) != ?", 0, 1, tuple(0, 1)), row(0, 0, 0));
    // Merging with < <= >= >
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND b < ? AND (b, c) != ?", 0, 1, tuple(0, 1)), row(0, 0, 0));
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND b <= ? AND (b, c) != ?", 0, 0, tuple(0, 1)), row(0, 0, 0));
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND b > ? AND (b, c) != ?", 0, 0, tuple(1, 1)), row(0, 1, 0));
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND b >= ? AND (b, c) != ?", 0, 1, tuple(1, 1)), row(0, 1, 0));
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND (b, c) < ? AND (b, c) != ?", 0, tuple(0, 2), tuple(0, 1)), row(0, 0, 0));
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND (b, c) <= ? AND (b, c) != ?", 0, tuple(0, 2), tuple(0, 1)), row(0, 0, 0));
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND (b, c) > ? AND (b, c) != ?", 0, tuple(0, 0), tuple(1, 1)), row(0, 0, 1), row(0, 1, 0));
    assertRows(execute("SELECT a, b, c FROM %s WHERE a = ? AND (b, c) >= ? AND (b, c) != ?", 0, tuple(0, 1), tuple(1, 1)), row(0, 0, 1), row(0, 1, 0));
}

