    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) > ? AND (c1, c2) <= ? AND (c1, c2) NOT IN (?)", 1, tuple(0, 2), tuple(1, 2), tuple(0, 4)), row(1, 0, 3, 13), row(1, 1, 1, 21), row(1, 1, 2, 22));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) >= ? AND (c1, c2) <= ? AND (c1, c2) NOT IN (?)", 1, tuple(0, 2), tuple(1, 2), tuple(0, 4)), row(1, 0, 2, 12), row(1, 0, 3, 13), row(1, 1, 1, 21), row(1, 1, 2, 22));
    // Mixed multi-column NOT IN with single column slice restriction:
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND c1 > ? AND (c1, c2) NOT IN (?)", 1, 0, tuple(1, 2)), row(1, 1, 1, 21), row(1, 1, 3, 23), row(1, 1, 4, 24));
