    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) < ? AND (c1, c2) NOT IN (?)", 1, tuple(1, 2), tuple(2, 5)), row(1, 1, 1, 21), row(1, 0, 1, 11), row(1, 0, 2, 12), row(1, 0, 3, 13), row(1, 0, 4, 14));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) > ? AND (c1, c2) NOT IN (?)", 1, tuple(1, 2), tuple(1, 1)), row(1, 1, 3, 23), row(1, 1, 4, 24));
    // Empty result set
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) > ? AND (c1, c2) NOT IN (?, ?)", 1, tuple(1, 2), tuple(1, 3), tuple(1, 4)));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) < ? AND (c1, c2) NOT IN (?, ?)", 1, tuple(0, 3), tuple(0, 2), tuple(0, 1)));
    // NOT IN values inside slice bounds
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) < ? AND (c1, c2) NOT IN (?)", 1, tuple(1, 2), tuple(0, 2)), row(1, 1, 1, 21), row(1, 0, 1, 11), row(1, 0, 3, 13), row(1, 0, 4, 14));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) <= ? AND (c1, c2) NOT IN (?)", 1, tuple(1, 2), tuple(0, 2)), row(1, 1, 1, 21), row(1, 1, 2, 22), row(1, 0, 1, 11), row(1, 0, 3, 13), row(1, 0, 4, 14));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) > ? AND (c1, c2) NOT IN (?)", 1, tuple(1, 1), tuple(1, 3)), row(1, 1, 2, 22), row(1, 1, 4, 24));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) >= ? AND (c1, c2) NOT IN (?)", 1, tuple(1, 1), tuple(1, 3)), row(1, 1, 1, 21), row(1, 1, 2, 22), row(1, 1, 4, 24));
    // One NOT IN value exactly the same as the slice bound
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) < ? AND (c1, c2) NOT IN (?, ?)", 1, tuple(1, 2), tuple(0, 2), tuple(1, 2)), row(1, 1, 1, 21), row(1, 0, 1, 11), row(1, 0, 3, 13), row(1, 0, 4, 14));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) <= ? AND (c1, c2) NOT IN (?, ?)", 1, tuple(1, 2), tuple(0, 2), tuple(1, 2)), row(1, 1, 1, 21), row(1, 0, 1, 11), row(1, 0, 3, 13), row(1, 0, 4, 14));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) > ? AND (c1, c2) NOT IN (?)", 1, tuple(1, 1), tuple(1, 1)), row(1, 1, 2, 22), row(1, 1, 3, 23), row(1, 1, 4, 24));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) >= ? AND (c1, c2) NOT IN (?)", 1, tuple(1, 1), tuple(1, 1)), row(1, 1, 2, 22), row(1, 1, 3, 23), row(1, 1, 4, 24));
    // NOT IN with both upper and lower bound
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) > ? AND (c1, c2) < ? AND (c1, c2) NOT IN (?)", 1, tuple(0, 2), tuple(1, 2), tuple(0, 4)), row(1, 1, 1, 21), row(1, 0, 3, 13));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) >= ? AND (c1, c2) < ? AND (c1, c2) NOT IN (?)", 1, tuple(0, 2), tuple(1, 2), tuple(0, 4)), row(1, 1, 1, 21), row(1, 0, 2, 12), row(1, 0, 3, 13));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) > ? AND (c1, c2) <= ? AND (c1, c2) NOT IN (?)", 1, tuple(0, 2), tuple(1, 2), tuple(0, 4)), row(1, 1, 1, 21), row(1, 1, 2, 22), row(1, 0, 3, 13));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) >= ? AND (c1, c2) <= ? AND (c1, c2) NOT IN (?)", 1, tuple(0, 2), tuple(1, 2), tuple(0, 4)), row(1, 1, 1, 21), row(1, 1, 2, 22), row(1, 0, 2, 12), row(1, 0, 3, 13));
    // Mixed multi-column NOT IN with single column slice restriction:
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND c1 > ? AND (c1, c2) NOT IN (?)", 1, 0, tuple(1, 2)), row(1, 1, 1, 21), row(1, 1, 3, 23), row(1, 1, 4, 24));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND c1 >= ? AND (c1, c2) NOT IN (?)", 1, 1, tuple(1, 2)), row(1, 1, 1, 21), row(1, 1, 3, 23), row(1, 1, 4, 24));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND c1 < ? AND (c1, c2) NOT IN (?)", 1, 1, tuple(0, 4)), row(1, 0, 1, 11), row(1, 0, 2, 12), row(1, 0, 3, 13));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND c1 <= ? AND (c1, c2) NOT IN (?)", 1, 0, tuple(0, 4)), row(1, 0, 1, 11), row(1, 0, 2, 12), row(1, 0, 3, 13));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND c1 >= ? AND c1 <= ? AND (c1, c2) NOT IN (?)", 1, 0, 1, tuple(0, 4)), row(1, 1, 1, 21), row(1, 1, 2, 22), row(1, 1, 3, 23), row(1, 1, 4, 24), row(1, 0, 1, 11), row(1, 0, 2, 12), row(1, 0, 3, 13));
    // Mixed single-column NOT IN with multi-column slice restriction:
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) > ? AND c1 NOT IN (?)", 1, tuple(0, 1), 1), row(1, 0, 2, 12), row(1, 0, 3, 13), row(1, 0, 4, 14));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) >= ? AND c1 NOT IN (?)", 1, tuple(0, 1), 1), row(1, 0, 1, 11), row(1, 0, 2, 12), row(1, 0, 3, 13), row(1, 0, 4, 14));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) < ? AND c1 NOT IN (?)", 1, tuple(1, 3), 1), row(1, 0, 1, 11), row(1, 0, 2, 12), row(1, 0, 3, 13), row(1, 0, 4, 14));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) < ? AND c1 NOT IN (?)", 1, tuple(1, 3), 0), row(1, 1, 1, 21), row(1, 1, 2, 22));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) <= ? AND c1 NOT IN (?)", 1, tuple(1, 3), 0), row(1, 1, 1, 21), row(1, 1, 2, 22), row(1, 1, 3, 23));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) >= ? AND (c1, c2) <= ? AND c1 NOT IN (?)", 1, tuple(0, 2), tuple(1, 3), 0), row(1, 1, 1, 21), row(1, 1, 2, 22), row(1, 1, 3, 23));
    // Mixed single-column and multi column slices with multi column NOT IN:
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) > ? AND c1 < ? AND (c1, c2) NOT IN (?)", 1, tuple(0, 1), 1, tuple(0, 3)), row(1, 0, 2, 12), row(1, 0, 4, 14));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND (c1, c2) > ? AND c1 <= ? AND (c1, c2) NOT IN (?)", 1, tuple(0, 1), 0, tuple(0, 3)), row(1, 0, 2, 12), row(1, 0, 4, 14));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND c1 > ? AND (c1, c2) < ? AND (c1, c2) NOT IN (?)", 1, 0, tuple(1, 4), tuple(1, 2)), row(1, 1, 1, 21), row(1, 1, 3, 23));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND c1 >= ? AND (c1, c2) < ? AND (c1, c2) NOT IN (?)", 1, 1, tuple(1, 4), tuple(1, 2)), row(1, 1, 1, 21), row(1, 1, 3, 23));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND c1 > ? AND c1 < ? AND (c1, c2) NOT IN (?)", 1, 0, 2, tuple(1, 2)), row(1, 1, 1, 21), row(1, 1, 3, 23), row(1, 1, 4, 24));
    assertRows(execute("SELECT * FROM %s WHERE pk = ? AND c1 >= ? AND c1 <= ? AND (c1, c2) NOT IN (?)", 1, 1, 1, tuple(1, 2)), row(1, 1, 1, 21), row(1, 1, 3, 23), row(1, 1, 4, 24));
}

@Test
public void testNormalSelectionOrderSingleClustering() throws Throwable {
    createTable("CREATE TABLE %s (a int, b int, c int, PRIMARY KEY (a, b))");
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 0, 0, 0);
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 0, 1, 1);
