@Test
public void testClusteringColumnRelations() throws Throwable {
    createTable("CREATE TABLE %s (a text, b int, c int, d int, primary key(a, b, c))");
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "first", 1, 5, 1);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "first", 2, 6, 2);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "first", 3, 7, 3);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "second", 4, 8, 4);
    assertRows(execute("select * from %s where a in (?, ?)", "first", "second"), row("first", 1, 5, 1), row("first", 2, 6, 2), row("first", 3, 7, 3), row("second", 4, 8, 4));
    assertRows(execute("select * from %s where a = ? and b = ? and c in (?, ?)", "first", 2, 6, 7), row("first", 2, 6, 2));
    assertRows(execute("select * from %s where a = ? and b in (?, ?) and c in (?, ?)", "first", 2, 3, 6, 7), row("first", 2, 6, 2), row("first", 3, 7, 3));
    assertRows(execute("select * from %s where a = ? and b in (?, ?) and c in (?, ?)", "first", 3, 2, 7, 6), row("first", 2, 6, 2), row("first", 3, 7, 3));
    assertRows(execute("select * from %s where a = ? and c in (?, ?) and b in (?, ?)", "first", 7, 6, 3, 2), row("first", 2, 6, 2), row("first", 3, 7, 3));
    assertRows(execute("select c, d from %s where a = ? and c in (?, ?) and b in (?, ?)", "first", 7, 6, 3, 2), row(6, 2), row(7, 3));
    assertRows(execute("select c, d from %s where a = ? and c in (?, ?) and b in (?, ?, ?)", "first", 7, 6, 3, 2, 3), row(6, 2), row(7, 3));
    assertRows(execute("select * from %s where a = ? and b in (?, ?) and c = ?", "first", 3, 2, 7), row("first", 3, 7, 3));
    assertRows(execute("select * from %s where a = ? and b in ? and c in ?", "first", Arrays.asList(3, 2), Arrays.asList(7, 6)), row("first", 2, 6, 2), row("first", 3, 7, 3));
    assertInvalidMessage("Invalid null value for column b", "select * from %s where a = ? and b in ? and c in ?", "first", null, Arrays.asList(7, 6));
    assertRows(execute("select * from %s where a = ? and c >= ? and b in (?, ?)", "first", 6, 3, 2), row("first", 2, 6, 2), row("first", 3, 7, 3));
    assertRows(execute("select * from %s where a = ? and c > ? and b in (?, ?)", "first", 6, 3, 2), row("first", 3, 7, 3));
    assertRows(execute("select * from %s where a = ? and c <= ? and b in (?, ?)", "first", 6, 3, 2), row("first", 2, 6, 2));
    assertRows(execute("select * from %s where a = ? and c < ? and b in (?, ?)", "first", 7, 3, 2), row("first", 2, 6, 2));
    assertRows(execute("select * from %s where a = ? and c >= ? and c <= ? and b in (?, ?)", "first", 6, 7, 3, 2), row("first", 2, 6, 2), row("first", 3, 7, 3));
    assertRows(execute("select * from %s where a = ? and c > ? and c <= ? and b in (?, ?)", "first", 6, 7, 3, 2), row("first", 3, 7, 3));
    assertEmpty(execute("select * from %s where a = ? and c > ? and c < ? and b in (?, ?)", "first", 6, 7, 3, 2));
    assertRows(execute("SELECT * FROM %s WHERE a = ? AND b = ? AND c BETWEEN ? AND ?", "first", 1, 4, 5), row("first", 1, 5, 1));
    assertInvalidMessage("c cannot be restricted by more than one relation if it includes an Equal", "select * from %s where a = ? and c > ? and c = ? and b in (?, ?)", "first", 6, 7, 3, 2);
    assertInvalidMessage("c cannot be restricted by more than one relation if it includes an Equal", "select * from %s where a = ? and c = ? and c > ?  and b in (?, ?)", "first", 6, 7, 3, 2);
    assertRows(execute("select * from %s where a = ? and c in (?, ?) and b in (?, ?) order by b DESC", "first", 7, 6, 3, 2), row("first", 3, 7, 3), row("first", 2, 6, 2));
    assertInvalidMessage("More than one restriction was found for the start bound on b", "select * from %s where a = ? and b > ? and b > ?", "first", 6, 3, 2);
    assertInvalidMessage("More than one restriction was found for the end bound on b", "select * from %s where a = ? and b < ? and b <= ?", "first", 6, 3, 2);
    assertInvalidMessage("More than one restriction was found for the start bound on b", "SELECT * FROM %s WHERE a = ? AND b > ? AND b BETWEEN ? AND ?", "first", 6, 3, 2);
    assertInvalidMessage("More than one restriction was found for the end bound on b", "SELECT * FROM %s WHERE a = ? AND b < ? AND b BETWEEN ? AND ?", "first", 6, 3, 2);
}

@Test
public void testPartitionKeyColumnRelations() throws Throwable {
    createTable("CREATE TABLE %s (a text, b int, c int, d int, primary key((a, b), c))");
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "first", 1, 1, 1);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "first", 2, 2, 2);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "first", 3, 3, 3);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "first", 4, 4, 4);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "second", 1, 1, 1);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "second", 4, 4, 4);
    assertRows(execute("select * from %s where a = ? and b = ?", "first", 2), row("first", 2, 2, 2));
    assertRows(execute("select * from %s where a in (?, ?) and b in (?, ?)", "first", "second", 2, 3), row("first", 2, 2, 2), row("first", 3, 3, 3));
    assertRows(execute("select * from %s where a in (?, ?) and b = ?", "first", "second", 4), row("first", 4, 4, 4), row("second", 4, 4, 4));
    assertRows(execute("select * from %s where a = ? and b in (?, ?)", "first", 3, 4), row("first", 3, 3, 3), row("first", 4, 4, 4));
    assertRows(execute("select * from %s where a in (?, ?) and b in (?, ?)", "first", "second", 1, 4), row("first", 1, 1, 1), row("first", 4, 4, 4), row("second", 1, 1, 1), row("second", 4, 4, 4));
    assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "select * from %s where a in (?, ?)", "first", "second");
    assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "select * from %s where a = ?", "first");
    assertInvalidMessage("b cannot be restricted by more than one relation if it includes a IN", "select * from %s where a = ? AND b IN (?, ?) AND b = ?", "first", 2, 2, 3);
    assertInvalidMessage("b cannot be restricted by more than one relation if it includes an Equal", "select * from %s where a = ? AND b = ? AND b IN (?, ?)", "first", 2, 2, 3);
    assertInvalidMessage("a cannot be restricted by more than one relation if it includes a IN", "select * from %s where a IN (?, ?) AND a = ? AND b = ?", "first", "second", "first", 3);
    assertInvalidMessage("a cannot be restricted by more than one relation if it includes an Equal", "select * from %s where a = ? AND a IN (?, ?) AND b IN (?, ?)", "first", "second", "first", 2, 3);
}

