public void testInRestrictionsWithAllowFiltering() {
    createTable("CREATE TABLE %s (pk1 int, pk2 int, c text, s int static, v int, primary key((pk1, pk2), c))");
    execute("INSERT INTO %s (pk1, pk2, c, s, v) values (?, ?, ?, ?, ?)", 1, 0, "5", 1, 3);
    execute("INSERT INTO %s (pk1, pk2, c, s, v) values (?, ?, ?, ?, ?)", 1, 0, "7", 1, 2);
    execute("INSERT INTO %s (pk1, pk2, c, s, v) values (?, ?, ?, ?, ?)", 1, 1, "7", 1, 3);
    execute("INSERT INTO %s (pk1, pk2, c, s, v) values (?, ?, ?, ?, ?)", 2, 0, "4", 2, 1);
    execute("INSERT INTO %s (pk1, pk2, c, s, v) values (?, ?, ?, ?, ?)", 2, 3, "6", 2, 8);
    // Test filtering on regular columns
    assertRows(execute("SELECT * FROM %s WHERE v IN (?, ?) ALLOW FILTERING", 4, 3), row(1, 0, "5", 1, 3), row(1, 1, "7", 1, 3));
    assertRows(execute("SELECT * FROM %s WHERE v IN ? ALLOW FILTERING", list(4, 3)), row(1, 0, "5", 1, 3), row(1, 1, "7", 1, 3));
    // Test filtering on clustering columns
    assertRows(execute("SELECT * FROM %s WHERE c IN (?, ?, ?) ALLOW FILTERING", "7", "6", "8"), row(2, 3, "6", 2, 8), row(1, 0, "7", 1, 2), row(1, 1, "7", 1, 3));
    assertRows(execute("SELECT * FROM %s WHERE c IN ? ALLOW FILTERING", list("7", "6", "8")), row(2, 3, "6", 2, 8), row(1, 0, "7", 1, 2), row(1, 1, "7", 1, 3));
    // Test filtering on partition keys
    assertRows(execute("SELECT * FROM %s WHERE pk1 IN (?, ?) ALLOW FILTERING", 1, 3), row(1, 0, "5", 1, 3), row(1, 0, "7", 1, 2), row(1, 1, "7", 1, 3));
    assertRows(execute("SELECT * FROM %s WHERE pk1 IN ? ALLOW FILTERING", list(1, 3)), row(1, 0, "5", 1, 3), row(1, 0, "7", 1, 2), row(1, 1, "7", 1, 3));
    // Test filtering on static columns
    assertRows(execute("SELECT * FROM %s WHERE s IN (?, ?) ALLOW FILTERING", 1, 3), row(1, 0, "5", 1, 3), row(1, 0, "7", 1, 2), row(1, 1, "7", 1, 3));
    assertRows(execute("SELECT * FROM %s WHERE s IN ? ALLOW FILTERING", list(1, 3)), row(1, 0, "5", 1, 3), row(1, 0, "7", 1, 2), row(1, 1, "7", 1, 3));
}

