@Test
public void testClusteringSlicesWithNotIn() {
    createTable("CREATE TABLE %s (a text, b int, c int, d int, primary key(a, b, c))");
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "key", 1, 4, 1);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "key", 2, 5, 2);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "key", 2, 6, 3);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "key", 2, 7, 4);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "key", 3, 8, 5);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "key", 3, 9, 6);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "key", 4, 1, 7);
    execute("insert into %s (a, b, c, d) values (?, ?, ?, ?)", "key", 4, 2, 8);
    // restrict first clustering column by NOT IN
    assertRows(execute("select * from %s where a = ? and b not in ?", "key", list(2, 4, 5)), row("key", 1, 4, 1), row("key", 3, 8, 5), row("key", 3, 9, 6));
    assertRows(execute("select * from %s where a = ? and b not in (?, ?, ?)", "key", 2, 4, 5), row("key", 1, 4, 1), row("key", 3, 8, 5), row("key", 3, 9, 6));
    // use different order of items in NOT IN list:
    assertRows(execute("select * from %s where a = ? and b not in (?, ?, ?)", "key", 5, 2, 4), row("key", 1, 4, 1), row("key", 3, 8, 5), row("key", 3, 9, 6));
    assertRows(execute("select * from %s where a = ? and b not in (?, ?, ?)", "key", 5, 4, 2), row("key", 1, 4, 1), row("key", 3, 8, 5), row("key", 3, 9, 6));
    // restrict last clustering column by NOT IN
    assertRows(execute("select * from %s where a = ? and b = ? and c not in ?", "key", 2, list(5, 6)), row("key", 2, 7, 4));
    assertRows(execute("select * from %s where a = ? and b = ? and c not in (?, ?)", "key", 2, 5, 6), row("key", 2, 7, 4));
    // empty NOT IN should have no effect:
    assertRows(execute("select * from %s where a = ? and b = ? and c not in ?", "key", 2, list()), row("key", 2, 5, 2), row("key", 2, 6, 3), row("key", 2, 7, 4));
    assertRows(execute("select * from %s where a = ? and b = ? and c not in ()", "key", 2), row("key", 2, 5, 2), row("key", 2, 6, 3), row("key", 2, 7, 4));
    // NOT IN value that doesn't match any data should have no effect:
    assertRows(execute("select * from %s where a = ? and b = ? and c not in (?)", "key", 2, 0), row("key", 2, 5, 2), row("key", 2, 6, 3), row("key", 2, 7, 4));
    // Duplicate NOT IN values:
    assertRows(execute("select * from %s where a = ? and b = ? and c not in (?, ?)", "key", 2, 5, 5), row("key", 2, 6, 3), row("key", 2, 7, 4));
    // mix NOT IN and '<' and '<=' comparison on the same column
    // empty
    assertRows(execute("select * from %s where a = ? and b not in ? and b < ?", "key", list(2, 5), 1));
    assertRows(execute("select * from %s where a = ? and b not in ? and b < ?", "key", list(2, 5), 3), row("key", 1, 4, 1));
    assertRows(execute("select * from %s where a = ? and b not in ? and b <= ?", "key", list(2), 2), row("key", 1, 4, 1));
    assertRows(execute("select * from %s where a = ? and b not in ? and b <= ?", "key", list(2), 3), row("key", 1, 4, 1), row("key", 3, 8, 5), row("key", 3, 9, 6));
    assertRows(execute("select * from %s where a = ? and b not in ? and b <= ?", "key", list(2), 10), row("key", 1, 4, 1), row("key", 3, 8, 5), row("key", 3, 9, 6), row("key", 4, 1, 7), row("key", 4, 2, 8));
    // mix NOT IN and '>' and '>=' comparison on the same column
    assertRows(execute("select * from %s where a = ? and b not in ? and b > ?", "key", list(2), 1), row("key", 3, 8, 5), row("key", 3, 9, 6), row("key", 4, 1, 7), row("key", 4, 2, 8));
    assertRows(execute("select * from %s where a = ? and b not in ? and b > ?", "key", list(2), 2), row("key", 3, 8, 5), row("key", 3, 9, 6), row("key", 4, 1, 7), row("key", 4, 2, 8));
    assertRows(execute("select * from %s where a = ? and b not in ? and b >= ?", "key", list(2), 2), row("key", 3, 8, 5), row("key", 3, 9, 6), row("key", 4, 1, 7), row("key", 4, 2, 8));
    assertRows(execute("select * from %s where a = ? and b not in ? and b >= ?", "key", list(2), 4), row("key", 4, 1, 7), row("key", 4, 2, 8));
    assertRows(execute("select * from %s where a = ? and b not in ? and b >= ?", "key", list(2), 0), row("key", 1, 4, 1), row("key", 3, 8, 5), row("key", 3, 9, 6), row("key", 4, 1, 7), row("key", 4, 2, 8));
    // mix NOT IN and range slice
    assertRows(execute("select * from %s where a = ? and b not in ? and b > ? and b < ?", "key", list(2), 1, 4), row("key", 3, 8, 5), row("key", 3, 9, 6));
    assertRows(execute("select * from %s where a = ? and b not in ? and b >= ? and b < ?", "key", list(2), 1, 4), row("key", 1, 4, 1), row("key", 3, 8, 5), row("key", 3, 9, 6));
    assertRows(execute("select * from %s where a = ? and b not in ? and b > ? and b <= ?", "key", list(2), 1, 4), row("key", 3, 8, 5), row("key", 3, 9, 6), row("key", 4, 1, 7), row("key", 4, 2, 8));
    assertRows(execute("select * from %s where a = ? and b not in ? and b >= ? and b <= ?", "key", list(2), 1, 4), row("key", 1, 4, 1), row("key", 3, 8, 5), row("key", 3, 9, 6), row("key", 4, 1, 7), row("key", 4, 2, 8));
    // Collision between a slice bound and NOT IN value:
    assertRows(execute("select * from %s where a = ? and b not in ? and b < ?", "key", list(2), 2), row("key", 1, 4, 1));
    assertRows(execute("select * from %s where a = ? and b not in ? and b > ?", "key", list(2), 2), row("key", 3, 8, 5), row("key", 3, 9, 6), row("key", 4, 1, 7), row("key", 4, 2, 8));
    // NOT IN value outside the slice range:
    assertRows(execute("select * from %s where a = ? and b not in ? and b > ? and b < ?", "key", list(0), 2, 4), row("key", 3, 8, 5), row("key", 3, 9, 6));
    assertRows(execute("select * from %s where a = ? and b not in ? and b > ? and b < ?", "key", list(10), 2, 4), row("key", 3, 8, 5), row("key", 3, 9, 6));
    // multiple NOT IN on the same column, use different ways of passing a list
    assertRows(execute("select * from %s where a = ? and b not in ? and b not in ?", "key", list(1, 2), list(4)), row("key", 3, 8, 5), row("key", 3, 9, 6));
    assertRows(execute("select * from %s where a = ? and b not in (?, ?) and b not in (?)", "key", 1, 2, 4), row("key", 3, 8, 5), row("key", 3, 9, 6));
    assertRows(execute("select * from %s where a = ? and b not in (?, ?) and b not in ?", "key", 1, 2, list(4)), row("key", 3, 8, 5), row("key", 3, 9, 6));
    // mix IN and NOT IN
    assertRows(execute("select * from %s where a = ? and b in ? and c not in ?", "key", list(2, 3), list(5, 6, 9)), row("key", 2, 7, 4), row("key", 3, 8, 5));
}

