@Test
public void testNotInRestrictionsWithAllowFiltering() {
    createTable("CREATE TABLE %s (pk int, c int, v int, primary key(pk, c))");
    execute("insert into %s (pk, c, v) values (?, ?, ?)", 1, 1, 1);
    execute("insert into %s (pk, c, v) values (?, ?, ?)", 1, 2, 2);
    execute("insert into %s (pk, c, v) values (?, ?, ?)", 1, 3, 3);
    execute("insert into %s (pk, c, v) values (?, ?, ?)", 1, 4, 4);
    execute("insert into %s (pk, c, v) values (?, ?, ?)", 1, 5, 5);
    // empty NOT IN set
    assertRows(execute("select * from %s where pk = ? and v not in ? allow filtering", 1, list()), row(1, 1, 1), row(1, 2, 2), row(1, 3, 3), row(1, 4, 4), row(1, 5, 5));
    assertRows(execute("select * from %s where pk = ? and v not in () allow filtering", 1), row(1, 1, 1), row(1, 2, 2), row(1, 3, 3), row(1, 4, 4), row(1, 5, 5));
    // NOT IN with values that don't match any data
    assertRows(execute("select * from %s where pk = ? and v not in (?, ?) allow filtering", 1, -6, 20), row(1, 1, 1), row(1, 2, 2), row(1, 3, 3), row(1, 4, 4), row(1, 5, 5));
    // NOT IN that excludes a few values
    assertRows(execute("select * from %s where pk = ? and v not in ? allow filtering", 1, list(2, 3)), row(1, 1, 1), row(1, 4, 4), row(1, 5, 5));
    assertRows(execute("select * from %s where pk = ? and v not in (?, ?) allow filtering", 1, 2, 3), row(1, 1, 1), row(1, 4, 4), row(1, 5, 5));
    // NOT IN with one-sided slice filters:
    assertRows(execute("select * from %s where pk = ? and v not in ? and v < ? allow filtering", 1, list(2, 3), 5), row(1, 1, 1), row(1, 4, 4));
    assertRows(execute("select * from %s where pk = ? and v not in ? and v < ? allow filtering", 1, list(2, 3, 10), 5), row(1, 1, 1), row(1, 4, 4));
    assertRows(execute("select * from %s where pk = ? and v not in ? and v <= ? allow filtering", 1, list(2, 3), 5), row(1, 1, 1), row(1, 4, 4), row(1, 5, 5));
    assertRows(execute("select * from %s where pk = ? and v not in ? and v <= ? allow filtering", 1, list(2, 3, 10), 5), row(1, 1, 1), row(1, 4, 4), row(1, 5, 5));
    assertRows(execute("select * from %s where pk = ? and v not in ? and v > ? allow filtering", 1, list(2, 3), 1), row(1, 4, 4), row(1, 5, 5));
    assertRows(execute("select * from %s where pk = ? and v not in ? and v > ? allow filtering", 1, list(0, 2, 3), 1), row(1, 4, 4), row(1, 5, 5));
    assertRows(execute("select * from %s where pk = ? and v not in ? and v >= ? allow filtering", 1, list(2, 3), 1), row(1, 1, 1), row(1, 4, 4), row(1, 5, 5));
    assertRows(execute("select * from %s where pk = ? and v not in ? and v >= ? allow filtering", 1, list(0, 2, 3), 1), row(1, 1, 1), row(1, 4, 4), row(1, 5, 5));
    // NOT IN with range filters:
    // empty
    assertRows(execute("select * from %s where pk = ? and v not in ? and v > ? and v < ? allow filtering", 1, list(2, 3), 1, 4));
    // empty
    assertRows(execute("select * from %s where pk = ? and v not in ? and v > ? and v < ? allow filtering", 1, list(2, 3), 1, 4));
    assertRows(execute("select * from %s where pk = ? and v not in ? and v > ? and v < ? allow filtering", 1, list(2, 3), 0, 5), row(1, 1, 1), row(1, 4, 4));
    assertRows(execute("select * from %s where pk = ? and v not in ? and v >= ? and v < ? allow filtering", 1, list(2, 3), 1, 4), row(1, 1, 1));
    assertRows(execute("select * from %s where pk = ? and v not in ? and v > ? and v <= ? allow filtering", 1, list(2, 3), 1, 4), row(1, 4, 4));
    assertRows(execute("select * from %s where pk = ? and v not in ? and v >= ? and v <= ? allow filtering", 1, list(2, 3), 1, 4), row(1, 1, 1), row(1, 4, 4));
    // more than one NOT IN clause
    assertRows(execute("select * from %s where pk = ? and v not in ? and v not in ? allow filtering", 1, list(2), list(3)), row(1, 1, 1), row(1, 4, 4), row(1, 5, 5));
}

@Test
public void testNonEqualsRelationWithFiltering() {
    createTable("CREATE TABLE %s (a int, b int, c int, PRIMARY KEY (a, b))");
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 0, 0, 0);
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 0, 1, 1);
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 0, 2, 2);
    execute("INSERT INTO %s (a, b, c) VALUES (?, ?, ?)", 0, 3, 3);
    assertRows(execute("SELECT a, b FROM %s WHERE a = ? AND c != ? ALLOW FILTERING", 0, 0), row(0, 1), row(0, 2), row(0, 3));
    assertRows(execute("SELECT a, b FROM %s WHERE a = ? AND c != ? ALLOW FILTERING", 0, 1), row(0, 0), row(0, 2), row(0, 3));
    assertRows(execute("SELECT a, b FROM %s WHERE a = ? AND c != ? ALLOW FILTERING", 0, -1), row(0, 0), row(0, 1), row(0, 2), row(0, 3));
    assertRows(execute("SELECT a, b FROM %s WHERE a = ? AND c != ? ALLOW FILTERING", 0, 5), row(0, 0), row(0, 1), row(0, 2), row(0, 3));
    assertRows(execute("SELECT a, b FROM %s WHERE a = ? AND c != ? AND c != ? ALLOW FILTERING", 0, 1, 2), row(0, 0), row(0, 3));
    assertRows(execute("SELECT a, b FROM %s WHERE a = ? AND c != ? AND c < ? ALLOW FILTERING", 0, 1, 2), row(0, 0));
    assertRows(execute("SELECT a, b FROM %s WHERE a = ? AND c != ? AND c <= ? ALLOW FILTERING", 0, 1, 2), row(0, 0), row(0, 2));
    assertRows(execute("SELECT a, b FROM %s WHERE a = ? AND c != ? AND c > ? ALLOW FILTERING", 0, 2, 0), row(0, 1), row(0, 3));
    assertRows(execute("SELECT a, b FROM %s WHERE a = ? AND c != ? AND c >= ? ALLOW FILTERING", 0, 2, 1), row(0, 1), row(0, 3));
}

@Test
public void testBetweenFilteringWithReversedOrdering() throws Throwable {
    createTable("CREATE TABLE %s(p int, c int, c2 int, abbreviation ascii, PRIMARY KEY (p, c, c2))");
    beforeAndAfterFlush(() -> {
        execute("INSERT INTO %s(p, c, c2, abbreviation) VALUES (0, 1, 1, 'CA')");
        execute("INSERT INTO %s(p, c, c2, abbreviation) VALUES (0, 2, 2, 'MA')");
        execute("INSERT INTO %s(p, c, c2, abbreviation) VALUES (0, 3, 3, 'MA')");
        execute("INSERT INTO %s(p, c, c2, abbreviation) VALUES (0, 4, 4, 'TX')");
        assertRows(execute("SELECT * FROM %s WHERE c2 BETWEEN 2 AND 3 ALLOW FILTERING"), row(0, 2, 2, "MA"), row(0, 3, 3, "MA"));
        assertRows(execute("SELECT * FROM %s WHERE c2 BETWEEN 3 AND 2 ALLOW FILTERING"), row(0, 2, 2, "MA"), row(0, 3, 3, "MA"));
    });
    createTable("CREATE TABLE %s(p int, c int, c2 int, abbreviation ascii, PRIMARY KEY (p, c, c2)) WITH CLUSTERING ORDER BY (c DESC, c2 DESC)");
    beforeAndAfterFlush(() -> {
        execute("INSERT INTO %s(p, c, c2, abbreviation) VALUES (0, 1, 1, 'CA')");
        execute("INSERT INTO %s(p, c, c2, abbreviation) VALUES (0, 2, 2, 'MA')");
        execute("INSERT INTO %s(p, c, c2, abbreviation) VALUES (0, 3, 3, 'MA')");
        execute("INSERT INTO %s(p, c, c2, abbreviation) VALUES (0, 4, 4, 'TX')");
        assertRows(execute("SELECT * FROM %s WHERE c2 BETWEEN 2 AND 3 ALLOW FILTERING"), row(0, 3, 3, "MA"), row(0, 2, 2, "MA"));
        assertRows(execute("SELECT * FROM %s WHERE c2 BETWEEN 3 AND 2 ALLOW FILTERING"), row(0, 3, 3, "MA"), row(0, 2, 2, "MA"));
    });
}

@Test
public void testSingleClustering() throws Throwable {
    createTable("CREATE TABLE %s (p text, c text, v text, s text static, PRIMARY KEY (p, c))");
    execute("INSERT INTO %s(p, c, v, s) values (?, ?, ?, ?)", "p1", "k1", "v1", "sv1");
    execute("INSERT INTO %s(p, c, v) values (?, ?, ?)", "p1", "k2", "v2");
    execute("INSERT INTO %s(p, s) values (?, ?)", "p2", "sv2");
    assertRows(execute("SELECT * FROM %s WHERE p=?", "p1"), row("p1", "k1", "sv1", "v1"), row("p1", "k2", "sv1", "v2"));
    assertRows(execute("SELECT * FROM %s WHERE p=?", "p2"), row("p2", null, "sv2", null));
    // Ascending order
    assertRows(execute("SELECT * FROM %s WHERE p=? ORDER BY c ASC", "p1"), row("p1", "k1", "sv1", "v1"), row("p1", "k2", "sv1", "v2"));
    assertRows(execute("SELECT * FROM %s WHERE p=? ORDER BY c ASC", "p2"), row("p2", null, "sv2", null));
    // Descending order
    assertRows(execute("SELECT * FROM %s WHERE p=? ORDER BY c DESC", "p1"), row("p1", "k2", "sv1", "v2"), row("p1", "k1", "sv1", "v1"));
    assertRows(execute("SELECT * FROM %s WHERE p=? ORDER BY c DESC", "p2"), row("p2", null, "sv2", null));
    // No order with one relation
    assertRows(execute("SELECT * FROM %s WHERE p=? AND c>=?", "p1", "k1"), row("p1", "k1", "sv1", "v1"), row("p1", "k2", "sv1", "v2"));
    assertRows(execute("SELECT * FROM %s WHERE p=? AND c>=?", "p1", "k2"), row("p1", "k2", "sv1", "v2"));
    assertEmpty(execute("SELECT * FROM %s WHERE p=? AND c>=?", "p1", "k3"));
    assertRows(execute("SELECT * FROM %s WHERE p=? AND c =?", "p1", "k1"), row("p1", "k1", "sv1", "v1"));
    assertRows(execute("SELECT * FROM %s WHERE p=? AND c<=?", "p1", "k1"), row("p1", "k1", "sv1", "v1"));
    assertEmpty(execute("SELECT * FROM %s WHERE p=? AND c<=?", "p1", "k0"));
    // Ascending with one relation
    assertRows(execute("SELECT * FROM %s WHERE p=? AND c>=? ORDER BY c ASC", "p1", "k1"), row("p1", "k1", "sv1", "v1"), row("p1", "k2", "sv1", "v2"));
    assertRows(execute("SELECT * FROM %s WHERE p=? AND c>=? ORDER BY c ASC", "p1", "k2"), row("p1", "k2", "sv1", "v2"));
    assertEmpty(execute("SELECT * FROM %s WHERE p=? AND c>=? ORDER BY c ASC", "p1", "k3"));
    assertRows(execute("SELECT * FROM %s WHERE p=? AND c =? ORDER BY c ASC", "p1", "k1"), row("p1", "k1", "sv1", "v1"));
    assertRows(execute("SELECT * FROM %s WHERE p=? AND c<=? ORDER BY c ASC", "p1", "k1"), row("p1", "k1", "sv1", "v1"));
    assertEmpty(execute("SELECT * FROM %s WHERE p=? AND c<=? ORDER BY c ASC", "p1", "k0"));
    // Descending with one relation
    assertRows(execute("SELECT * FROM %s WHERE p=? AND c>=? ORDER BY c DESC", "p1", "k1"), row("p1", "k2", "sv1", "v2"), row("p1", "k1", "sv1", "v1"));
    assertRows(execute("SELECT * FROM %s WHERE p=? AND c>=? ORDER BY c DESC", "p1", "k2"), row("p1", "k2", "sv1", "v2"));
    assertEmpty(execute("SELECT * FROM %s WHERE p=? AND c>=? ORDER BY c DESC", "p1", "k3"));
    assertRows(execute("SELECT * FROM %s WHERE p=? AND c =? ORDER BY c DESC", "p1", "k1"), row("p1", "k1", "sv1", "v1"));
    assertRows(execute("SELECT * FROM %s WHERE p=? AND c<=? ORDER BY c DESC", "p1", "k1"), row("p1", "k1", "sv1", "v1"));
    assertEmpty(execute("SELECT * FROM %s WHERE p=? AND c<=? ORDER BY c DESC", "p1", "k0"));
    // IN
    assertRows(execute("SELECT * FROM %s WHERE p=? AND c IN (?, ?)", "p1", "k1", "k2"), row("p1", "k1", "sv1", "v1"), row("p1", "k2", "sv1", "v2"));
    assertRows(execute("SELECT * FROM %s WHERE p=? AND c IN (?, ?) ORDER BY c ASC", "p1", "k1", "k2"), row("p1", "k1", "sv1", "v1"), row("p1", "k2", "sv1", "v2"));
