        assertRows(execute("SELECT * FROM %s WHERE a <= 11 AND c > 15 AND d >= 16 ALLOW FILTERING"), row(11, 15, 16, 17, 18));
        assertRows(execute("SELECT * FROM %s WHERE a <= 11 AND b >= 15 AND c > 15 AND d >= 16 ALLOW FILTERING"), row(11, 15, 16, 17, 18));
        assertRows(execute("SELECT * FROM %s WHERE a <= 100 AND b >= 15 AND c > 0 AND d <= 100 ALLOW FILTERING"), row(11, 15, 16, 17, 18), row(31, 32, 33, 34, 35), row(21, 22, 23, 24, 25));
        assertInvalidMessage("Clustering column \"d\" cannot be restricted (preceding column \"c\" is restricted by a non-EQ relation)", "SELECT * FROM %s WHERE a <= 11 AND c > 15 AND d >= 16");
    });
    // test clutering order
    createTable("CREATE TABLE %s (a int, b int, c int, d int, e int, PRIMARY KEY ((a, b), c, d)) WITH CLUSTERING ORDER BY (c DESC, d ASC)");
    execute("INSERT INTO %s (a,b,c,d,e) VALUES (11, 11, 13, 14, 15)");
    execute("INSERT INTO %s (a,b,c,d,e) VALUES (11, 11, 14, 17, 18)");
    execute("INSERT INTO %s (a,b,c,d,e) VALUES (11, 12, 15, 14, 15)");
    execute("INSERT INTO %s (a,b,c,d,e) VALUES (11, 12, 16, 17, 18)");
    execute("INSERT INTO %s (a,b,c,d,e) VALUES (21, 11, 23, 24, 25)");
    execute("INSERT INTO %s (a,b,c,d,e) VALUES (21, 11, 24, 34, 35)");
    execute("INSERT INTO %s (a,b,c,d,e) VALUES (21, 12, 25, 24, 25)");
    execute("INSERT INTO %s (a,b,c,d,e) VALUES (21, 12, 26, 34, 35)");
    beforeAndAfterFlush(() -> {
        assertRowsIgnoringOrder(execute("SELECT * FROM %s WHERE b >= 12 ALLOW FILTERING"), row(11, 12, 15, 14, 15), row(11, 12, 16, 17, 18), row(21, 12, 25, 24, 25), row(21, 12, 26, 34, 35));
    });
}

@Test
public void testAllowFilteringOnPartitionKeyWithoutIndicesWithCollections() throws Throwable {
    createTable("CREATE TABLE %s (a int, b int, c list<int>, d set<int>, e map<int, int>, PRIMARY KEY ((a, b)))");
    execute("INSERT INTO %s (a, b, c, d, e) VALUES (1, 2, [1, 6], {2, 12}, {1: 6})");
    execute("INSERT INTO %s (a, b, c, d, e) VALUES (1, 3, [3, 2], {6, 4}, {3: 2})");
    execute("INSERT INTO %s (a, b, c, d, e) VALUES (1, 4, [1, 2], {2, 4}, {1: 2})");
    execute("INSERT INTO %s (a, b, c, d, e) VALUES (2, 3, [3, 6], {6, 12}, {3: 6})");
    beforeAndAfterFlush(() -> {
        // Checks filtering for lists
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE b < 0 AND c CONTAINS 2");
        assertRows(execute("SELECT * FROM %s WHERE b >= 4 AND c CONTAINS 2 ALLOW FILTERING"), row(1, 4, list(1, 2), set(2, 4), map(1, 2)));
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE b < 0 AND c NOT CONTAINS 2");
        assertRows(execute("SELECT * FROM %s WHERE a > 0 AND b <= 3 AND c CONTAINS 2 AND c CONTAINS 3 ALLOW FILTERING"), row(1, 3, list(3, 2), set(6, 4), map(3, 2)));
        assertRows(execute("SELECT * FROM %s WHERE a > 0 AND b <= 3 AND c NOT CONTAINS 1 AND c NOT CONTAINS 6 ALLOW FILTERING"), row(1, 3, list(3, 2), set(6, 4), map(3, 2)));
        // Checks filtering for sets
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE a = 1 AND d CONTAINS 4");
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE a = 1 AND d NOT CONTAINS 4");
        assertRows(execute("SELECT * FROM %s WHERE d CONTAINS 4 ALLOW FILTERING"), row(1, 3, list(3, 2), set(6, 4), map(3, 2)), row(1, 4, list(1, 2), set(2, 4), map(1, 2)));
        assertRows(execute("SELECT * FROM %s WHERE d NOT CONTAINS 4 ALLOW FILTERING"), row(2, 3, list(3, 6), set(6, 12), map(3, 6)), row(1, 2, list(1, 6), set(2, 12), map(1, 6)));
        assertRows(execute("SELECT * FROM %s WHERE d CONTAINS 4 AND d CONTAINS 6 ALLOW FILTERING"), row(1, 3, list(3, 2), set(6, 4), map(3, 2)));
        assertRows(execute("SELECT * FROM %s WHERE d NOT CONTAINS 4 AND d NOT CONTAINS 6 ALLOW FILTERING"), row(1, 2, list(1, 6), set(2, 12), map(1, 6)));
        // Checks filtering for maps
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE e CONTAINS 2");
        assertInvalidMessage(StatementRestrictions.REQUIRES_ALLOW_FILTERING_MESSAGE, "SELECT * FROM %s WHERE e NOT CONTAINS 2");
        assertRows(execute("SELECT * FROM %s WHERE a < 2 AND b >= 3 AND e CONTAINS 2 ALLOW FILTERING"), row(1, 3, list(3, 2), set(6, 4), map(3, 2)), row(1, 4, list(1, 2), set(2, 4), map(1, 2)));
        assertRows(execute("SELECT * FROM %s WHERE a < 2 AND b >= 3 AND e NOT CONTAINS 6 ALLOW FILTERING"), row(1, 3, list(3, 2), set(6, 4), map(3, 2)), row(1, 4, list(1, 2), set(2, 4), map(1, 2)));
        assertRows(execute("SELECT * FROM %s WHERE a = 1 AND e CONTAINS KEY 1 ALLOW FILTERING"), row(1, 4, list(1, 2), set(2, 4), map(1, 2)), row(1, 2, list(1, 6), set(2, 12), map(1, 6)));
        assertRows(execute("SELECT * FROM %s WHERE a = 1 AND e NOT CONTAINS KEY 3 ALLOW FILTERING"), row(1, 4, list(1, 2), set(2, 4), map(1, 2)), row(1, 2, list(1, 6), set(2, 12), map(1, 6)));
        assertRows(execute("SELECT * FROM %s WHERE a in (1) AND b in (2) AND e[1] = 6 ALLOW FILTERING"), row(1, 2, list(1, 6), set(2, 12), map(1, 6)));
        assertRows(execute("SELECT * FROM %s WHERE a in (1) AND b in (2) AND e[1] != 2 ALLOW FILTERING"), row(1, 2, list(1, 6), set(2, 12), map(1, 6)));
        assertRows(execute("SELECT * FROM %s WHERE a = 1 AND e CONTAINS KEY 1 AND e CONTAINS 2 ALLOW FILTERING"), row(1, 4, list(1, 2), set(2, 4), map(1, 2)));
        assertRows(execute("SELECT * FROM %s WHERE a = 1 AND e CONTAINS KEY 1 AND e NOT CONTAINS 6 ALLOW FILTERING"), row(1, 4, list(1, 2), set(2, 4), map(1, 2)));
        assertRows(execute("SELECT * FROM %s WHERE a >= 1 AND b in (3) AND c CONTAINS 2 AND d CONTAINS 4 AND e CONTAINS KEY 3 ALLOW FILTERING"), row(1, 3, list(3, 2), set(6, 4), map(3, 2)));
        assertRows(execute("SELECT * FROM %s WHERE a >= 1 AND b in (3) AND c CONTAINS 2 AND d CONTAINS 4 AND e NOT CONTAINS KEY 1 ALLOW FILTERING"), row(1, 3, list(3, 2), set(6, 4), map(3, 2)));
    });
    // Checks filtering with null
    assertInvalidMessage("Invalid null value for column c", "SELECT * FROM %s WHERE a > 1 AND c CONTAINS null ALLOW FILTERING");
    assertInvalidMessage("Invalid null value for column d", "SELECT * FROM %s WHERE b < 1 AND d CONTAINS null ALLOW FILTERING");
    assertInvalidMessage("Invalid null value for column e", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e CONTAINS null ALLOW FILTERING");
    assertInvalidMessage("Invalid null value for column e", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e CONTAINS KEY null ALLOW FILTERING");
    assertInvalidMessage("Invalid null map key for column e", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e[null] = 2 ALLOW FILTERING");
    assertInvalidMessage("Invalid null value for e[1]", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e[1] = null ALLOW FILTERING");
    assertInvalidMessage("Invalid null value for column c", "SELECT * FROM %s WHERE a > 1 AND c NOT CONTAINS null ALLOW FILTERING");
    assertInvalidMessage("Invalid null value for column d", "SELECT * FROM %s WHERE b < 1 AND d NOT CONTAINS null ALLOW FILTERING");
    assertInvalidMessage("Invalid null value for column e", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e NOT CONTAINS null ALLOW FILTERING");
    assertInvalidMessage("Invalid null value for column e", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e NOT CONTAINS KEY null ALLOW FILTERING");
    assertInvalidMessage("Invalid null map key for column e", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e[null] != 2 ALLOW FILTERING");
    assertInvalidMessage("Invalid null value for e[1]", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e[1] != null ALLOW FILTERING");
    // Checks filtering with unset
    assertInvalidMessage("Invalid unset value for column c", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND c CONTAINS ? ALLOW FILTERING", unset());
    assertInvalidMessage("Invalid unset value for column d", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND d CONTAINS ? ALLOW FILTERING", unset());
    assertInvalidMessage("Invalid unset value for column e", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e CONTAINS ? ALLOW FILTERING", unset());
    assertInvalidMessage("Invalid unset value for column e", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e CONTAINS KEY ? ALLOW FILTERING", unset());
    assertInvalidMessage("Invalid unset map key for column e", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e[?] = 2 ALLOW FILTERING", unset());
    assertInvalidMessage("Invalid unset value for e[1]", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e[1] = ? ALLOW FILTERING", unset());
    assertInvalidMessage("Invalid unset value for column c", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND c NOT CONTAINS ? ALLOW FILTERING", unset());
    assertInvalidMessage("Invalid unset value for column d", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND d NOT CONTAINS ? ALLOW FILTERING", unset());
    assertInvalidMessage("Invalid unset value for column e", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e NOT CONTAINS ? ALLOW FILTERING", unset());
    assertInvalidMessage("Invalid unset value for column e", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e NOT CONTAINS KEY ? ALLOW FILTERING", unset());
    assertInvalidMessage("Invalid unset map key for column e", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e[?] != 2 ALLOW FILTERING", unset());
    assertInvalidMessage("Invalid unset value for e[1]", "SELECT * FROM %s WHERE a >= 1 AND b < 1 AND e[1] != ? ALLOW FILTERING", unset());
}

@Test
public void testAllowFilteringOnPartitionKeyWithCounters() throws Throwable {
    createTable("CREATE TABLE %s (a int, b int, c int, cnt counter, PRIMARY KEY ((a, b), c))");
    execute("UPDATE %s SET cnt = cnt + ? WHERE a = ? AND b = ? AND c = ?", 14L, 11, 12, 13);
    execute("UPDATE %s SET cnt = cnt + ? WHERE a = ? AND b = ? AND c = ?", 24L, 21, 22, 23);
    execute("UPDATE %s SET cnt = cnt + ? WHERE a = ? AND b = ? AND c = ?", 27L, 21, 22, 26);
    execute("UPDATE %s SET cnt = cnt + ? WHERE a = ? AND b = ? AND c = ?", 34L, 31, 32, 33);
    execute("UPDATE %s SET cnt = cnt + ? WHERE a = ? AND b = ? AND c = ?", 24L, 41, 42, 43);
    beforeAndAfterFlush(() -> {
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE cnt = 24"), row(41, 42, 43, 24L), row(21, 22, 23, 24L));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE b > 22 AND cnt = 24"), row(41, 42, 43, 24L));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE b > 10 AND b < 25 AND cnt = 24"), row(21, 22, 23, 24L));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE b > 10 AND c < 25 AND cnt = 24"), row(21, 22, 23, 24L));
        assertInvalidMessage("ORDER BY is only supported when the partition key is restricted by an EQ or an IN.", "SELECT * FROM %s WHERE a = 21 AND b > 10 AND cnt > 23 ORDER BY c DESC ALLOW FILTERING");
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE a = 21 AND b = 22 AND cnt > 23 ORDER BY c DESC"), row(21, 22, 26, 27L), row(21, 22, 23, 24L));
        assertRows(executeFilteringOnly("SELECT * FROM %s WHERE cnt > 20 AND cnt < 30"), row(41, 42, 43, 24L), row(21, 22, 23, 24L), row(21, 22, 26, 27L));
    });
}

