        assertInvalidMessage("Clustering column restrictions require the use of secondary indices or filtering" + " for map-element restrictions and for the following operators: CONTAINS, CONTAINS KEY, LIKE, " + "ANN, NOT CONTAINS, NOT CONTAINS KEY", "SELECT * FROM %s WHERE a = 21 AND c NOT CONTAINS 2");
        assertRows(execute("SELECT * FROM %s WHERE b > 20 AND c CONTAINS 2 ALLOW FILTERING"), row(21, 22, list(2, 3), 24));
        assertRows(execute("SELECT * FROM %s WHERE b > 20 AND c NOT CONTAINS 2 ALLOW FILTERING"), row(21, 22, list(3, 3), 34));
        assertInvalidMessage("Clustering column \"c\" cannot be restricted (preceding column \"b\" is restricted by a non-EQ relation)", "SELECT * FROM %s WHERE b > 20 AND c NOT CONTAINS 2");
        assertInvalidMessage("Clustering column \"c\" cannot be restricted (preceding column \"b\" is restricted by a non-EQ relation)", "SELECT * FROM %s WHERE b > 20 AND c CONTAINS 2");
        assertRows(execute("SELECT * FROM %s WHERE c CONTAINS 3 ALLOW FILTERING"), row(11, 12, list(1, 3), 14), row(21, 22, list(2, 3), 24), row(21, 22, list(3, 3), 34));
        assertEmpty(execute("SELECT * FROM %s WHERE c NOT CONTAINS 3 ALLOW FILTERING"));
    });
    createTable("CREATE TABLE %s (a int, b int, c frozen<map<text, text>>, d int, PRIMARY KEY (a, b, c))");
