    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 21, 22, 23, list(2, 4));
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 21, 25, 26, list(2, 7));
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 31, 32, 33, list(3, 4));
    beforeAndAfterFlush(() -> {
        assertRows(executeFilteringOnly("SELECT a, b, c, d FROM %s WHERE a = 21 AND c > 20 ORDER BY b DESC"), row(21, 25, 26, list(2, 7)), row(21, 22, 23, list(2, 4)));
        assertRows(executeFilteringOnly("SELECT a, b, c, d FROM %s WHERE a IN(21, 31) AND c > 20 ORDER BY b DESC"), row(31, 32, 33, list(3, 4)), row(21, 25, 26, list(2, 7)), row(21, 22, 23, list(2, 4)));
    });
}

