        assertInvalidMessage("Slice restrictions are not supported on collections containing durations", "SELECT * FROM %s WHERE l < [2s, 3s] ALLOW FILTERING");
        assertRows(execute("SELECT * FROM %s WHERE l CONTAINS 1s ALLOW FILTERING"), row(0, list(Duration.from("1s"), Duration.from("2s"))), row(2, list(Duration.from("1s"), Duration.from("3s"))));
    }
}

