    updateView("INSERT INTO %s (p, c, v) VALUES (0, 0, 0) USING TTL 3 and timestamp 1;");
    Util.flush(ks);
    Thread.sleep(4000);
    assertEmpty(execute("SELECT * from %s WHERE c = ? AND p = ?", 0, 0));
    // reversed order
    execute("truncate %s;");
    updateView("INSERT INTO %s (p, c, v) VALUES (0, 0, 0) USING TTL 3 and timestamp 1;");
    Util.flush(ks);
    updateView("INSERT INTO %s (p, c, v) VALUES (0, 0, 0) USING timestamp 1;");
    Util.flush(ks);
    Thread.sleep(4000);
    assertEmpty(execute("SELECT * from %s WHERE c = ? AND p = ?", 0, 0));
}

