@Test
public void testNonPrimaryRestrictions() throws Throwable {
    createTable("CREATE TABLE %s (a int, b int, c int, d int, PRIMARY KEY (a, b))");
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 0, 0, 0, 0);
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 0, 0, 1, 0);
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 0, 1, 0, 0);
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 0, 1, 1, 0);
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 1, 0, 0, 0);
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 1, 0, 1, 0);
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 1, 1, 0, 0);
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 1, 1, 1, 0);
    // only accept rows where c = 1
    createView("CREATE MATERIALIZED VIEW %s AS SELECT * FROM %s " + "WHERE a IS NOT NULL AND b IS NOT NULL AND c IS NOT NULL AND c = 1 " + "PRIMARY KEY (a, b, c)");
    assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(0, 0, 1, 0), row(0, 1, 1, 0), row(1, 0, 1, 0), row(1, 1, 1, 0));
    // insert new rows that do not match the filter
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 2, 0, 0, 0);
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 2, 1, 2, 0);
    assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(0, 0, 1, 0), row(0, 1, 1, 0), row(1, 0, 1, 0), row(1, 1, 1, 0));
    // insert new row that does match the filter
    execute("INSERT INTO %s (a, b, c, d) VALUES (?, ?, ?, ?)", 1, 2, 1, 0);
    assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(0, 0, 1, 0), row(0, 1, 1, 0), row(1, 0, 1, 0), row(1, 1, 1, 0), row(1, 2, 1, 0));
    // update rows that don't match the filter
    execute("UPDATE %s SET d = ? WHERE a = ? AND b = ?", 2, 2, 0);
    execute("UPDATE %s SET d = ? WHERE a = ? AND b = ?", 1, 2, 1);
    assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(0, 0, 1, 0), row(0, 1, 1, 0), row(1, 0, 1, 0), row(1, 1, 1, 0), row(1, 2, 1, 0));
    // update a row that does match the filter
    execute("UPDATE %s SET d = ? WHERE a = ? AND b = ?", 1, 1, 0);
    assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(0, 0, 1, 0), row(0, 1, 1, 0), row(1, 0, 1, 1), row(1, 1, 1, 0), row(1, 2, 1, 0));
    // delete rows that don't match the filter
    execute("DELETE FROM %s WHERE a = ? AND b = ?", 2, 0);
    assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(0, 0, 1, 0), row(0, 1, 1, 0), row(1, 0, 1, 1), row(1, 1, 1, 0), row(1, 2, 1, 0));
    // delete a row that does match the filter
    execute("DELETE FROM %s WHERE a = ? AND b = ?", 1, 2);
    assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(0, 0, 1, 0), row(0, 1, 1, 0), row(1, 0, 1, 1), row(1, 1, 1, 0));
    // delete a partition that matches the filter
    execute("DELETE FROM %s WHERE a = ?", 1);
    assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(0, 0, 1, 0), row(0, 1, 1, 0));
    dropView();
    dropTable("DROP TABLE %s");
}

