        assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(1, 0, 0, 0), row(1, 0, 1, 0), row(1, 1, 0, 1), row(1, 1, 1, 0), row(1, 1, 2, 0));
        // delete rows that don't match the filter
        execute("DELETE FROM %s WHERE a = ? AND b = ? AND c = ?", 0, 0, 0);
        execute("DELETE FROM %s WHERE a = ? AND b = ? AND c = ?", 0, 1, 0);
        execute("DELETE FROM %s WHERE a = ? AND b = ?", 0, 0);
        assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(1, 0, 0, 0), row(1, 0, 1, 0), row(1, 1, 0, 1), row(1, 1, 1, 0), row(1, 1, 2, 0));
        // delete a row that does match the filter
        execute("DELETE FROM %s WHERE a = ? AND b = ? AND c = ?", 1, 1, 0);
        assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(1, 0, 0, 0), row(1, 0, 1, 0), row(1, 1, 1, 0), row(1, 1, 2, 0));
        // delete a partition that matches the filter
        execute("DELETE FROM %s WHERE a = ? AND b = ?", 1, 0);
        assertRowsIgnoringOrder(executeView("SELECT a, b, c, d FROM %s"), row(1, 1, 1, 0), row(1, 1, 2, 0));
        execute("DELETE FROM %s WHERE a = ? AND b = ?", 1, 1);
        assertEmpty(executeView("SELECT * FROM %s"));
    }
}

