@Test
public void testRangeTombstone() throws Throwable {
    createTable("CREATE TABLE %s (" + "k int, " + "asciival ascii, " + "bigintval bigint, " + "textval1 text, " + "textval2 text, " + "PRIMARY KEY((k, asciival), bigintval, textval1)" + ")");
    createView("CREATE MATERIALIZED VIEW %s AS SELECT * FROM %s " + "WHERE textval2 IS NOT NULL AND k IS NOT NULL AND asciival IS NOT NULL AND bigintval IS NOT NULL AND textval1 IS NOT NULL " + "PRIMARY KEY ((textval2, k), asciival, bigintval, textval1)");
    for (int i = 0; i < 100; i++) updateView("INSERT into %s (k,asciival,bigintval,textval1,textval2) VALUES (?,?,?,?,?)", 0, "foo", (long) i % 2, "bar" + i, "baz");
    Assert.assertEquals(50, execute("select * from %s where k = 0 and asciival = 'foo' and bigintval = 0").size());
    Assert.assertEquals(50, execute("select * from %s where k = 0 and asciival = 'foo' and bigintval = 1").size());
    Assert.assertEquals(100, executeView("select * from %s").size());
    //Check the builder works
    createView("CREATE MATERIALIZED VIEW %s AS SELECT * FROM %s " + "WHERE textval2 IS NOT NULL AND k IS NOT NULL AND asciival IS NOT NULL AND bigintval IS NOT NULL AND textval1 IS NOT NULL " + "PRIMARY KEY ((textval2, k), asciival, bigintval, textval1)");
    Assert.assertEquals(100, executeView("select * from %s").size());
    createView("CREATE MATERIALIZED VIEW %s AS SELECT * FROM %s " + "WHERE textval2 IS NOT NULL AND k IS NOT NULL AND asciival IS NOT NULL AND bigintval IS NOT NULL AND textval1 IS NOT NULL " + "PRIMARY KEY ((textval2, k), bigintval, textval1, asciival)");
    Assert.assertEquals(100, executeView("select * from %s").size());
    Assert.assertEquals(100, executeView("select asciival from %s where textval2 = ? and k = ?", "baz", 0).size());
    //Write a RT and verify the data is removed from index
    updateView("DELETE FROM %s WHERE k = ? AND asciival = ? and bigintval = ?", 0, "foo", 0L);
    Assert.assertEquals(50, executeView("select asciival from %s where textval2 = ? and k = ?", "baz", 0).size());
}

@Test
public void testRangeTombstone2() throws Throwable {
    createTable("CREATE TABLE %s (" + "k int, " + "asciival ascii, " + "bigintval bigint, " + "textval1 text, " + "PRIMARY KEY((k, asciival), bigintval)" + ")");
    createView("CREATE MATERIALIZED VIEW %s AS SELECT * FROM %s " + "WHERE textval1 IS NOT NULL AND k IS NOT NULL AND asciival IS NOT NULL AND bigintval IS NOT NULL " + "PRIMARY KEY ((textval1, k), asciival, bigintval)");
    for (int i = 0; i < 100; i++) updateView("INSERT into %s (k,asciival,bigintval,textval1)VALUES(?,?,?,?)", 0, "foo", (long) i % 2, "bar" + i);
    Assert.assertEquals(1, execute("select * from %s where k = 0 and asciival = 'foo' and bigintval = 0").size());
    Assert.assertEquals(1, execute("select * from %s where k = 0 and asciival = 'foo' and bigintval = 1").size());
    Assert.assertEquals(2, execute("select * from %s").size());
    Assert.assertEquals(2, executeView("select * from %s").size());
    //Write a RT and verify the data is removed from index
    updateView("DELETE FROM %s WHERE k = ? AND asciival = ? and bigintval = ?", 0, "foo", 0L);
    Assert.assertEquals(1, execute("select * from %s").size());
    Assert.assertEquals(1, executeView("select * from %s").size());
}

