@Test
public void testVirtualTable() throws Throwable {
    TableMetadata metadata = TableMetadata.builder("vk", "vt").kind(TableMetadata.Kind.VIRTUAL).addPartitionKeyColumn("k", Int32Type.instance).addClusteringColumn("c", Int32Type.instance).addRegularColumn("v", Int32Type.instance).addStaticColumn("s", Int32Type.instance).build();
    SimpleDataSet data = new SimpleDataSet(metadata);
    VirtualTable table = new AbstractVirtualTable(metadata) {

        public DataSet data() {
            return data;
        }
    };
    VirtualKeyspaceRegistry.instance.register(new VirtualKeyspace("vk", ImmutableList.of(table)));
    // column selection on unrestricted partition range query
    test("SELECT * FROM vk.vt");
    test("SELECT k FROM vk.vt", "SELECT * FROM vk.vt");
    test("SELECT c FROM vk.vt", "SELECT * FROM vk.vt");
    test("SELECT s FROM vk.vt");
    test("SELECT v FROM vk.vt");
    test("SELECT k, c, s, v FROM vk.vt", "SELECT s, v FROM vk.vt");
    // column selection on partition directed query
    test("SELECT * FROM vk.vt WHERE k = 1");
    test("SELECT k FROM vk.vt WHERE k = 1", "SELECT * FROM vk.vt WHERE k = 1");
    test("SELECT c FROM vk.vt WHERE k = 1", "SELECT * FROM vk.vt WHERE k = 1");
    test("SELECT v FROM vk.vt WHERE k = 1");
    test("SELECT s FROM vk.vt WHERE k = 1");
    test("SELECT k, c, s, v FROM vk.vt WHERE k = 1", "SELECT s, v FROM vk.vt WHERE k = 1");
    // clustering filters
    test("SELECT * FROM vk.vt WHERE k = 0 AND c = 1");
    test("SELECT * FROM vk.vt WHERE k = 0 AND c < 1");
    test("SELECT * FROM vk.vt WHERE k = 0 AND c > 1");
    test("SELECT * FROM vk.vt WHERE k = 0 AND c <= 1");
    test("SELECT * FROM vk.vt WHERE k = 0 AND c >= 1");
    test("SELECT * FROM vk.vt WHERE k = 0 AND c > 1 AND c <= 2");
    test("SELECT * FROM vk.vt WHERE k = 0 AND c >= 1 AND c < 2");
    test("SELECT * FROM vk.vt WHERE k = 0 AND c BETWEEN 1 AND 2", "SELECT * FROM vk.vt WHERE k = 0 AND c >= 1 AND c <= 2");
    // token restrictions
    test("SELECT * FROM vk.vt WHERE token(k) > 0");
    test("SELECT * FROM vk.vt WHERE token(k) < 0");
    test("SELECT * FROM vk.vt WHERE token(k) >= 0");
    test("SELECT * FROM vk.vt WHERE token(k) <= 0");
    test("SELECT * FROM vk.vt WHERE token(k) = 0", "SELECT * FROM vk.vt WHERE token(k) >= 0 AND token(k) <= 0");
    test("SELECT * FROM vk.vt WHERE token(k) BETWEEN 0 AND 0", "SELECT * FROM vk.vt WHERE token(k) >= 0 AND token(k) <= 0");
    // row filters
    test("SELECT * FROM vk.vt WHERE c = 1 ALLOW FILTERING");
    test("SELECT * FROM vk.vt WHERE s = 1 ALLOW FILTERING");
    test("SELECT * FROM vk.vt WHERE v = 1 ALLOW FILTERING");
    test("SELECT * FROM vk.vt WHERE k = 0 AND v = 1 ALLOW FILTERING");
    test("SELECT * FROM vk.vt WHERE k = 0 AND v BETWEEN 1 AND 2 ALLOW FILTERING");
    test("SELECT * FROM vk.vt WHERE k = 0 AND c = 1 AND v = 1 ALLOW FILTERING");
    test("SELECT * FROM vk.vt WHERE token(k) > 0 AND v = 1 ALLOW FILTERING");
    test("SELECT * FROM vk.vt WHERE token(k) > 0 AND c = 1 AND v = 1 ALLOW FILTERING");
    // grouped partition-directed queries, maybe producing multiple queries
    test("SELECT * FROM vk.vt WHERE k IN (0)", "SELECT * FROM vk.vt WHERE k = 0");
    test("SELECT * FROM vk.vt WHERE k IN (0, 1)", "SELECT * FROM vk.vt WHERE k = 0", "SELECT * FROM vk.vt WHERE k = 1");
    test("SELECT * FROM vk.vt WHERE k IN (0, 1) AND c = 0", "SELECT * FROM vk.vt WHERE k = 0 AND c = 0", "SELECT * FROM vk.vt WHERE k = 1 AND c = 0");
    test("SELECT * FROM vk.vt WHERE k IN (0, 1) AND c > 0", "SELECT * FROM vk.vt WHERE k = 0 AND c > 0", "SELECT * FROM vk.vt WHERE k = 1 AND c > 0");
    // order by
    test("SELECT * FROM vk.vt WHERE k = 0 ORDER BY c", "SELECT * FROM vk.vt WHERE k = 0");
    test("SELECT * FROM vk.vt WHERE k = 0 ORDER BY c ASC", "SELECT * FROM vk.vt WHERE k = 0");
    test("SELECT * FROM vk.vt WHERE k = 0 ORDER BY c DESC");
    // order by clustering filter
    test("SELECT * FROM vk.vt WHERE k = 0 AND c = 1 ORDER BY c", "SELECT * FROM vk.vt WHERE k = 0 AND c = 1");
    test("SELECT * FROM vk.vt WHERE k = 0 AND c = 1 ORDER BY c ASC", "SELECT * FROM vk.vt WHERE k = 0 AND c = 1");
    test("SELECT * FROM vk.vt WHERE k = 0 AND c = 1 ORDER BY c DESC");
}

@Test
public void testIsNewGroupWithClusteringColumns() {
    ClusteringComparator comparator = newComparator(false, false, false);
    GroupMaker groupMaker = GroupMaker.newPkPrefixGroupMaker(comparator, 2);
    assertTrue(groupMaker.isNewGroup(partitionKey(1), clustering(1, 1, 1)));
    assertFalse(groupMaker.isNewGroup(partitionKey(1), clustering(1, 1, 2)));
    assertFalse(groupMaker.isNewGroup(partitionKey(1), clustering(1, 1, 3)));
    assertTrue(groupMaker.isNewGroup(partitionKey(1), clustering(1, 2, 1)));
    assertTrue(groupMaker.isNewGroup(partitionKey(1), clustering(1, 3, 1)));
    assertFalse(groupMaker.isNewGroup(partitionKey(1), clustering(1, 3, 2)));
    assertTrue(groupMaker.isNewGroup(partitionKey(1), clustering(2, 1, 1)));
    assertFalse(groupMaker.isNewGroup(partitionKey(1), clustering(2, 1, 2)));
    assertTrue(groupMaker.isNewGroup(partitionKey(2), clustering(2, 2, 1)));
