    assertReplay(2, COMMIT_LOG_REPLAY_LIST, format("%s.%s,%s", KEYSPACE1_REPLAY, KEYSPACE1_REPLAY_TABLE1, KEYSPACE1_REPLAY));
    // test for wrong formats
    String invalidFormat = format("%s.%s.%s", KEYSPACE1_REPLAY, KEYSPACE1_REPLAY_TABLE1, KEYSPACE1_REPLAY);
    try {
        assertReplay(2, COMMIT_LOG_REPLAY_LIST, invalidFormat);
        fail(format("replay should fail on -D%s=%s as it is in invalid format", COMMIT_LOG_REPLAY_LIST.getKey(), invalidFormat));
    } catch (IllegalArgumentException ex) {
        assertEquals(format("%s property contains an item which is not " + "in format 'keyspace' or 'keyspace.table' but it is '%s'", COMMIT_LOG_REPLAY_LIST.getKey(), invalidFormat), ex.getMessage());
    }
    String invalidFormat2 = format("%s.%s,%s.", KEYSPACE1_REPLAY, KEYSPACE1_REPLAY_TABLE1, KEYSPACE1_REPLAY);
    try {
        assertReplay(2, COMMIT_LOG_REPLAY_LIST, invalidFormat2);
        fail(format("replay should fail on -D%s=%s as it is in invalid format", COMMIT_LOG_REPLAY_LIST.getKey(), invalidFormat2));
    } catch (IllegalArgumentException ex) {
        assertEquals(format("Invalid pair: '%s.'", KEYSPACE1_REPLAY), ex.getMessage());
    }
}

