    String noTTLKey = "nottl";
    new RowUpdateBuilder(cfs.metadata(), timestamp, noTTLKey).add("col311", ByteBufferUtil.EMPTY_BYTE_BUFFER).build().applyUnsafe();
    // also write to other key to ensure overlap for UCS
    new RowUpdateBuilder(cfs.metadata(), timestamp, 1, key).add("col7", ByteBufferUtil.EMPTY_BYTE_BUFFER).build().applyUnsafe();
