    assertThatExceptionOfType(ConfigurationException.class).describedAs("Should have thrown a ConfigurationException when min_sstable_size is greater than target_sstable_size").isThrownBy(() -> Controller.validateOptions(options)).withMessageContaining(format("Invalid configuration, %s (%s) should be less than 70%% of the targetSSTableSize (%s)", Controller.MIN_SSTABLE_SIZE_OPTION, FBUtilities.prettyPrintMemory(limit + 1), FBUtilities.prettyPrintMemory(Controller.DEFAULT_TARGET_SSTABLE_SIZE)));
    // test min < configured target table size * INV_SQRT_2
    limit = (int) Math.ceil(Controller.MIN_TARGET_SSTABLE_SIZE * 2 * Controller.INVERSE_SQRT_2);
    options.put(Controller.MIN_SSTABLE_SIZE_OPTION, format("%sB", limit + 1));
    options.put(Controller.TARGET_SSTABLE_SIZE_OPTION, format("%sB", Controller.MIN_TARGET_SSTABLE_SIZE * 2));
    assertThatExceptionOfType(ConfigurationException.class).describedAs("Should have thrown a ConfigurationException when min_sstable_size is greater than target_sstable_size").isThrownBy(() -> Controller.validateOptions(options)).withMessageContaining(format("Invalid configuration, %s (%s) should be less than 70%% of the targetSSTableSize (%s)", Controller.MIN_SSTABLE_SIZE_OPTION, FBUtilities.prettyPrintMemory(limit + 1), FBUtilities.prettyPrintMemory(Controller.MIN_TARGET_SSTABLE_SIZE * 2)));
}

