    assertEquals(2L, cfs.getCachedCounter(bytes(1), c2, cd, null).count);
    assertEquals(1L, cfs.getCachedCounter(bytes(2), c1, cd, null).count);
    assertEquals(2L, cfs.getCachedCounter(bytes(2), c2, cd, null).count);
}

