    Assertions.assertThat(IndexHints.create(indexMetadata("idx1", "idx2"), indexMetadata("idx3", "idx4"))).isNotEqualTo(IndexHints.NONE).matches(i -> i.included.size() == 2).matches(i -> i.excluded.size() == 2).matches(i -> i.includes("idx1")).matches(i -> i.includes("idx2")).matches(i -> !i.includes("idx3")).matches(i -> !i.includes("idx4")).matches(i -> !i.excludes("idx1")).matches(i -> !i.excludes("idx2")).matches(i -> i.excludes("idx3")).matches(i -> i.excludes("idx4"));
