@Test
public void testDuplicatedHints() {
    createTable("CREATE TABLE %s (k int PRIMARY KEY, v1 int, v2 int, v3 int)");
    String idx1 = createIndex("CREATE INDEX idx1 ON %s(v1) USING 'legacy_local_table'");
    String idx2 = createIndex("CREATE INDEX idx2 ON %s(v2) USING 'sai'");
    String idx3 = createIndex("CREATE CUSTOM INDEX idx3 ON %s(v3) USING 'org.apache.cassandra.index.sasi.SASIIndex'");
    assertThatIndexQueryPlanFor("SELECT * FROM %s WHERE v1=0 WITH included_indexes={idx1,idx1}").selects(idx1);
    assertThatIndexQueryPlanFor("SELECT * FROM %s WHERE v2=0 WITH included_indexes={idx2,idx2}").selects(idx2);
    assertThatIndexQueryPlanFor("SELECT * FROM %s WHERE v3=0 WITH included_indexes={idx3,idx3}").selects(idx3);
    assertNeedsAllowFiltering("SELECT * FROM %s WHERE v1=0 WITH excluded_indexes={idx1,idx1}");
    assertNeedsAllowFiltering("SELECT * FROM %s WHERE v2=0 WITH excluded_indexes={idx2,idx2}");
    assertNeedsAllowFiltering("SELECT * FROM %s WHERE v3=0 WITH excluded_indexes={idx3,idx3}");
    assertThatIndexQueryPlanFor("SELECT * FROM %s WHERE v1=0 ALLOW FILTERING WITH excluded_indexes={idx1,idx1}").selectsNone();
    assertThatIndexQueryPlanFor("SELECT * FROM %s WHERE v2=0 ALLOW FILTERING WITH excluded_indexes={idx2,idx2}").selectsNone();
    assertThatIndexQueryPlanFor("SELECT * FROM %s WHERE v3=0 ALLOW FILTERING WITH excluded_indexes={idx3,idx3}").selectsNone();
    assertConflictingHints("SELECT * FROM %s WHERE v1=0 WITH included_indexes={idx1} AND excluded_indexes={idx1}", "idx1");
    assertConflictingHints("SELECT * FROM %s WHERE v2=0 WITH included_indexes={idx2} AND excluded_indexes={idx2}", "idx2");
    assertConflictingHints("SELECT * FROM %s WHERE v3=0 WITH included_indexes={idx3} AND excluded_indexes={idx3}", "idx3");
}

/**
 * Tests that CQL will throw an exception when trying to specify more indexes than can fit in a short.
 */
@Test
public void testMaxHints() {
    // prepare a set of index names that exceeds the limit
    Set<QualifiedName> indexes = new HashSet<>();
    for (int i = 0; i <= Short.MAX_VALUE; i++) indexes.add(new QualifiedName(keyspace(), "idx" + i));
    // test too many included indexes
    Assertions.assertThatThrownBy(() -> IndexHints.fromCQLNames(indexes, null, null, null)).isInstanceOf(InvalidRequestException.class).hasMessageContaining(TOO_MANY_INDEXES_ERROR + indexes.size());
    // test too many excluded indexes
    Assertions.assertThatThrownBy(() -> IndexHints.fromCQLNames(null, indexes, null, null)).isInstanceOf(InvalidRequestException.class).hasMessageContaining(TOO_MANY_INDEXES_ERROR + indexes.size());
}

/**
 * Tests that the index hints serialization throws an exception when trying to serialize more indexes than can fit
 * in a short.
 */
@Test
public void testMaxHintsOnSerialization() {
    // prepare a set of indexes that exceeds the limit
    Set<IndexMetadata> indexes = new HashSet<>();
    for (int i = 0; i <= Short.MAX_VALUE; i++) indexes.add(IndexMetadata.fromSchemaMetadata("idx" + i, IndexMetadata.Kind.CUSTOM, Collections.emptyMap()));
    // test too many included indexes
    try (DataOutputBuffer out = new DataOutputBuffer()) {
        IndexHints hints = IndexHints.create(indexes, null);
        Assertions.assertThatThrownBy(() -> IndexHints.serializer.serialize(hints, out, MessagingService.VERSION_51)).isInstanceOf(AssertionError.class).hasMessageContaining(TOO_MANY_INDEXES_ERROR + indexes.size());
    }
    // test too many excluded indexes
    try (DataOutputBuffer out = new DataOutputBuffer()) {
        IndexHints hints = IndexHints.create(null, indexes);
        Assertions.assertThatThrownBy(() -> IndexHints.serializer.serialize(hints, out, MessagingService.VERSION_51)).isInstanceOf(AssertionError.class).hasMessageContaining(TOO_MANY_INDEXES_ERROR + indexes.size());
    }
}

@Test
public void testMultipleIndexesPerColumnAndCaseSensitivity() {
    createTable("CREATE TABLE %s (k int PRIMARY KEY, v text)");
    String sensitive = createIndex("CREATE INDEX sensitive ON %s(v) USING 'legacy_local_table'");
    String insensitive = createIndex("CREATE INDEX insensitive ON %s(v) USING 'sai' WITH OPTIONS = { 'case_sensitive' : false }");
    String insert = "INSERT INTO %s (k, v) VALUES (?, ?)";
    Object[] row1 = new Object[] { 1, "A" };
    Object[] row2 = new Object[] { 2, "a" };
    execute(insert, row1);
    execute(insert, row2);
    String query = "SELECT * FROM %s WHERE v='A'";
    // SAI has priority over legacy
    assertThatIndexQueryPlanFor(query, row1, row2).selects(insensitive);
    assertThatIndexQueryPlanFor(query + " WITH included_indexes={sensitive}", row1).selects(sensitive);
    assertThatIndexQueryPlanFor(query + " WITH included_indexes={insensitive}", row1, row2).selects(insensitive);
    assertThatIndexQueryPlanFor(query + " WITH excluded_indexes={sensitive}", row1, row2).selects(insensitive);
    assertThatIndexQueryPlanFor(query + " WITH excluded_indexes={insensitive}", row1).selects(sensitive);
    assertNeedsAllowFiltering(query + " WITH excluded_indexes={sensitive, insensitive}");
    assertThatIndexQueryPlanFor(query + " ALLOW FILTERING WITH excluded_indexes={sensitive, insensitive}", row1).selectsNone();
}

@Test
public void testCQLFilterClose() {
    // CASSANDRA-15126
    TableMetadata metadata = TableMetadata.builder("testks", "testcf").addPartitionKeyColumn("pk", Int32Type.instance).addStaticColumn("s", Int32Type.instance).addRegularColumn("r", Int32Type.instance).offline().build();
    ColumnMetadata s = metadata.getColumn(new ColumnIdentifier("s", true));
    ColumnMetadata r = metadata.getColumn(new ColumnIdentifier("r", true));
    ByteBuffer one = Int32Type.instance.decompose(1);
    RowFilter filter = RowFilter.none().withNewExpressions(new ArrayList<>());
    filter.add(s, Operator.NEQ, one);
    AtomicBoolean closed = new AtomicBoolean();
    UnfilteredPartitionIterator iter = filter.filter(new SingletonUnfilteredPartitionIterator(new UnfilteredRowIterator() {

        public DeletionTime partitionLevelDeletion() {
            return null;
        }

        public EncodingStats stats() {
            return null;
        }

        public TableMetadata metadata() {
            return metadata;
        }

        public boolean isReverseOrder() {
            return false;
        }

        public RegularAndStaticColumns columns() {
            return null;
        }

        public DecoratedKey partitionKey() {
            return null;
        }

        public boolean hasNext() {
            return false;
        }

        public Unfiltered next() {
            return null;
        }

        public Row staticRow() {
            return BTreeRow.create(Clustering.STATIC_CLUSTERING, LivenessInfo.EMPTY, Row.Deletion.LIVE, BTree.singleton(new BufferCell(s, 1, Cell.NO_TTL, Cell.NO_DELETION_TIME, one, null)));
        }

        public void close() {
            closed.set(true);
        }
    }), 1);
    assertFalse(iter.hasNext());
    assertTrue(closed.get());
    filter = RowFilter.none().withNewExpressions(new ArrayList<>());
    filter.add(r, Operator.NEQ, one);
    closed.set(false);
    iter = filter.filter(new SingletonUnfilteredPartitionIterator(new UnfilteredRowIterator() {

        boolean hasNext = true;

        public DeletionTime partitionLevelDeletion() {
            return null;
        }

        public EncodingStats stats() {
            return null;
        }

        public TableMetadata metadata() {
            return metadata;
        }

        public boolean isReverseOrder() {
            return false;
        }

        public RegularAndStaticColumns columns() {
            return null;
        }

        public DecoratedKey partitionKey() {
            return null;
        }

        public Row staticRow() {
            return Rows.EMPTY_STATIC_ROW;
        }

        public boolean hasNext() {
            boolean r = hasNext;
            hasNext = false;
            return r;
        }

        public Unfiltered next() {
            return BTreeRow.create(Clustering.EMPTY, LivenessInfo.EMPTY, Row.Deletion.LIVE, BTree.singleton(new BufferCell(r, 1, Cell.NO_TTL, Cell.NO_DELETION_TIME, one, null)));
        }

        public void close() {
            closed.set(true);
        }
    }), 1);
    assertFalse(iter.hasNext());
    assertTrue(closed.get());
}

@Test
public void testMutableIntersections() {
    TableMetadata metadata = TableMetadata.builder("testks", "testcf").addPartitionKeyColumn("pk", Int32Type.instance).addRegularColumn("r", Int32Type.instance).addRegularColumn("t", UTF8Type.instance).offline().build();
    RowFilter filter = RowFilter.none().withNewExpressions(new ArrayList<>());
    assertFalse(filter.isMutableIntersection());
    ColumnMetadata r = metadata.getColumn(new ColumnIdentifier("r", true));
    RowFilter.Expression gt = new RowFilter.SimpleExpression(r, Operator.GT, ByteBufferUtil.EMPTY_BYTE_BUFFER);
    filter = filter.withNewExpressions(Collections.singletonList(gt));
    assertFalse(filter.isMutableIntersection());
    RowFilter.Expression lt = new RowFilter.SimpleExpression(r, Operator.LT, ByteBufferUtil.EMPTY_BYTE_BUFFER);
    filter = filter.withNewExpressions(ImmutableList.of(gt, lt));
    assertFalse(filter.isMutableIntersection());
    ColumnMetadata t = metadata.getColumn(new ColumnIdentifier("t", true));
    RowFilter.Expression eq = new RowFilter.SimpleExpression(t, Operator.EQ, ByteBufferUtil.EMPTY_BYTE_BUFFER);
    filter = filter.withNewExpressions(ImmutableList.of(gt, lt, eq));
    assertTrue(filter.isMutableIntersection());
}

@Test
public void testIntersectsSingleSlice() {
    List<AbstractType<?>> types = new ArrayList<>();
    types.add(Int32Type.instance);
    types.add(Int32Type.instance);
    types.add(Int32Type.instance);
    ClusteringComparator cc = new ClusteringComparator(types);
    ClusteringPrefix.Kind sk = INCL_START_BOUND;
    ClusteringPrefix.Kind ek = INCL_END_BOUND;
    // filter falls entirely before sstable
    Slice slice = Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 1, 0, 0));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 2, 0, 0), makeBound(ek, 3, 0, 0)));
    // same case, but with empty start
    slice = Slice.make(makeBound(sk), makeBound(ek, 1, 0, 0));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 2, 0, 0), makeBound(ek, 3, 0, 0)));
    // same case, but with missing components for start
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 1, 0, 0));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 2, 0, 0), makeBound(ek, 3, 0, 0)));
    // same case, but with missing components for start and end
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 1, 0));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 2, 0, 0), makeBound(ek, 3, 0, 0)));
    // end of slice matches start of sstable for the first component, but not the second component
    slice = Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 1, 0, 0));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 1, 1, 0), makeBound(ek, 3, 0, 0)));
    // same case, but with missing components for start
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 1, 0, 0));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 1, 1, 0), makeBound(ek, 3, 0, 0)));
    // same case, but with missing components for start and end
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 1, 0));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 1, 1, 0), makeBound(ek, 3, 0, 0)));
    // first two components match, but not the last
    slice = Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 1, 1, 0));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek, 3, 1, 1)));
    // all three components in slice end match the start of the sstable
    slice = Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 1, 1, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek, 3, 1, 1)));
    // filter falls entirely after sstable
    slice = Slice.make(makeBound(sk, 4, 0, 0), makeBound(ek, 4, 0, 0));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 2, 0, 0), makeBound(ek, 3, 0, 0)));
    // same case, but with empty end
    slice = Slice.make(makeBound(sk, 4, 0, 0), makeBound(ek));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 2, 0, 0), makeBound(ek, 3, 0, 0)));
    // same case, but with missing components for end
    slice = Slice.make(makeBound(sk, 4, 0, 0), makeBound(ek, 1));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 2, 0, 0), makeBound(ek, 3, 0, 0)));
    // same case, but with missing components for start and end
    slice = Slice.make(makeBound(sk, 4, 0), makeBound(ek, 1));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 2, 0, 0), makeBound(ek, 3, 0, 0)));
    // start of slice matches end of sstable for the first component, but not the second component
    slice = Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek, 2, 0, 0));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 1, 0, 0)));
    // start of slice matches end of sstable for the first two components, but not the last component
    slice = Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek, 2, 0, 0));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 1, 1, 0)));
    // all three components in the slice start match the end of the sstable
    slice = Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek, 2, 0, 0));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 1, 1, 1)));
    // slice covers entire sstable (with no matching edges)
    slice = Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 2, 0, 0));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1, 1)));
    // same case, but with empty ends
    slice = Slice.make(makeBound(sk), makeBound(ek));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1, 1)));
    // same case, but with missing components
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 2, 0));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1, 1)));
    // slice covers entire sstable (with matching start)
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 0, 0));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1, 1)));
    // slice covers entire sstable (with matching end)
    slice = Slice.make(makeBound(sk, 0, 0, 0), makeBound(ek, 1, 1, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1, 1)));
    // slice covers entire sstable (with matching start and end)
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1, 1)));
    // slice falls entirely within sstable (with matching start)
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1, 0));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1, 1)));
    // same case, but with a missing end component
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1, 1)));
    // slice falls entirely within sstable (with matching end)
    slice = Slice.make(makeBound(sk, 1, 1, 0), makeBound(ek, 1, 1, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1, 1)));
    // same case, but with a missing start component
    slice = Slice.make(makeBound(sk, 1, 1), makeBound(ek, 1, 1, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 1, 1, 1)));
    // slice falls entirely within sstable
    slice = Slice.make(makeBound(sk, 1, 1, 0), makeBound(ek, 1, 1, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 2, 2)));
    // same case, but with a missing start component
    slice = Slice.make(makeBound(sk, 1, 1), makeBound(ek, 1, 1, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 2, 2)));
    // same case, but with a missing start and end components
    slice = Slice.make(makeBound(sk, 1), makeBound(ek, 1, 2));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 2, 2)));
    // same case, but with an equal first component and missing start and end components
    slice = Slice.make(makeBound(sk, 1), makeBound(ek, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 2, 2)));
    // slice falls entirely within sstable (slice start and end are the same)
    slice = Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek, 1, 1, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 2, 2)));
    // slice starts within sstable, empty end
    slice = Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 0, 0)));
    // same case, but with missing end components
    slice = Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek, 3));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 0, 0)));
    // slice starts within sstable (matching sstable start), empty end
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 0, 0)));
    // same case, but with missing end components
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 3));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 0, 0)));
    // slice starts within sstable (matching sstable end), empty end
    slice = Slice.make(makeBound(sk, 2, 0, 0), makeBound(ek));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 0, 0)));
    // same case, but with missing end components
    slice = Slice.make(makeBound(sk, 2, 0, 0), makeBound(ek, 3));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 0, 0)));
    // slice ends within sstable, empty end
    slice = Slice.make(makeBound(sk), makeBound(ek, 1, 1, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 0, 0)));
    // same case, but with missing start components
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 1, 1, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 0, 0)));
    // slice ends within sstable (matching sstable start), empty start
    slice = Slice.make(makeBound(sk), makeBound(ek, 1, 0, 0));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 0, 0)));
    // same case, but with missing start components
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 1, 0, 0));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 0, 0)));
    // slice ends within sstable (matching sstable end), empty start
    slice = Slice.make(makeBound(sk), makeBound(ek, 2, 0, 0));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 0, 0)));
    // same case, but with missing start components
    slice = Slice.make(makeBound(sk, 0), makeBound(ek, 2, 0, 0));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 0, 0)));
    // empty min/max column names
    slice = Slice.make(makeBound(sk), makeBound(ek));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk), makeBound(ek)));
    slice = Slice.make(makeBound(sk, 1), makeBound(ek));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk), makeBound(ek)));
    slice = Slice.make(makeBound(sk), makeBound(ek, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk), makeBound(ek)));
    slice = Slice.make(makeBound(sk, 1), makeBound(ek, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk), makeBound(ek)));
    slice = Slice.make(makeBound(sk), makeBound(ek));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk), makeBound(ek, 1)));
    slice = Slice.make(makeBound(sk), makeBound(ek, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk), makeBound(ek, 1)));
    slice = Slice.make(makeBound(sk), makeBound(ek, 1));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk), makeBound(ek, 2)));
    slice = Slice.make(makeBound(sk), makeBound(ek, 2));
    assertSlicesIntersect(cc, slice, Slice.make(makeBound(sk), makeBound(ek, 1)));
    slice = Slice.make(makeBound(sk, 2), makeBound(ek, 3));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk), makeBound(ek, 1)));
    // basic check on reversed slices
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 0, 0, 0));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 2, 0, 0), makeBound(ek, 3, 0, 0)));
    slice = Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 0, 0, 0));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 1, 1, 0), makeBound(ek, 3, 0, 0)));
    slice = Slice.make(makeBound(sk, 1, 1, 1), makeBound(ek, 1, 1, 0));
    assertSlicesDoNotIntersect(cc, slice, Slice.make(makeBound(sk, 1, 0, 0), makeBound(ek, 2, 2, 2)));
}

