@Test
public void testValuesIgnored() throws Throwable {
    // Using a sorted set below to ensure the order in the error message checked below are not random
    Values<Integer> ignored = new Values<>("x", REASON, state -> Collections.emptySet(), state -> insertionOrderedSet(4, 6, 20), state -> Collections.emptySet(), "integer");
    Set<Integer> triggeredOn = set();
    assertValid(() -> ignored.guard(set(3), triggeredOn::add, userClientState));
    assertEquals(set(), triggeredOn);
    assertWarns(() -> ignored.guard(set(4), triggeredOn::add, userClientState), "Ignoring provided values [4] as they are not supported for integer (ignored values are: [4, 6, 20])");
    assertEquals(set(4), triggeredOn);
    triggeredOn.clear();
    assertWarns(() -> ignored.guard(set(4, 6), triggeredOn::add, null), "Ignoring provided values [4, 6] as they are not supported for integer (ignored values are: [4, 6, 20])");
    assertEquals(set(4, 6), triggeredOn);
    triggeredOn.clear();
    assertWarns(() -> ignored.guard(set(4, 5, 6, 7), triggeredOn::add, null), "Ignoring provided values [4, 6] as they are not supported for integer (ignored values are: [4, 6, 20])");
    assertEquals(set(4, 6), triggeredOn);
    triggeredOn.clear();
    assertThrows(() -> ignored.guard(set(4), userClientState), AssertionError.class, "There isn't an ignore action for integer, but value 4 is setup to be ignored");
}

