@Test
@SuppressWarnings("rawtypes")
public void allTypesCovered() {
    // this test just makes sure that all types are covered and no new type is left out
    Set<Class<? extends AbstractType>> subTypes = reflections.getSubTypesOf(AbstractType.class);
    Set<Class<? extends AbstractType>> coverage = AbstractTypeGenerators.knownTypes();
    StringBuilder sb = new StringBuilder();
    for (Class<? extends AbstractType> klass : Sets.difference(subTypes, coverage)) {
        if (Modifier.isAbstract(klass.getModifiers()))
            continue;
        if (isTestType(klass))
            continue;
        if (isPrefixCompositeType(klass))
            continue;
        String name = klass.getCanonicalName();
        if (name == null)
            name = klass.getName();
        sb.append(name).append('\n');
    }
    if (sb.length() > 0)
        throw new AssertionError("Uncovered types:\n" + sb);
}

@Test
@SuppressWarnings("rawtypes")
public void meaninglessEmptyness() {
    // this test just makes sure that all types are covered and no new type is left out
    Set<Class<? extends AbstractType>> subTypes = reflections.getSubTypesOf(AbstractType.class);
    for (var klass : subTypes) {
        if (Modifier.isAbstract(klass.getModifiers()))
            continue;
        if (isTestType(klass))
            continue;
        if (isPrefixCompositeType(klass))
            continue;
        AbstractType<?> type = null;
        for (var f : klass.getDeclaredFields()) {
            if (!(Modifier.isPublic(f.getModifiers()) && Modifier.isStatic(f.getModifiers())))
                continue;
            if (AbstractType.class.isAssignableFrom(f.getType())) {
                try {
                    type = (AbstractType<?>) f.get(null);
                    break;
                } catch (IllegalAccessException e) {
                    throw new RuntimeException(e);
                }
            }
        }
        if (type == null) {
            for (var c : klass.getDeclaredConstructors()) {
                if (c.getParameterCount() == 0) {
                    try {
                        type = (AbstractType<?>) c.newInstance();
                        break;
                    } catch (InstantiationException | IllegalAccessException | InvocationTargetException e) {
                        throw new RuntimeException(e);
                    }
                }
            }
        }
        if (type == null)
            continue;
        if (type.isEmptyValueMeaningless()) {
            Assertions.assertThat(AbstractTypeGenerators.supportsMeaninglessEmptyness(type)).describedAs("New type %s detected that says its emptyness is meaningless, but it isn't allowed to be!  This is a legacy concept only!", type.getClass()).isTrue();
            Assertions.assertThat(type.isNull(ByteBufferUtil.EMPTY_BYTE_BUFFER)).isTrue();
        }
    }
}

