@Test
public void testMemtable() throws Throwable {
    String keyspace = createKeyspace("CREATE KEYSPACE %s with replication = { 'class' : 'SimpleStrategy', 'replication_factor' : 1 } and durable_writes = false");
    String table = createTable(keyspace, "CREATE TABLE %s ( userid bigint, picid bigint, commentid bigint, PRIMARY KEY(userid, picid))" + " with compression = {'enabled': false}" + " and memtable = '" + memtableClass + "'" + // to trigger splitting of sstables, CASSANDRA-18123
    " and compaction = { 'class': 'UnifiedCompactionStrategy', 'base_shard_count': '4' }");
    execute("use " + keyspace + ';');
    String writeStatement = "INSERT INTO " + table + "(userid,picid,commentid)VALUES(?,?,?)";
    ColumnFamilyStore cfs = Keyspace.open(keyspace).getColumnFamilyStore(table);
    cfs.disableAutoCompaction();
    Util.flush(cfs);
    long i;
    long limit = partitions;
    logger.info("Writing {} partitions of {} rows", partitions, rowsPerPartition);
    for (i = 0; i < limit; ++i) {
        for (long j = 0; j < rowsPerPartition; ++j) execute(writeStatement, i, j, i + j);
    }
    logger.info("Deleting partitions between {} and {}", deletedPartitionsStart, deletedPartitionsEnd);
    for (i = deletedPartitionsStart; i < deletedPartitionsEnd; ++i) {
        // no partition exists, but we will create a tombstone
        execute("DELETE FROM " + table + " WHERE userid = ?", i);
    }
    logger.info("Deleting rows between {} and {}", deletedRowsStart, deletedRowsEnd);
    for (i = deletedRowsStart; i < deletedRowsEnd; ++i) {
        // no row exists, but we will create a tombstone (and partition)
        execute("DELETE FROM " + table + " WHERE userid = ? AND picid = ?", i, 0L);
    }
    logger.info("Reading {} partitions", partitions);
    for (i = 0; i < limit; ++i) {
        UntypedResultSet result = execute("SELECT * FROM " + table + " WHERE userid = ?", i);
        if (i >= deletedPartitionsStart && i < deletedPartitionsEnd)
            assertEmpty(result);
        else {
            int start = 0;
            if (i >= deletedRowsStart && i < deletedRowsEnd)
                start = 1;
            Object[][] rows = new Object[rowsPerPartition - start][];
            for (long j = start; j < rowsPerPartition; ++j) rows[(int) (j - start)] = row(i, j, i + j);
            assertRows(result, rows);
        }
    }
    int deletedPartitions = deletedPartitionsEnd - deletedPartitionsStart;
    int deletedRows = deletedRowsEnd - deletedRowsStart;
    logger.info("Selecting *");
    UntypedResultSet result = execute("SELECT * FROM " + table);
    assertRowCount(result, rowsPerPartition * (partitions - deletedPartitions) - deletedRows);
    Util.flush(cfs);
    logger.info("Selecting *");
    result = execute("SELECT * FROM " + table);
    assertRowCount(result, rowsPerPartition * (partitions - deletedPartitions) - deletedRows);
    try (Refs<SSTableReader> refs = new Refs()) {
        Collection<SSTableReader> sstables = cfs.getLiveSSTables();
        if (// persistent memtables won't flush
        sstables.isEmpty()) {
            assert cfs.streamFromMemtable();
            cfs.writeAndAddMemtableRanges(null, () -> ImmutableList.of(new Range(Util.testPartitioner().getMinimumToken().minKeyBound(), Util.testPartitioner().getMinimumToken().minKeyBound())), refs);
            sstables = refs;
            Assert.assertTrue(cfs.getLiveSSTables().isEmpty());
        }
        // make sure the row counts are correct in both the metadata as well as the cardinality estimator
        // (see CASSANDRA-18123)
        long totalPartitions = 0;
        for (SSTableReader sstable : sstables) {
            long sstableKeys = sstable.estimatedKeys();
            long cardinality = SSTableReader.getApproximateKeyCount(ImmutableList.of(sstable));
            // should be within 10% of each other
            Assert.assertEquals((double) sstableKeys, (double) cardinality, sstableKeys * 0.1);
            totalPartitions += sstableKeys;
        }
        Assert.assertEquals((double) partitions, (double) totalPartitions, partitions * 0.1);
    }
}

@Test
public void testSize() throws Throwable {
    // Make sure memtables use the correct allocation type, i.e. that setup has worked.
    // If this fails, make sure the test is not reusing an already-initialized JVM.
    checkMemtablePool();
    CQLTester.disablePreparedReuseForTest();
    String keyspace = createKeyspace("CREATE KEYSPACE %s with replication = { 'class' : 'SimpleStrategy', 'replication_factor' : 1 } and durable_writes = false");
    try {
        String table = createTable(keyspace, "CREATE TABLE %s ( userid bigint, picid bigint, commentid bigint, PRIMARY KEY(userid, picid))" + " with compression = {'enabled': false}" + " and memtable = '" + memtableClass + "'");
        execute("use " + keyspace + ';');
        String writeStatement = "INSERT INTO " + table + "(userid,picid,commentid)VALUES(?,?,?)";
        forcePreparedValues();
        ColumnFamilyStore cfs = Keyspace.open(keyspace).getColumnFamilyStore(table);
        cfs.disableAutoCompaction();
        Util.flush(cfs);
        Memtable memtable = cfs.getTracker().getView().getCurrentMemtable();
        long deepSizeBefore = meter.measureDeep(memtable);
        logger.info("Memtable deep size before {}", FBUtilities.prettyPrintMemory(deepSizeBefore));
        long i;
        long limit = partitions;
        logger.info("Writing {} partitions of {} rows", partitions, rowsPerPartition);
        for (i = 0; i < limit; ++i) {
            for (long j = 0; j < rowsPerPartition; ++j) execute(writeStatement, i, j, i + j);
        }
        logger.info("Deleting {} partitions", deletedPartitions);
        limit += deletedPartitions;
        for (; i < limit; ++i) {
            // no partition exists, but we will create a tombstone
            execute("DELETE FROM " + table + " WHERE userid = ?", i);
        }
        logger.info("Deleting {} rows", deletedRows);
        limit += deletedRows;
        for (; i < limit; ++i) {
            // no row exists, but we will create a tombstone (and partition)
            execute("DELETE FROM " + table + " WHERE userid = ? AND picid = ?", i, 0L);
        }
        Assert.assertSame("Memtable flushed during test. Test was not carried out correctly.", memtable, cfs.getTracker().getView().getCurrentMemtable());
        Memtable.MemoryUsage usage = Memtable.getMemoryUsage(memtable);
        long actualHeap = usage.ownsOnHeap;
        logger.info(String.format("Memtable in %s mode: %d ops, %s serialized bytes, %s", DatabaseDescriptor.getMemtableAllocationType(), memtable.operationCount(), FBUtilities.prettyPrintMemory(memtable.getLiveDataSize()), usage));
        long deepSizeAfter = meter.measureDeep(memtable);
        logger.info("Memtable deep size {}", FBUtilities.prettyPrintMemory(deepSizeAfter));
        long expectedHeap = deepSizeAfter - deepSizeBefore;
        long max_difference = MAX_DIFFERENCE_PERCENT * expectedHeap / 100;
        long trie_overhead = memtable instanceof TrieMemtable ? ((TrieMemtable) memtable).unusedReservedMemory() : 0;
        switch(DatabaseDescriptor.getMemtableAllocationType()) {
            case heap_buffers:
                max_difference += SLAB_OVERHEAD;
                // adjust trie memory with unused buffer space if on-heap
                actualHeap += trie_overhead;
                break;
            case unslabbed_heap_buffers:
                // adjust trie memory with unused buffer space if on-heap
                actualHeap += trie_overhead;
                break;
        }
        double deltaPerPartition = (expectedHeap - actualHeap) / (double) totalPartitions;
        String message = String.format("Expected heap usage close to %s, got %s, %s difference. " + "Delta per partition: %.2f bytes", FBUtilities.prettyPrintMemory(expectedHeap), FBUtilities.prettyPrintMemory(actualHeap), FBUtilities.prettyPrintMemory(expectedHeap - actualHeap), deltaPerPartition);
        logger.info(message);
        Assert.assertTrue(message, Math.abs(actualHeap - expectedHeap) <= max_difference);
    } finally {
        execute(String.format("DROP KEYSPACE IF EXISTS %s", keyspace));
    }
}

