@Test
public void checkPartitionCountAndPartitionKeysSizeReportedByFlushSet() {
    String keyspace = createKeyspace("CREATE KEYSPACE %s with replication = { 'class' : 'SimpleStrategy', 'replication_factor' : 1 } and durable_writes = false");
    String table = createTable(keyspace, "CREATE TABLE %s ( userid bigint, picid bigint, commentid bigint, PRIMARY KEY(userid, picid))" + " WITH memtable = 'trie_" + shardsCount + "'");
    String tableToCompare = createTable(keyspace, "CREATE TABLE %s ( userid bigint, picid bigint, commentid bigint, PRIMARY KEY(userid, picid))" + " WITH memtable = 'skiplist'");
    execute("use " + keyspace + ';');
    String writeStatement = "INSERT INTO " + table + "(userid,picid,commentid) VALUES (?,?,?)";
    String writeStatementToCompare = "INSERT INTO " + tableToCompare + "(userid,picid,commentid) VALUES (?,?,?)";
    ColumnFamilyStore cfs = Keyspace.open(keyspace).getColumnFamilyStore(table);
    ColumnFamilyStore cfsToCompare = Keyspace.open(keyspace).getColumnFamilyStore(tableToCompare);
    for (long i = 0; i < partitions; ++i) {
        for (long j = 0; j < rowsPerPartition; ++j) {
            execute(writeStatement, i, j, i + j);
            execute(writeStatementToCompare, i, j, i + j);
        }
    }
    Memtable memtable = cfs.getCurrentMemtable();
    Memtable memtableToCompare = cfsToCompare.getCurrentMemtable();
    {
        Memtable.FlushablePartitionSet<?> flushSetNull = memtable.getFlushSet(null, null);
        Assert.assertEquals(partitions, flushSetNull.partitionCount());
        Assert.assertEquals(partitions * Long.BYTES, flushSetNull.partitionKeysSize());
    }
    {
        Memtable.FlushablePartitionSet<?> flushSetFromMinToMax = memtable.getFlushSet(getMinPosition(cfs), getMaxPosition(cfs));
        Assert.assertEquals(partitions, flushSetFromMinToMax.partitionCount());
        Assert.assertEquals(partitions * Long.BYTES, flushSetFromMinToMax.partitionKeysSize());
    }
    ShardBoundaries shardBoundaries = cfs.localRangeSplits(shardsCount);
    testShardRanges(shardBoundaries, cfs, memtable, memtableToCompare);
    // to test partial covered shards
    // a prime number to not match with shard boundaries
    ShardBoundaries nonMatchingShardBoundaries1 = cfs.localRangeSplits(13);
    testShardRanges(nonMatchingShardBoundaries1, cfs, memtable, memtableToCompare);
    // to check small ranges within shard boundaries
    ShardBoundaries nonMatchingShardBoundaries2 = cfs.localRangeSplits(32);
    testShardRanges(nonMatchingShardBoundaries2, cfs, memtable, memtableToCompare);
    // to test the case when a flush position is a partition key
    {
        ByteBuffer oneOfWrittenPartitionKeys = LongType.instance.decompose(0L);
        DecoratedKey decoratedKey = cfs.getPartitioner().decorateKey(oneOfWrittenPartitionKeys);
        testRange(memtable, memtableToCompare, getMinPosition(cfs), decoratedKey);
        testRange(memtable, memtableToCompare, decoratedKey, getMaxPosition(cfs));
    }
}

/**
 * Verifies that {@link sun.misc.Cleaner} works and that mmap'd files can be deleted.
 */
@Test
public void testMmapFile() throws Exception {
    ObjectName bpmName = new ObjectName("java.nio:type=BufferPool,name=mapped");
    MBeanServer mbs = ManagementFactory.getPlatformMBeanServer();
    Long mmapCount = (Long) mbs.getAttribute(bpmName, "Count");
    Long mmapMemoryUsed = (Long) mbs.getAttribute(bpmName, "MemoryUsed");
    Assert.assertEquals("# of mapped buffers should be 0", Long.valueOf(0L), mmapCount);
    Assert.assertEquals("amount of mapped memory should be 0", Long.valueOf(0L), mmapMemoryUsed);
    File f1 = FileUtils.createTempFile("MmapFileTest1", ".bin");
    File f2 = FileUtils.createTempFile("MmapFileTest2", ".bin");
    File f3 = FileUtils.createTempFile("MmapFileTest2", ".bin");
    try {
        int size = 1024 * 1024;
        Util.setFileLength(f1, size);
        Util.setFileLength(f2, size);
        Util.setFileLength(f3, size);
        try (FileChannel channel = FileChannel.open(f1.toPath(), StandardOpenOption.WRITE, StandardOpenOption.READ)) {
            MappedByteBuffer buffer = channel.map(FileChannel.MapMode.READ_WRITE, 0, size);
            mmapCount = (Long) mbs.getAttribute(bpmName, "Count");
            mmapMemoryUsed = (Long) mbs.getAttribute(bpmName, "MemoryUsed");
            Assert.assertEquals("mapped buffers don't work?", Long.valueOf(1L), mmapCount);
            Assert.assertTrue("mapped buffers don't work?", mmapMemoryUsed >= size);
            Assert.assertTrue(buffer.isDirect());
            buffer.putInt(42);
            buffer.putInt(42);
            buffer.putInt(42);
            buffer.putInt(42);
            buffer.putInt(42);
            MemoryUtil.clean(buffer);
        }
        mmapCount = (Long) mbs.getAttribute(bpmName, "Count");
        mmapMemoryUsed = (Long) mbs.getAttribute(bpmName, "MemoryUsed");
        Assert.assertEquals("# of mapped buffers should be 0", Long.valueOf(0L), mmapCount);
        Assert.assertEquals("amount of mapped memory should be 0", Long.valueOf(0L), mmapMemoryUsed);
        try (FileChannel channel = FileChannel.open(f2.toPath(), StandardOpenOption.WRITE, StandardOpenOption.READ)) {
            MappedByteBuffer buffer = channel.map(FileChannel.MapMode.READ_WRITE, 0, size);
            // # of mapped buffers is == 1 here - seems that previous direct buffer for 'f1' is deallocated now
            mmapCount = (Long) mbs.getAttribute(bpmName, "Count");
            mmapMemoryUsed = (Long) mbs.getAttribute(bpmName, "MemoryUsed");
            Assert.assertEquals("mapped buffers don't work?", Long.valueOf(1L), mmapCount);
            Assert.assertTrue("mapped buffers don't work?", mmapMemoryUsed >= size);
            Assert.assertTrue(buffer.isDirect());
            buffer.putInt(42);
            buffer.putInt(42);
            buffer.putInt(42);
            buffer.putInt(42);
            buffer.putInt(42);
            MemoryUtil.clean(buffer);
        }
        mmapCount = (Long) mbs.getAttribute(bpmName, "Count");
        mmapMemoryUsed = (Long) mbs.getAttribute(bpmName, "MemoryUsed");
        Assert.assertEquals("# of mapped buffers should be 0", Long.valueOf(0L), mmapCount);
        Assert.assertEquals("amount of mapped memory should be 0", Long.valueOf(0L), mmapMemoryUsed);
        try (FileChannel channel = FileChannel.open(f3.toPath(), StandardOpenOption.WRITE, StandardOpenOption.READ)) {
            MappedByteBuffer buffer = channel.map(FileChannel.MapMode.READ_WRITE, 0, size);
            mmapCount = (Long) mbs.getAttribute(bpmName, "Count");
            mmapMemoryUsed = (Long) mbs.getAttribute(bpmName, "MemoryUsed");
            Assert.assertEquals("mapped buffers don't work?", Long.valueOf(1L), mmapCount);
            Assert.assertTrue("mapped buffers don't work?", mmapMemoryUsed >= size);
            Assert.assertTrue(buffer.isDirect());
            buffer.putInt(42);
            buffer.putInt(42);
            buffer.putInt(42);
            buffer.putInt(42);
            buffer.putInt(42);
            MemoryUtil.clean(buffer);
        }
        mmapCount = (Long) mbs.getAttribute(bpmName, "Count");
        mmapMemoryUsed = (Long) mbs.getAttribute(bpmName, "MemoryUsed");
        Assert.assertEquals("# of mapped buffers should be 0", Long.valueOf(0L), mmapCount);
        Assert.assertEquals("amount of mapped memory should be 0", Long.valueOf(0L), mmapMemoryUsed);
        Assert.assertTrue(f1.tryDelete());
        Assert.assertTrue(f2.tryDelete());
        Assert.assertTrue(f3.tryDelete());
    } finally {
        Runtime.getRuntime().gc();
        f1.tryDelete();
        f2.tryDelete();
        f3.tryDelete();
    }
}

