@Test
public void mergeRowsWithSameExpiryDifferentTTLCommutesLiveness() {
    long now1 = FBUtilities.nowInSeconds();
    long ts1 = secondToTs(now1);
    long ldt = now1 + 1000;
    Row.Builder r1Builder = BTreeRow.unsortedBuilder();
    r1Builder.newRow(c1);
    LivenessInfo originalLiveness = LivenessInfo.withExpirationTime(ts1, 100, ldt);
    r1Builder.addPrimaryKeyLivenessInfo(originalLiveness);
    Row.Builder r2Builder = BTreeRow.unsortedBuilder();
    r2Builder.newRow(c1);
    LivenessInfo loweredTTL = LivenessInfo.withExpirationTime(ts1, 50, ldt);
    r2Builder.addPrimaryKeyLivenessInfo(loweredTTL);
    Cell<?> r2v = expiringWithExpirationTime(v, ts1, 75, ldt, BB1);
    Cell<?> r2m2 = expiringWithExpirationTime(m, ts1, 50, ldt, BB1, CellPath.create(BB2));
    Cell<?> r2m3 = expiringWithExpirationTime(m, ts1, 75, ldt, BB2, CellPath.create(BB3));
    Cell<?> r2m4 = expiringWithExpirationTime(m, ts1, 100, ldt, BB3, CellPath.create(BB4));
    List<Cell<?>> expectedCells = Lists.newArrayList(r2v, r2m2, r2m3, r2m4);
    expectedCells.forEach(r1Builder::addCell);
    expectedCells.forEach(r2Builder::addCell);
    Row r1 = r1Builder.build();
    Row r2 = r2Builder.build();
    Row r1r2 = Rows.merge(r1, r2);
    Row r2r1 = Rows.merge(r2, r1);
    DiffListener mergedListener = new DiffListener();
    Rows.diff(mergedListener, r1r2, r2r1);
    mergedListener.liveness.forEach(pair -> Assert.assertEquals(pair.merged, pair.original));
    mergedListener.cells.forEach(pair -> assertCellsEqual(pair.merged, pair.original));
}

@Test
public void testLegacyCellIterator() {
    // Creates a table with
    //   - 3 Simple columns: a, c and e
    //   - 2 Complex columns: b and d
    TableMetadata metadata = TableMetadata.builder("dummy_ks", "dummy_tbl").addPartitionKeyColumn("k", BytesType.instance).addRegularColumn("a", BytesType.instance).addRegularColumn("b", MapType.getInstance(Int32Type.instance, BytesType.instance, true)).addRegularColumn("c", BytesType.instance).addRegularColumn("d", MapType.getInstance(Int32Type.instance, BytesType.instance, true)).addRegularColumn("e", BytesType.instance).build();
    ColumnMetadata a = metadata.getColumn(new ColumnIdentifier("a", false));
    ColumnMetadata b = metadata.getColumn(new ColumnIdentifier("b", false));
    ColumnMetadata c = metadata.getColumn(new ColumnIdentifier("c", false));
    ColumnMetadata d = metadata.getColumn(new ColumnIdentifier("d", false));
    ColumnMetadata e = metadata.getColumn(new ColumnIdentifier("e", false));
    Row row;
    // Row with only simple columns
    row = makeDummyRow(liveCell(a), liveCell(c), liveCell(e));
    assertCellOrder(row.cellsInLegacyOrder(metadata, false), liveCell(a), liveCell(c), liveCell(e));
    assertCellOrder(row.cellsInLegacyOrder(metadata, true), liveCell(e), liveCell(c), liveCell(a));
    // Row with only complex columns
    row = makeDummyRow(liveCell(b, 1), liveCell(b, 2), liveCell(d, 3), liveCell(d, 4));
    assertCellOrder(row.cellsInLegacyOrder(metadata, false), liveCell(b, 1), liveCell(b, 2), liveCell(d, 3), liveCell(d, 4));
    assertCellOrder(row.cellsInLegacyOrder(metadata, true), liveCell(d, 4), liveCell(d, 3), liveCell(b, 2), liveCell(b, 1));
    // Row with mixed simple and complex columns
    row = makeDummyRow(liveCell(a), liveCell(c), liveCell(e), liveCell(b, 1), liveCell(b, 2), liveCell(d, 3), liveCell(d, 4));
    assertCellOrder(row.cellsInLegacyOrder(metadata, false), liveCell(a), liveCell(b, 1), liveCell(b, 2), liveCell(c), liveCell(d, 3), liveCell(d, 4), liveCell(e));
    assertCellOrder(row.cellsInLegacyOrder(metadata, true), liveCell(e), liveCell(d, 4), liveCell(d, 3), liveCell(c), liveCell(b, 2), liveCell(b, 1), liveCell(a));
}

@Test
public void emptyPartitionDeletionTest() throws Throwable {
    // create cell tombstone, range tombstone, partition deletion
    createTable("CREATE TABLE %s (pk int, ck1 int, ck2 int, v1 int, v2 int, PRIMARY KEY (pk, ck1, ck2))");
    // partition deletion
    execute("DELETE FROM %s USING TIMESTAMP 160 WHERE pk=1");
    // flush and generate 1 sstable
    ColumnFamilyStore cfs = Keyspace.open(keyspace()).getColumnFamilyStore(currentTable());
    Util.flush(cfs);
    cfs.disableAutoCompaction();
    cfs.forceMajorCompaction();
    assertEquals(1, cfs.getLiveSSTables().size());
    SSTableReader reader = cfs.getLiveSSTables().iterator().next();
    try (ISSTableScanner scanner = reader.getScanner();
        CloseableIterator<UnfilteredRowIterator> throttled = ThrottledUnfilteredIterator.throttle(scanner, 100)) {
        assertTrue(throttled.hasNext());
        UnfilteredRowIterator iterator = throttled.next();
        assertFalse(throttled.hasNext());
        assertFalse(iterator.hasNext());
        assertEquals(iterator.partitionLevelDeletion().markedForDeleteAt(), 160);
    }
    // test opt out
    try (ISSTableScanner scanner = reader.getScanner();
        CloseableIterator<UnfilteredRowIterator> throttled = ThrottledUnfilteredIterator.throttle(scanner, 0)) {
        assertEquals(scanner, throttled);
    }
}

