    assertRows(concat, row(1, cell(v1Metadata, 1), cell(v2Metadata, 1)), row(3, cell(v1Metadata, 3), cell(v2Metadata, 3)), row(4, cell(v1Metadata, 4), cell(v2Metadata, 4)));
}

