        spinUntilSuccess(() -> Assertions.assertThat(execute(QUERY_TRACES, id.toString(), "WAIT_PROGRESS").size()).isGreaterThan(0));
        execute(ERASE_TRACES1, id.toString(), "FETCH", Long.MAX_VALUE);
