@Test
public void inflight() throws ExecutionException, InterruptedException {
    ProtocolModifiers.Toggles.setPermitLocalExecution(false);
    AccordMsgFilter filter = new AccordMsgFilter();
    MessagingService.instance().outboundSink.add(filter);
    try {
        String tableName = createTable("CREATE TABLE %s (k int, c int, v int, PRIMARY KEY (k, c)) WITH transactional_mode = 'full'");
        AccordService accord = accord();
        TxnId id = accord.node().nextTxnIdWithDefaultFlags(Txn.Kind.Write, Routable.Domain.Key);
        String insertTxn = String.format("BEGIN TRANSACTION\n" + "    LET r = (SELECT * FROM %s.%s WHERE k = ? AND c = ?);\n" + "    IF r IS NULL THEN\n " + "        INSERT INTO %s.%s (k, c, v) VALUES (?, ?, ?);\n" + "    END IF\n" + "COMMIT TRANSACTION", KEYSPACE, tableName, KEYSPACE, tableName);
        Txn txn = createTxn(insertTxn, 0, 0, 0, 0, 0);
        filter.appliesTo(id);
        accord.node().coordinate(id, txn).beginAsResult();
        filter.preAccept.awaitThrowUncheckedOnInterrupt();
        assertRows(execute(QUERY_TXN_BLOCKED_BY, id.toString()), row(id.toString(), KEYSPACE, tableName, anyInt(), 0, ByteBufferUtil.EMPTY_BYTE_BUFFER, "Self", any(), null, anyOf(SaveStatus.PreAccepted.name(), SaveStatus.ReadyToExecute.name())));
        filter.apply.awaitThrowUncheckedOnInterrupt();
        assertRows(execute(QUERY_TXN_BLOCKED_BY, id.toString()), row(id.toString(), KEYSPACE, tableName, anyInt(), 0, ByteBufferUtil.EMPTY_BYTE_BUFFER, "Self", any(), null, SaveStatus.ReadyToExecute.name()));
    } finally {
        filter.reset();
        MessagingService.instance().outboundSink.remove(filter);
    }
}

@Test
public void blocked() throws ExecutionException, InterruptedException {
    ProtocolModifiers.Toggles.setPermitLocalExecution(false);
    ProtocolModifiers.Toggles.setPermittedFastPaths(new TxnId.FastPaths(Unoptimised));
    AccordMsgFilter filter = new AccordMsgFilter();
    MessagingService.instance().outboundSink.add(filter);
    try {
        String tableName = createTable("CREATE TABLE %s (k int, c int, v int, PRIMARY KEY (k, c)) WITH transactional_mode = 'full'");
        AccordService accord = accord();
        TxnId first = accord.node().nextTxnIdWithDefaultFlags(Txn.Kind.Write, Routable.Domain.Key);
        String insertTxn = String.format("BEGIN TRANSACTION\n" + "    LET r = (SELECT * FROM %s.%s WHERE k = ? AND c = ?);\n" + "    IF r IS NULL THEN\n " + "        INSERT INTO %s.%s (k, c, v) VALUES (?, ?, ?);\n" + "    END IF\n" + "COMMIT TRANSACTION", KEYSPACE, tableName, KEYSPACE, tableName);
        filter.appliesTo(first);
        accord.node().coordinate(first, createTxn(insertTxn, 0, 0, 0, 0, 0)).beginAsResult();
        filter.preAccept.awaitThrowUncheckedOnInterrupt();
        spinUntilSuccess(() -> assertRows(execute(QUERY_TXN_BLOCKED_BY, first.toString()), row(first.toString(), KEYSPACE, tableName, anyInt(), 0, ByteBufferUtil.EMPTY_BYTE_BUFFER, "Self", any(), null, anyOf(SaveStatus.PreAccepted.name(), SaveStatus.ReadyToExecute.name()))));
        filter.apply.awaitThrowUncheckedOnInterrupt();
        spinUntilSuccess(() -> assertRows(execute(QUERY_TXN_BLOCKED_BY, first.toString()), row(first.toString(), KEYSPACE, tableName, anyInt(), 0, ByteBufferUtil.EMPTY_BYTE_BUFFER, "Self", anyNonNull(), null, SaveStatus.ReadyToExecute.name())));
        TxnId second = accord.node().nextTxnIdWithDefaultFlags(Txn.Kind.Write, Routable.Domain.Key);
        filter.reset();
        filter.appliesTo(second);
        accord.node().coordinate(second, createTxn(insertTxn, 0, 0, 0, 0, 0)).beginAsResult();
        filter.commit.awaitThrowUncheckedOnInterrupt();
        Awaitility.await("waiting on key").atMost(1, TimeUnit.MINUTES).until(() -> {
            UntypedResultSet rs = execute(QUERY_TXN_BLOCKED_BY, second.toString());
            return rs.size() == 2;
        });
        assertRows(execute(QUERY_TXN_BLOCKED_BY, second.toString()), row(second.toString(), KEYSPACE, tableName, anyInt(), 0, ByteBufferUtil.EMPTY_BYTE_BUFFER, "Self", anyNonNull(), null, SaveStatus.Stable.name()), row(second.toString(), KEYSPACE, tableName, anyInt(), 1, first.toString(), "Key", anyNonNull(), anyNonNull(), SaveStatus.ReadyToExecute.name()));
        assertRows(execute(QUERY_TXN_BLOCKED_BY + " AND depth < 1", second.toString()), row(second.toString(), KEYSPACE, tableName, anyInt(), 0, ByteBufferUtil.EMPTY_BYTE_BUFFER, "Self", anyNonNull(), null, SaveStatus.Stable.name()));
    } finally {
        filter.reset();
        MessagingService.instance().outboundSink.remove(filter);
    }
}

