        Awaitility.await().until(() -> !states.isEmpty());
        Map.Entry<InetAddressAndPort, EndpointState> entry = states.entrySet().stream().findFirst().orElseThrow(AssertionError::new);
        InetAddressAndPort endpoint = entry.getKey();
        EndpointState localState = new EndpointState(entry.getValue());
