    bounds.add(bounds(0, 5));
    bounds.add(bounds(21, 22));
    bounds.add(bounds(1, 8));
    Set<Bounds<Token>> nonOverlappingBounds = Bounds.getNonOverlappingBounds(bounds);
    assertEquals(3, nonOverlappingBounds.size());
