    execute("INSERT INTO %s (k, c) VALUES (?, ?)", row3);
    execute("INSERT INTO %s (k, c) VALUES (?, ?)", row4);
    assertRowsIgnoringOrder(execute("SELECT * FROM %s WHERE c = ?", "c0"), row1, row3);
