@Test
public void unindexedContainsExpressions() {
    createTable("CREATE TABLE %s (k int PRIMARY KEY, v int, m map<int, int>)");
    // just to make sure that SAI is involved
    createIndex("CREATE INDEX ON %s(v) USING 'SAI'");
    Object[] row = row(0, 1, map(2, 3));
    execute("INSERT INTO %s (k, v, m) VALUES (?, ?, ?)", row);
    execute("INSERT INTO %s (k, v, m) VALUES (?, ?, ?)", 1, 1, map(12, 13));
    // try without any indexes on the map
    assertRows(execute("SELECT k, v, m FROM %s WHERE v = 1 AND m CONTAINS 3 ALLOW FILTERING"), row);
    assertRows(execute("SELECT k, v, m FROM %s WHERE v = 1 AND m CONTAINS KEY 2 ALLOW FILTERING"), row);
    assertRows(execute("SELECT k, v, m FROM %s WHERE v = 1 AND m CONTAINS KEY 2 AND m CONTAINS 3 ALLOW FILTERING"), row);
    // try with index on map values
    createIndex("CREATE INDEX ON %s(m) USING 'SAI'");
    assertRows(execute("SELECT k, v, m FROM %s WHERE v = 1 AND m CONTAINS 3"), row);
    assertRows(execute("SELECT k, v, m FROM %s WHERE v = 1 AND m CONTAINS KEY 2 ALLOW FILTERING"), row);
    assertRows(execute("SELECT k, v, m FROM %s WHERE v = 1 AND m CONTAINS KEY 2 AND m CONTAINS 3 ALLOW FILTERING"), row);
    // try with index on map keys
    createIndex("CREATE INDEX ON %s(KEYS(m)) USING 'SAI'");
    assertRows(execute("SELECT k, v, m FROM %s WHERE v = 1 AND m CONTAINS 3"), row);
    assertRows(execute("SELECT k, v, m FROM %s WHERE v = 1 AND m CONTAINS KEY 2"), row);
    assertRows(execute("SELECT k, v, m FROM %s WHERE v = 1 AND m CONTAINS KEY 2 AND m CONTAINS 3"), row);
}

@Test
public void partialUpdateTest() {
    createTable("CREATE TABLE %s (pk int, c1 text, c2 text, PRIMARY KEY(pk))");
    createIndex("CREATE CUSTOM INDEX ON %s(c1) USING 'StorageAttachedIndex'");
    createIndex("CREATE CUSTOM INDEX ON %s(c2) USING 'StorageAttachedIndex'");
    execute("INSERT INTO %s (pk, c1, c2) VALUES (?, ?, ?)", 1, "a", "a");
    flush();
    execute("UPDATE %s SET c1 = ? WHERE pk = ?", "b", 1);
    flush();
    execute("UPDATE %s SET c2 = ? WHERE pk = ?", "c", 1);
    flush();
    UntypedResultSet resultSet = execute("SELECT pk FROM %s WHERE c1 = 'b' AND c2='c'");
    assertRows(resultSet, row(1));
}

@Test
public void splitRowsWithBooleanLogic() {
    createTable(KEYSPACE, "CREATE TABLE %s (pk int primary key, str_val text, val text)");
    createIndex("CREATE CUSTOM INDEX ON %s(str_val) USING 'StorageAttachedIndex'");
    createIndex("CREATE CUSTOM INDEX ON %s(val) USING 'StorageAttachedIndex'");
    disableCompaction(KEYSPACE);
    // flush a sstable with 2 partial rows
    execute("INSERT INTO %s (pk, str_val) VALUES (3, 'A')");
    execute("INSERT INTO %s (pk, val) VALUES (1, 'A')");
    flush();
    // flush another sstable with 2 more partial rows, where PK 3 is now a complete row
    execute("INSERT INTO %s (pk, val) VALUES (3, 'A')");
    execute("INSERT INTO %s (pk, str_val) VALUES (2, 'A')");
    flush();
    // pk 3 should match
    var result = execute("SELECT pk FROM %s WHERE str_val = 'A' AND val = 'A'");
    assertRows(result, row(3));
}

