/**
 * This test tries to induce rounding errors involving decimal values with wide significands.
 *
 * Two values are indexed:
 * <ul>
 * <li>1.0</li>
 * <li>1.(510 zeros)1</li>
 * </ul>
 */
@Test
public void runQueriesWithDecimalValueCollision() throws Throwable {
    final int significandSizeInDecimalDigits = 512;
    // String.repeat(int) exists in JDK 11 and later, but this line was introduced on JDK 8
    String wideDecimalString = "1." + StringUtils.repeat('0', significandSizeInDecimalDigits - 2) + '1';
    BigDecimal wideDecimal = new BigDecimal(wideDecimalString);
    // Sanity checks that this value was actually constructed as intended
    Preconditions.checkState(wideDecimal.precision() == significandSizeInDecimalDigits, "expected precision %s, but got %s; string representation is \"%s\"", significandSizeInDecimalDigits, wideDecimal.precision(), wideDecimalString);
    Preconditions.checkState(wideDecimalString.equals(wideDecimal.toPlainString()), "expected: %s; actual: %s", wideDecimalString, wideDecimal.toPlainString());
    execute("INSERT INTO %s (pk, ck, dec) VALUES (0, 1, 1.0)");
    execute("INSERT INTO %s (pk, ck, dec) VALUES (2, 0, " + wideDecimalString + ')');
    // EQ queries
    assertRows(execute("SELECT * FROM %s WHERE dec = 1.0"), row(0, 1, BigDecimal.valueOf(1.0D)));
    assertRows(execute("SELECT * FROM %s WHERE dec = " + wideDecimalString), row(2, 0, wideDecimal));
    // LT/LTE queries
    assertRows(execute("SELECT * FROM %s WHERE dec < " + wideDecimalString), row(0, 1, BigDecimal.valueOf(1.0D)));
    assertRowsIgnoringOrder(execute("SELECT * FROM %s WHERE dec <= " + wideDecimalString), row(0, 1, BigDecimal.valueOf(1.0D)), row(2, 0, wideDecimal));
    assertEmpty(execute("SELECT * FROM %s WHERE dec < 1.0"));
    assertRows(execute("SELECT * FROM %s WHERE dec <= 1.0"), row(0, 1, BigDecimal.valueOf(1.0D)));
    // GT/GTE queries
    assertRows(execute("SELECT * FROM %s WHERE dec > 1.0"), row(2, 0, wideDecimal));
    assertRowsIgnoringOrder(execute("SELECT * FROM %s WHERE dec >= " + wideDecimalString), row(2, 0, wideDecimal));
    assertEmpty(execute("SELECT * FROM %s WHERE dec > " + wideDecimalString));
    assertRowsIgnoringOrder(execute("SELECT * FROM %s WHERE dec >= 1.0"), row(0, 1, BigDecimal.valueOf(1.0D)), row(2, 0, wideDecimal));
}

/**
 * This is a control method with small (two-significant-digit) values.
