    assertRowsIgnoringOrder(execute("SELECT * FROM %s WHERE dec = 2.2"), row(-2, 1, BigDecimal.valueOf(2.2D)), row(-2, 2, BigDecimal.valueOf(2.2D)), row(2, 1, BigDecimal.valueOf(2.2D)), row(2, 2, BigDecimal.valueOf(2.2D)));
