@Test
@SuppressWarnings("BusyWait")
public void nodetoolStopInitialIndexBuild() throws Throwable {
    createTable(CREATE_TABLE_TEMPLATE);
    disableCompaction(KEYSPACE);
    // create 100 rows into 1 sstable
    int num = 100;
    int sstable = 1;
    for (int i = 0; i < num; i++) {
        execute("INSERT INTO %s (id1, v1, v2) VALUES ('" + i + "', 0, '0');");
    }
    flush();
    Injections.Barrier delayIndexBuilderCompletion = Injections.newBarrierAwait("delayIndexBuilder", 1, true).add(InvokePointBuilder.newInvokePoint().onClass(StorageAttachedIndexBuilder.class).onMethod("build")).build();
    Injections.inject(delayIndexBuilderCompletion);
    IndexIdentifier numericIndexIdentifier = createIndexIdentifier(createIndexAsync(String.format(CREATE_INDEX_TEMPLATE, "v1")));
    IndexTermType numericIndexTermType = createIndexTermType(Int32Type.instance);
    waitForAssert(() -> assertTrue(getCompactionTasks() > 0), 1000, TimeUnit.MILLISECONDS);
    // Stop initial index build by interrupting active and pending compactions
    int attempt = 20;
    while (getCompactionTasks() > 0 && attempt > 0) {
        System.out.println("Attempt " + attempt + " at stopping the compaction tasks");
        // only interrupts active compactions, not pending compactions.
        CompactionManager.instance.stopCompaction(OperationType.INDEX_BUILD.name());
        // let blocked builder to continue, but still block pending builder threads
        delayIndexBuilderCompletion.reset();
        Thread.sleep(3000);
        attempt--;
    }
    if (getCompactionTasks() > 0)
        fail("Compaction tasks are not interrupted.");
    delayIndexBuilderCompletion.disable();
    // initial index builder should have stopped abruptly resulting in the index not being queryable
    verifyInitialIndexFailed(numericIndexIdentifier.indexName);
    Assertions.assertThat(getNotQueryableIndexes()).isNotEmpty();
    ColumnFamilyStore cfs = Keyspace.open(KEYSPACE).getColumnFamilyStore(currentTable());
    for (Index i : cfs.indexManager.listIndexes()) {
        StorageAttachedIndex index = (StorageAttachedIndex) i;
        assertEquals(0, index.memtableIndexManager().size());
        View view = index.view();
        assertTrue("Expect index build stopped", view.getIndexes().isEmpty());
    }
    assertEquals("Segment memory limiter should revert to zero on interrupted compactions.", 0L, getSegmentBufferUsedBytes());
    assertEquals("There should be no segment builders in progress.", 0L, getColumnIndexBuildsInProgress());
    // rebuild index
    ColumnFamilyStore.rebuildSecondaryIndex(KEYSPACE, currentTable(), numericIndexIdentifier.indexName);
    verifyIndexFiles(numericIndexTermType, numericIndexIdentifier, sstable);
    ResultSet rows = executeNet("SELECT id1 FROM %s WHERE v1>=0");
    assertEquals(num, rows.all().size());
    assertEquals("Segment memory limiter should revert to zero following rebuild.", 0L, getSegmentBufferUsedBytes());
    assertEquals("There should be no segment builders in progress.", 0L, getColumnIndexBuildsInProgress());
    assertTrue(verifyChecksum(numericIndexTermType, numericIndexIdentifier));
}

@Test
public void shouldMarkQueryableInInitializationTask() throws Throwable {
    createTable(CREATE_TABLE_TEMPLATE);
    disableCompaction(KEYSPACE);
    IndexIdentifier idxIdentifier = createIndexIdentifier(createIndexAsync(String.format(CREATE_INDEX_TEMPLATE, "v1")));
    // create 10 SSTables
    for (int i = 0; i < 10; i++) {
        execute("INSERT INTO %s (id1, v1, v2) VALUES (?, ?, ?)", String.valueOf(i), i, String.valueOf(i));
        flush();
    }
    ResultSet rows = executeNet("SELECT id1 FROM %s WHERE v1 >= 5");
    assertEquals(5, rows.all().size());
    // Make the index artificially non-queryable:
    ColumnFamilyStore cfs = getCurrentColumnFamilyStore();
    Index index = cfs.indexManager.getIndexByName(idxIdentifier.indexName);
    cfs.indexManager.makeIndexNonQueryable(index, Index.Status.BUILD_FAILED);
    // Query should fail with the index in an artificially non-queryable state:
    assertThatThrownBy(() -> executeNet("SELECT id1 FROM %s WHERE v1 >= 5")).isInstanceOf(ReadFailureException.class);
    // Node must not yet be initialized for pre-emptive index validation to occur:
    StorageService.instance.unsafeSetUninitialized();
    // Simply getting the initialization task (and not running it) will validate and mark the index queryable again:
    cfs.indexManager.buildIndex(index);
    StorageService.instance.unsafeSetInitialized();
    rows = executeNet("SELECT id1 FROM %s WHERE v1 >= 5");
    assertEquals(5, rows.all().size());
}

