@Test
public void testAbortCompactionWithEarlyOpenSSTables() throws Throwable {
    createTable(CREATE_TABLE_TEMPLATE);
    IndexIdentifier numericIndexIdentifier = createIndexIdentifier(createIndex(String.format(CREATE_INDEX_TEMPLATE, "v1")));
    IndexIdentifier literalIndexIdentifier = createIndexIdentifier(createIndex(String.format(CREATE_INDEX_TEMPLATE, "v2")));
    int sstables = 2;
    int num = 10;
    for (int i = 0; i < num; i++) {
        if (i == num / sstables)
            flush();
        execute("INSERT INTO %s (id1, v1, v2) VALUES (?, 0, '0')", Integer.toString(i));
    }
    flush();
    // make sure early open is triggered
    Injections.Counter earlyOpenCounter = Injections.newCounter("early_open_counter").add(InvokePointBuilder.newInvokePoint().onClass(LifecycleTransaction.class).onMethod("checkpoint")).build();
    // abort compaction
    String errMessage = "Injected failure!";
    Injection failSSTableCompaction = Injections.newCustom("fail_sstable_compaction").add(InvokePointBuilder.newInvokePoint().onClass(SSTableWriter.class).onMethod("prepareToCommit")).add(ActionBuilder.newActionBuilder().actions().doThrow(RuntimeException.class, Expression.quote(errMessage))).build();
    try {
        Injections.inject(failSSTableCompaction, earlyOpenCounter);
        compact();
        fail("Expected compaction being interrupted");
    } catch (Throwable e) {
        while (e.getCause() != null) e = e.getCause();
        assertTrue(String.format("Expected %s, but got %s", errMessage, e.getMessage()), e.getMessage().contains(errMessage));
    } finally {
        earlyOpenCounter.disable();
        failSSTableCompaction.disable();
    }
    assertNotEquals(0, earlyOpenCounter.get());
    // verify indexes are working
    assertNumRows(num, "SELECT id1 FROM %%s WHERE v1=0");
    assertNumRows(num, "SELECT id1 FROM %%s WHERE v2='0'");
    verifySSTableIndexes(numericIndexIdentifier, sstables);
    verifySSTableIndexes(literalIndexIdentifier, sstables);
}

