@Test
public void testValidation() {
    // Iterators being merged via concatanation must not include each other
    assertThatThrownBy(() -> buildConcat(build(1L, 4L), build(2L, 3L))).isInstanceOf(IllegalArgumentException.class).hasMessage(createErrorMessage(4, 2));
    // Iterators being merged via concatanation must not overlap
    assertThatThrownBy(() -> buildConcat(build(1L, 4L), build(2L, 5L))).isInstanceOf(IllegalArgumentException.class).hasMessage(createErrorMessage(4, 2));
    assertThatThrownBy(() -> buildConcat(build(1L, 4L), build(0L, 3L))).isInstanceOf(IllegalArgumentException.class).hasMessage(createErrorMessage(4, 0));
    // Iterators being merged via concatanation must be sorted
    assertThatThrownBy(() -> buildConcat(build(2L, 4L), build(0L, 1L))).isInstanceOf(IllegalArgumentException.class).hasMessage(createErrorMessage(4, 0));
    // allow min boundary included
    KeyRangeIterator concat = buildConcat(build(1L, 4L), build(4L, 5L));
    assertEquals(convert(1L, 4L, 4L, 5L), convert(concat));
    // with empty iterator
    concat = buildConcat(build(), build(0L, 1L));
    assertEquals(convert(0L, 1L), convert(concat));
    concat = buildConcat(build(0L, 1L), build());
    assertEquals(convert(0L, 1L), convert(concat));
    concat = buildConcat(build(), build(0L, 1L), build());
    assertEquals(convert(0L, 1L), convert(concat));
    concat = buildConcat(build(), build(0L, 1L), build(), build(2L, 3L));
    assertEquals(convert(0L, 1L, 2L, 3L), convert(concat));
}

