@Test
public void testVirtualTableThroughIndexLifeCycle() throws Throwable {
    // create the table and verify that the virtual table is empty before creating any indexes
    assertEmpty(execute(SELECT));
    createTable("CREATE TABLE %s (k int, c int, v1 text, PRIMARY KEY (k, c))");
    // create the index simulating a long build and verify that there is an empty record in the virtual table
    Injections.inject(blockIndexBuild);
    String v1IndexName = createIndexAsync(String.format("CREATE CUSTOM INDEX ON %%s(v1) USING '%s'", StorageAttachedIndex.class.getName()));
    assertRows(execute(SELECT), row(v1IndexName, "v1", false, true, true));
    // unblock the long build and verify that there is a finished empty record in the virtual table
    blockIndexBuild.countDown();
    blockIndexBuild.disable();
    waitForTableIndexesQueryable();
    assertRows(execute(SELECT), row(v1IndexName, "v1", true, false, true));
    // insert some data and verify that virtual table record is still empty since we haven't flushed yet
    execute("INSERT INTO %s(k, c, v1) VALUES (?, ?, ?)", 1, 10, "1000");
    execute("INSERT INTO %s(k, c, v1) VALUES (?, ?, ?)", 2, 20, "2000");
    assertRows(execute(SELECT), row(v1IndexName, "v1", true, false, true));
    // flush the memtable and verify the not-empty record in the virtual table
    flush();
    assertRows(execute(SELECT), row(v1IndexName, "v1", true, false, true));
    // flush a second memtable and verify the updated record in the virtual table
    execute("INSERT INTO %s(k, c, v1) VALUES (?, ?, ?)", 3, 30, "3000");
    flush();
    assertRows(execute(SELECT), row(v1IndexName, "v1", true, false, true));
    // compact and verify that the cell count decreases
    compact();
    waitForCompactionsFinished();
    assertRowsIgnoringOrderAndExtra(execute(SELECT), row(v1IndexName, "v1", true, false, true));
    // truncate the base table and verify that there is still an entry in the virtual table, and it's empty
    truncate(false);
    assertRowsIgnoringOrderAndExtra(execute(SELECT), row(v1IndexName, "v1", true, false, true));
    // drop the base table and verify that the virtual table is empty
    dropTable("DROP TABLE %s");
    assertEmpty(execute(SELECT));
}

@Test
public void testSegmentsMetadata() throws Throwable {
    createTable("CREATE TABLE %s (k int, c int, v1 text, PRIMARY KEY (k, c))");
    String literalIndex = createIndex("CREATE CUSTOM INDEX ON %s(v1) USING 'StorageAttachedIndex'");
    int num = 100;
    String insert = "INSERT INTO %s(k, c, v1) VALUES (?, ?, ?)";
    // the virtual table should be empty before adding contents
    assertEmpty(execute(SELECT, literalIndex));
    // insert rows and verify that the virtual table is empty before flushing
    for (int i = 0; i < num / 2; i++) execute(insert, i, 10, "1000");
    assertEmpty(execute(SELECT, literalIndex));
    // flush the memtable and verify the new record in the virtual table
    flush();
    Object[] row1 = row(0L, (long) (num / 2), 0L, (long) (num / 2 - 1));
    assertRows(execute(SELECT, literalIndex), row1);
    // flush a second memtable and verify both the old and the new record in the virtual table
    for (int i = num / 2; i < num; i++) execute(insert, i, 20, "2000");
    flush();
    Object[] row2 = row(0L, (long) (num / 2), 0L, (long) (num / 2 - 1));
    assertRows(execute(SELECT, literalIndex), row1, row2);
    // force compaction, there is only 1 sstable
    compact();
    waitForCompactions();
    Object[] row3 = row(0L, (long) num, 0L, (long) (num - 1));
    assertRows(execute(SELECT, literalIndex), row3);
    for (int lastValidSegmentRowId : Arrays.asList(0, 1, 2, 3, 5, 9, 25, 49, 59, 99, 101)) {
        SegmentBuilder.updateLastValidSegmentRowId(lastValidSegmentRowId);
        // compaction to rewrite segments
        StorageService.instance.upgradeSSTables(KEYSPACE, false, currentTable());
        List<Object[]> segmentRows = new ArrayList<>();
        for (int row = 0; row < num / (lastValidSegmentRowId + 1); row++) segmentRows.add(row((long) (row * (lastValidSegmentRowId + 1)), (long) (lastValidSegmentRowId + 1), (long) (row * (lastValidSegmentRowId + 1)), (long) (row * (lastValidSegmentRowId + 1) + lastValidSegmentRowId)));
        long prevMaxSSTableRowId = segmentRows.isEmpty() ? -1L : (long) segmentRows.get(segmentRows.size() - 1)[3];
        if (prevMaxSSTableRowId < 99L) {
            segmentRows.add(row(prevMaxSSTableRowId + 1, 99 - prevMaxSSTableRowId, prevMaxSSTableRowId + 1, 99L));
        }
        UntypedResultSet resultSet = execute(SELECT, literalIndex);
        assertRows(execute(SELECT, literalIndex), segmentRows.toArray(new Object[][] {}));
        // verify index metadata length
        Map<String, Long> indexLengths = new HashMap<>();
        for (UntypedResultSet.Row row : execute(SELECT_INDEX_METADATA)) {
            int minTerm = Integer.parseInt(row.getString(SegmentsSystemView.MIN_TERM));
            int maxTerm = Integer.parseInt(row.getString(SegmentsSystemView.MAX_TERM));
            assertTrue(minTerm >= 100);
            assertTrue(maxTerm <= 2000);
            Map<String, Map<String, String>> indexMetadatas = row.getMap(SegmentsSystemView.COMPONENT_METADATA, UTF8Type.instance, MapType.getInstance(UTF8Type.instance, UTF8Type.instance, true));
            for (Map.Entry<String, Map<String, String>> entry : indexMetadatas.entrySet()) {
                final String indexType = entry.getKey();
                final String str = entry.getValue().getOrDefault(SegmentMetadata.ComponentMetadata.LENGTH, "0");
                final long length = Long.parseLong(str);
                final long value = indexLengths.getOrDefault(indexType, 0L);
                indexLengths.put(indexType, value + length);
            }
        }
        if (!TEST_ENCRYPTION.getBoolean())
            assertEquals(indexFileLengths(), indexLengths);
    }
    // drop the numeric index and verify that there are not entries for it in the table
    assertNotEquals(0, execute(SELECT, literalIndex).size());
    // drop the string index and verify that there are not entries for it in the table
    dropIndex("DROP INDEX %s." + literalIndex);
    assertEmpty(execute(SELECT, literalIndex));
}

@Test
public void testVirtualTableThroughIndexLifeCycle() throws Throwable {
    createTable("CREATE TABLE %s (k text, c text, v1 text, v2 text, PRIMARY KEY (k, c))");
    disableCompaction();
    String v1IndexName = createIndex("CREATE INDEX ON %s(v1) USING 'sai'");
    String insert = "INSERT INTO %s(k, c, v1, v2) VALUES (?, ?, ?, ?)";
    // the virtual table should be empty before adding contents
    assertEmpty(execute(SELECT));
    // insert a row and verify that the virtual table is empty before flushing
    execute(insert, "1", "10", "100", "1000");
    assertEmpty(execute(SELECT));
    // flush the memtable and verify the new record in the virtual table
    flush();
    SSTableId id1 = currentIdsSorted()[0];
    Object[] row1 = readRow(v1IndexName, id1, "v1", 1L, 0L, 0L);
    assertRowsIgnoringOrder(execute(SELECT), row1);
    // flush a second memtable and verify both the old and the new record in the virtual table
    execute(insert, "2", "20", "200", "2000");
    execute(insert, "3", "30", "300", "3000");
    flush();
    SSTableId id2 = currentIdsSorted()[1];
    Object[] row2 = readRow(v1IndexName, id2, "v1", 2L, 0L, 1L);
    assertRowsIgnoringOrder(execute(SELECT), row1, row2);
    // create a second index, this should create a new additional entry in the table for each sstable
    String v2IndexName = createIndex("CREATE INDEX ON %s(v2) USING 'sai'");
    Object[] row3 = readRow(v2IndexName, id1, "v2", 1L, 0L, 0L);
    Object[] row4 = readRow(v2IndexName, id2, "v2", 2L, 0L, 1L);
    assertRowsIgnoringOrder(execute(SELECT), row1, row2, row3, row4);
    // create a new sstable that only contains data for the second index, this should add only one new entry
    execute(insert, "4", "40", null, "4000");
    flush();
    SSTableId id3 = currentIdsSorted()[2];
    Object[] row5 = readRow(v2IndexName, id3, "v2", 1L, 0L, 0L);
    assertRowsIgnoringOrder(execute(SELECT), row1, row2, row3, row4, row5);
    // create a new sstable with rows with contents for either one of the indexes or the other
    execute(insert, "5", "50", "500", null);
    execute(insert, "6", "60", null, "6000");
    flush();
    SSTableId id4 = currentIdsSorted()[3];
    Object[] row6 = readRow(v1IndexName, id4, "v1", 1L, 1L, 1L);
    Object[] row7 = readRow(v2IndexName, id4, "v2", 1L, 0L, 0L);
    assertRowsIgnoringOrder(execute(SELECT), row1, row2, row6, row3, row4, row5, row7);
    // compact the table and verify that the virtual table has a single entry per index
    ColumnFamilyStore cfs = getCurrentColumnFamilyStore();
    Util.compact(cfs, Iterables.toList(cfs.getSSTables(SSTableSet.LIVE)));
    waitForCompactions();
    SSTableId[] ids5 = currentIdsSorted();
    // Compaction may result in sstables with generation 5 or 6. Try both.
    // key 4, key 6 are not indexable on v1
    Object[] row8 = readRow(v1IndexName, ids5, "v1", 4L, 2L, 5L);
    // key 5 is not indexable on v2
    Object[] row9 = readRow(v2IndexName, ids5, "v2", 5L, 0L, 5L);
    assertRowsIgnoringOrder(execute(SELECT), row8, row9);
    // drop the first index and verify that there are not entries for it in the table
    dropIndex("DROP INDEX %s." + v1IndexName);
    assertRowsIgnoringOrder(execute(SELECT), row9);
    // drop the base table and verify that the virtual table is empty
    dropTable("DROP TABLE %s");
    assertEmpty(execute(SELECT));
}

