@Test
public void testConstrainedIteration() throws IOException {
    // This is not too relevant: due to the way we construct separators we can't be good enough on the left side.
    Pair<List<ClusteringPrefix<?>>, RowIndexReader> random = generateRandomIndexSingletons(COUNT);
    List<ClusteringPrefix<?>> keys = random.left;
    for (int i = 0; i < 500; ++i) {
        boolean exactLeft = RANDOM.nextBoolean();
        boolean exactRight = RANDOM.nextBoolean();
        ClusteringPrefix<?> left = exactLeft ? keys.get(RANDOM.nextInt(keys.size())) : generateRandomKey();
        ClusteringPrefix<?> right = exactRight ? keys.get(RANDOM.nextInt(keys.size())) : generateRandomKey();
        if (comparator.compare(right, left) < 0) {
            ClusteringPrefix<?> t = left;
            left = right;
            right = t;
            boolean b = exactLeft;
            exactLeft = exactRight;
            exactRight = b;
        }
        try (RowIndexReverseIterator iter = new RowIndexReverseIterator(fh, root, comparator.asByteComparable(left), comparator.asByteComparable(right), random.right.version)) {
            IndexInfo indexInfo = iter.nextIndexInfo();
            if (indexInfo == null) {
                int idx = Collections.binarySearch(keys, right, comparator);
                if (idx < 0)
                    // less than or equal
                    idx = -2 - idx;
                if (idx <= 0)
                    continue;
                assertTrue(comparator.asByteComparable(left) + " <= " + comparator.asByteComparable(keys.get(idx)) + " <= " + comparator.asByteComparable(right) + " but " + idx + " wasn't iterated.", comparator.compare(left, keys.get(idx - 1)) > 0);
                continue;
            }
            int idx = (int) indexInfo.offset;
            if (indexInfo.offset == END_MARKER)
                idx = keys.size();
            if (idx > 0)
                assertTrue(comparator.compare(right, keys.get(idx - 1)) > 0);
            if (idx < keys.size() - 1)
                assertTrue(comparator.compare(right, keys.get(idx + 1)) < 0);
            if (// must be precise on exact, otherwise could be in any relation
            exactRight)
                assertEquals(right, keys.get(idx));
            while (true) {
                --idx;
                IndexInfo ii = iter.nextIndexInfo();
                if (ii == null)
                    break;
                assertEquals(idx, (int) ii.offset);
            }
            // seek at last returned
            ++idx;
            if (idx < keys.size() - 1)
                assertTrue(comparator.compare(left, keys.get(idx + 1)) < 0);
            // Because of the way we build the index (using non-prefix separator) we are usually going to miss the last item.
            if (idx >= 2)
                assertTrue(comparator.compare(left, keys.get(idx - 2)) > 0);
        } catch (AssertionError e) {
            logger.error(e.getMessage(), e);
            ClusteringPrefix<?> ll = left;
            ClusteringPrefix<?> rr = right;
            logger.info(keys.stream().filter(x -> comparator.compare(ll, x) <= 0 && comparator.compare(x, rr) <= 0).map(clustering -> comparator.asByteComparable(clustering)).map(bc -> bc.byteComparableAsString(VERSION)).collect(Collectors.joining(", ")));
            logger.info("Left {}{} Right {}{}", comparator.asByteComparable(left), exactLeft ? "#" : "", comparator.asByteComparable(right), exactRight ? "#" : "");
            try (RowIndexReverseIterator iter2 = new RowIndexReverseIterator(fh, root, comparator.asByteComparable(left), comparator.asByteComparable(right), version)) {
                IndexInfo ii;
                while ((ii = iter2.nextIndexInfo()) != null) {
                    logger.info(comparator.asByteComparable(keys.get((int) ii.offset)).toString());
                }
                logger.info("Left {}{} Right {}{}", comparator.asByteComparable(left), exactLeft ? "#" : "", comparator.asByteComparable(right), exactRight ? "#" : "");
            }
            throw e;
        }
    }
}

@Test
public void testReverseIteration() throws IOException {
    Pair<List<ClusteringPrefix<?>>, RowIndexReader> random = generateRandomIndexSingletons(COUNT);
    List<ClusteringPrefix<?>> keys = random.left;
    for (int i = 0; i < 1000; ++i) {
        boolean exactRight = RANDOM.nextBoolean();
        ClusteringPrefix<?> right = exactRight ? keys.get(RANDOM.nextInt(keys.size())) : generateRandomKey();
        int idx = 0;
        try (RowIndexReverseIterator iter = new RowIndexReverseIterator(fh, root, ByteComparable.EMPTY, comparator.asByteComparable(right), random.right.version)) {
            IndexInfo indexInfo = iter.nextIndexInfo();
            if (indexInfo == null) {
                idx = Collections.binarySearch(keys, right, comparator);
                if (idx < 0)
                    // less than or equal
                    idx = -2 - idx;
                assertTrue(comparator.asByteComparable(keys.get(idx)) + " <= " + comparator.asByteComparable(right) + " but " + idx + " wasn't iterated.", idx < 0);
                continue;
            }
            idx = (int) indexInfo.offset;
            if (indexInfo.offset == END_MARKER)
                idx = keys.size();
            if (idx > 0)
                assertTrue(comparator.compare(right, keys.get(idx - 1)) > 0);
            if (idx < keys.size() - 1)
                assertTrue(comparator.compare(right, keys.get(idx + 1)) < 0);
            if (// must be precise on exact, otherwise could be in any relation
            exactRight)
                assertEquals(right, keys.get(idx));
            while (true) {
                --idx;
                IndexInfo ii = iter.nextIndexInfo();
                if (ii == null)
                    break;
                assertEquals(idx, (int) ii.offset);
            }
            assertEquals(-1, idx);
        } catch (AssertionError e) {
            logger.error(e.getMessage(), e);
            ClusteringPrefix<?> rr = right;
            logger.info(keys.stream().filter(x -> comparator.compare(x, rr) <= 0).map(comparator::asByteComparable).map(bc -> bc.byteComparableAsString(VERSION)).collect(Collectors.joining(", ")));
            logger.info("Right {}{}", comparator.asByteComparable(right), exactRight ? "#" : "");
            try (RowIndexReverseIterator iter2 = new RowIndexReverseIterator(fh, root, ByteComparable.EMPTY, comparator.asByteComparable(right), version)) {
                IndexInfo ii;
                while ((ii = iter2.nextIndexInfo()) != null) {
                    logger.info(comparator.asByteComparable(keys.get((int) ii.offset)).toString());
                }
            }
            logger.info("Right {}{}", comparator.asByteComparable(right), exactRight ? "#" : "");
            throw e;
        }
    }
}

@Test
@BMRules(rules = { @BMRule(name = "force_add_index_block_after_range_tombstone_boundary_marker_big", targetClass = "org.apache.cassandra.io.sstable.format.big.BigFormatPartitionWriter", targetMethod = "addUnfiltered", targetLocation = "AT EXIT", condition = "$1 instanceof org.apache.cassandra.db.rows.RangeTombstoneBoundaryMarker", action = "$this.addIndexBlock()"), @BMRule(name = "force_add_index_block_after_range_tombstone_boundary_marker_bti", targetClass = "org.apache.cassandra.io.sstable.format.bti.BtiFormatPartitionWriter", targetMethod = "addUnfiltered", targetLocation = "AT EXIT", condition = "$1 instanceof org.apache.cassandra.db.rows.RangeTombstoneBoundaryMarker", action = "$this.addIndexBlock()") })
public void testBoundaryMarkerAtTheEndOfIndexBlock() throws Throwable {
    int expectedRows = 10;
    IntFunction<String> fmt = (i) -> String.format("%05d", i);
    createTable("CREATE TABLE %s (k int, c int, v text, PRIMARY KEY (k, c)) WITH CLUSTERING ORDER BY (c ASC)");
    for (int i = 0; i < expectedRows; i++) {
        // delete (0; 1] and then insert 1 will make a range tombstone boundary marker (0; 0]
        execute("DELETE FROM %s WHERE k = ? AND c > ? AND c <= ?", 0, i - 1, i);
        execute("INSERT INTO %s (k, c, v) VALUES (?, ?, ?)", 0, i, fmt.apply(i));
    }
    flush();
    ResultSet r = executeNetWithPaging("SELECT * FROM %s", 1);
    Iterator<Row> iter = r.iterator();
    int n = 0;
    while (iter.hasNext()) {
        Row row = iter.next();
        int c = row.getInt("c");
        String v = row.getString("v");
        logger.info("Read row: " + row);
        assertThat(v).isEqualTo(fmt.apply(c));
        n++;
    }
    assertThat(n).isEqualTo(expectedRows);
}

