@Test
public void testGenerateSstables() throws Throwable {
    SSTableFormat<?, ?> format = DatabaseDescriptor.getSelectedSSTableFormat();
    Random rand = new Random();
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < 128; i++) {
        sb.append((char) ('a' + rand.nextInt(26)));
    }
    String randomString = sb.toString();
    for (int pk = 0; pk < 5; pk++) {
        String valPk = Integer.toString(pk);
        QueryProcessor.executeInternal(String.format("INSERT INTO legacy_tables.legacy_%s_simple (pk, val) VALUES ('%s', '%s')", format.getLatestVersion(), valPk, "foo bar baz"));
        QueryProcessor.executeInternal(String.format("UPDATE legacy_tables.legacy_%s_simple_counter SET val = val + 1 WHERE pk = '%s'", format.getLatestVersion(), valPk));
        QueryProcessor.executeInternal(String.format("INSERT INTO legacy_tables.legacy_%s_tuple (pk, val, val2, val3, val4, extra)" + " VALUES ('%s', ({1,2,3},{'a','b','c'}), ({1,2,3},{'a','b','c'}), {name: ('abc','def')}, {name: ('abc','def')}, '%s')", format.getLatestVersion(), valPk, randomString));
        for (int ck = 0; ck < 50; ck++) {
            String valCk = Integer.toString(ck);
            QueryProcessor.executeInternal(String.format("INSERT INTO legacy_tables.legacy_%s_clust (pk, ck, val) VALUES ('%s', '%s', '%s')", format.getLatestVersion(), valPk, valCk + longString, randomString));
            QueryProcessor.executeInternal(String.format("UPDATE legacy_tables.legacy_%s_clust_counter SET val = val + 1 WHERE pk = '%s' AND ck='%s'", format.getLatestVersion(), valPk, valCk + longString));
            // note: to emulate BE for offsets in Summary you can comment temporary the following line:
            // offset = Integer.reverseBytes(offset);
            // in org.apache.cassandra.io.sstable.indexsummary.IndexSummary.IndexSummarySerializer.serialize
            QueryProcessor.executeInternal(String.format("INSERT INTO legacy_tables.legacy_%s_clust_be_index_summary (pk, ck, val) VALUES ('%s', '%s', '%s')", format.getLatestVersion(), valPk, valCk + longString, randomString));
        }
    }
    StorageService.instance.forceKeyspaceFlush(LEGACY_TABLES_KEYSPACE, ColumnFamilyStore.FlushReason.UNIT_TESTS);
    File ksDir = new File(LEGACY_SSTABLE_ROOT, String.format("%s/legacy_tables", format.getLatestVersion()));
    ksDir.tryCreateDirectories();
    copySstablesFromTestData(format.getLatestVersion(), "legacy_%s_simple", ksDir);
    copySstablesFromTestData(format.getLatestVersion(), "legacy_%s_simple_counter", ksDir);
    copySstablesFromTestData(format.getLatestVersion(), "legacy_%s_clust", ksDir);
    copySstablesFromTestData(format.getLatestVersion(), "legacy_%s_clust_counter", ksDir);
    copySstablesFromTestData(format.getLatestVersion(), "legacy_%s_tuple", ksDir);
    copySstablesFromTestData(format.getLatestVersion(), "legacy_%s_clust_be_index_summary", ksDir);
}

@Test
public void testSerialization() throws IOException {
    Map<MetadataType, MetadataComponent> originalMetadata = constructMetadata(false);
    MetadataSerializer serializer = new MetadataSerializer();
    Version latestVersion = DatabaseDescriptor.getSelectedSSTableFormat().getLatestVersion();
    File statsFile = serialize(originalMetadata, serializer, DatabaseDescriptor.getSelectedSSTableFormat().getLatestVersion());
    Descriptor desc = new Descriptor(statsFile.parent(), "", "", new SequenceBasedSSTableId(0), DatabaseDescriptor.getSelectedSSTableFormat());
    try (RandomAccessReader in = RandomAccessReader.open(statsFile)) {
        Map<MetadataType, MetadataComponent> deserialized = serializer.deserialize(desc, in, EnumSet.allOf(MetadataType.class));
        for (MetadataType type : MetadataType.values()) {
            if ((type != MetadataType.STATS) || latestVersion.hasImprovedMinMax())
                assertEquals(originalMetadata.get(type), deserialized.get(type));
        }
    }
}

@Test
public void testHistogramSterilization() throws IOException {
    Map<MetadataType, MetadataComponent> originalMetadata = constructMetadata(false);
    // Modify the histograms to overflow:
    StatsMetadata originalStats = (StatsMetadata) originalMetadata.get(MetadataType.STATS);
    originalStats.estimatedCellPerPartitionCount.add(Long.MAX_VALUE);
    originalStats.estimatedPartitionSize.add(Long.MAX_VALUE);
    assertTrue(originalStats.estimatedCellPerPartitionCount.isOverflowed());
    assertTrue(originalStats.estimatedPartitionSize.isOverflowed());
    // Serialize w/ overflowed histograms:
    MetadataSerializer serializer = new MetadataSerializer();
    File statsFile = serialize(originalMetadata, serializer, format.getLatestVersion());
    Descriptor desc = new Descriptor(statsFile.parent(), "", "", new SequenceBasedSSTableId(0), format);
    try (RandomAccessReader in = RandomAccessReader.open(statsFile)) {
        // Deserialie and verify that the two histograms have had their overflow buckets cleared:
        Map<MetadataType, MetadataComponent> deserialized = serializer.deserialize(desc, in, EnumSet.allOf(MetadataType.class));
        StatsMetadata deserializedStats = (StatsMetadata) deserialized.get(MetadataType.STATS);
        assertFalse(deserializedStats.estimatedCellPerPartitionCount.isOverflowed());
        assertFalse(deserializedStats.estimatedPartitionSize.isOverflowed());
    }
}

@Test
public void testMinorVersionsCompatibilty() throws Throwable {
    Map<Character, List<String>> supportedVersions = new LinkedHashMap<>();
    for (char major = 'a'; major <= 'z'; major++) {
        for (char minor = 'a'; minor <= 'z'; minor++) {
            Version version = format.getVersion(String.format("%s%s", major, minor));
            if (version.isCompatible())
                supportedVersions.computeIfAbsent(major, ignored -> new ArrayList<>()).add(version.version);
        }
    }
    for (List<String> minorVersions : supportedVersions.values()) testVersions(minorVersions);
}

