@Test
public void testFlushObserver() throws Exception {
    try (LifecycleTransaction transaction = LifecycleTransaction.offline(OperationType.COMPACTION)) {
        FlushObserver observer = new FlushObserver();
        Descriptor descriptor = new Descriptor(sstableFormat.getLatestVersion(), directory, cfm.keyspace, cfm.name, idGen.get());
        Index.Group indexGroup = mock(Index.Group.class);
        when(indexGroup.getFlushObserver(any(), any(), any())).thenReturn(observer);
        SSTableWriter.Builder<?, ?> writerBuilder = descriptor.getFormat().getWriterFactory().builder(descriptor).setKeyCount(10).setTableMetadataRef(TableMetadataRef.forOfflineTools(cfm)).setMetadataCollector(new MetadataCollector(cfm.comparator).sstableLevel(0)).setSerializationHeader(new SerializationHeader(true, cfm, cfm.regularAndStaticColumns(), EncodingStats.NO_STATS)).setSecondaryIndexGroups(Collections.singleton(indexGroup)).addDefaultComponents(Collections.emptySet());
        assertThat(observer.beginCalled).isFalse();
        assertThat(observer.isComplete).isFalse();
        SSTableWriter writer = writerBuilder.build(transaction, null);
        assertThat(observer.beginCalled).isTrue();
        assertThat(observer.isComplete).isFalse();
        SSTableReader reader;
        Multimap<ByteBuffer, Cell<?>> expected = ArrayListMultimap.create();
        try {
            final long now = System.currentTimeMillis();
            ByteBuffer key = UTF8Type.instance.fromString("key1");
            expected.putAll(key, Arrays.asList(BufferCell.live(getColumn(cfm, "age"), now, Int32Type.instance.decompose(27)), BufferCell.live(getColumn(cfm, "first_name"), now, UTF8Type.instance.fromString("jack")), BufferCell.live(getColumn(cfm, "height"), now, LongType.instance.decompose(183L))));
            writer.append(new RowIterator(cfm, key.duplicate(), Collections.singletonList(buildRow(expected.get(key)))));
            key = UTF8Type.instance.fromString("key2");
            expected.putAll(key, Arrays.asList(BufferCell.live(getColumn(cfm, "age"), now, Int32Type.instance.decompose(30)), BufferCell.live(getColumn(cfm, "first_name"), now, UTF8Type.instance.fromString("jim")), BufferCell.live(getColumn(cfm, "height"), now, LongType.instance.decompose(180L))));
            writer.append(new RowIterator(cfm, key, Collections.singletonList(buildRow(expected.get(key)))));
            key = UTF8Type.instance.fromString("key3");
            expected.putAll(key, Arrays.asList(BufferCell.live(getColumn(cfm, "age"), now, Int32Type.instance.decompose(30)), BufferCell.live(getColumn(cfm, "first_name"), now, UTF8Type.instance.fromString("ken")), BufferCell.live(getColumn(cfm, "height"), now, LongType.instance.decompose(178L))));
            writer.append(new RowIterator(cfm, key, Collections.singletonList(buildRow(expected.get(key)))));
            writer.onSSTableWriterSwitched();
            reader = writer.finish(true);
        } finally {
            FileUtils.closeQuietly(writer);
        }
        Assert.assertTrue(observer.isWriterSwitched);
        Assert.assertTrue(observer.isComplete);
        Assert.assertEquals(expected.size(), observer.rows.size());
        for (Triple<ByteBuffer, Long, Long> e : observer.rows.keySet()) {
            ByteBuffer key = e.getLeft();
            long indexPosition = e.getRight();
            DecoratedKey indexKey = reader.keyAtPositionFromSecondaryIndex(indexPosition);
            Assert.assertEquals(0, UTF8Type.instance.compare(key, indexKey.getKey()));
            Assert.assertEquals(expected.get(key), observer.rows.get(e));
        }
    }
}

@Test
public void testFailedInitialization() throws Exception {
    try (LifecycleTransaction transaction = LifecycleTransaction.offline(OperationType.COMPACTION)) {
        FlushObserver observer1 = new FlushObserver();
        FlushObserver observer2 = new FlushObserver();
        Index.Group indexGroup1 = mock(Index.Group.class);
        Index.Group indexGroup2 = mock(Index.Group.class);
        when(indexGroup1.getFlushObserver(any(), any(), any())).thenReturn(observer1);
        when(indexGroup2.getFlushObserver(any(), any(), any())).thenReturn(observer2);
        observer2.failOnBegin = true;
        Descriptor descriptor = new Descriptor(sstableFormat.getLatestVersion(), directory, cfm.keyspace, cfm.name, idGen.get());
        assertThatRuntimeException().isThrownBy(() -> descriptor.getFormat().getWriterFactory().builder(descriptor).setKeyCount(10).setTableMetadataRef(TableMetadataRef.forOfflineTools(cfm)).setMetadataCollector(new MetadataCollector(cfm.comparator).sstableLevel(0)).setSerializationHeader(new SerializationHeader(true, cfm, cfm.regularAndStaticColumns(), EncodingStats.NO_STATS)).setSecondaryIndexGroups(List.of(indexGroup1, indexGroup2)).addDefaultComponents(Collections.emptySet()).build(transaction, null)).withMessage("Failed to initialize");
        assertThat(observer1.beginCalled).isTrue();
        assertThat(observer1.isComplete).isFalse();
