@BMRule(name = "fail_on_deserialize", targetClass = "org.apache.cassandra.streaming.StreamSession", targetMethod = "messageReceived", targetLocation = "AT ENTRY", action = "throw new RuntimeException();")
public void testLoadingSSTableFail() throws Exception {
    // This test verifies that all references are closed if the sstable loading fails for some reason on the server
    // side. This is done by throwing an exception in StreamSession.messageReceived() which is called when the
    // server receives a stream message from the client. After completion, we check that all references are closed.
    Rule.disableTriggers();
    File dataDir = dataDir(CF_STANDARD1);
    TableMetadata metadata = Schema.instance.getTableMetadata(KEYSPACE1, CF_STANDARD1);
    try (CQLSSTableWriter writer = CQLSSTableWriter.builder().inDirectory(dataDir).forTable(String.format(schema, KEYSPACE1, CF_STANDARD1)).using(String.format(query, KEYSPACE1, CF_STANDARD1)).build()) {
        writer.addRow("key1", "col1", "100");
    }
    ColumnFamilyStore cfs = Keyspace.open(KEYSPACE1).getColumnFamilyStore(CF_STANDARD1);
    // wait for sstables to be on disk else we won't be able to stream them
    Util.flush(cfs);
    final CountDownLatch latch = new CountDownLatch(1);
    Rule.enableTriggers();
    SSTableLoader loader = new SSTableLoader(dataDir, new TestClient(), new OutputHandler.SystemOutput(false, false));
    AsyncFuture<StreamState> result = loader.stream(Collections.emptySet(), completionStreamListener(latch)).await();
    assertThat(result.isSuccess()).isFalse();
    checkAllRefsAreClosed(loader);
}

@Test
public void testTrackMaxDeletionTime() {
    Keyspace keyspace = Keyspace.open(KEYSPACE1);
    ColumnFamilyStore store = keyspace.getColumnFamilyStore("Standard1");
    long timestamp = System.currentTimeMillis();
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) new RowUpdateBuilder(store.metadata(), timestamp, 10 + j, Integer.toString(i)).clustering(Integer.toString(j)).add("val", ByteBufferUtil.EMPTY_BYTE_BUFFER).build().applyUnsafe();
    }
    new RowUpdateBuilder(store.metadata(), timestamp, 10000, "longttl").clustering("col").add("val", ByteBufferUtil.EMPTY_BYTE_BUFFER).build().applyUnsafe();
    Util.flush(store);
    assertEquals(1, store.getLiveSSTables().size());
    int ttltimestamp = (int) (System.currentTimeMillis() / 1000);
    long firstDelTime = 0;
    for (SSTableReader sstable : store.getLiveSSTables()) {
        firstDelTime = sstable.getMaxLocalDeletionTime();
        assertEquals(ttltimestamp + 10000, firstDelTime, DELTA);
    }
    new RowUpdateBuilder(store.metadata(), timestamp, 20000, "longttl2").clustering("col").add("val", ByteBufferUtil.EMPTY_BYTE_BUFFER).build().applyUnsafe();
    ttltimestamp = (int) (System.currentTimeMillis() / 1000);
    Util.flush(store);
    assertEquals(2, store.getLiveSSTables().size());
    List<SSTableReader> sstables = new ArrayList<>(store.getLiveSSTables());
    if (sstables.get(0).getMaxLocalDeletionTime() < sstables.get(1).getMaxLocalDeletionTime()) {
        assertEquals(sstables.get(0).getMaxLocalDeletionTime(), firstDelTime);
        assertEquals(sstables.get(1).getMaxLocalDeletionTime(), ttltimestamp + 20000, DELTA);
    } else {
        assertEquals(sstables.get(1).getMaxLocalDeletionTime(), firstDelTime);
        assertEquals(sstables.get(0).getMaxLocalDeletionTime(), ttltimestamp + 20000, DELTA);
    }
    Util.compact(store, store.getLiveSSTables());
    assertEquals(1, store.getLiveSSTables().size());
    for (SSTableReader sstable : store.getLiveSSTables()) {
        assertEquals(sstable.getMaxLocalDeletionTime(), ttltimestamp + 20000, DELTA);
    }
}

/**
 * 1. create a row with columns with ttls, 5x100 and 1x1000
 * 2. flush, verify (maxLocalDeletionTime = time+1000)
 * 3. delete column with ttl=1000
 * 4. flush, verify the new sstable (maxLocalDeletionTime = ~now)
 * 5. compact
 * 6. verify resulting sstable has maxLocalDeletionTime = time + 100.
 */
@Test
public void testWithDeletes() {
    Keyspace keyspace = Keyspace.open(KEYSPACE1);
    ColumnFamilyStore store = keyspace.getColumnFamilyStore("Standard2");
    long timestamp = System.currentTimeMillis();
    for (int i = 0; i < 5; i++) new RowUpdateBuilder(store.metadata(), timestamp, 100, "deletetest").clustering("deletecolumn" + i).add("val", ByteBufferUtil.EMPTY_BYTE_BUFFER).build().applyUnsafe();
    new RowUpdateBuilder(store.metadata(), timestamp, 1000, "deletetest").clustering("todelete").add("val", ByteBufferUtil.EMPTY_BYTE_BUFFER).build().applyUnsafe();
    Util.flush(store);
    assertEquals(1, store.getLiveSSTables().size());
    int ttltimestamp = (int) (System.currentTimeMillis() / 1000);
    long firstMaxDelTime = 0;
    for (SSTableReader sstable : store.getLiveSSTables()) {
        firstMaxDelTime = sstable.getMaxLocalDeletionTime();
        assertEquals(ttltimestamp + 1000, firstMaxDelTime, DELTA);
    }
    RowUpdateBuilder.deleteRow(store.metadata(), timestamp + 1, "deletetest", "todelete").applyUnsafe();
    Util.flush(store);
    assertEquals(2, store.getLiveSSTables().size());
    boolean foundDelete = false;
    for (SSTableReader sstable : store.getLiveSSTables()) {
        if (sstable.getMaxLocalDeletionTime() != firstMaxDelTime) {
            assertEquals(sstable.getMaxLocalDeletionTime(), ttltimestamp, DELTA);
            foundDelete = true;
        }
    }
    assertTrue(foundDelete);
    Util.compact(store, store.getLiveSSTables());
    assertEquals(1, store.getLiveSSTables().size());
    for (SSTableReader sstable : store.getLiveSSTables()) {
        assertEquals(ttltimestamp + 100, sstable.getMaxLocalDeletionTime(), DELTA);
    }
}

