@Test
public void testGetPositionsForRanges() {
    ColumnFamilyStore store = discardSSTables(KEYSPACE1, CF_STANDARD2);
    partitioner = store.getPartitioner();
    // insert data and compact to a single sstable
    for (int j = 0; j < 10; j++) {
        new RowUpdateBuilder(store.metadata(), j, String.valueOf(j)).clustering("0").add("val", ByteBufferUtil.EMPTY_BYTE_BUFFER).build().applyUnsafe();
    }
    Util.flush(store);
    CompactionManager.instance.performMaximal(store);
    List<Range<Token>> ranges = new ArrayList<>();
    // 1 key
    ranges.add(new Range<>(t(0), t(1)));
    // 2 keys
    ranges.add(new Range<>(t(2), t(4)));
    // wrapping range from key to end
    ranges.add(new Range<>(t(6), partitioner.getMinimumToken()));
    // empty range (should be ignored)
    ranges.add(new Range<>(t(9), t(91)));
    // confirm that positions increase continuously
    SSTableReader sstable = store.getLiveSSTables().iterator().next();
    long previous = -1;
    for (SSTableReader.PartitionPositionBounds section : sstable.getPositionsForRanges(ranges)) {
        assert previous <= section.lowerPosition : previous + " ! < " + section.lowerPosition;
        assert section.lowerPosition < section.upperPosition : section.lowerPosition + " ! < " + section.upperPosition;
        previous = section.upperPosition;
    }
}

@Test
public void testOnDiskSizeForRanges() {
    ColumnFamilyStore store = discardSSTables(KEYSPACE1, CF_STANDARD2);
    partitioner = store.getPartitioner();
    int count = 1000;
    // insert data and compact to a single sstable
    for (int j = 0; j < count; j++) {
        new RowUpdateBuilder(store.metadata(), 15000, k0(j)).clustering("0").add("val", ByteBufferUtil.EMPTY_BYTE_BUFFER).build().applyUnsafe();
    }
    store.forceBlockingFlush(UNIT_TESTS);
    store.forceMajorCompaction();
    SSTableReader sstable = store.getLiveSSTables().iterator().next();
    // Non-compression-dependent checks
    // Check several ways of going through the whole file
    assertEquals(sstable.onDiskLength(), onDiskSizeForRanges(sstable, Collections.singleton(new Range<>(t(cut(k0(0), 1)), t0(count - 1)))));
    assertEquals(sstable.onDiskLength(), onDiskSizeForRanges(sstable, Collections.singleton(new Range<>(sstable.getPartitioner().getMinimumToken(), sstable.getPartitioner().getMinimumToken()))));
    assertEquals(sstable.onDiskLength(), onDiskSizeForRanges(sstable, Collections.singleton(new Range<>(sstable.getPartitioner().getMinimumToken(), sstable.getLast().getToken()))));
    // Split at exact match
    assertEquals(sstable.onDiskLength(), onDiskSizeForRanges(sstable, ImmutableList.of(new Range<>(t(cut(k0(0), 1)), t0(347)), new Range<>(t0(347), t0(count - 1)))));
    // Split at different prefixes pointing to the same position
    assertEquals(sstable.onDiskLength(), onDiskSizeForRanges(sstable, ImmutableList.of(new Range<>(t(cut(k0(0), 1)), t(cut(k0(600), 2))), new Range<>(t(cut(k0(600), 1)), t0(count - 1)))));
    // Size one row
    double oneRowSize = sstable.uncompressedLength() * 1.0 / count;
    System.out.println("One row size: " + oneRowSize);
    if (!sstable.compression) {
        double delta = 0.9;
        // Ranges are end-inclusive, indexes are adjusted by one here to account for that.
        assertEquals((52 - 38), onDiskSizeForRanges(sstable, Collections.singleton(new Range<>(t0(37), t0(51)))) / oneRowSize, delta);
        // Try non-matching positions (inexact indexes are not adjusted for the count).
        assertEquals((34 - 30), onDiskSizeForRanges(sstable, Collections.singleton(new Range<>(t(cut(k0(30), 1)), t0(33)))) / oneRowSize, delta);
        assertEquals((700 - 554), onDiskSizeForRanges(sstable, Collections.singleton(new Range<>(t0(553), t(cut(k0(700), 2))))) / oneRowSize, delta);
        assertEquals((500 - 30), onDiskSizeForRanges(sstable, Collections.singleton(new Range<>(t(cut(k0(30), 1)), t(cut(k0(500), 2))))) / oneRowSize, delta);
        // Try a list
        List<Range<Token>> ranges = ImmutableList.of(new Range<>(t0(37), t0(51)), new Range<>(t0(71), t(cut(k0(100), 2))), new Range<>(t(cut(k0(230), 1)), t0(243)), new Range<>(t(cut(k0(260), 1)), t(cut(k0(300), 2))), new Range<>(t0(373), t0(382)), new Range<>(t0(382), t0(385)), // empty range
        new Range<>(t(cut(k0(400), 2)), t(cut(k0(400), 1))), // touching ranges
        new Range<>(t0(563), t(cut(k0(600), 2))), new Range<>(t(cut(k0(600), 1)), t0(621)));
        assertEquals((52 - 38 + 100 - 72 + 244 - 230 + 300 - 260 + 383 - 374 + 386 - 383 + 400 - 400 + 622 - 564), onDiskSizeForRanges(sstable, ranges) / oneRowSize, delta);
        // Check going through the whole file
        assertEquals(sstable.onDiskLength(), onDiskSizeForRanges(sstable, Collections.singleton(new Range<>(t(cut(k0(0), 1)), t0(count - 1)))));
        assertEquals(sstable.onDiskLength(), onDiskSizeForRanges(sstable, ImmutableList.of(new Range<>(t(cut(k0(0), 1)), t0(347)), new Range<>(t0(347), t0(count - 1)))));
        assertEquals(sstable.onDiskLength(), onDiskSizeForRanges(sstable, ImmutableList.of(new Range<>(t(cut(k0(0), 1)), t(cut(k0(600), 2))), new Range<>(t(cut(k0(600), 1)), t0(count - 1)))));
    } else {
        // It's much harder to test with compression.
        // Check first three rows have the same size (they must be in the same chunk)
        final long row0size = onDiskSizeForRanges(sstable, Collections.singleton(new Range<>(t(cut(k0(0), 1)), t0(0))));
        assertEquals(row0size, onDiskSizeForRanges(sstable, Collections.singleton(new Range<>(t0(0), t0(1)))));
        assertEquals(row0size, onDiskSizeForRanges(sstable, Collections.singleton(new Range<>(t0(1), t0(2)))));
        // As well as the first three rows together
        assertEquals(row0size, onDiskSizeForRanges(sstable, Collections.singleton(new Range<>(t(cut(k0(0), 1)), t0(2)))));
        // And also when we query for them in separate ranges
        assertEquals(row0size, onDiskSizeForRanges(sstable, ImmutableList.of(new Range<>(t(cut(k0(0), 1)), t0(0)), new Range<>(t0(0), t0(1)))));
        assertEquals(row0size, onDiskSizeForRanges(sstable, ImmutableList.of(new Range<>(t(cut(k0(0), 1)), t0(0)), new Range<>(t0(1), t0(2)))));
        assertEquals(row0size, onDiskSizeForRanges(sstable, ImmutableList.of(new Range<>(t(cut(k0(0), 1)), t0(0)), new Range<>(t0(0), t0(1)), new Range<>(t0(1), t0(2)))));
        // Finally, check that if we query for every second row we get the total size of the file.
        assertEquals(sstable.onDiskLength(), onDiskSizeForRanges(sstable, IntStream.range(0, count).filter(i -> i % 2 != 0).mapToObj(i -> new Range<>(t0(i), t0(i + 1))).collect(Collectors.toList())));
    }
}

@Test
public void testOnDiskSizeCompressedBoundaries() {
    ColumnFamilyStore store = discardSSTables(KEYSPACE1, CF_COMPRESSED);
    partitioner = store.getPartitioner();
    int count = 1000;
    // Use a longish string to let a key align with a chunk boundary
    ByteBuffer dataBuf = ByteBufferUtil.bytes(String.format("%43d", 123));
    // insert data and compact to a single sstable
    for (int j = 0; j < count; j++) {
        new RowUpdateBuilder(store.metadata(), 15000, k0(j)).clustering("0").add("val", dataBuf).build().applyUnsafe();
    }
    store.forceBlockingFlush(UNIT_TESTS);
    store.forceMajorCompaction();
    SSTableReader sstable = store.getLiveSSTables().iterator().next();
    int chunkLength = sstable.getCompressionMetadata().chunkLength();
    System.out.println("Chunk length: " + chunkLength);
    int[] alignedKeys = IntStream.range(0, count).filter(i -> (sstable.getPosition(dk0(i), SSTableReader.Operator.EQ) & (chunkLength - 1)) == 0).toArray();
    assertTrue("Test needs an aligned key, try changing the length of dataBuf", alignedKeys.length > 1);
    for (int k : alignedKeys) assertEquals("Coverage must not include chunk starting at end position", sstable.getCompressionMetadata().chunkFor(sstable.getPosition(dk0(k), SSTableReader.Operator.EQ)).offset, // inclusive end
    onDiskSizeForRanges(sstable, Collections.singleton(new Range<>(partitioner.getMinimumToken(), t0(k - 1)))));
}

