@Test
public void testLifecycleAndMultipleInstancesCreation() throws InterruptedException {
    final List<List<Counter>> metricsPerIteration = new ArrayList<>();
    int METRICS_COUNT = 50;
    int ITERATIONS_COUNT = 100;
    long TASKS_COUNT = 100_000;
    int THREADS = 20;
    boolean DESTROY_COUNTERS_AT_THE_END_OF_ITERATION = true;
    for (int iteration = 0; iteration < ITERATIONS_COUNT; iteration++) {
        {
            final List<Counter> metrics = new ArrayList<>();
            for (int i = 0; i < METRICS_COUNT; i++) metrics.add(new ThreadLocalCounter());
            metricsPerIteration.add(metrics);
        }
        // note: these threads are FastThreadLocalThread instances
        // so, we recycle thread local metrics using io.netty.util.concurrent.FastThreadLocal.onRemoval
        LocalAwareExecutorPlus executor = executorFactory().localAware().pooled("executor-" + iteration, THREADS);
        for (int i = 0; i < TASKS_COUNT; i++) {
            executor.submit(() -> {
                for (List<Counter> metricSet : metricsPerIteration) for (Counter metric : metricSet) metric.inc();
            });
        }
        boolean allIncremented = false;
        while (!allIncremented) {
            allIncremented = true;
            for (int metricSetId = 0; metricSetId < metricsPerIteration.size(); metricSetId++) for (Counter metric : metricsPerIteration.get(metricSetId)) allIncremented &= TASKS_COUNT * (metricsPerIteration.size() - metricSetId) == metric.getCount();
        }
        assertEquals(THREADS, ThreadLocalMetrics.getThreadLocalMetricsObjectsCount());
        executor.shutdown();
        executor.awaitTermination(30, TimeUnit.SECONDS);
        for (int metricSetId = 0; metricSetId < metricsPerIteration.size(); metricSetId++) for (Counter metric : metricsPerIteration.get(metricSetId)) assertEquals(TASKS_COUNT * (metricsPerIteration.size() - metricSetId), metric.getCount());
        if (DESTROY_COUNTERS_AT_THE_END_OF_ITERATION) {
            metricsPerIteration.clear();
        }
        LOGGER.info("id generator state: {}, free IDs: {}", ThreadLocalMetrics.idGenerator.get(), ThreadLocalMetrics.freeMetricIdSet);
        LOGGER.info("iteration completed: {} / {}", iteration + 1, ITERATIONS_COUNT);
    }
}

