@Test
public void failedAck() {
    DatabaseDescriptor.getRepairRetrySpec().maxAttempts = new RetrySpec.MaxAttempt(Integer.MAX_VALUE);
    DatabaseDescriptor.setRepairPendingCompactionRejectThreshold(1);
    Gen<RepairStage> stageGen = Gens.enums().all(RepairStage.class);
    qt().withPure(false).withExamples(10).check(rs -> {
        Cluster cluster = new Cluster(rs);
        enableMessageFaults(cluster);
        Gen<Cluster.Node> coordinatorGen = Gens.pick(cluster.nodes.keySet()).map(cluster.nodes::get);
        List<Closeable> closeables = new ArrayList<>();
        for (int example = 0; example < 100; example++) {
            Cluster.Node coordinator = coordinatorGen.next(rs);
            RepairCoordinator repair = coordinator.repair(KEYSPACE, irOption(rs, coordinator, KEYSPACE, ignore -> TABLES), false);
            repair.run();
            // make sure the failing node is not the coordinator, else messaging isn't used
            InetAddressAndPort failingAddress = rs.pickUnorderedSet(repair.state.getNeighborsAndRanges().participants);
            Cluster.Node failingNode = cluster.nodes.get(failingAddress);
            RepairStage stage = stageGen.next(rs);
            switch(stage) {
                case PREPARE:
                    {
                        ICompactionManager cm = failingNode.compactionManager();
                        Mockito.when(cm.getPendingTasks()).thenReturn(42);
                        closeables.add(() -> Mockito.when(cm.getPendingTasks()).thenReturn(0));
                    }
                    break;
                case VALIDATION:
                    {
                        cluster.addListener(new MessageListener() {

                            @Override
                            public void preHandle(Cluster.Node node, Message<?> msg) {
                                if (node != failingNode)
                                    return;
                                if (msg.verb() != Verb.VALIDATION_REQ)
                                    return;
                                ValidationRequest req = (ValidationRequest) msg.payload;
                                if (rs.nextBoolean()) {
                                    // fail ctx.repair().consistent.local.maybeSetRepairing(desc.parentSessionId);
                                    LocalSession session = node.activeRepairService.consistent.local.getSession(req.desc.parentSessionId);
                                    session.setState(ConsistentSession.State.FAILED);
                                } else {
                                    // fail previewKind(desc.parentSessionId);
                                    node.activeRepairService.removeParentRepairSession(req.desc.parentSessionId);
                                }
                                cluster.removeListener(this);
                            }
                        });
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Unknown stage: " + stage);
            }
            cluster.processAll();
            Assertions.assertThat(repair.state.getResult().kind).describedAs("Unexpected state: %s -> %s; example %d", repair.state, repair.state.getResult(), example).isEqualTo(Completable.Result.Kind.FAILURE);
            switch(stage) {
                case PREPARE:
                    {
                        Assertions.assertThat(repair.state.getResult().message).describedAs("Unexpected state: %s -> %s; example %d", repair.state, repair.state.getResult(), example).contains("Got negative replies from endpoints [" + failingAddress + "]");
                    }
                    break;
                case VALIDATION:
                    {
                        Assertions.assertThat(repair.state.getResult().message).describedAs("Unexpected state: %s -> %s; example %d", repair.state, repair.state.getResult(), example).contains("Got VALIDATION_REQ failure from " + failingAddress + ": UNKNOWN");
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Unknown stage: " + stage);
            }
            closeables.forEach(Closeable::close);
            closeables.clear();
        }
    });
}

@Test
public void failingRepair() {
    // to avoid unlucky timing issues, retry until success; given enough retries we should eventually become success
    DatabaseDescriptor.getRepairRetrySpec().maxAttempts = new RetrySpec.MaxAttempt(Integer.MAX_VALUE);
    Gen<RepairJobStage> stageGen = Gens.enums().all(RepairJobStage.class);
    qt().withPure(false).withExamples(10).check(rs -> {
        Cluster cluster = new Cluster(rs);
        enableMessageFaults(cluster);
        Gen<Cluster.Node> coordinatorGen = Gens.pick(cluster.nodes.keySet()).map(cluster.nodes::get);
        List<Closeable> closeables = new ArrayList<>();
        for (int example = 0; example < 100; example++) {
            Cluster.Node coordinator = coordinatorGen.next(rs);
            // exclude accord repair as this test breaks validation/sync; which accord doesn't have
            RepairOption options = repairOption(rs, coordinator, KEYSPACE, TABLES);
            RepairCoordinator repair = coordinator.repair(KEYSPACE, options, false);
            repair.run();
            InetAddressAndPort failingAddress = pickParticipant(rs, coordinator, repair);
            Cluster.Node failingNode = cluster.nodes.get(failingAddress);
            RepairJobStage stage = stageGen.next(rs);
            // because of local syncs reaching out to the failing address, a different address may actually be what failed
            Set<InetAddressAndPort> syncFailedAddresses = new HashSet<>();
            switch(stage) {
                case VALIDATION:
                    {
                        closeables.add(failingNode.doValidation((cfs, validator) -> {
                            long delayNanos = rs.nextLong(TimeUnit.MILLISECONDS.toNanos(5), TimeUnit.MINUTES.toNanos(1));
                            cluster.unorderedScheduled.schedule(() -> validator.fail(new SimulatedFault("Validation failed")), delayNanos, TimeUnit.NANOSECONDS);
                        }));
                    }
                    break;
                case SYNC:
                    {
                        closeables.add(failingNode.doValidation((cfs, validator) -> addMismatch(rs, cfs, validator)));
                        List<InetAddressAndPort> addresses = ImmutableList.<InetAddressAndPort>builder().add(coordinator.addressAndPort).addAll(repair.state.getNeighborsAndRanges().participants).build();
                        for (InetAddressAndPort address : addresses) {
                            closeables.add(cluster.nodes.get(address).doSync(plan -> {
                                long delayNanos = rs.nextLong(TimeUnit.SECONDS.toNanos(5), TimeUnit.MINUTES.toNanos(10));
                                cluster.unorderedScheduled.schedule(() -> {
                                    if (address == failingAddress || plan.getCoordinator().getPeers().contains(failingAddress)) {
                                        syncFailedAddresses.add(address);
                                        SimulatedFault fault = new SimulatedFault("Sync failed");
                                        for (StreamEventHandler handler : plan.handlers()) handler.onFailure(fault);
                                    } else {
                                        StreamState success = new StreamState(plan.planId(), plan.streamOperation(), Collections.emptySet());
                                        for (StreamEventHandler handler : plan.handlers()) handler.onSuccess(success);
                                    }
                                }, delayNanos, TimeUnit.NANOSECONDS);
                                return null;
                            }));
                        }
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Unknown stage: " + stage);
            }
            cluster.processAll();
            Assertions.assertThat(repair.state.isComplete()).describedAs("Repair job did not complete, and no work is pending...").isTrue();
            Assertions.assertThat(repair.state.getResult().kind).describedAs("Unexpected state: %s -> %s; example %d", repair.state, repair.state.getResult(), example).isEqualTo(Completable.Result.Kind.FAILURE);
            switch(stage) {
                case VALIDATION:
                    {
                        // Got VALIDATION_REQ failure from Ero2.MJ.N8kkw2.w3iFYdDw.HJiVYC32.mWb.b.xwi3tZ.s5k1l.mb.asTy_7QmQ.Q3.u.kjgh.GKjx.g1aKfkjB.YlyKg9.DyQszn7F.Ox2DMYIph.xlgH.EV.A9yEz2J.l6UHdC.C6FYLXE.J0CNHBH./[4905:e9f:2f00:e418:baac:b8d9:9ff9:6604]:33363: UNKNOWN"
                        Assertions.assertThat(repair.state.getResult().message).describedAs("Unexpected state: %s -> %s; example %d", repair.state, repair.state.getResult(), example).// ValidationResponse with null tree seen
                        containsAnyOf("Validation failed in " + failingAddress, // ack was dropped and on retry the participate detected dup so rejected as the task failed
                        "Got VALIDATION_REQ failure from " + failingAddress + ": UNKNOWN");
                    }
                    break;
                case SYNC:
                    AbstractStringAssert<?> a = Assertions.assertThat(repair.state.getResult().message).describedAs("Unexpected state: %s -> %s; example %d", repair.state, repair.state.getResult(), example);
                    // SymmetricRemoteSyncTask + AsymmetricRemoteSyncTask
                    // ... Sync failed between /[81fc:714:2c56:a2d3:faf3:eb7c:e4dd:cb9e]:54401 and /220.3.10.72:21402
                    // LocalSyncTask
                    // ... failed with error Sync failed
                    // Dedup nack, but may be remote or local sync!
                    // ... Got SYNC_REQ failure from ...: UNKNOWN
                    String failingMsg = repair.state.getResult().message;
                    if (failingMsg.contains("Sync failed between")) {
                        a.contains("Sync failed between").contains(failingAddress.toString());
                    } else if (failingMsg.contains("Got SYNC_REQ failure from")) {
                        Assertions.assertThat(syncFailedAddresses).isNotEmpty();
                        a.containsAnyOf(syncFailedAddresses.stream().map(s -> "Got SYNC_REQ failure from " + s + ": UNKNOWN").collect(Collectors.toList()).toArray(String[]::new));
                    } else {
                        a.contains("failed with error Sync failed");
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Unknown stage: " + stage);
            }
            assertParticipateResult(cluster, repair, Completable.Result.Kind.FAILURE);
            closeables.forEach(Closeable::close);
            closeables.clear();
        }
    });
}

@Test
public void happyPath() {
    // disable all retries, no delays/drops are possible
    DatabaseDescriptor.getRepairRetrySpec().maxAttempts = RetrySpec.MaxAttempt.DISABLED;
    Map<String, LongArrayList> repairTypeRuntimes = new HashMap<>();
    long realStartNanos = System.nanoTime();
    qt().withPure(false).withExamples(10).check(rs -> {
        Cluster cluster = new Cluster(rs);
        Gen<Cluster.Node> coordinatorGen = Gens.pick(cluster.nodes.keySet()).map(cluster.nodes::get);
        List<Closeable> closeables = new ArrayList<>();
        for (int example = 0; example < 100; example++) {
            Cluster.Node coordinator = coordinatorGen.next(rs);
            long nowNanos = System.nanoTime();
            RepairCoordinator repair = coordinator.repair(KEYSPACE, repairOption(rs, coordinator, KEYSPACE, TABLES));
            repair.run();
            boolean shouldSync = rs.nextBoolean();
            if (shouldSync)
                closeables.add(cluster.nodes.get(pickParticipant(rs, coordinator, repair)).doValidation((cfs, validator) -> addMismatch(rs, cfs, validator)));
            runAndAssertSuccess(cluster, example, shouldSync, repair);
            repairTypeRuntimes.computeIfAbsent(repair.state.getType(), ignore -> new LongArrayList()).addLong(System.nanoTime() - nowNanos);
            closeables.forEach(Closeable::close);
            closeables.clear();
        }
    });
    long realDurationNanos = System.nanoTime() - realStartNanos;
    long repairDurationsNanos = 0;
    StringBuilder sb = new StringBuilder();
    for (Map.Entry<String, LongArrayList> e : repairTypeRuntimes.entrySet()) {
        sb.append(e.getKey());
        long[] times = e.getValue().toLongArray();
        repairDurationsNanos += LongStream.of(times).sum();
        Arrays.sort(times);
        long min = times[0];
        long median = times[times.length / 2];
        long max = times[times.length - 1];
        sb.append(": min=").append(TimeUnit.NANOSECONDS.toMillis(min)).append(", median=").append(TimeUnit.NANOSECONDS.toMillis(median)).append(", max=").append(TimeUnit.NANOSECONDS.toMillis(max)).append(", count=").append(times.length).append('\n');
    }
    logger.info("Repair runtimes (in millis):\nTest Duration {}\nRepair Duration {}\n{}", TimeUnit.NANOSECONDS.toMillis(realDurationNanos), TimeUnit.NANOSECONDS.toMillis(repairDurationsNanos), sb);
}

/**
 * When there is no difference between two, SymmetricLocalSyncTask should return stats with 0 difference.
 */
@Test
public void testNoDifference() throws Throwable {
    final InetAddressAndPort ep2 = InetAddressAndPort.getByName("127.0.0.2");
    Range<Token> range = new Range<>(partitioner.getMinimumToken(), partitioner.getRandomToken());
    RepairJobDesc desc = new RepairJobDesc(nextTimeUUID(), nextTimeUUID(), KEYSPACE1, "Standard1", Arrays.asList(range));
    MerkleTrees tree1 = createInitialTree(desc);
    MerkleTrees tree2 = createInitialTree(desc);
    // difference the trees
    // note: we reuse the same endpoint which is bogus in theory but fine here
    TreeResponse r1 = new TreeResponse(local, tree1);
    TreeResponse r2 = new TreeResponse(ep2, tree2);
    LocalSyncTask task = new LocalSyncTask(SharedContext.Global.instance, desc, r1.endpoint, r2.endpoint, MerkleTrees.difference(r1.trees, r2.trees), NO_PENDING_REPAIR, true, true, PreviewKind.NONE);
    task.run();
    assertTrue(task.stat.differences.isEmpty());
}

@Test
public void testDifference() throws Throwable {
    Range<Token> range = new Range<>(partitioner.getMinimumToken(), partitioner.getRandomToken());
    TimeUUID parentRepairSession = nextTimeUUID();
    Keyspace keyspace = Keyspace.open(KEYSPACE1);
    ColumnFamilyStore cfs = keyspace.getColumnFamilyStore("Standard1");
    ActiveRepairService.instance().registerParentRepairSession(parentRepairSession, FBUtilities.getBroadcastAddressAndPort(), Arrays.asList(cfs), Arrays.asList(range), false, ActiveRepairService.UNREPAIRED_SSTABLE, false, PreviewKind.NONE);
    RepairJobDesc desc = new RepairJobDesc(parentRepairSession, nextTimeUUID(), KEYSPACE1, "Standard1", Arrays.asList(range));
    MerkleTrees tree1 = createInitialTree(desc);
    MerkleTrees tree2 = createInitialTree(desc);
    // change a range in one of the trees
    Token token = partitioner.midpoint(range.left, range.right);
    tree1.invalidate(token);
    MerkleTree.TreeRange changed = tree1.get(token);
    changed.hash("non-empty hash!".getBytes());
    Set<Range<Token>> interesting = new HashSet<>();
    interesting.add(changed);
    // difference the trees
    // note: we reuse the same endpoint which is bogus in theory but fine here
    TreeResponse r1 = new TreeResponse(local, tree1);
    TreeResponse r2 = new TreeResponse(InetAddressAndPort.getByName("127.0.0.2"), tree2);
    LocalSyncTask task = new LocalSyncTask(SharedContext.Global.instance, desc, r1.endpoint, r2.endpoint, MerkleTrees.difference(r1.trees, r2.trees), NO_PENDING_REPAIR, true, true, PreviewKind.NONE);
    NettyStreamingConnectionFactory.MAX_CONNECT_ATTEMPTS = 1;
    try {
        task.run();
    } finally {
        NettyStreamingConnectionFactory.MAX_CONNECT_ATTEMPTS = 3;
    }
    // ensure that the changed range was recorded
    assertEquals("Wrong differing ranges", interesting.size(), task.stat.differences.size());
}

