@Test
public void testCreate5NodeStandardSyncTasksWithTransient() {
    List<TreeResponse> treeResponses = Arrays.asList(treeResponse(addr1, RANGE_1, "one", RANGE_2, "one", RANGE_3, "one"), treeResponse(addr2, RANGE_1, "two", RANGE_2, "two", RANGE_3, "two"), treeResponse(addr3, RANGE_1, "three", RANGE_2, "three", RANGE_3, "three"), treeResponse(addr4, RANGE_1, "four", RANGE_2, "four", RANGE_3, "four"), treeResponse(addr5, RANGE_1, "five", RANGE_2, "five", RANGE_3, "five"));
    Predicate<InetAddressAndPort> isTransient = ep -> ep.equals(addr4) || ep.equals(addr5);
    Map<SyncNodePair, SyncTask> tasks = toMap(RepairJob.createStandardSyncTasks(SharedContext.Global.instance, JOB_DESC, treeResponses, // local
    addr1, // transient
    isTransient, false, true, PreviewKind.ALL));
    SyncNodePair[] pairs = new SyncNodePair[] { pair(addr1, addr2), pair(addr1, addr3), pair(addr1, addr4), pair(addr1, addr5), pair(addr2, addr4), pair(addr2, addr4), pair(addr2, addr5), pair(addr3, addr4), pair(addr3, addr5) };
    for (SyncNodePair pair : pairs) {
        SyncTask task = tasks.get(pair);
        // Local only if addr1 is a coordinator
        assertThat(task).hasLocal(pair.coordinator.equals(addr1)).// All ranges to be synchronised
        hasRanges(RANGE_1, RANGE_2, RANGE_3);
        boolean isRemote = !pair.coordinator.equals(addr1) && !pair.peer.equals(addr1);
        boolean involvesTransient = isTransient.test(pair.coordinator) || isTransient.test(pair.peer);
        assertThat(isRemote && involvesTransient).withFailMessage("Coordinator: %s\n, Peer: %s\n", pair.coordinator, pair.peer).isEqualTo(task instanceof AsymmetricRemoteSyncTask);
    }
}

