public void testConviction() throws Exception {
    InetAddressAndPort remote = InetAddressAndPort.getByName("127.0.0.2");
    Gossiper.instance.initializeNodeUnsafe(remote, UUID.randomUUID(), 1);
    // Set up RepairSession
    TimeUUID parentSessionId = nextTimeUUID();
    IPartitioner p = Murmur3Partitioner.instance;
    Range<Token> repairRange = new Range<>(p.getToken(ByteBufferUtil.bytes(0)), p.getToken(ByteBufferUtil.bytes(100)));
    Set<InetAddressAndPort> endpoints = Sets.newHashSet(remote);
    RepairSession session = new RepairSession(SharedContext.Global.instance, new Scheduler.NoopScheduler(), parentSessionId, new CommonRange(endpoints, Collections.emptySet(), Arrays.asList(repairRange)), false, "Keyspace1", RepairParallelism.SEQUENTIAL, false, false, PreviewKind.NONE, false, false, false, false, false, "Standard1");
    // perform convict
    session.convict(remote, Double.MAX_VALUE);
    // RepairSession should throw ExecutorException with the cause of IOException when getting its value
    try {
