@Test
public void fromSystemTablesPreservesExistingSchemaProperties() {
    TableMetadata defaultTable = AuthKeyspace.metadata().tables.getNullable(AuthKeyspace.ROLES);
    TableMetadata modifiedTable = defaultTable.unbuild().id(TableId.fromLong(0)).comment("Testing").gcGraceSeconds(60).compaction(CompactionParams.lcs(new HashMap<>())).speculativeRetry(new PercentileSpeculativeRetryPolicy(50.0)).build();
    assertThat(modifiedTable).isNotEqualTo(defaultTable);
    TableMetadata nonstandard = TableMetadata.builder(SchemaConstants.AUTH_KEYSPACE_NAME, "nonstandard").addPartitionKeyColumn("pk", Int32Type.instance).comment("A non-standard table that should be preserved").params(TableParams.builder().readRepair(ReadRepairStrategy.NONE).build()).build();
    KeyspaceMetadata km = KeyspaceMetadata.create(SchemaConstants.AUTH_KEYSPACE_NAME, KeyspaceParams.simple(3), Tables.of(modifiedTable, nonstandard));
    DistributedSchema schema = DistributedSchema.fromSystemTables(Keyspaces.of(km), Set.of(DatabaseDescriptor.getLocalDataCenter()));
    KeyspaceMetadata merged = schema.getKeyspaceMetadata(SchemaConstants.AUTH_KEYSPACE_NAME);
    assertThat(merged.getTableOrViewNullable(AuthKeyspace.ROLES)).isEqualTo(modifiedTable);
    assertThat(merged.getTableOrViewNullable("nonstandard")).isEqualTo(nonstandard);
    // check all other default tables in the auth keyspace were included in the merged schema
    AuthKeyspace.metadata().tables.forEach(tm -> {
        if (!tm.name.equals(AuthKeyspace.ROLES))
            assertThat(merged.getTableOrViewNullable(tm.name)).isEqualTo(tm);
    });
}

@Test
public void dropKS() throws ConfigurationException {
    // sanity
    final KeyspaceMetadata ks = Schema.instance.getKeyspaceMetadata(KEYSPACE1);
    assertNotNull(ks);
    final TableMetadata cfm = ks.tables.getNullable(TABLE2);
    assertNotNull(cfm);
    // write some data, force a flush, then verify that files exist on disk.
    for (int i = 0; i < 100; i++) QueryProcessor.executeInternal(String.format("INSERT INTO %s.%s (key, name, val) VALUES (?, ?, ?)", KEYSPACE1, TABLE2), "dropKs", "col" + i, "anyvalue");
    ColumnFamilyStore cfs = Keyspace.open(cfm.keyspace).getColumnFamilyStore(cfm.name);
    assertNotNull(cfs);
    Util.flush(cfs);
    assertTrue(!cfs.getDirectories().sstableLister(Directories.OnTxnErr.THROW).list().isEmpty());
    SchemaTestUtil.announceKeyspaceDrop(ks.name);
    assertNull(Schema.instance.getKeyspaceMetadata(ks.name));
    // write should fail.
    boolean success = true;
    try {
        QueryProcessor.executeInternal(String.format("INSERT INTO %s.%s (key, name, val) VALUES (?, ?, ?)", KEYSPACE1, TABLE2), "dropKs", "col0", "anyvalue");
    } catch (Throwable th) {
        success = false;
    }
    assertFalse("This mutation should have failed since the KS no longer exists.", success);
    // reads should fail too.
    boolean threw = false;
    try {
        Keyspace.open(ks.name);
    } catch (Throwable th) {
        threw = true;
    }
    assertTrue(threw);
}

