@Test
public void reversedTypeTest() throws Throwable {
    try (Cluster cluster = builder().withNodes(1).start()) {
        cluster.coordinator(1).execute("CREATE KEYSPACE ks WITH replication = {'class': 'SimpleStrategy', 'replication_factor' : 1};", ConsistencyLevel.ALL);
        StringBuilder sb = new StringBuilder();
        sb.append("CREATE TABLE ks.tbl (pk int");
        int counter = 1;
        List<String> asc = new ArrayList<>();
        List<String> desc = new ArrayList<>();
        for (CQL3Type.Native value : CQL3Type.Native.values()) {
            if (value == CQL3Type.Native.EMPTY || value == CQL3Type.Native.COUNTER || value == CQL3Type.Native.DURATION)
                continue;
            String name = "ck" + (counter++);
            sb.append(", ").append(name).append(" ").append(value.toString());
            asc.add(name);
            name = "ck" + (counter++);
            sb.append(", ").append(name).append(" ").append(value.toString());
            desc.add(name);
        }
        for (CQL3Type.Native value : CQL3Type.Native.values()) {
            if (value == CQL3Type.Native.EMPTY || value == CQL3Type.Native.COUNTER)
                continue;
            sb.append(", static").append(counter++).append(" ").append(value.toString()).append(" static");
        }
        for (CQL3Type.Native value : CQL3Type.Native.values()) {
            if (value == CQL3Type.Native.EMPTY || value == CQL3Type.Native.COUNTER)
                continue;
            sb.append(", regular").append(counter++).append(" ").append(value.toString());
        }
        sb.append(", primary key (pk");
        for (String s : asc) sb.append(", ").append(s);
        for (String s : desc) sb.append(", ").append(s);
        sb.append("))");
        sb.append(" WITH CLUSTERING ORDER BY (");
        for (int i = 0; i < asc.size(); i++) {
            if (i > 0)
                sb.append(", ");
            sb.append(asc.get(i)).append(" ASC");
        }
        for (int i = 0; i < desc.size(); i++) {
            sb.append(", ");
            sb.append(desc.get(i)).append(" DESC");
        }
        sb.append(");");
        System.out.println("sb.toString() = " + sb.toString());
        cluster.coordinator(1).execute(sb.toString(), ConsistencyLevel.ALL);
        cluster.get(1).runOnInstance(() -> {
            TableMetadata before = ClusterMetadata.current().schema.getKeyspaceMetadata("ks").getTableOrViewNullable("tbl");
            ByteBuffer out = null;
            try (DataOutputBuffer dob = new DataOutputBuffer()) {
                TableMetadata.serializer.serialize(before, dob, NodeVersion.CURRENT_METADATA_VERSION);
                out = dob.buffer();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            Assert.assertEquals(out.limit(), TableMetadata.serializer.serializedSize(before, NodeVersion.CURRENT_METADATA_VERSION));
            TableMetadata after = null;
            try {
                after = TableMetadata.serializer.deserialize(new DataInputBuffer(out, true), Types.builder().build(), UserFunctions.builder().build(), NodeVersion.CURRENT_METADATA_VERSION);
            } catch (IOException e) {
                e.printStackTrace();
                throw new RuntimeException(e);
            }
            Assert.assertEquals(Tables.diff(Tables.of(before), Tables.of(after)).toString(), after, before);
        });
    }
}

@Test
public void testPartitionKeyAsCQLLiteral() {
    String keyspaceName = "keyspace";
    String tableName = "table";
    // composite type
    CompositeType type1 = CompositeType.getInstance(UTF8Type.instance, UTF8Type.instance, UTF8Type.instance);
    TableMetadata metadata1 = TableMetadata.builder(keyspaceName, tableName).addPartitionKeyColumn("key", type1).offline().build();
    assertEquals("('test:', 'composite!', 'type)')", metadata1.partitionKeyAsCQLLiteral(type1.decompose("test:", "composite!", "type)")));
    // composite type with tuple
    TupleType tupleType = new TupleType(Arrays.asList(FloatType.instance, UTF8Type.instance));
    CompositeType type2 = CompositeType.getInstance(tupleType, IntegerType.instance);
    TableMetadata metadata2 = TableMetadata.builder(keyspaceName, tableName).addPartitionKeyColumn("key", type2).offline().build();
    ByteBuffer tupleValue = tupleType.pack(FloatType.instance.decompose(0.33f), UTF8Type.instance.decompose("tuple test"));
    assertEquals("((0.33, 'tuple test'), 10)", metadata2.partitionKeyAsCQLLiteral(type2.decompose(tupleValue, BigInteger.valueOf(10))));
    // plain type
    TableMetadata metadata3 = TableMetadata.builder(keyspaceName, tableName).offline().addPartitionKeyColumn("key", UTF8Type.instance).build();
    assertEquals("'non-composite test'", metadata3.partitionKeyAsCQLLiteral(UTF8Type.instance.decompose("non-composite test")));
}

@Test
public void testPrimaryKeyAsCQLLiteral() {
    String keyspaceName = "keyspace";
    String tableName = "table";
    TableMetadata metadata;
    // one partition key column, no clustering key
    metadata = TableMetadata.builder(keyspaceName, tableName).offline().addPartitionKeyColumn("key", UTF8Type.instance).build();
    assertEquals("'Test'", metadata.primaryKeyAsCQLLiteral(UTF8Type.instance.decompose("Test"), Clustering.EMPTY));
    // two partition key columns, no clustering key
    metadata = TableMetadata.builder(keyspaceName, tableName).offline().addPartitionKeyColumn("k1", UTF8Type.instance).addPartitionKeyColumn("k2", Int32Type.instance).build();
    assertEquals("('Test', -12)", metadata.primaryKeyAsCQLLiteral(CompositeType.getInstance(UTF8Type.instance, Int32Type.instance).decompose("Test", -12), Clustering.EMPTY));
    // one partition key column, one clustering key column
    metadata = TableMetadata.builder(keyspaceName, tableName).offline().addPartitionKeyColumn("key", UTF8Type.instance).addClusteringColumn("clustering", UTF8Type.instance).build();
    assertEquals("('k', 'Cluster')", metadata.primaryKeyAsCQLLiteral(UTF8Type.instance.decompose("k"), Clustering.make(UTF8Type.instance.decompose("Cluster"))));
    assertEquals("'k'", metadata.primaryKeyAsCQLLiteral(UTF8Type.instance.decompose("k"), Clustering.EMPTY));
    assertEquals("'k'", metadata.primaryKeyAsCQLLiteral(UTF8Type.instance.decompose("k"), Clustering.STATIC_CLUSTERING));
    // one partition key column, two clustering key columns
    metadata = TableMetadata.builder(keyspaceName, tableName).offline().addPartitionKeyColumn("key", UTF8Type.instance).addClusteringColumn("c1", UTF8Type.instance).addClusteringColumn("c2", UTF8Type.instance).build();
    assertEquals("('k', 'c1', 'c2')", metadata.primaryKeyAsCQLLiteral(UTF8Type.instance.decompose("k"), Clustering.make(UTF8Type.instance.decompose("c1"), UTF8Type.instance.decompose("c2"))));
    assertEquals("'k'", metadata.primaryKeyAsCQLLiteral(UTF8Type.instance.decompose("k"), Clustering.EMPTY));
    assertEquals("'k'", metadata.primaryKeyAsCQLLiteral(UTF8Type.instance.decompose("k"), Clustering.STATIC_CLUSTERING));
    // two partition key columns, two clustering key columns
    CompositeType composite = CompositeType.getInstance(Int32Type.instance, BooleanType.instance);
    metadata = TableMetadata.builder(keyspaceName, tableName).offline().addPartitionKeyColumn("k1", Int32Type.instance).addPartitionKeyColumn("k2", BooleanType.instance).addClusteringColumn("c1", UTF8Type.instance).addClusteringColumn("c2", UTF8Type.instance).build();
    assertEquals("(0, true, 'Cluster_1', 'Cluster_2')", metadata.primaryKeyAsCQLLiteral(composite.decompose(0, true), Clustering.make(UTF8Type.instance.decompose("Cluster_1"), UTF8Type.instance.decompose("Cluster_2"))));
    assertEquals("(1, true)", metadata.primaryKeyAsCQLLiteral(composite.decompose(1, true), Clustering.EMPTY));
    assertEquals("(2, true)", metadata.primaryKeyAsCQLLiteral(composite.decompose(2, true), Clustering.STATIC_CLUSTERING));
}

