        }).addIf(c -> !c.cms.metadata().inProgressSequences.isEmpty(), (rs, state) -> new SimpleCommand<>(String.format("Next Epoch Step; epoch=%d", state.cms.metadata().epoch.getEpoch() + 1), Cluster::incrementInProgressSequences));
    }).addAllIf(Cluster::hasNoPendingWork, b -> {
        b.addIf(cluster -> cluster.joined().size() <= cluster.maxNodes, EpochSyncTest::addNode).addIf(cluster -> cluster.joined().size() > cluster.minNodes, EpochSyncTest::removeNode);
    }).addIf(Cluster::hasWork, EpochSyncTest::processSome).add(rs -> new SimpleCommand<>("Validate", c -> c.validate(false))).add((rs, cluster) -> new SimpleCommand<>("Bump Epoch " + (cluster.cms.metadata().epoch.getEpoch() + 1), Cluster::bumpEpoch)).build());
}

