@Test
public void value() {
    Gen<AbstractType<?>> typeGen = toGen(new AbstractTypeGenerators.TypeGenBuilder().withoutUnsafeEquality().build());
    qt().check(rs -> {
        AbstractType<?> type = typeGen.next(rs);
        TableMetadata metadata = TableMetadata.builder("ks", "tbl").addPartitionKeyColumn("pk", type.freeze()).addClusteringColumn("ck", type.freeze()).addRegularColumn("r", type).addStaticColumn("s", type).partitioner(Murmur3Partitioner.instance).build();
        ByteBuffer value = toGen(AbstractTypeGenerators.getTypeSupport(type).bytesGen()).next(rs);
        List<ByteBuffer> complexValue = type.isMultiCell() ? split(type, value) : null;
        Clustering<?> clustering = BufferClustering.make(value);
        SimplePartition partition = new SimplePartition(metadata, metadata.partitioner.decorateKey(value));
        for (TxnCondition.Kind kind : TxnCondition.Value.supported()) {
            for (ProtocolVersion version : ProtocolVersion.SUPPORTED) {
                for (ColumnMetadata column : metadata.columns()) {
                    TxnReference ref = TxnReference.column(0, metadata, column);
                    // empty logic reuses this which doesn't make the most sense... flesh it out
                    TxnCondition.Value condition = new TxnCondition.Value(ref.asColumn(), kind, value, version);
                    partition.clear().addEmptyAndLive(clustering);
                    // empty partition
                    boolean expected;
                    switch(kind) {
                        case EQUAL:
                        case LESS_THAN_OR_EQUAL:
                        case GREATER_THAN_OR_EQUAL:
                            expected = column.isPrimaryKeyColumn();
                            break;
                        case NOT_EQUAL:
                        case LESS_THAN:
                        case GREATER_THAN:
                            expected = false;
                            break;
                        default:
                            throw new UnsupportedOperationException(kind.name());
                    }
                    Assertions.assertThat(condition.applies(TxnData.of(0, new TxnDataKeyValue(partition.filtered())))).describedAs("column=%s, type=%s, kind=%s", column.name, type.asCQL3Type(), kind.name()).isEqualTo(expected);
                    if (column.isPrimaryKeyColumn())
                        continue;
                    // with value
                    if (type.isMultiCell()) {
                        partition.clear().add(column.isStatic() ? Clustering.STATIC_CLUSTERING : clustering).addComplex(column, complexValue).build();
                    } else {
                        partition.clear().add(column.isStatic() ? Clustering.STATIC_CLUSTERING : clustering).add(column, value).build();
                    }
                    switch(kind) {
                        case EQUAL:
                        case LESS_THAN_OR_EQUAL:
                        case GREATER_THAN_OR_EQUAL:
                            expected = true;
                            break;
                        case NOT_EQUAL:
                        case LESS_THAN:
                        case GREATER_THAN:
                            expected = false;
                            break;
                        default:
                            throw new UnsupportedOperationException(kind.name());
                    }
                    Assertions.assertThat(condition.applies(TxnData.of(0, new TxnDataKeyValue(partition.filtered())))).describedAs("column=%s, type=%s, kind=%s", column.name, type.asCQL3Type(), kind.name()).isEqualTo(expected);
                }
            }
        }
    });
}

