@Test
public void testTombstoneWarning() throws Exception {
    final int iterations = 10000;
    createTable("CREATE TABLE %s (pk int, ck int, v int, PRIMARY KEY (pk, ck))");
    try (SimpleClient client = new SimpleClient(nativeAddr.getHostAddress(), nativePort, version, true, new EncryptionOptions.ClientEncryptionOptions())) {
        client.connect(false);
        for (int i = 0; i < iterations; i++) {
            executeWithRetries(client, new QueryMessage(String.format("INSERT INTO %s.%s (pk, ck, v) VALUES (1, %s, 1)", KEYSPACE, currentTable(), i), QueryOptions.DEFAULT));
        }
        ColumnFamilyStore store = Keyspace.open(KEYSPACE).getColumnFamilyStore(currentTable());
        Util.flush(store);
        for (int i = 0; i < iterations; i++) {
            executeWithRetries(client, new QueryMessage(String.format("DELETE v FROM %s.%s WHERE pk = 1 AND ck = %s", KEYSPACE, currentTable(), i), QueryOptions.DEFAULT));
        }
        Util.flush(store);
        {
            Message.Response resp = executeWithRetries(client, new QueryMessage(String.format("SELECT * FROM %s.%s WHERE pk = 1", KEYSPACE, currentTable()), QueryOptions.DEFAULT));
            assertEquals(1, resp.getWarnings().size());
        }
    }
}

