    // referenced state
    CloseableIterator<PaxosKeyState> iterator = tableData.iterator(ALL_RANGES);
    Assert.assertEquals(1, updateFile.getActiveReaders());
    Assert.assertFalse(updateFile.isMarkedDeleted());
