@Test
public void fuzzParser() {
    Gen<IntFunction<String>> expressionGen = random -> i -> {
        switch(i) {
            case 0:
                return String.format("p%d * %d", random.nextInt(100), random.nextInt(0, Integer.MAX_VALUE));
            case 1:
                return String.format("p%d * %d * attempts", random.nextInt(100), random.nextInt(0, Integer.MAX_VALUE));
            case 2:
                return String.format("p%d * attempts", random.nextInt(100));
            case 3:
                return String.format("p%d * %d ^ attempts", random.nextInt(100), random.nextInt(0, Integer.MAX_VALUE));
            case 4:
                return String.format("%dms", random.nextInt(0, Integer.MAX_VALUE));
            default:
                throw new IllegalArgumentException(Integer.toString(i));
        }
    };
    RandomTestRunner.test().check(rs -> {
        IntFunction<String> expression = expressionGen.next(rs);
        for (int i = 0; i < 10_000; i++) {
            RetryStrategy.parse(String.format("%dms <= %s", rs.nextInt(0, Integer.MAX_VALUE), expression.apply(rs.nextInt(5))), new TestLatencySourceFactory());
            RetryStrategy.parse(String.format("%dms <= %s <= %dms", rs.nextInt(0, Integer.MAX_VALUE), expression.apply(rs.nextInt(4)), rs.nextInt(0, Integer.MAX_VALUE)), new TestLatencySourceFactory());
            RetryStrategy.parse(String.format("%dms <= %s ... %s <= %dms", rs.nextInt(0, Integer.MAX_VALUE), expression.apply(rs.nextInt(4)), expression.apply(rs.nextInt(4)), rs.nextInt(0, Integer.MAX_VALUE)), new TestLatencySourceFactory());
        }
    });
}

