@Test
public void testScheduleTimeout() throws Exception {
    InetAddressAndPort peer = FBUtilities.getBroadcastAddressAndPort();
    StreamSession session = new StreamSession(StreamOperation.BOOTSTRAP, peer, FACTORY, null, current_version, false, 0, nextTimeUUID(), PreviewKind.ALL);
    session.init(new StreamResultFuture(nextTimeUUID(), StreamOperation.OTHER, nextTimeUUID(), PreviewKind.NONE));
    ColumnFamilyStore cfs = Keyspace.open(KEYSPACE1).getColumnFamilyStore(CF_STANDARD);
    // create two sstables
    for (int i = 0; i < 2; i++) {
        SchemaLoader.insertData(KEYSPACE1, CF_STANDARD, i, 1);
        Util.flush(cfs);
    }
    // create streaming task that streams those two sstables
    session.state(StreamSession.State.PREPARING);
    StreamTransferTask task = new StreamTransferTask(session, cfs.metadata.id);
    for (SSTableReader sstable : cfs.getLiveSSTables()) {
        List<Range<Token>> ranges = new ArrayList<>();
        ranges.add(new Range<>(sstable.getFirst().getToken(), sstable.getLast().getToken()));
        task.addTransferStream(new CassandraOutgoingFile(StreamOperation.BOOTSTRAP, sstable.selfRef(), sstable.getPositionsForRanges(ranges), ranges, 1));
    }
    assertEquals(14, task.getTotalNumberOfFiles());
    // if file sending completes before timeout then the task should be canceled.
    session.state(StreamSession.State.STREAMING);
    Future f = task.scheduleTimeout(0, 0, TimeUnit.NANOSECONDS);
    f.get();
    // when timeout runs on second file, task should be completed
    f = task.scheduleTimeout(1, 10, TimeUnit.MILLISECONDS);
    task.complete(1);
    try {
        f.get();
        Assert.assertTrue(false);
    } catch (CancellationException ex) {
    }
    assertEquals(StreamSession.State.WAIT_COMPLETE, session.state());
    // when all streaming are done, time out task should not be scheduled.
    assertNull(task.scheduleTimeout(1, 1, TimeUnit.SECONDS));
}

@Test
public void testFailSessionDuringTransferShouldNotReleaseReferences() throws Exception {
    InetAddressAndPort peer = FBUtilities.getBroadcastAddressAndPort();
    StreamCoordinator streamCoordinator = new StreamCoordinator(StreamOperation.BOOTSTRAP, 1, new NettyStreamingConnectionFactory(), false, false, null, PreviewKind.NONE);
    StreamResultFuture future = StreamResultFuture.createInitiator(nextTimeUUID(), StreamOperation.OTHER, Collections.<StreamEventHandler>emptyList(), streamCoordinator);
    StreamSession session = new StreamSession(StreamOperation.BOOTSTRAP, peer, FACTORY, null, current_version, false, 0, null, PreviewKind.NONE);
    session.init(future);
    ColumnFamilyStore cfs = Keyspace.open(KEYSPACE1).getColumnFamilyStore(CF_STANDARD);
    // create two sstables
    for (int i = 0; i < 2; i++) {
        SchemaLoader.insertData(KEYSPACE1, CF_STANDARD, i, 1);
        Util.flush(cfs);
    }
    // create streaming task that streams those two sstables
    StreamTransferTask task = new StreamTransferTask(session, cfs.metadata.id);
    List<Ref<SSTableReader>> refs = new ArrayList<>(cfs.getLiveSSTables().size());
    for (SSTableReader sstable : cfs.getLiveSSTables()) {
        List<Range<Token>> ranges = new ArrayList<>();
        ranges.add(new Range<>(sstable.getFirst().getToken(), sstable.getLast().getToken()));
        Ref<SSTableReader> ref = sstable.selfRef();
        refs.add(ref);
        task.addTransferStream(new CassandraOutgoingFile(StreamOperation.BOOTSTRAP, ref, sstable.getPositionsForRanges(ranges), ranges, 1));
    }
    assertEquals(14, task.getTotalNumberOfFiles());
    //add task to stream session, so it is aborted when stream session fails
    session.transfers.put(TableId.generate(), task);
    //make a copy of outgoing file messages, since task is cleared when it's aborted
    Collection<OutgoingStreamMessage> files = new LinkedList<>(task.streams.values());
    //simulate start transfer
    for (OutgoingStreamMessage file : files) {
        file.startTransfer();
    }
    //fail stream session mid-transfer
    session.onError(new Exception("Fake exception")).get(5, TimeUnit.SECONDS);
    //make sure reference was not released
    for (Ref<SSTableReader> ref : refs) {
        assertEquals(1, ref.globalCount());
    }
    //wait for stream to abort asynchronously
    int tries = 10;
    while (ScheduledExecutors.nonPeriodicTasks.getActiveTaskCount() > 0) {
        if (tries < 1)
            throw new RuntimeException("test did not complete in time");
        Thread.sleep(10);
        tries--;
    }
    //simulate finish transfer
    for (OutgoingStreamMessage file : files) {
        file.finishTransfer();
    }
    //now reference should be released
    for (Ref<SSTableReader> ref : refs) {
        assertEquals(0, ref.globalCount());
    }
}

/**
 * Starts a test instance, then generates a randomised ClusterMetadata instance, writes it to
 * file and finally re-initialises test instance's ClusterMetadataService. This exercises the
 * same code paths as the counterpart test in o.a.c.distributed.test.log, but in a unit test
 * it is much easier to generate random metadata, which need not actually be valid for a
 * running service, so that we can better exercise the deserialisation code.
 */
@Test
public void bootFromExportedMetadataTest() throws Throwable {
    // sorting to preserve primary replicas requires real data in Directory
    // and DataPlacements, this test uses completely random data so disable it
    CassandraRelevantProperties.TCM_SORT_REPLICA_GROUPS.setBoolean(false);
    // We will be re-intialising the ClusterMetadata and CMS, which requires
    // us to disable MBean registration. This does not happen outside of tests
    CassandraRelevantProperties.ORG_APACHE_CASSANDRA_DISABLE_MBEAN_REGISTRATION.setBoolean(true);
    // General test setup, no need to use Paxos for log commits or to replicate
    // to (non-existent) peers
    CassandraRelevantProperties.TCM_USE_ATOMIC_LONG_PROCESSOR.setBoolean(true);
    CassandraRelevantProperties.TCM_USE_TEST_NO_OP_REPLICATOR.setBoolean(true);
    ServerTestUtils.daemonInitialization();
    DatabaseDescriptor.setPartitionerUnsafe(Murmur3Partitioner.instance);
    ServerTestUtils.prepareServerNoRegister();
    Epoch epoch = epoch(new Random(System.nanoTime()));
    ClusterMetadata first = ClusterMetadata.current();
    for (int i = 0; i < 100; i++) epoch = doTest(Epoch.create(epoch.getEpoch() + 100), first);
}

@Test
public void metadataKeyExists() throws IllegalAccessException {
    ClusterMetadata empty = new ClusterMetadata(Murmur3Partitioner.instance);
    // Theese are fields that should not have MetadataKeys and should be ignored.
    Set<String> exclude = ImmutableSet.of("metadataIdentifier", "epoch", "partitioner", "extensions", "locator");
    // Mapping of ClusterMetadata field names to MetadataKey name; mapping is only needed if the names don't match.
    Map<String, String> mapping = ImmutableMap.of("directory", "node_directory", "placements", "data_placements");
    for (Field field : ClusterMetadata.class.getDeclaredFields()) {
        if (Modifier.isStatic(field.getModifiers()) || !Modifier.isPublic(field.getModifiers()) || !Modifier.isFinal(field.getModifiers()))
            continue;
        String name = field.getName();
        if (exclude.contains(name))
            continue;
        if (mapping.containsKey(name))
            name = mapping.get(name);
        String snakeName = FBUtilities.camelToSnake(name).toUpperCase(Locale.ROOT);
        Assertions.assertThat(NAME_TO_KEY.keySet()).describedAs("Unable to locate MetadataKey for %s", snakeName).contains(snakeName);
        MetadataKey expectedKey = (MetadataKey) NAME_TO_KEY.get(snakeName).get(null);
        if (!MetadataKeys.CORE_METADATA.containsKey(expectedKey))
            throw new IllegalStateException("MetadataKeys.CORE_METADATA is missing key " + expectedKey + " for field " + name);
        Assertions.assertThat(field.get(empty)).describedAs("Extraction function does not seem to match the field %s and key %s", name, snakeName).isSameAs(MetadataKeys.CORE_METADATA.get(expectedKey).apply(empty));
    }
}

