    logState = SystemKeyspaceStorage.SystemKeyspace.getLogState(toQuery);
    assertEquals(lastSnapshot, logState.baseState);
    boolean containsExpectedEntries = logState.entries.stream().map(entry -> entry.epoch.getEpoch()).allMatch(e -> e > lastSnapshot.epoch.getEpoch() && e <= maxEpoch.getEpoch() && e != toDelete.getEpoch());
    assertTrue(containsExpectedEntries);
}

