@Test
public void testMultiDC() throws Throwable {
    UniformRangePlacement rangePlacement = new UniformRangePlacement();
    Random rng = new Random(1);
    int idx = 1;
    TokenPlacementModel.NodeFactory factory = TokenPlacementModel.nodeFactory();
    List<TokenPlacementModel.Node> nodes = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        for (int j = 1; j <= 3; j++) {
            int dc = j;
            int rack = (rng.nextInt(3) + 1);
            TokenPlacementModel.Node node = factory.make(idx, dc, rack);
            ClusterMetadataTestHelper.register(idx, node.dc(), node.rack());
            ClusterMetadataTestHelper.join(idx, node.token());
            nodes.add(node);
            idx++;
        }
    }
    nodes.sort(TokenPlacementModel.Node::compareTo);
    ClusterMetadataService.instance().processor().fetchLogAndWait();
    DataPlacements placements = rangePlacement.calculatePlacements(ClusterMetadata.current().epoch, ClusterMetadata.current(), Keyspaces.of(ClusterMetadata.current().schema.getKeyspaces().get("test").get()));
    TokenPlacementModel.ReplicatedRanges predicted = RF.replicate(nodes);
    ReplicationParams replicationParams = ClusterMetadata.current().schema.getKeyspaces().get("test").get().params.replication;
    MetadataChangeSimulationTest.match(placements.get(replicationParams).reads, predicted.asMap());
}

@Test
public void testSplittingPlacementWithSingleRange() {
    // Special case of splitting a range that was created because the initial token list contained a single token,
    // which is either the min or max value in the token space. Any other single token would produce two ranges -
    // (MIN, t] & (t, MAX] - but because (x, x] denotes a wraparound, this case produces (MIN, MAX] and we need to
    // verify that we can safely split that when more tokens are introduced. This test supposes MIN = 0, MAX = 100
    ReplicaGroups before = ReplicaGroups.builder().withReplicaGroup(VersionedEndpoints.forRange(Epoch.EMPTY, rg(0, 100, 1, 2, 3))).build();
    // existing token is MIN (i.e. 0 for the purposes of this test)
    List<Token> tokens = ImmutableList.of(token(0), token(30), token(60), token(90));
    ReplicaGroups after = ReplicaGroups.splitRangesForPlacement(tokens, before);
    assertPlacement(after, rg(0, 30, 1, 2, 3), rg(30, 60, 1, 2, 3), rg(60, 90, 1, 2, 3), rg(90, 100, 1, 2, 3));
    // existing token is MAX (i.e. 100 for the purposes of this test).
    tokens = ImmutableList.of(token(30), token(60), token(90), token(100));
    after = ReplicaGroups.splitRangesForPlacement(tokens, before);
    assertPlacement(after, rg(0, 30, 1, 2, 3), rg(30, 60, 1, 2, 3), rg(60, 90, 1, 2, 3), rg(90, 100, 1, 2, 3));
}

