public void testCombiningPlacements() {
    EndpointsForRange[] firstGroups = { rg(0, 100, 1, 2, 3), rg(100, 200, 1, 2, 3), rg(200, 300, 1, 2, 3), rg(300, 400, 1, 2, 3) };
    ReplicaGroups p1 = ReplicaGroups.builder().withReplicaGroups(Arrays.asList(firstGroups).stream().map(this::v).collect(Collectors.toList())).build();
    EndpointsForRange[] secondGroups = { rg(0, 100, 2, 3, 4), rg(100, 200, 2, 3, 5), rg(200, 300, 2, 3, 6), rg(300, 400, 2, 3, 7) };
    ReplicaGroups p2 = ReplicaGroups.builder().withReplicaGroups(Arrays.asList(secondGroups).stream().map(this::v).collect(Collectors.toList())).build();
    ReplicationParams params = ReplicationParams.simple(1);
    DataPlacements map1 = DataPlacements.builder(1).with(params, new DataPlacement(p1, p1)).build();
    DataPlacements map2 = DataPlacements.builder(1).with(params, new DataPlacement(p2, p2)).build();
    DataPlacement p3 = map1.combineReplicaGroups(map2).get(params);
    for (ReplicaGroups placement : new ReplicaGroups[] { p3.reads, p3.writes }) {
        assertPlacement(placement, rg(0, 100, 1, 2, 3, 4), rg(100, 200, 1, 2, 3, 5), rg(200, 300, 1, 2, 3, 6), rg(300, 400, 1, 2, 3, 7));
