    tool = ToolRunner.invokeNodetool("invalidatepermissionscache", "role1", "--function", "f[Int32Type]");
    assertThat(tool.getExitCode()).isEqualTo(1);
    assertThat(tool.getStdout()).isEqualTo(wrapByDefaultNodetoolMessage("--function option should be passed along with --functions-in-keyspace option"));
    assertThat(tool.getCleanedStderr()).isEmpty();
    tool = ToolRunner.invokeNodetool("invalidatepermissionscache", "role1", "--functions-in-keyspace", KEYSPACE, "--function", "f[x]");
    assertThat(tool.getExitCode()).isEqualTo(1);
    assertThat(tool.getStdout()).isEqualTo(wrapByDefaultNodetoolMessage("An error was encountered when looking up function definition: Unable to find abstract-type class 'org.apache.cassandra.db.marshal.x'"));
    assertThat(tool.getCleanedStderr()).isEmpty();
}

