    runCompareTest(testTables, "table_name", "table1 > table2 > table3 > table4 > table5 > table6", humanReadable, true);
    // bloom filter space used: 2 > 4 > 6 > 1 > 3 > 5
    runCompareTest(testTables, "bloom_filter_space_used", "table2 > table4 > table6 > table1 > table3 > table5", humanReadable, ascending);
    // space used by snapshots: 5 > 1 > 2 > 4 > 3 = 6
    runCompareTest(testTables, "space_used_by_snapshots_total", "table5 > table1 > table2 > table4 > table3 > table6", humanReadable, ascending);
    // space used live: 6 > 5 > 4 > 2 > 1 = 3
    runCompareTest(testTables, "space_used_live", "table6 > table5 > table4 > table2 > table1 > table3", humanReadable, ascending);
    // space used total: 1 > 2 > 3 > 4 > 5 > 6
    runCompareTest(testTables, "space_used_total", "table1 > table2 > table3 > table4 > table5 > table6", humanReadable, ascending);
    // memtable data size: 6 > 5 > 4 > 3 > 2 > 1
    runCompareTest(testTables, "memtable_data_size", "table6 > table5 > table4 > table3 > table2 > table1", humanReadable, ascending);
}

