public void testTupleType() {
    TupleType tt = new TupleType(Arrays.asList(UTF8Type.instance, DecimalType.instance, IntegerType.instance, BytesType.instance));
    Random prng = new Random();
    List<ByteBuffer> tuplesData = new ArrayList<>();
    String[] utf8Values = new String[] { "a", "©", newRandomAlphanumeric(prng, 10), newRandomAlphanumeric(prng, 100) };
    BigDecimal[] decimalValues = new BigDecimal[] { null, BigDecimal.ZERO, BigDecimal.ONE, BigDecimal.valueOf(1234567891011121314L, 50), BigDecimal.valueOf(1234567891011121314L, 50).negate() };
    BigInteger[] varintValues = new BigInteger[] { null, BigInteger.ZERO, BigInteger.TEN.pow(1000), BigInteger.TEN.pow(1000).negate() };
