@Test
public void testSSTableReaderLeakIsDetected() {
    DatabaseDescriptor.clientInitialization();
    DatabaseDescriptor.setPartitionerUnsafe(ByteOrderedPartitioner.instance);
    Descriptor descriptor = Descriptor.fromFileWithComponent(new File("test/data/legacy-sstables/nb/legacy_tables/legacy_nb_simple/nb-400-big-Data.db"), false).left;
    TableMetadata tm = TableMetadata.builder("legacy_tables", "legacy_nb_simple").addPartitionKeyColumn("pk", UTF8Type.instance).addRegularColumn("val", UTF8Type.instance).build();
    AtomicBoolean leakDetected = new AtomicBoolean();
    AtomicBoolean runOnCloseExecuted1 = new AtomicBoolean();
    AtomicBoolean runOnCloseExecuted2 = new AtomicBoolean();
    Ref.OnLeak prevOnLeak = Ref.ON_LEAK;
    try {
        Ref.ON_LEAK = state -> {
            leakDetected.set(true);
        };
        {
            SSTableReader reader = SSTableReader.openNoValidation(null, descriptor, TableMetadataRef.forOfflineTools(tm));
            reader.runOnClose(() -> runOnCloseExecuted1.set(true));
            // second time to actually create lambda referencing to lambda, see runOnClose impl
            reader.runOnClose(() -> runOnCloseExecuted2.set(true));
            //noinspection UnusedAssignment
            // this is required, otherwise GC will not attempt to collect the created reader
            reader = null;
        }
        Awaitility.await().atMost(Duration.ofSeconds(30)).pollDelay(Duration.ofSeconds(1)).untilAsserted(() -> {
            System.gc();
            System.gc();
            System.gc();
            System.gc();
            assertThat(leakDetected.get()).isTrue();
        });
        assertThat(runOnCloseExecuted1.get()).isTrue();
        assertThat(runOnCloseExecuted2.get()).isTrue();
    } finally {
        Ref.ON_LEAK = prevOnLeak;
    }
}

@Test
public void testUnfair() throws InterruptedException {
    Semaphore s = Semaphore.newSemaphore(2);
    List<Future<Boolean>> fs = start(s);
    s.release(1);
    while (s.permits() == 1) Thread.yield();
    Assert.assertEquals(1, fs.stream().filter(Future::isDone).count());
    s.release(1);
    while (s.permits() == 1) Thread.yield();
    Assert.assertEquals(2, fs.stream().filter(Future::isDone).count());
    s.release(1);
    while (s.permits() == 1) Thread.yield();
    Assert.assertEquals(3, fs.stream().filter(Future::isDone).count());
    s.release(1);
    Assert.assertEquals(1, s.permits());
}

@Test
public void testFair() throws InterruptedException, ExecutionException, TimeoutException {
    Semaphore s = Semaphore.newFairSemaphore(2);
    List<Future<Boolean>> fs = start(s);
    s.release(1);
    fs.get(0).get(1L, MINUTES);
    s.release(1);
    fs.get(1).get(1L, MINUTES);
    s.release(1);
    fs.get(2).get(1L, MINUTES);
    s.release(1);
    Assert.assertEquals(1, s.permits());
}

