@Test
public void testPrettyPrintAndParse() {
    String[] tests = new String[] { "1", "", "", "1", "1K", "", "", "1e3", "1 KiB", " ", "B", "1024", "10 B/s", " ", "B/s", "10", "10.2 MiB/s", null, "B/s", "10695475.2", "10e+5", "", "", "10e5", "10*2^20", "", "", "10485760", "1024*2^-10", "", "", "1", "1024 miB", " ", "B", "1", "1000000um", "", "m", "1", "10e+25s", "", "s", "10e25", "1.12345e-25", "", "", "1.12345e-25", "10e+45", "", "", "10e45", "1.12345e-45", "", "", "1.12345e-45", "55.3 garbage", null, null, "55.3", "0.00TiB", "", "B", "0", "-23", null, null, "-23", "-55 Gt", " ", "t", "-55e9", "-123e+3", null, null, "-123000", "-876ns", "", "s", "-876e-9", Long.toString(Long.MAX_VALUE), null, null, Long.toString(Long.MAX_VALUE), Long.toString(Long.MIN_VALUE), null, null, Long.toString(Long.MIN_VALUE), "Infinity Kg", " ", "Kg", "+Infinity", "NaN", "", "", "NaN", "-Infinity", "", "", "-Infinity" };
    for (int i = 0; i < tests.length; i += 4) {
        String v = tests[i];
        String sep = tests[i + 1];
        String unit = tests[i + 2];
        double exp = Double.parseDouble(tests[i + 3]);
        String vBin = FBUtilities.prettyPrintBinary(exp, unit == null ? "" : unit, sep == null ? " " : sep);
        String vDec = FBUtilities.prettyPrintDecimal(exp, unit == null ? "w" : unit, sep == null ? "\t" : sep);
        LOGGER.info("{} binary {} decimal {} expected {}", v, vBin, vDec, exp);
        Assert.assertEquals(exp, FBUtilities.parseHumanReadable(v, sep, unit), getDelta(exp));
        Assert.assertEquals(exp, FBUtilities.parseHumanReadable(vBin, sep, unit), getDelta(exp));
        Assert.assertEquals(exp, FBUtilities.parseHumanReadable(vDec, sep, unit), getDelta(exp));
        if (((long) exp) == exp)
            Assert.assertEquals(exp, FBUtilities.parseHumanReadable(FBUtilities.prettyPrintMemory((long) exp), null, "B"), getDelta(exp));
    }
}

@Test
public void testPrettyPrintAndParseRange() {
    String unit = "";
    String sep = "";
    for (int exp = -100; exp < 100; ++exp) {
        for (// avoid hitting 0 exactly
        double base = -1.0; // avoid hitting 0 exactly
        base <= 1.0; // avoid hitting 0 exactly
        base += 0.12) {
            for (boolean binary : new boolean[] { false, true }) {
                double value = binary ? Math.scalb(base, exp * 10) : base * Math.pow(10, exp);
                String vBin = FBUtilities.prettyPrintBinary(value, unit, sep);
