    assertEquals(1, evaluationTimes.get());
    Pair<String, Object[]> loggedMsg = logged.get(Level.INFO).remove();
    assertEquals("TESTING {}", loggedMsg.left);
    assertArrayEquals(params, loggedMsg.right);
