@Test
public void testMultiSetPullOldestRandom() {
    int size;
    int range = 100;
    Random rand = new Random();
    for (int i = 0; i < 100; ++i) {
        size = rand.nextInt(range) + 2;
        Interval<Integer, String>[] input = new Interval[size];
        char c = 'A';
        for (int j = 0; j < size; ++j) {
            int start = rand.nextInt(range);
            input[j] = (new Interval<>(start, start + 1 + random.nextInt(range - start), Character.toString(c++)));
        }
        List<Set<Interval<Integer, String>>> overlaps = Overlaps.constructOverlapSets(Arrays.asList(input), (x, y) -> x.min >= y.max, Comparator.comparingInt(x -> x.min), Comparator.comparingInt(x -> x.max));
        String[] overlapSets = mapOverlapSetsToStrings(overlaps).toArray(new String[0]);
        int maxOverlap = Arrays.stream(overlapSets).mapToInt(String::length).max().getAsInt();
        for (int limit = 1; limit <= maxOverlap + 1; ++limit) {
            String pulled = pullLast(limit, overlapSets);
            String message = pulled + " from " + overlapSets + " limit " + limit;
            Assert.assertTrue(message + ", size " + pulled.length(), pulled.length() >= Math.min(size, limit));
            String e = "";
            for (char j = 'A'; j < pulled.length() + 'A'; ++j) e += Character.toString(j);
            Assert.assertEquals("Must select oldest " + message, e, pulled);
            int countAtLimit = 0;
            for (String set : overlapSets) {
                int count = 0;
                for (int j = 0; j < set.length(); ++j) if (pulled.indexOf(set.charAt(j)) >= 0)
                    ++count;
                Assert.assertTrue(message + " set " + set + " elements " + count, count <= limit);
                if (count == limit)
                    ++countAtLimit;
            }
            if (pulled.length() < size)
                Assert.assertTrue(message + " must have at least one set of size " + limit, countAtLimit > 0);
            else
                Assert.assertTrue(message, limit >= maxOverlap);
        }
    }
}

@Test
public void test() {
    int samples = 3_000;
    int examples = 10;
    LongArrayList byToken = new LongArrayList(samples * examples, -1);
    LongArrayList modelByToken = new LongArrayList(samples * examples, -1);
    LongArrayList byTokenLength = new LongArrayList(samples * examples, -1);
    LongArrayList byRange = new LongArrayList(samples * examples, -1);
    LongArrayList modelByRange = new LongArrayList(samples * examples, -1);
    LongArrayList byRangeLength = new LongArrayList(samples * examples, -1);
    qt().withExamples(examples).check(rs -> {
        var map = create(modelType);
        var model = createOracleForValidating(modelType);
        Gen<Range> rangeGen = rangeGen(rs, pattern, samples);
        for (int i = 0; i < samples; i++) {
            var range = rangeGen.next(rs);
            var value = SMALL_INT_GEN.nextInt(rs);
            map.put(range, value);
            model.put(range, value);
        }
        map.done();
        model.done();
        //            Assertions.assertThat(map.actual()).hasSize(samples);
        if (rangeGen instanceof NoOverlap)
            ((NoOverlap) rangeGen).reset();
        Gen.IntGen tokenGe = TOKEN_DISTRIBUTION.next(rs);
        for (int i = 0; i < samples; i++) {
            {
                // key lookup
                var lookup = IntKey.routing(tokenGe.nextInt(rs));
                var actual = timed(byToken, () -> map.intersectsToken(lookup));
                var expected = timed(modelByToken, () -> model.intersectsToken(lookup));
                byTokenLength.addLong(expected.size());
                Assertions.assertThat(sort(actual)).describedAs("Write=%d; token=%s", i, lookup).isEqualTo(sort(expected));
            }
            {
                // range lookup
                var lookup = rangeGen.next(rs);
                var actual = timed(byRange, () -> map.intersects(lookup));
                var expected = timed(modelByRange, () -> model.intersects(lookup));
                byRangeLength.addLong(expected.size());
                Assertions.assertThat(sort(actual)).describedAs("Write=%d; range=%s", i, lookup).isEqualTo(sort(expected));
            }
        }
    });
    StringBuilder sb = new StringBuilder();
    sb.append("=======");
    sb.append("\nPattern: " + pattern);
    sb.append("\nModel: " + modelType);
    sb.append("\nBy Token:");
    sb.append("\n\tSizes: " + stats(byTokenLength, false));
    sb.append("\n\t" + modelType + ": " + stats(modelByToken, true));
    sb.append("\n\tTree: " + stats(byToken, true));
    sb.append("\nBy Range:");
    sb.append("\n\tSizes: " + stats(byRangeLength, false));
    sb.append("\n\t" + modelType + ": " + stats(modelByRange, true));
    sb.append("\n\tTree: " + stats(byRange, true));
    logger.info(sb.toString());
}

