/**
 * Stateful test for RTree.
 * <p>
 * This test is very similar to {@link RangeTreeTest#test} but is fully mutable, so can not
 * use the immutable search trees (else rebuidling becomes a large cost).  Both tests should exist as they use different
 * models, which helps build confidence that the RTree does the correct thing; that test also covers start and end
 * inclusive, which this test does not.
 */
@Test
public void test() {
    stateful().check(commands(() -> State::new, state -> new Sut(state.sizeTarget, state.numChildren)).add((rs, state) -> new Create(state.newRange(rs), SMALL_INT_GEN.nextInt(rs))).add((rs, state) -> new Read(state.newRange(rs))).add((rs, state) -> new KeyRead(IntKey.routing(state.tokenGen.nextInt(rs)))).add((rs, state) -> new RangeRead(state.rangeGen.next(rs))).add(Iterate.instance).add(Clear.instance).addAllIf(state -> !state.uniqRanges.isEmpty(), b -> b.add((rs, state) -> new Read(rs.pickOrderedSet(state.uniqRanges))).add((rs, state) -> {
        Range range = rs.pickOrderedSet(state.uniqRanges);
        int token = rs.nextInt(((IntKey.Routing) range.start()).key, ((IntKey.Routing) range.end()).key) + 1;
        return new KeyRead(IntKey.routing(token));
    }).add((rs, state) -> new RangeRead(rs.pickOrderedSet(state.uniqRanges))).add((rs, state) -> new Update(rs.pickOrderedSet(state.uniqRanges), SMALL_INT_GEN.nextInt(rs))).add((rs, state) -> new Delete(rs.pickOrderedSet(state.uniqRanges)))).build());
}

